window.MUSOKU_VOLUME_DATA["26"] = {"meta":{"series":"Mushoku Tensei: Jobless Reincarnation","volume":26,"title":"Mushoku Tensei: Jobless Reincarnation Vol. 26","blurb":"The last volume: the threat of the Fighting God, three stories, and the world that comes after Rudeus.","slug":"vol26","author":"Rifujin na Magonote","illustrator":"Shirotaka","publisher":"Seven Seas Entertainment","language":"en","source":"Mushoku Tensei - Jobless Reincarnation Volume-26.epub","schemaVersion":2,"notes":"Extracted from the user's EPUB for a personal reading edition.","generatedAt":"2026-10-20T15:27:14.465177+00:00","attribution":"Speaker labels were assigned by contextual review, page by page. Diary excerpts, remembered quotations, imagined speech, and narration containing quoted fragments are distinguished from live dialogue.","sceneMetadata":"Each scene carries a location and cast. Cast lists include present characters, not only speaking characters.","assetBase":"images/vol26"},"stats":{"chapters":10,"scenes":35,"words":48538,"paragraphs":1581,"blockTypes":{"narration":811,"quotation":5,"silence":1,"spacer":146,"speech":615,"thought":3},"speechBlocks":615,"attributedSpeech":615,"speechCoverage":1.0,"embeddedDialogueBlocks":9,"speakers":29},"chapters":[{"id":"ch01","number":1,"title":"The Threat of the Fighting God","pov":"Sandor","kind":"main","wordCount":8872,"scenes":[{"id":"ch01-s01","pov":"Sandor","povHeader":null,"sceneHeader":"Sandor","location":"The beach at the Third City of Heirelil, the first clash with the Fighting God","cast":["Alex Rybak","Badigadi","Geese","Sandor"],"blocks":[{"id":"ch01-p0003","sourceIndex":3,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch01-p0004","sourceIndex":4,"type":"narration","text":"MY NAME IS Alex Kalman Rybak. I am the son of North God Kalman by blood, heir to his arts and his name. North God Kalman I… Well, we don’t use the numeral when we talk about him; we just call him North God Kalman, but regardless, North God Kalman I was my father. As North God Kalman II, I traveled the world on a quest to become a true hero to bring glory to the name of Kalman. I defeated dragons and a gargantuan behemoth, an evil priest who’d seized control of a nation and a giant man-eating monkey that haunted the hinterlands of the central continent, as well as a foolish tyrant and the guardian of a labyrinth that had wiped out many of the clans of the central continent… With the world’s strongest magic sword, the physical toughness I inherited from my mother, and the ultimate sword-fighting ­techniques developed by my father, I destroyed everyone who stood against me. I gained the title and reputation of the strongest swordsman around. That won me the people’s gratitude and their highest esteem. Thanks to my immortal demon blood, I retained my vigor and was able to continue as a hero even though long years went by. I felt elated. As far as I was concerned, I was invincible. I went on, crushing all my opponents, drunk on my own power.","html":"MY NAME IS Alex Kalman Rybak. I am the son of North God Kalman by blood, heir to his arts and his name. North God Kalman I… Well, we don’t use the numeral when we talk about him; we just call him North God Kalman, but regardless, North God Kalman I was my father. As North God Kalman II, I traveled the world on a quest to become a true hero to bring glory to the name of Kalman. I defeated dragons and a gargantuan behemoth, an evil priest who’d seized control of a nation and a giant man-eating monkey that haunted the hinterlands of the central continent, as well as a foolish tyrant and the guardian of a labyrinth that had wiped out many of the clans of the central continent… With the world’s strongest magic sword, the physical toughness I inherited from my mother, and the ultimate sword-fighting ­techniques developed by my father, I destroyed everyone who stood against me. I gained the title and reputation of the strongest swordsman around. That won me the people’s gratitude and their highest esteem. Thanks to my immortal demon blood, I retained my vigor and was able to continue as a hero even though long years went by. I felt elated. As far as I was concerned, I was invincible. I went on, crushing all my opponents, drunk on my own power. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0005","sourceIndex":5,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch01-p0006","sourceIndex":6,"type":"narration","text":"One moment stood out. A moment that convinced me that I really was a hero.","html":"One moment stood out. A moment that convinced me that I really was a hero.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0007","sourceIndex":7,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch01-p0008","sourceIndex":8,"type":"narration","text":"One day on the road, a young boy, not yet of age, stole my magic sword. He took it to a backstreet tavern full of washed-up nobodies. Their leader, a student of Sword God Style, picked up the sword—he was a Sword Saint. Usually, I would’ve wiped the floor with a Sword Saint. I could have taken him with my bare hands.","html":"One day on the road, a young boy, not yet of age, stole my magic sword. He took it to a backstreet tavern full of washed-up nobodies. Their leader, a student of Sword God Style, picked up the sword—he was a Sword Saint. Usually, I would’ve wiped the floor with a Sword Saint. I could have taken him with my bare hands.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0009","sourceIndex":9,"type":"narration","text":"…You wouldn’t believe how that fight went. The fearsome power of the magic sword elevated the abilities of that washed-up nobody to those of a Sword Emperor—perhaps even greater. It didn’t matter that it was the first time he’d ever picked it up. I barely managed to defeat him, but the experience left me deeply shaken. It also left me with a question.","html":"…You wouldn’t believe how that fight went. The fearsome power of the magic sword elevated the abilities of that washed-up nobody to those of a Sword Emperor—perhaps even greater. It didn’t matter that it was the first time he’d ever picked it up. I barely managed to defeat him, but the experience left me deeply shaken. It also left me with a question.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0010","sourceIndex":10,"type":"narration","text":"Am I truly strong?","html":"Am I truly strong?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0011","sourceIndex":11,"type":"narration","text":"While I stood there, consumed by shock after the ­battle, that nobody swordsman said, “It’s all your fault these parts are such a mess.” That jogged my memory. I was in that country. The one where I’d defeated the evil priest who’d seized power and the foolish despot. The priest had been evil, but it was religion that’d kept this nation stable. The king had been a tyrant, but his iron rule had preserved national unity.","html":"While I stood there, consumed by shock after the ­battle, that nobody swordsman said, “It’s all your fault these parts are such a mess.” That jogged my memory. I was in that country. The one where I’d defeated the evil priest who’d seized power and the foolish despot. The priest had been evil, but it was religion that’d kept this nation stable. The king had been a tyrant, but his iron rule had preserved national unity. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0012","sourceIndex":12,"type":"narration","text":"Things were different now. Now, these lands were known as the Conflict Zone. Once one great nation, it was now divided into a multitude of smaller countries all fighting amongst themselves. As one fell, another was born in an endless cycle. All were bogged down in a war in which not even the victors were spared. Larger ­nations went on preying upon them; people went on dying. And it was my fault. I’d decided their ruler was evil and ­defeated him without ever bothering to consider what anyone else thought about it. My actions had robbed these people of their peace. Acknowledging this, I was left with another question.","html":"Things were different now. Now, these lands were known as the Conflict Zone. Once one great nation, it was now divided into a multitude of smaller countries all fighting amongst themselves. As one fell, another was born in an endless cycle. All were bogged down in a war in which not even the victors were spared. Larger ­nations went on preying upon them; people went on dying. And it was my fault. I’d decided their ruler was evil and ­defeated him without ever bothering to consider what anyone else thought about it. My actions had robbed these people of their peace. Acknowledging this, I was left with another question. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0013","sourceIndex":13,"type":"narration","text":"Am I really a hero?","html":"Am I really a hero? ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0014","sourceIndex":14,"type":"narration","text":"For some time, I carried these questions with me. I put down the magic sword, and I gave up being a hero.","html":"For some time, I carried these questions with me. I put down the magic sword, and I gave up being a hero.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0015","sourceIndex":15,"type":"thought","text":"In other words, the answer I arrived at for both questions was “No.”","html":"In other words, the answer I arrived at for both questions was “No.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","attributionNote":"Inner narration; the quoted 'No.' is not spoken aloud.","speakerConfidence":"high"},{"id":"ch01-p0016","sourceIndex":16,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch01-p0017","sourceIndex":17,"type":"narration","text":"Don’t get the wrong idea. I love heroes. I love listening to all those glorious heroic epics. I still find myself wishing I could be like them, even now. Alas, I didn’t have a talent for heroism, but I still liked to think maybe, with just a little luck, when the right moment came… I’m sure you understand. You know that people aren’t simple like that. What I did when I gave up heroism was I stopped straining to force myself into the hero mold. After contemplating it, I traded out my sword for a staff and focused my efforts on training others. I chose the staff because I thought it was the best of all weapons. It’s simple, and you can find a staff like this one anywhere, so it doesn’t matter if it gets stolen, and it’s only as good a weapon as you are a fighter. From a tactical perspective, there’s also an advantage to a weapon that’s a little longer than a sword. Honestly, though, anything would have done so long as it wasn’t a magic sword.","html":"Don’t get the wrong idea. I love heroes. I love listening to all those glorious heroic epics. I still find myself wishing I could be like them, even now. Alas, I didn’t have a talent for heroism, but I still liked to think maybe, with just a little luck, when the right moment came… I’m sure you understand. You know that people aren’t simple like that. What I did when I gave up heroism was I stopped straining to force myself into the hero mold. After contemplating it, I traded out my sword for a staff and focused my efforts on training others. I chose the staff because I thought it was the best of all weapons. It’s simple, and you can find a staff like this one anywhere, so it doesn’t matter if it gets stolen, and it’s only as good a weapon as you are a fighter. From a tactical perspective, there’s also an advantage to a weapon that’s a little longer than a sword. Honestly, though, anything would have done so long as it wasn’t a magic sword.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0018","sourceIndex":18,"type":"narration","text":"As for why I wanted to train other people, I think a lot of that might have come from…how to put it…a desire to atone for my sins? It seemed to me that I’d been horribly contemptuous of the people around me. That makes it sound like I thought of them as expendable, but it was more that I divided the world into the main character (me) and the supporting characters (everyone else). I deluded myself that I was the protagonist, which was why I found it so easy to call people evil and pass judgment on them without a thought for the consequences. It’s mortifying to recall. Everyone is the protagonist in their own life, everyone has their own desires—just like me. Because I admired heroes so much, my deeds seemed righteous, but the truth wasn’t so grandiose. I was no different from the rulers I’d struck down. My dream of becoming a hero was, in short, mere ambition. It was when I realized that that I started to think maybe it would be better to be a supporting character in a true hero’s story rather than a hero in my own right. That was how it was with my father, North God Kalman. Yes, he fought alongside Dragon God Urupen and Armored Dragon King Perugius as one of the Three Godslayers, but if you think of it like a story, he wasn’t the protagonist. He’d always be the protagonist in my eyes, of course—to me, he was a hero through and through. But my perspective wasn’t the only one.","html":"As for why I wanted to train other people, I think a lot of that might have come from…how to put it…a desire to atone for my sins? It seemed to me that I’d been horribly contemptuous of the people around me. That makes it sound like I thought of them as expendable, but it was more that I divided the world into the main character (me) and the supporting characters (everyone else). I deluded myself that I was the protagonist, which was why I found it so easy to call people evil and pass judgment on them without a thought for the consequences. It’s mortifying to recall. Everyone is the protagonist in their own life, everyone has their own desires—just like me. Because I admired heroes so much, my deeds seemed righteous, but the truth wasn’t so grandiose. I was no different from the rulers I’d struck down. My dream of becoming a hero was, in short, mere ambition. It was when I realized that that I started to think maybe it would be better to be a supporting character in a true hero’s story rather than a hero in my own right. That was how it was with my father, North God Kalman. Yes, he fought alongside Dragon God Urupen and Armored Dragon King Perugius as one of the Three Godslayers, but if you think of it like a story, he wasn’t the protagonist. He’d always be the protagonist in my eyes, of course—to me, he was a hero through and through. But my perspective wasn’t the only one.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0019","sourceIndex":19,"type":"narration","text":"Point being, that was why I tried putting myself in the same position as him. Though I must admit, I also thought being a mentor to a hero sounded pretty smooth…","html":"Point being, that was why I tried putting myself in the same position as him. Though I must admit, I also thought being a mentor to a hero sounded pretty smooth…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0020","sourceIndex":20,"type":"narration","text":"Taking on all those students turned out to be unexpectedly interesting. It gave me a glimpse into how much more there was to North God style. Things I’d never realized. Some warriors were born with physical disadvantages—some had lost their arms, some were blind since birth—but they all devised their own workarounds, carving out their own ways to win. The North God style that I had learned was what my father taught my mother. Immortal demons’ sword fighting relies on brute force, employing their immortality as much as ­possible, so that’s what I thought North God style was all about. But really, North God style was created so that those without strength or who had lost something could still survive on the battlefield. It was taking on all those students that taught me that. Aside from that, things I’d only thought I’d understood came into real focus one after another, my perspective broadened, and I won the respect of many. That respect was a little mellower than what I’d experienced when I was being held up as a hero, but for some reason, it made me happier. At the same time, though I only came to use it by avoiding anything like a magic sword, I grew proud of my staff, my choice of weapon. I’d realized that I’d become steadfast in living my father’s philosophy. The thought, I recall, brought tears to my eyes. After that, I became less interested in doing heroic deeds myself.","html":"Taking on all those students turned out to be unexpectedly interesting. It gave me a glimpse into how much more there was to North God style. Things I’d never realized. Some warriors were born with physical disadvantages—some had lost their arms, some were blind since birth—but they all devised their own workarounds, carving out their own ways to win. The North God style that I had learned was what my father taught my mother. Immortal demons’ sword fighting relies on brute force, employing their immortality as much as ­possible, so that’s what I thought North God style was all about. But really, North God style was created so that those without strength or who had lost something could still survive on the battlefield. It was taking on all those students that taught me that. Aside from that, things I’d only thought I’d understood came into real focus one after another, my perspective broadened, and I won the respect of many. That respect was a little mellower than what I’d experienced when I was being held up as a hero, but for some reason, it made me happier. At the same time, though I only came to use it by avoiding anything like a magic sword, I grew proud of my staff, my choice of weapon. I’d realized that I’d become steadfast in living my father’s philosophy. The thought, I recall, brought tears to my eyes. After that, I became less interested in doing heroic deeds myself.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0021","sourceIndex":21,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch01-p0022","sourceIndex":22,"type":"narration","text":"All sorts of things happened after that, until I ended up in the service of Queen Ariel. In her, I saw that same quality I’d seen in Hero King Gauniss. My assessment wasn’t wrong. I entered Ariel’s service, then before I knew it she had assembled a group of remarkable advisors and laid a rock-solid foundation for the governance of Asura. Despite this team she had assembled, Ariel didn’t start any wars. Instead, she set about making policies to increase national prosperity. She invested a particularly large amount in magical technology and appointed young people to her ministries. When I asked her why was doing so much, even to the point that she faced ­opposition, her answer surprised me. She told me she was doing what she could in her lifetime to oppose Laplace when he was resurrected some decades hence.","html":"All sorts of things happened after that, until I ended up in the service of Queen Ariel. In her, I saw that same quality I’d seen in Hero King Gauniss. My assessment wasn’t wrong. I entered Ariel’s service, then before I knew it she had assembled a group of remarkable advisors and laid a rock-solid foundation for the governance of Asura. Despite this team she had assembled, Ariel didn’t start any wars. Instead, she set about making policies to increase national prosperity. She invested a particularly large amount in magical technology and appointed young people to her ministries. When I asked her why was doing so much, even to the point that she faced ­opposition, her answer surprised me. She told me she was doing what she could in her lifetime to oppose Laplace when he was resurrected some decades hence. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0023","sourceIndex":23,"type":"narration","text":"Marvelous! What a great ruler! Truly, I could not have chosen a better master!","html":"Marvelous! What a great ruler! Truly, I could not have chosen a better master!","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0024","sourceIndex":24,"type":"narration","text":"Or so I thought. Only then I poked around some more myself and noticed the shady character scurrying around in Ariel’s shadow. That somebody was Rudeus Greyrat. It didn’t take me long to work out that he was a follower of the Dragon God—Ariel was happy to tell me the whole story. She said that Dragon God Orsted was supporting her.","html":"Or so I thought. Only then I poked around some more myself and noticed the shady character scurrying around in Ariel’s shadow. That somebody was Rudeus Greyrat. It didn’t take me long to work out that he was a follower of the Dragon God—Ariel was happy to tell me the whole story. She said that Dragon God Orsted was supporting her. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0025","sourceIndex":25,"type":"narration","text":"I’d heard of Dragon God Orsted’s unsavory reputation. One person said he’d stabbed an ally of theirs through the heart without warning. Another said he’d suddenly pushed them off a cliff. Another, that he’d snatched the prize they were after out from under their nose. Yet another, that he’d stolen a magic item they’d just gotten their hands on. I don’t usually pay much heed to reports from onlookers, but every story I chanced upon repeated his misdeeds.","html":"I’d heard of Dragon God Orsted’s unsavory reputation. One person said he’d stabbed an ally of theirs through the heart without warning. Another said he’d suddenly pushed them off a cliff. Another, that he’d snatched the prize they were after out from under their nose. Yet another, that he’d stolen a magic item they’d just gotten their hands on. I don’t usually pay much heed to reports from onlookers, but every story I chanced upon repeated his misdeeds.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0026","sourceIndex":26,"type":"narration","text":"I have had the privilege of being in the presence of the individual in question on one occasion… Just one look at him struck fear into my heart. The Dragon God and the North God are sworn allies, and the bond of friendship between North God Kalman and Dragon God Urupen will never be broken. It was unthinkable that I should feel fear towards the man who bore the name of Dragon God, even as I was grateful to him. On the contrary, I wanted to nurture a friendship with this generation’s Dragon God. Yet I felt fear.","html":"I have had the privilege of being in the presence of the individual in question on one occasion… Just one look at him struck fear into my heart. The Dragon God and the North God are sworn allies, and the bond of friendship between North God Kalman and Dragon God Urupen will never be broken. It was unthinkable that I should feel fear towards the man who bore the name of Dragon God, even as I was grateful to him. On the contrary, I wanted to nurture a friendship with this generation’s Dragon God. Yet I felt fear. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0027","sourceIndex":27,"type":"narration","text":"I speculated that perhaps it was a curse—a curse that made everyone who saw him fear him… It wasn’t until later that I learned I was right, but that is a story for another time. Because of that heavy curse, this was the first time I’d encountered anyone serving him. This Rudeus Greyrat… You want to know my first impression of him? Well, all right. I thought he looked weak. There was cleverness in him too, but it was more base cunning than intelligence. He seemed trivial. After what Queen Ariel and Ghislaine had told me, I’d expected someone impressive, but in person, he was fully mundane.","html":"I speculated that perhaps it was a curse—a curse that made everyone who saw him fear him… It wasn’t until later that I learned I was right, but that is a story for another time. Because of that heavy curse, this was the first time I’d encountered anyone serving him. This Rudeus Greyrat… You want to know my first impression of him? Well, all right. I thought he looked weak. There was cleverness in him too, but it was more base cunning than intelligence. He seemed trivial. After what Queen Ariel and Ghislaine had told me, I’d expected someone impressive, but in person, he was fully mundane.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0028","sourceIndex":28,"type":"narration","text":"Despite that, he didn’t strike me as the type of weasel you’ll often find toadying up to great warriors or people in power. The contrast between the man and the esteem he inspired intrigued me, and I wondered if he might actually turn out to be hero material. As such, when Queen Ariel sent me to be his backup, I eagerly accepted the task.","html":"Despite that, he didn’t strike me as the type of weasel you’ll often find toadying up to great warriors or people in power. The contrast between the man and the esteem he inspired intrigued me, and I wondered if he might actually turn out to be hero material. As such, when Queen Ariel sent me to be his backup, I eagerly accepted the task. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0029","sourceIndex":29,"type":"narration","text":"Then I took part in a thrilling battle, one that featured the Abyssal King, the Ogre God, the Sword God, and my own son, North God Kalman III. It began with schemes smoldering, then exploding into open conflict… It was just like one of the battles from when I’d been trying to be a hero. Indeed, you’d be hard-pressed to find a fiery battle like that one in the modern day. It was on the level of the battles I’d fought in the past.","html":"Then I took part in a thrilling battle, one that featured the Abyssal King, the Ogre God, the Sword God, and my own son, North God Kalman III. It began with schemes smoldering, then exploding into open conflict… It was just like one of the battles from when I’d been trying to be a hero. Indeed, you’d be hard-pressed to find a fiery battle like that one in the modern day. It was on the level of the battles I’d fought in the past.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0030","sourceIndex":30,"type":"narration","text":"Little did I know there was far more to it than even that.","html":"Little did I know there was far more to it than even that.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0031","sourceIndex":31,"type":"narration","text":"Enter the Fighting God. The ultimate being who, long, long before the Laplace War, had ended the Second Great Human-Demon War. I’d never imagined that he’d turn out to be Uncle Badigadi, but thinking about it, it wasn’t out of character. That musclehead was always acting like there was more to him than met the eye. My mother used to say, “Badi puts on a smart guy act but he’s really a moron.” Isn’t it the opposite? I’d thought. Isn’t he putting on a moron act? Don’t people think you’re an idiot because you get this sort of thing backward? But now that we’d come to this juncture, I sort of got where she was coming from. A moron pretending to be clever—yes. That was fair.","html":"Enter the Fighting God. The ultimate being who, long, long before the Laplace War, had ended the Second Great Human-Demon War. I’d never imagined that he’d turn out to be Uncle Badigadi, but thinking about it, it wasn’t out of character. That musclehead was always acting like there was more to him than met the eye. My mother used to say, “Badi puts on a smart guy act but he’s really a moron.” Isn’t it the opposite? I’d thought. Isn’t he putting on a moron act? Don’t people think you’re an idiot because you get this sort of thing backward? But now that we’d come to this juncture, I sort of got where she was coming from. A moron pretending to be clever—yes. That was fair.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0032","sourceIndex":32,"type":"narration","text":"In any case, back to Fighting God Badigadi. If the legends were true, he was the ultimate being, wreaking havoc during the Second Great Human-Demon War and entrenching his position as Number Three of the Seven Great Powers.","html":"In any case, back to Fighting God Badigadi. If the legends were true, he was the ultimate being, wreaking havoc during the Second Great Human-Demon War and entrenching his position as Number Three of the Seven Great Powers. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0033","sourceIndex":33,"type":"narration","text":"Facing him down, I thought, I really never did have what it took to be a hero.","html":"Facing him down, I thought, I really never did have what it took to be a hero.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0034","sourceIndex":34,"type":"narration","text":"You see, no legendary being like him had ever made an appearance in my tale. There’d been challenging ­opponents, of course, and others whose strength had impressed me. I’d held them in esteem. But after I picked up the magic sword, I’d never found another opponent who outclassed me. It wasn’t until I’d set down the sword, my name, and my title, not until I’d given up on being the protagonist of my own story and committed myself to someone else’s fight as a side character, that a ­legendary opponent finally appeared. Maybe Rudeus Greyrat was hero material. He probably wouldn’t like me saying it, but that’s what it’s like for heroes. They encounter the enemies they’re meant to defeat.","html":"You see, no legendary being like him had ever made an appearance in my tale. There’d been challenging ­opponents, of course, and others whose strength had impressed me. I’d held them in esteem. But after I picked up the magic sword, I’d never found another opponent who outclassed me. It wasn’t until I’d set down the sword, my name, and my title, not until I’d given up on being the protagonist of my own story and committed myself to someone else’s fight as a side character, that a ­legendary opponent finally appeared. Maybe Rudeus Greyrat was hero material. He probably wouldn’t like me saying it, but that’s what it’s like for heroes. They encounter the enemies they’re meant to defeat.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0035","sourceIndex":35,"type":"narration","text":"And I encountered ones destined to defeat me.","html":"And I encountered ones destined to defeat me.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0036","sourceIndex":36,"type":"speech","text":"“Things never turn out how you’d like…” I muttered. In my hands now wasn’t a magic sword, but an unremarkable staff. You couldn’t ask for a weapon more unfit for going toe to toe with the Fighting God. It wouldn’t even make a good scene for the heroic epic that would be ­written later.","html":"“Things never turn out how you’d like…” I muttered. In my hands now wasn’t a magic sword, but an unremarkable staff. You couldn’t ask for a weapon more unfit for going toe to toe with the Fighting God. It wouldn’t even make a good scene for the heroic epic that would be ­written later.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0037","sourceIndex":37,"type":"speech","text":"“Fwahahaha! Such is the nature of life and death!”","html":"“Fwahahaha! Such is the nature of life and death!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch01-p0038","sourceIndex":38,"type":"speech","text":"“That doesn’t carry much weight, coming from you.”","html":"“That doesn’t carry much weight, coming from you.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","speakerConfidence":"high"},{"id":"ch01-p0039","sourceIndex":39,"type":"speech","text":"“Fie! Nothing in my life has turned out as I would have liked it!”","html":"“Fie! Nothing in my life has turned out as I would have liked it!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch01-p0040","sourceIndex":40,"type":"speech","text":"“Is that right? Please, do tell me. I’m riveted.” Back when I’d been trying to be a hero, I hadn’t gone in for banter like this. I’d become a side character. Even when their goal is simply to buy time, a legendary warrior strives for it as best they can. Badigadi was the Wise Demon King. Contrary to his appearance, he was very learned, and he liked to impart his knowledge to people. Saying I was interested should be enough to get him talking.","html":"“Is that right? Please, do tell me. I’m riveted.” Back when I’d been trying to be a hero, I hadn’t gone in for banter like this. I’d become a side character. Even when their goal is simply to buy time, a legendary warrior strives for it as best they can. Badigadi was the Wise Demon King. Contrary to his appearance, he was very learned, and he liked to impart his knowledge to people. Saying I was interested should be enough to get him talking.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0041","sourceIndex":41,"type":"narration","text":"Alas, it wasn’t to be. The monkey-faced demon at his side interrupted our conversation.","html":"Alas, it wasn’t to be. The monkey-faced demon at his side interrupted our conversation.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0042","sourceIndex":42,"type":"speech","text":"“We ain’t got that sorta time. C’mon, bud, stomp this guy already and head after the boss.”","html":"“We ain’t got that sorta time. C’mon, bud, stomp this guy already and head after the boss.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","speakerConfidence":"high"},{"id":"ch01-p0043","sourceIndex":43,"type":"narration","text":"I had the feeling I’d seen his face before, but I couldn’t for the life of me remember where. I didn’t sense any threat in the way he held himself. He didn’t seem all that important. In his face, though, I saw extraordinary resolve. That wasn’t so surprising, given he’d accompanied the Fighting God into battle.","html":"I had the feeling I’d seen his face before, but I couldn’t for the life of me remember where. I didn’t sense any threat in the way he held himself. He didn’t seem all that important. In his face, though, I saw extraordinary resolve. That wasn’t so surprising, given he’d accompanied the Fighting God into battle.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0044","sourceIndex":44,"type":"speech","text":"“Fwahahaha! Very well! But this fellow here, he’s a former hero and he’s got an ardent following across the world. You can’t just treat him like riff-raff.”","html":"“Fwahahaha! Very well! But this fellow here, he’s a former hero and he’s got an ardent following across the world. You can’t just treat him like riff-raff.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch01-p0045","sourceIndex":45,"type":"speech","text":"“I know that, jeez. Only I know another thing too, pal. The chances of North God Kalman II beating Fighting God Badigadi in this fight? They’re pretty close to zilch.”","html":"“I know that, jeez. Only I know another thing too, pal. The chances of North God Kalman II beating Fighting God Badigadi in this fight? They’re pretty close to zilch.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","speakerConfidence":"high"},{"id":"ch01-p0046","sourceIndex":46,"type":"speech","text":"“Oho! Zilch, is it?”","html":"“Oho! Zilch, is it?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch01-p0047","sourceIndex":47,"type":"speech","text":"“Look, I know how this goes. The silver-tongued North God’s gonna have you twisted round his little finger if you let him talk.”","html":"“Look, I know how this goes. The silver-tongued North God’s gonna have you twisted round his little finger if you let him talk.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","speakerConfidence":"high"},{"id":"ch01-p0048","sourceIndex":48,"type":"speech","text":"“Fwahahaha! Never in my wildest dreams would be taken in by the likes of Alex!”","html":"“Fwahahaha! Never in my wildest dreams would be taken in by the likes of Alex!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch01-p0049","sourceIndex":49,"type":"speech","text":"“Big talk from a guy what got taken in by the likes of me.”","html":"“Big talk from a guy what got taken in by the likes of me.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","speakerConfidence":"high"},{"id":"ch01-p0050","sourceIndex":50,"type":"speech","text":"“There’s no ‘likes of’ about it. I’d take you and your resolve a thousand times over a wishy-washy good-for-naught who ran around kicking up a fuss about how he was going to be a hero until he ran into a setback, dropped the idea, and settled for a bit part.”","html":"“There’s no ‘likes of’ about it. I’d take you and your resolve a thousand times over a wishy-washy good-for-naught who ran around kicking up a fuss about how he was going to be a hero until he ran into a setback, dropped the idea, and settled for a bit part.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","speakerConfidence":"high"},{"id":"ch01-p0051","sourceIndex":51,"type":"narration","text":"The Fighting God turned back to me. My plan had failed… It hurt a little that Uncle Badi thought of me as a “good-for-naught,” I admit. I liked to think I’d put some consideration into where I was now.","html":"The Fighting God turned back to me. My plan had failed… It hurt a little that Uncle Badi thought of me as a “good-for-naught,” I admit. I liked to think I’d put some consideration into where I was now.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0052","sourceIndex":52,"type":"narration","text":"But more importantly, perhaps this meant that the monkey-faced demon had made a serious effort to woo my uncle. That must be Geese. I’d better watch out for him. He was the man Rudeus Greyrat had been hunting for, after all.","html":"But more importantly, perhaps this meant that the monkey-faced demon had made a serious effort to woo my uncle. That must be Geese. I’d better watch out for him. He was the man Rudeus Greyrat had been hunting for, after all.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0053","sourceIndex":53,"type":"speech","text":"“Fwahaha! Then prepare yourself!” Suddenly, the golden armor lurched toward me with ferocious power. I hadn’t felt such raw might since I faced off against the King Dragon Blade Kajakut—back before I had the magic sword.","html":"“Fwahaha! Then prepare yourself!” Suddenly, the golden armor lurched toward me with ferocious power. I hadn’t felt such raw might since I faced off against the King Dragon Blade Kajakut—back before I had the magic sword. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0054","sourceIndex":54,"type":"narration","text":"This could well be my final fight. I might have been wanting for strength, but life was giving me a worthy rival. It was time to fight and let fate decide who I was.","html":"This could well be my final fight. I might have been wanting for strength, but life was giving me a worthy rival. It was time to fight and let fate decide who I was.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0055","sourceIndex":55,"type":"speech","text":"“Come on then!” I bellowed, facing down Badigadi. “I, Alex Rybak, North God Kalman II, shall be your opponent!”","html":"“Come on then!” I bellowed, facing down Badigadi. “I, Alex Rybak, North God Kalman II, shall be your opponent!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","speakerConfidence":"high"},{"id":"ch01-p0056","sourceIndex":56,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":2876,"speechCount":15,"speakers":["Badigadi","Geese","Sandor"]},{"id":"ch01-s02","pov":"Sandor","povHeader":null,"sceneHeader":null,"location":"The beach at the Third City of Heirelil","cast":["Alex Rybak","Atofe","Badigadi","Cliff","Elinalise","Eris","Geese","Moore","Ogre God Marta","Rudeus","Ruijerd","Sandor"],"blocks":[{"id":"ch01-p0058","sourceIndex":58,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch01-p0059","sourceIndex":59,"type":"narration","text":"Have you ever been chewed up and tossed out again like an old rag in the span of five minutes? And to add insult to injury, ever had it happen when you’ve reached a venerable sort of age and been renowned as a teacher?","html":"Have you ever been chewed up and tossed out again like an old rag in the span of five minutes? And to add insult to injury, ever had it happen when you’ve reached a venerable sort of age and been renowned as a teacher?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0060","sourceIndex":60,"type":"narration","text":"I have. Right now, in fact. Fighting God Badigadi was strong. This was my old uncle who, every now and then, liked to drop cryptic comments with an air of significance about his past and skills; I never thought he would be this tough. The only thing I’d thought when I’d sparred with him in the past was that he might be a demon king, but I assumed he was nothing to my mother. Yet now, in a few blows, he’d snapped my staff in two and beaten me to a pulp. I’d been confident in my skill with both my staff and my fists, but he’d thrashed me as though the skills I’d honed over the past hundred years counted for nothing at all.","html":"I have. Right now, in fact. Fighting God Badigadi was strong. This was my old uncle who, every now and then, liked to drop cryptic comments with an air of significance about his past and skills; I never thought he would be this tough. The only thing I’d thought when I’d sparred with him in the past was that he might be a demon king, but I assumed he was nothing to my mother. Yet now, in a few blows, he’d snapped my staff in two and beaten me to a pulp. I’d been confident in my skill with both my staff and my fists, but he’d thrashed me as though the skills I’d honed over the past hundred years counted for nothing at all.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0061","sourceIndex":61,"type":"narration","text":"This was the power of the Fighting God. At first glance, you might think he’d simply augmented his strength and speed. Exchanging blows with him revealed the unbelievable degree to which the armor had improved his defenses. Badigadi wouldn’t be a force to challenge me with your average boosted armor. I could have taken him down empty-handed, whereas he’d never rival me under similar conditions.","html":"This was the power of the Fighting God. At first glance, you might think he’d simply augmented his strength and speed. Exchanging blows with him revealed the unbelievable degree to which the armor had improved his defenses. Badigadi wouldn’t be a force to challenge me with your average boosted armor. I could have taken him down empty-handed, whereas he’d never rival me under similar conditions.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0062","sourceIndex":62,"type":"narration","text":"Thinking about it, that wasn’t a surprise. Armor exists to protect you, as does defensive technique. Putting on a suit of armor that enhanced your abilities would enhance that too. Add an insurmountable gap in fundamental power and speed on top of that, and your opponent’s in a real fix. It’s like a mouse trying to kill a dragon. The dragon might die from some poison or disease carried by the mouse, but alas, the person inside that armor now was more resistant to such things than anyone alive. Immortal demons don’t die. Poison affects them, and they can fall ill, but neither will lead to death for an ­immortal demon.","html":"Thinking about it, that wasn’t a surprise. Armor exists to protect you, as does defensive technique. Putting on a suit of armor that enhanced your abilities would enhance that too. Add an insurmountable gap in fundamental power and speed on top of that, and your opponent’s in a real fix. It’s like a mouse trying to kill a dragon. The dragon might die from some poison or disease carried by the mouse, but alas, the person inside that armor now was more resistant to such things than anyone alive. Immortal demons don’t die. Poison affects them, and they can fall ill, but neither will lead to death for an ­immortal demon.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0063","sourceIndex":63,"type":"narration","text":"I had no means of doing harm to the Fighting God’s Armor. I was up the creek without a paddle. If I had a magic sword…if I’d had the King Dragon Blade Kajakut, there was so much power wrapped up in that sword that with it, I could have done something.","html":"I had no means of doing harm to the Fighting God’s Armor. I was up the creek without a paddle. If I had a magic sword…if I’d had the King Dragon Blade Kajakut, there was so much power wrapped up in that sword that with it, I could have done something.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0064","sourceIndex":64,"type":"narration","text":"But as I see it, a true hero is one who uses their wits when they aren’t strong enough. Not that I was the sharpest fellow. The blood of the infamous immortal demon king Atoferatofe flowed through my veins, so there was no chance of that. I had moments of ingenuity, but when push came to shove, I went to brute force. It was no wonder I ended up dependent on my magic sword and robbing people of peace.","html":"But as I see it, a true hero is one who uses their wits when they aren’t strong enough. Not that I was the sharpest fellow. The blood of the infamous immortal demon king Atoferatofe flowed through my veins, so there was no chance of that. I had moments of ingenuity, but when push came to shove, I went to brute force. It was no wonder I ended up dependent on my magic sword and robbing people of peace.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0065","sourceIndex":65,"type":"narration","text":"But that wouldn’t pass muster this time. I had to do something…but I was at a loss.","html":"But that wouldn’t pass muster this time. I had to do something…but I was at a loss.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0066","sourceIndex":66,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch01-p0067","sourceIndex":67,"type":"narration","text":"Our Father who art in heaven, grant me wisdom.","html":"Our Father who art in heaven, grant me wisdom.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0068","sourceIndex":68,"type":"speech","text":"“Yaaaargh!” Just then, I heard a familiar, female voice—my mother. There was Immortal Demon King Atoferatofe, standing a little way above the rest of us, and she wasn’t alone. In the distance, I could see the hulking figure of the Ogre God. Somehow, I also sensed that the others were hurrying to the scene.","html":"“Yaaaargh!” Just then, I heard a familiar, female voice—my mother. There was Immortal Demon King Atoferatofe, standing a little way above the rest of us, and she wasn’t alone. In the distance, I could see the hulking figure of the Ogre God. Somehow, I also sensed that the others were hurrying to the scene.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Atofe","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0069","sourceIndex":69,"type":"speech","text":"“Come on, we should fall back and—” I started to say, then stopped. The others were one thing, but my mother wouldn’t be stopped now that she’d heard the enemy was attacking. The Ogre God, who made protecting this area his life’s mission, would join her. If Atofe and the Ogre God started to fight, it’d be a bad look if I didn’t join them. As far as fighting power goes, the three of us were among the greatest alive, if I do say so myself.","html":"“Come on, we should fall back and—” I started to say, then stopped. The others were one thing, but my mother wouldn’t be stopped now that she’d heard the enemy was attacking. The Ogre God, who made protecting this area his life’s mission, would join her. If Atofe and the Ogre God started to fight, it’d be a bad look if I didn’t join them. As far as fighting power goes, the three of us were among the greatest alive, if I do say so myself.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0070","sourceIndex":70,"type":"speech","text":"“Whoa!” Just then, something heavy came crashing down in front of me—a woman. Though…somehow, there was something a bit embarrassing about calling her a woman. Even if it were accurate.","html":"“Whoa!” Just then, something heavy came crashing down in front of me—a woman. Though…somehow, there was something a bit embarrassing about calling her a woman. Even if it were accurate.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0071","sourceIndex":71,"type":"speech","text":"“Mwaaahahahahaha!” It was Mother. Immortal Demon King Atoferatofe had arrived, swooping down with calculated drama.","html":"“Mwaaahahahahaha!” It was Mother. Immortal Demon King Atoferatofe had arrived, swooping down with calculated drama.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Atofe","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0072","sourceIndex":72,"type":"speech","text":"“I’ll back you up,” she said. As a rule, you couldn’t go asking for all the reasons why my mother did what she did. Immortal Demons as a species were all about acting on the spur of the moment, according to their own peculiar rules.","html":"“I’ll back you up,” she said. As a rule, you couldn’t go asking for all the reasons why my mother did what she did. Immortal Demons as a species were all about acting on the spur of the moment, according to their own peculiar rules.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Atofe","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0073","sourceIndex":73,"type":"speech","text":"“Fwahaha! Sister mine, this scoundrel just challenged me to single combat! Would you interfere in a duel between demon king and champion?!”","html":"“Fwahaha! Sister mine, this scoundrel just challenged me to single combat! Would you interfere in a duel between demon king and champion?!” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch01-p0074","sourceIndex":74,"type":"narration","text":"One of those peculiar rules was: Single-combat is to be observed without interference.","html":"One of those peculiar rules was: Single-combat is to be observed without interference.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0075","sourceIndex":75,"type":"speech","text":"“Eh? Is that true?” she demanded.","html":"“Eh? Is that true?” she demanded.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Atofe","speakerConfidence":"high"},{"id":"ch01-p0076","sourceIndex":76,"type":"speech","text":"“What? I never said that it was.”","html":"“What? I never said that it was.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch01-p0077","sourceIndex":77,"type":"narration","text":"Lying through your teeth is another of the skills fostered in North God Style.","html":"Lying through your teeth is another of the skills fostered in North God Style.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0078","sourceIndex":78,"type":"speech","text":"“He says he never said it!”","html":"“He says he never said it!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","speakerConfidence":"high"},{"id":"ch01-p0079","sourceIndex":79,"type":"speech","text":"“Fwahahahaha! You really are a moron, sister mine!”","html":"“Fwahahahaha! You really are a moron, sister mine!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch01-p0080","sourceIndex":80,"type":"speech","text":"“Screw you! I’m no moron!”","html":"“Screw you! I’m no moron!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Atofe","speakerConfidence":"high"},{"id":"ch01-p0081","sourceIndex":81,"type":"narration","text":"Even if this hadn’t been single combat, it wasn’t like my mother to offer backup to anyone. Perhaps to her, the fact that we were fighting a demon king made our side the champion’s party. If that were so, this was unusual. Her demon king role was a point of pride for her, one that she placed a lot of importance on. She’d rarely ever stepped away from that role until now. Maybe acting like Rudeus’s familiar had wrought some change within her. Either that, or she had some history with the Fighting God Armor.","html":"Even if this hadn’t been single combat, it wasn’t like my mother to offer backup to anyone. Perhaps to her, the fact that we were fighting a demon king made our side the champion’s party. If that were so, this was unusual. Her demon king role was a point of pride for her, one that she placed a lot of importance on. She’d rarely ever stepped away from that role until now. Maybe acting like Rudeus’s familiar had wrought some change within her. Either that, or she had some history with the Fighting God Armor.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0082","sourceIndex":82,"type":"speech","text":"“Sandor!”","html":"“Sandor!” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Eris","attributionNote":"Someone in the arriving party calls Sandor's name.","speakerConfidence":"medium"},{"id":"ch01-p0083","sourceIndex":83,"type":"narration","text":"The rest of the team had caught up. There was Master Rudeus and Miss Eris, Master Cliff, and Miss Elinalise, and even Guard Captain Moore. That was heartening. Although it made my heart swell, I had to wonder if it would be enough for a chance at victory…","html":"The rest of the team had caught up. There was Master Rudeus and Miss Eris, Master Cliff, and Miss Elinalise, and even Guard Captain Moore. That was heartening. Although it made my heart swell, I had to wonder if it would be enough for a chance at victory…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0084","sourceIndex":84,"type":"narration","text":"Ah, well. Nothing for it but to try.","html":"Ah, well. Nothing for it but to try.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0085","sourceIndex":85,"type":"speech","text":"“Master Rudeus…”","html":"“Master Rudeus…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","speakerConfidence":"high"},{"id":"ch01-p0086","sourceIndex":86,"type":"speech","text":"“Fall back and get healed up! We’ll hold him here!”","html":"“Fall back and get healed up! We’ll hold him here!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0087","sourceIndex":87,"type":"narration","text":"Oh no, I thought. Rudeus was too focused on what was right in front of him. He was probably thinking that the arch-nemesis he’d been pursuing all this time had shown up out of the blue and looked ready to fight. We’d been caught off guard, but we were rallying. He couldn’t have been more wrong.","html":"Oh no, I thought. Rudeus was too focused on what was right in front of him. He was probably thinking that the arch-nemesis he’d been pursuing all this time had shown up out of the blue and looked ready to fight. We’d been caught off guard, but we were rallying. He couldn’t have been more wrong.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0088","sourceIndex":88,"type":"narration","text":"But he wasn’t going to listen if I recommended we retreat now. Without a plan, if we retreated here we’d be stuck. I didn’t have any idea what an adequate plan might look like.","html":"But he wasn’t going to listen if I recommended we retreat now. Without a plan, if we retreated here we’d be stuck. I didn’t have any idea what an adequate plan might look like.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0089","sourceIndex":89,"type":"narration","text":"Which meant we really did have to do this now.","html":"Which meant we really did have to do this now.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0090","sourceIndex":90,"type":"narration","text":"It wasn’t that it was a bad idea on Master Rudeus’s part, not by any means. I only saw it because of the fight I’d just gone through: With the might we had now, we couldn’t beat Fighting God Badigadi.","html":"It wasn’t that it was a bad idea on Master Rudeus’s part, not by any means. I only saw it because of the fight I’d just gone through: With the might we had now, we couldn’t beat Fighting God Badigadi.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0091","sourceIndex":91,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":1116,"speechCount":14,"speakers":["Atofe","Badigadi","Eris","Geese","Rudeus","Sandor"]},{"id":"ch01-s03","pov":"Sandor","povHeader":null,"sceneHeader":null,"location":"The beach at the Third City of Heirelil","cast":["Alex Rybak","Atofe","Badigadi","Cliff","Elinalise","Eris","Geese","Moore","Ogre God Marta","Rudeus","Ruijerd","Sandor"],"blocks":[{"id":"ch01-p0093","sourceIndex":93,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch01-p0094","sourceIndex":94,"type":"narration","text":"Our battle with Badigadi began with me submerged in the ocean up to my waist. Engaging him at close range were my mother and the Ogre God, as well as Miss Eris and Master Ruijerd. After Master Cliff cast a healing spell on me, I supported them from a distance. Against such a deadly enemy, we needed to keep the full situation in mind.","html":"Our battle with Badigadi began with me submerged in the ocean up to my waist. Engaging him at close range were my mother and the Ogre God, as well as Miss Eris and Master Ruijerd. After Master Cliff cast a healing spell on me, I supported them from a distance. Against such a deadly enemy, we needed to keep the full situation in mind. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0095","sourceIndex":95,"type":"narration","text":"Badigadi took on all four of them with Geese still riding on his shoulder. Even burdened by Geese, Badigadi handled his opponents as though they were toddlers.","html":"Badigadi took on all four of them with Geese still riding on his shoulder. Even burdened by Geese, Badigadi handled his opponents as though they were toddlers.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0096","sourceIndex":96,"type":"speech","text":"“Gyaaaah!” Even at this distance, I could tell Mother was mad. You wouldn’t guess it to look at her, but she was fully initiated in North God Style. Our arts had made great strides in the past few hundred years. On top of that, she was an immortal demon king. After however many thousands of years raining terror down upon humans, her power was uncontested. Just her name was enough to make any demon king who knew her of old tremble.","html":"“Gyaaaah!” Even at this distance, I could tell Mother was mad. You wouldn’t guess it to look at her, but she was fully initiated in North God Style. Our arts had made great strides in the past few hundred years. On top of that, she was an immortal demon king. After however many thousands of years raining terror down upon humans, her power was uncontested. Just her name was enough to make any demon king who knew her of old tremble.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Atofe","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0097","sourceIndex":97,"type":"narration","text":"Yet she was powerless against Badigadi, as were the other three. Miss Eris’s sword moved too fast for the eye to see, but she couldn’t cut through Badigadi. Master Ruijerd’s dead-on hits were all parried.","html":"Yet she was powerless against Badigadi, as were the other three. Miss Eris’s sword moved too fast for the eye to see, but she couldn’t cut through Badigadi. Master Ruijerd’s dead-on hits were all parried.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0098","sourceIndex":98,"type":"narration","text":"Badigadi dominated.","html":"Badigadi dominated.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0099","sourceIndex":99,"type":"narration","text":"Atofe’s personal guard encircled him at a distance, flinging magic at him. Ice arrows, flame arrows, and stone cannons all rained down on Badigadi—but it was as though every move was snuffed out right before it made contact. The guards’ spells didn’t reach Geese. Was that the Fighting God Armor’s power, or was Geese using a Magic Item? Probably the latter. I didn’t know much about Geese, but I was sure he’d done his homework where Master Rudeus was concerned. The Man-God was involved here, so it was best to assume that he had a plan worked out for how to counter us. In other words, our first priority was to take down Geese. Unfortunately, you only had to look at how badly Mother was struggling to know that getting close to him would be no easy task.","html":"Atofe’s personal guard encircled him at a distance, flinging magic at him. Ice arrows, flame arrows, and stone cannons all rained down on Badigadi—but it was as though every move was snuffed out right before it made contact. The guards’ spells didn’t reach Geese. Was that the Fighting God Armor’s power, or was Geese using a Magic Item? Probably the latter. I didn’t know much about Geese, but I was sure he’d done his homework where Master Rudeus was concerned. The Man-God was involved here, so it was best to assume that he had a plan worked out for how to counter us. In other words, our first priority was to take down Geese. Unfortunately, you only had to look at how badly Mother was struggling to know that getting close to him would be no easy task.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0100","sourceIndex":100,"type":"speech","text":"“I’ll hit him with magic first!” Rudeus called. “Back me up!” After watching the battle for a while, Master Rudeus seemed to have made up his mind. Despite coming across as a bit of a coward, when the moment of crisis came, he wasn’t running.","html":"“I’ll hit him with magic first!” Rudeus called. “Back me up!” After watching the battle for a while, Master Rudeus seemed to have made up his mind. Despite coming across as a bit of a coward, when the moment of crisis came, he wasn’t running.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0101","sourceIndex":101,"type":"narration","text":"He inhaled. I sensed the magic gathering in his hands. For a moment, I hesitated, unsure whether he might catch Mother and the Ogre God in whatever he was going to do. His target…well, who else would it be? It was Geese. He’d reached the same conclusion I had. With his magic, it should’ve been simple to directly attack an opponent he had a clear line of sight on.","html":"He inhaled. I sensed the magic gathering in his hands. For a moment, I hesitated, unsure whether he might catch Mother and the Ogre God in whatever he was going to do. His target…well, who else would it be? It was Geese. He’d reached the same conclusion I had. With his magic, it should’ve been simple to directly attack an opponent he had a clear line of sight on.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0102","sourceIndex":102,"type":"narration","text":"What sort of magic was he planning on using? The spells he favored were Stone Cannon, Quagmire, and Deep Mist… But the Stone Cannons the guards were firing were being vaporized.","html":"What sort of magic was he planning on using? The spells he favored were Stone Cannon, Quagmire, and Deep Mist… But the Stone Cannons the guards were firing were being vaporized.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0103","sourceIndex":103,"type":"speech","text":"“All right.” Master Rudeus raised his hand above his head, and a sudden gust of wind bellowed. The air crackled with unbridled magic. I looked up at the sky and saw at once that black clouds had closed over the dark sky. They were growing. Rain began to fall around us. In the distance, a roll of thunder. The wind howled, stirring up waves on the ocean. This had to be the Saint-tier water spell, Cumulonimbus…except that spell was solely for use against enemy armies. Even if it did work on the Fighting God, it would also do terrible damage to our allies. The ocean swelled before my eyes. As the waves started to grow larger, Mother and the others looked like they were struggling a little. Only a little, mind you.","html":"“All right.” Master Rudeus raised his hand above his head, and a sudden gust of wind bellowed. The air crackled with unbridled magic. I looked up at the sky and saw at once that black clouds had closed over the dark sky. They were growing. Rain began to fall around us. In the distance, a roll of thunder. The wind howled, stirring up waves on the ocean. This had to be the Saint-tier water spell, Cumulonimbus…except that spell was solely for use against enemy armies. Even if it did work on the Fighting God, it would also do terrible damage to our allies. The ocean swelled before my eyes. As the waves started to grow larger, Mother and the others looked like they were struggling a little. Only a little, mind you.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0104","sourceIndex":104,"type":"narration","text":"Master Rudeus must’ve intended to strike just beyond them with the King-tier water spell, Lighting. Usually, you’d compress Cumulonimbus before it was complete and bring it down as lighting. This time, the clouds went on expanding. Tornadoes spun up around them and the fierce winds and rain lashed at my face. With my poor understanding of magic, I wouldn’t have seen it, but I knew offensive strategy, and so I understood: a special technique. Master Rudeus was about to use a special technique.","html":"Master Rudeus must’ve intended to strike just beyond them with the King-tier water spell, Lighting. Usually, you’d compress Cumulonimbus before it was complete and bring it down as lighting. This time, the clouds went on expanding. Tornadoes spun up around them and the fierce winds and rain lashed at my face. With my poor understanding of magic, I wouldn’t have seen it, but I knew offensive strategy, and so I understood: a special technique. Master Rudeus was about to use a special technique.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0105","sourceIndex":105,"type":"narration","text":"The waves grew higher, and the shockwaves from the three who continued to fight sent up plumes of water. Clouds filled the entirety of the sky. It was dark and I couldn’t even see fifty meters in front of me due to the rain. Even then, while I wouldn’t have lost sight of my opponent, I wouldn’t be surprised if these fighters had lost sight of Rudeus. He, by contrast, was aided by the Eye of Distant Sight.","html":"The waves grew higher, and the shockwaves from the three who continued to fight sent up plumes of water. Clouds filled the entirety of the sky. It was dark and I couldn’t even see fifty meters in front of me due to the rain. Even then, while I wouldn’t have lost sight of my opponent, I wouldn’t be surprised if these fighters had lost sight of Rudeus. He, by contrast, was aided by the Eye of Distant Sight.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0106","sourceIndex":106,"type":"narration","text":"The demon eye would no doubt be fixed as usual on the three fighters. Demon King Badigadi neutralized the power of demonic eyes, so he, and Geese up there on his shoulder, would be nigh impossible to make out. But Master Rudeus had to be able to see Atofe and the Ogre God, and so know where to aim.","html":"The demon eye would no doubt be fixed as usual on the three fighters. Demon King Badigadi neutralized the power of demonic eyes, so he, and Geese up there on his shoulder, would be nigh impossible to make out. But Master Rudeus had to be able to see Atofe and the Ogre God, and so know where to aim.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0107","sourceIndex":107,"type":"narration","text":"Master Rudeus’s raised hand closed in a fist. An accumulation of magic, so enormous I felt my hair stand on end, rose into the heavens. Just like that, the clouds contracted. Those clouds that had seemed as though they might cover the whole world vanished in an instant.","html":"Master Rudeus’s raised hand closed in a fist. An accumulation of magic, so enormous I felt my hair stand on end, rose into the heavens. Just like that, the clouds contracted. Those clouds that had seemed as though they might cover the whole world vanished in an instant.","className":"P_Prose_Formatting__And__Page_Break","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0108","sourceIndex":108,"type":"narration","text":"I could see the moon.","html":"I could see the moon.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0109","sourceIndex":109,"type":"thought","text":"He was waiting for his moment. I didn’t say anything. Not, “Now!” Or, “On my word!” or anything else. Why? Because Master Rudeus knew what he was doing. He wouldn’t miss his mark.","html":"He was waiting for his moment. I didn’t say anything. Not, “Now!” Or, “On my word!” or anything else. Why? Because Master Rudeus knew what he was doing. He wouldn’t miss his mark.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","attributionNote":"Inner narration; 'Now!' and 'On my word!' were never said.","speakerConfidence":"high"},{"id":"ch01-p0110","sourceIndex":110,"type":"narration","text":"Mother and the Ogre God both attacked at once, and Badigadi threw both of them back. For a split second, there was distance between them and the Fighting God.","html":"Mother and the Ogre God both attacked at once, and Badigadi threw both of them back. For a split second, there was distance between them and the Fighting God. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0111","sourceIndex":111,"type":"narration","text":"That was the moment. Rudeus swung his arm down.","html":"That was the moment. Rudeus swung his arm down.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0112","sourceIndex":112,"type":"speech","text":"“Lightning.”","html":"“Lightning.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0113","sourceIndex":113,"type":"narration","text":"It was like no Lightning I’d ever seen before. The spell Lightning compresses thunderclouds to bring down a bolt of lightning. But what came shooting down now wasn’t lightning. It was a pillar of light. The moment it materialized, all sound around us was blotted out. For a moment, the rain stopped, and the world was engulfed in still, frigid brightness.","html":"It was like no Lightning I’d ever seen before. The spell Lightning compresses thunderclouds to bring down a bolt of lightning. But what came shooting down now wasn’t lightning. It was a pillar of light. The moment it materialized, all sound around us was blotted out. For a moment, the rain stopped, and the world was engulfed in still, frigid brightness.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0114","sourceIndex":114,"type":"narration","text":"Beneath the pillar of light, a vast tower of water rose. Then came a thunderous rumble, akin to the thunder after ordinary lightning, battering my eardrums.","html":"Beneath the pillar of light, a vast tower of water rose. Then came a thunderous rumble, akin to the thunder after ordinary lightning, battering my eardrums.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0115","sourceIndex":115,"type":"speech","text":"“…and…to…of earth…”","html":"“…and…to…of earth…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Cliff","speakerConfidence":"high"},{"id":"ch01-p0116","sourceIndex":116,"type":"narration","text":"Through the roar, I heard snatches of Master Cliff’s incantation. In response, Master Rudeus began to prepare another spell.","html":"Through the roar, I heard snatches of Master Cliff’s incantation. In response, Master Rudeus began to prepare another spell. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0117","sourceIndex":117,"type":"narration","text":"A mass of water rushing toward me obscured my ­vision. The impact of his Lightning spell had raised a tidal wave on an Apocalyptic scale. Before my eyes, the water rushed closer, sweeping up everything in its path—","html":"A mass of water rushing toward me obscured my ­vision. The impact of his Lightning spell had raised a tidal wave on an Apocalyptic scale. Before my eyes, the water rushed closer, sweeping up everything in its path—","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0118","sourceIndex":118,"type":"speech","text":"“Sand Swarm.” It collided with the mass of sand, and the two slammed into one another, each canceling the other out. Through the combination of Master Rudeus and Master Cliff’s magic, the water dissipated into brown rain, muddying the waters of the ocean and the beach. I watched the rain fall, then turned back to the Fighting God.","html":"“Sand Swarm.” It collided with the mass of sand, and the two slammed into one another, each canceling the other out. Through the combination of Master Rudeus and Master Cliff’s magic, the water dissipated into brown rain, muddying the waters of the ocean and the beach. I watched the rain fall, then turned back to the Fighting God.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Cliff","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0119","sourceIndex":119,"type":"narration","text":"I strained my eyes, trying to locate a trace of gold.","html":"I strained my eyes, trying to locate a trace of gold.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0120","sourceIndex":120,"type":"narration","text":"I found nothing. I couldn’t make out any trace of him.","html":"I found nothing. I couldn’t make out any trace of him.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0121","sourceIndex":121,"type":"speech","text":"“Did I get him?” Master Rudeus murmured, perhaps not realizing he’d said it out loud.","html":"“Did I get him?” Master Rudeus murmured, perhaps not realizing he’d said it out loud.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0122","sourceIndex":122,"type":"narration","text":"Not that saying it could rob us of a victory, but it was still an unlucky phrase. I knew from experience. If you’re muttering, “Did I get him?” you didn’t.","html":"Not that saying it could rob us of a victory, but it was still an unlucky phrase. I knew from experience. If you’re muttering, “Did I get him?” you didn’t.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0123","sourceIndex":123,"type":"narration","text":"I twitched, sensing something above me. I looked up. Miss Eris and Master Ruijerd seemed to have sensed it too. A split second later, a pillar of sand materialized. Something was coming down out of the sky. Even drenched in the muddy rain, it sparkled.","html":"I twitched, sensing something above me. I looked up. Miss Eris and Master Ruijerd seemed to have sensed it too. A split second later, a pillar of sand materialized. Something was coming down out of the sky. Even drenched in the muddy rain, it sparkled.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0124","sourceIndex":124,"type":"narration","text":"Gold.","html":"Gold.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0125","sourceIndex":125,"type":"speech","text":"“Ugh.” I heard Master Rudeus groan.","html":"“Ugh.” I heard Master Rudeus groan.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0126","sourceIndex":126,"type":"narration","text":"It hit the ground right in front of him. Even in the Magic Armor, the golden armor was twice his size. Was what lay beneath that helmet really the face I knew?","html":"It hit the ground right in front of him. Even in the Magic Armor, the golden armor was twice his size. Was what lay beneath that helmet really the face I knew?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0127","sourceIndex":127,"type":"speech","text":"“Thought I was a goner,” came a voice from the armor’s shoulder. Its source was the mud-drenched, monkey-faced demon, Geese Nukadia.","html":"“Thought I was a goner,” came a voice from the armor’s shoulder. Its source was the mud-drenched, monkey-faced demon, Geese Nukadia. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0128","sourceIndex":128,"type":"narration","text":"Then, the armor spoke. “I am Fighting God Badigadi! Friend to the Man-God, heir to the name of Fighting God! I challenge Rudeus Greyrat to single combat!”","html":"Then, the armor spoke. “I am Fighting God Badigadi! Friend to the Man-God, heir to the name of Fighting God! I challenge Rudeus Greyrat to single combat!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","embeddedDialogue":true,"attributionNote":"Narration with the Fighting God's challenge.","speakerConfidence":"high"},{"id":"ch01-p0129","sourceIndex":129,"type":"speech","text":"“N-no thank you!”","html":"“N-no thank you!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0130","sourceIndex":130,"type":"speech","text":"“Fwahahaha! You’re wasting your breath!”","html":"“Fwahahaha! You’re wasting your breath!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch01-p0131","sourceIndex":131,"type":"narration","text":"There was no time to stop him. The golden armor’s punch hit Rudeus straight on. One hit was all it took. One hit and the Magic Armor fell apart. Rudeus was thrown into the sky, falling back to the ground with a thud.","html":"There was no time to stop him. The golden armor’s punch hit Rudeus straight on. One hit was all it took. One hit and the Magic Armor fell apart. Rudeus was thrown into the sky, falling back to the ground with a thud.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0132","sourceIndex":132,"type":"speech","text":"“Rudeus!” Miss Eris’s cry echoed around us.","html":"“Rudeus!” Miss Eris’s cry echoed around us.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Eris","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0133","sourceIndex":133,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":1430,"speechCount":12,"speakers":["Atofe","Badigadi","Cliff","Eris","Geese","Rudeus"]},{"id":"ch01-s04","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The beach at the Third City of Heirelil, then the Superd Village","cast":["Alex Rybak","Atofe","Badigadi","Cliff","Elinalise","Eris","Geese","Moore","Ogre God Marta","Orsted","Rudeus","Ruijerd","Sandor","Superd Warrior"],"blocks":[{"id":"ch01-p0135","sourceIndex":135,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch01-p0136","sourceIndex":136,"type":"narration","text":"Have you ever seen someone mauled, then tossed out like an old rag?","html":"Have you ever seen someone mauled, then tossed out like an old rag?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0137","sourceIndex":137,"type":"narration","text":"I have. I’ve seen it more times than I can count, and I’ve done it to people with my own hands. I wasn’t on the giving side of it this time. Just now, the majestic Magic Armor had been torn into scrap metal, Rudeus tumbling from it like a ragdoll. He was face down at first, so I couldn’t see it, but he was at least ragged enough to make the scrappy regulars at your tavern laugh and say, “Looking handsome, boy!”","html":"I have. I’ve seen it more times than I can count, and I’ve done it to people with my own hands. I wasn’t on the giving side of it this time. Just now, the majestic Magic Armor had been torn into scrap metal, Rudeus tumbling from it like a ragdoll. He was face down at first, so I couldn’t see it, but he was at least ragged enough to make the scrappy regulars at your tavern laugh and say, “Looking handsome, boy!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0138","sourceIndex":138,"type":"narration","text":"Over the following ten seconds, the rest of our side fell to pieces.","html":"Over the following ten seconds, the rest of our side fell to pieces.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0139","sourceIndex":139,"type":"narration","text":"Mother exploded. The attack left only her legs behind, and now she had to regenerate. Of course, she’d be back and cackling before too long. The Ogre God was beaten black and blue, and his arm was broken. Ogres are hard to kill, but going off the amount of blood coming out of his mouth, if he didn’t get a healing spell soon, he was going to die. With Rudeus down too, morale plummeted. Miss Eris ran to Rudeus’s side, calling out to him as she held her sword at the ready. Master Ruijerd wasn’t such a coward that he’d give up the fight just because his commander went down, but he was visibly shaken. Master Cliff had lost his nerve and Miss Elinalise’s shield was shattered, forcing her withdrawal. Moore would fight on to the death for my mother, but without her, it looked like he’d decided to retreat.","html":"Mother exploded. The attack left only her legs behind, and now she had to regenerate. Of course, she’d be back and cackling before too long. The Ogre God was beaten black and blue, and his arm was broken. Ogres are hard to kill, but going off the amount of blood coming out of his mouth, if he didn’t get a healing spell soon, he was going to die. With Rudeus down too, morale plummeted. Miss Eris ran to Rudeus’s side, calling out to him as she held her sword at the ready. Master Ruijerd wasn’t such a coward that he’d give up the fight just because his commander went down, but he was visibly shaken. Master Cliff had lost his nerve and Miss Elinalise’s shield was shattered, forcing her withdrawal. Moore would fight on to the death for my mother, but without her, it looked like he’d decided to retreat.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0140","sourceIndex":140,"type":"narration","text":"The time had come.","html":"The time had come.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0141","sourceIndex":141,"type":"narration","text":"I reached down and picked up my mother’s fallen sword, the sword of Demon King Atoferatofe. One of the forty-eight magic swords crafted by the great demon swordsmith Julian Harisco. This was the magic sword Jawbreaker. That gruff old mule of a smith had made an offering of it to my mother in his father’s honor. Apparently, she’d shown a rare display of gravitas when she accepted it, and from that day forth, she’d kept it on her person at all times. She’d never let anyone else wield it.","html":"I reached down and picked up my mother’s fallen sword, the sword of Demon King Atoferatofe. One of the forty-eight magic swords crafted by the great demon swordsmith Julian Harisco. This was the magic sword Jawbreaker. That gruff old mule of a smith had made an offering of it to my mother in his father’s honor. Apparently, she’d shown a rare display of gravitas when she accepted it, and from that day forth, she’d kept it on her person at all times. She’d never let anyone else wield it.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0142","sourceIndex":142,"type":"narration","text":"Well. With this, I could let loose a little.","html":"Well. With this, I could let loose a little.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0143","sourceIndex":143,"type":"speech","text":"“Master Ruijerd! Master Moore!” The two of them glanced my way for just a second. They didn’t have their full attention to spare, but they were listening. “I’ll make an opening for you! Fall back!”","html":"“Master Ruijerd! Master Moore!” The two of them glanced my way for just a second. They didn’t have their full attention to spare, but they were listening. “I’ll make an opening for you! Fall back!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0144","sourceIndex":144,"type":"narration","text":"All heroic epics come to an end. Fairy tales closed on a great finale after vanquishing an evil demon king, but reality wasn’t so generous. Almost always, the end is quite tedious. You challenged an enemy greater than yourself, or you fell for someone’s plot, or else you were challenged by a new hero. You lost. You died. That’s how it was for my father, North God Kalman. No matter how incredible a hero might be, no matter how strong, so long as they engage in war, defeat and death are sure to catch up with them eventually. A hero, after all, is heroic. Even when they know the hero dies in the end, people light up at his glorious exploits. The heroes’ way imprints itself onto their hearts.","html":"All heroic epics come to an end. Fairy tales closed on a great finale after vanquishing an evil demon king, but reality wasn’t so generous. Almost always, the end is quite tedious. You challenged an enemy greater than yourself, or you fell for someone’s plot, or else you were challenged by a new hero. You lost. You died. That’s how it was for my father, North God Kalman. No matter how incredible a hero might be, no matter how strong, so long as they engage in war, defeat and death are sure to catch up with them eventually. A hero, after all, is heroic. Even when they know the hero dies in the end, people light up at his glorious exploits. The heroes’ way imprints itself onto their hearts. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0145","sourceIndex":145,"type":"narration","text":"My death here wouldn’t be written down anywhere, though… Just like my father, North God Kalman. The death he went to was never written down.","html":"My death here wouldn’t be written down anywhere, though… Just like my father, North God Kalman. The death he went to was never written down. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0146","sourceIndex":146,"type":"narration","text":"Well, I looked up to my father. Why not go the same way? I’d go up against an enemy I had no hope of defeating and go down in a blaze of glory. It wasn’t the death I’d pictured for myself… But hell, whose death is?","html":"Well, I looked up to my father. Why not go the same way? I’d go up against an enemy I had no hope of defeating and go down in a blaze of glory. It wasn’t the death I’d pictured for myself… But hell, whose death is?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0147","sourceIndex":147,"type":"speech","text":"“In my left hand, a sword.”","html":"“In my left hand, a sword.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","speakerConfidence":"high"},{"id":"ch01-p0148","sourceIndex":148,"type":"narration","text":"Been a while since I said this out loud. Hope I don’t choke or stammer…","html":"Been a while since I said this out loud. Hope I don’t choke or stammer…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0149","sourceIndex":149,"type":"speech","text":"“In my right hand, a sword.” I gripped the hilt with both hands. Power bubbled up from the pit of my stomach, flowing out to fill my body. I set my sights on the raging golden armor.","html":"“In my right hand, a sword.” I gripped the hilt with both hands. Power bubbled up from the pit of my stomach, flowing out to fill my body. I set my sights on the raging golden armor.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0150","sourceIndex":150,"type":"speech","text":"“With these, mine arms, countless lives shall I claim, and a hundred million deaths I deliver!”","html":"“With these, mine arms, countless lives shall I claim, and a hundred million deaths I deliver!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","speakerConfidence":"high"},{"id":"ch01-p0151","sourceIndex":151,"type":"narration","text":"The words I’d said countless times in my life when the crucial moment came. I’d told myself that once I’d spoken those words, defeat was out of the question. I hadn’t spoken them once since I gave up being a hero. Even after all this time, as I went to meet defeat, I was surprised at how they flowed off my tongue.","html":"The words I’d said countless times in my life when the crucial moment came. I’d told myself that once I’d spoken those words, defeat was out of the question. I hadn’t spoken them once since I gave up being a hero. Even after all this time, as I went to meet defeat, I was surprised at how they flowed off my tongue.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0152","sourceIndex":152,"type":"speech","text":"“I am North God Alex Rybak. Prepare yourself!”","html":"“I am North God Alex Rybak. Prepare yourself!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","speakerConfidence":"high"},{"id":"ch01-p0153","sourceIndex":153,"type":"narration","text":"This would be my final battle, so I’d make it count.","html":"This would be my final battle, so I’d make it count.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0154","sourceIndex":154,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch01-p0156","sourceIndex":156,"type":"narration","text":"Rudeus","html":"<strong> Rudeus </strong>","className":"P_TEXTBODY_CENTERALIGN","italic":false,"bold":true,"dropCap":false},{"id":"ch01-p0157","sourceIndex":157,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch01-p0158","sourceIndex":158,"type":"narration","text":"WHEN I CAME TO, I smelled something good. It was a little sweaty, but pleasant and familiar. In the corner of my eye, I saw rippling red hair, just as I felt a warmth on my cheek. Something was pressed against it.","html":"WHEN I CAME TO, I smelled something good. It was a little sweaty, but pleasant and familiar. In the corner of my eye, I saw rippling red hair, just as I felt a warmth on my cheek. Something was pressed against it.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0159","sourceIndex":159,"type":"speech","text":"“Are you awake?!” Whatever was touching my cheek spoke. That was Eris’s voice. Awareness rushed back. Eris was carrying me on her back.","html":"“Are you awake?!” Whatever was touching my cheek spoke. That was Eris’s voice. Awareness rushed back. Eris was carrying me on her back.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Eris","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0160","sourceIndex":160,"type":"speech","text":"“What’s going on?” Jerking upright, I looked about. A few others, looking like refugees, were walking with us. Cliff, Elinalise, and Ruijerd.","html":"“What’s going on?” Jerking upright, I looked about. A few others, looking like refugees, were walking with us. Cliff, Elinalise, and Ruijerd.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0161","sourceIndex":161,"type":"speech","text":"“We lost,” Eris said curtly. She sounded bitter.","html":"“We lost,” Eris said curtly. She sounded bitter. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Eris","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0162","sourceIndex":162,"type":"narration","text":"They’d gone in again against the Fighting God only to be beaten to a pulp. Eris had blacked out after one hit, and Elinalise’s shield was shattered. Atofe and the Ogre God had put up a valiant fight, but the Fighting God had thrown them off again and again. Because I was down for the count, Moore had ordered our retreat. Ruijerd retrieved Eris and me. With Atofe, her personal guard, the Ogre God, and Sandor covering our retreat, we’d gotten away.","html":"They’d gone in again against the Fighting God only to be beaten to a pulp. Eris had blacked out after one hit, and Elinalise’s shield was shattered. Atofe and the Ogre God had put up a valiant fight, but the Fighting God had thrown them off again and again. Because I was down for the count, Moore had ordered our retreat. Ruijerd retrieved Eris and me. With Atofe, her personal guard, the Ogre God, and Sandor covering our retreat, we’d gotten away.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0163","sourceIndex":163,"type":"speech","text":"“Right.” I was reeling. We’d lost, just like that. I didn’t think of myself as the toughest guy around or anything like that. The first time I took the Version One out against Orsted, I’d lost then too. I knew I wasn’t invincible. Still, my confidence had been bolstered by a run of recent victories. I’d beaten Atofe and Alec. I hadn’t beaten Alec alone, but a win was a win. I’d still always tried to consider the possibility I might lose. This was my first one-punch knockout. This was the first time I’d been blown to smithereens and knocked out cold in a single hit.","html":"“Right.” I was reeling. We’d lost, just like that. I didn’t think of myself as the toughest guy around or anything like that. The first time I took the Version One out against Orsted, I’d lost then too. I knew I wasn’t invincible. Still, my confidence had been bolstered by a run of recent victories. I’d beaten Atofe and Alec. I hadn’t beaten Alec alone, but a win was a win. I’d still always tried to consider the possibility I might lose. This was my first one-punch knockout. This was the first time I’d been blown to smithereens and knocked out cold in a single hit.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0164","sourceIndex":164,"type":"narration","text":"Had I underestimated Badigadi? Had I thought, Fighting God or not, the demon king would still pull his punches?","html":"Had I underestimated Badigadi? Had I thought, Fighting God or not, the demon king would still pull his punches?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0165","sourceIndex":165,"type":"speech","text":"“What’s our next move?” Eris asked.","html":"“What’s our next move?” Eris asked.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Eris","speakerConfidence":"high"},{"id":"ch01-p0166","sourceIndex":166,"type":"narration","text":"I thought about it. Next…what should we do? I wouldn’t have said we were all out of options, but there was no way any smart-ass plan I came up with would beat the Fighting God. I didn’t have much faith in our firepower. A glance around told me Sandor, the Ogre God, Atofe, and her personal guard weren’t with us. They could be dead. That left me, Eris, Ruijerd, Cliff, Elinalise…and the Superd warriors, if they counted. I definitely didn’t count as reliable firepower; without the Magic Armor, I was more of a ­liability. All I could do was make a river, or a mountain, or set the mountain on fire. You know, like in that folktale, The Three Lucky Charms. After drinking up the river, leaping over the mountain, and putting out the fire with the river water, the Fighting God would come chasing after me, just like the witch in that story. We couldn’t win with our current lineup.","html":"I thought about it. Next…what should we do? I wouldn’t have said we were all out of options, but there was no way any smart-ass plan I came up with would beat the Fighting God. I didn’t have much faith in our firepower. A glance around told me Sandor, the Ogre God, Atofe, and her personal guard weren’t with us. They could be dead. That left me, Eris, Ruijerd, Cliff, Elinalise…and the Superd warriors, if they counted. I definitely didn’t count as reliable firepower; without the Magic Armor, I was more of a ­liability. All I could do was make a river, or a mountain, or set the mountain on fire. You know, like in that folktale, The Three Lucky Charms. After drinking up the river, leaping over the mountain, and putting out the fire with the river water, the Fighting God would come chasing after me, just like the witch in that story. We couldn’t win with our current lineup.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0167","sourceIndex":167,"type":"speech","text":"“We have no choice but to flee,” Ruijerd said, looking me in the eye.","html":"“We have no choice but to flee,” Ruijerd said, looking me in the eye.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","speakerConfidence":"high"},{"id":"ch01-p0168","sourceIndex":168,"type":"speech","text":"“Ruijerd…”","html":"“Ruijerd…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0169","sourceIndex":169,"type":"speech","text":"“He’s one of the Seven Great Powers. The real thing. We can’t win against him even with all our strength combined.”","html":"“He’s one of the Seven Great Powers. The real thing. We can’t win against him even with all our strength combined.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","speakerConfidence":"high"},{"id":"ch01-p0170","sourceIndex":170,"type":"narration","text":"So we’d run away. We’d run back to the Superd village, then…and then what? In The Three Lucky Charms, the boy ran to a temple, where the priest used his wiles to beat the witch. We did have Priest Orsted back in the Superd Village. And yet… The Fighting God and Geese wanted to kill me and use up Orsted’s power. If Orsted fought the Fighting God, he’d have to expend mana on an order of magnitude greater than he would have in a fight with the likes of the North God and the Sword God. No question, if that happened, we’d lose the war. And those two would chase us to the ends of the world to achieve their goal. There was nowhere we could go and be safe.","html":"So we’d run away. We’d run back to the Superd village, then…and then what? In The Three Lucky Charms, the boy ran to a temple, where the priest used his wiles to beat the witch. We did have Priest Orsted back in the Superd Village. And yet… The Fighting God and Geese wanted to kill me and use up Orsted’s power. If Orsted fought the Fighting God, he’d have to expend mana on an order of magnitude greater than he would have in a fight with the likes of the North God and the Sword God. No question, if that happened, we’d lose the war. And those two would chase us to the ends of the world to achieve their goal. There was nowhere we could go and be safe.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0171","sourceIndex":171,"type":"speech","text":"“Even if we run, we can’t win,” I said.","html":"“Even if we run, we can’t win,” I said.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0172","sourceIndex":172,"type":"speech","text":"“Then all we can hope for is to fight and die with honor,” Ruijerd said.","html":"“Then all we can hope for is to fight and die with honor,” Ruijerd said.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","speakerConfidence":"high"},{"id":"ch01-p0173","sourceIndex":173,"type":"narration","text":"When you fought and died with honor and lost, you still lost. You didn’t get to call that a win. When you die, that’s it.","html":"When you fought and died with honor and lost, you still lost. You didn’t get to call that a win. When you die, that’s it.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0174","sourceIndex":174,"type":"speech","text":"“Rudeus, pull yourself together.” Eris’s hand squeezed mine. Her grip was warm and firm. She’d saved me more times than I could remember with those hands. She’d held our child with those hands.","html":"“Rudeus, pull yourself together.” Eris’s hand squeezed mine. Her grip was warm and firm. She’d saved me more times than I could remember with those hands. She’d held our child with those hands.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Eris","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0175","sourceIndex":175,"type":"speech","text":"“Right.” Calm down and think, Rudy. How can we win?","html":"“Right.” Calm down and think, Rudy. How can we win?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0176","sourceIndex":176,"type":"narration","text":"We needed information before anything else. If the Fighting God Armor had a weak point, for example, that’d do nicely. Unfortunately, as the story told it, that armor was the strongest in existence, crafted by Laplace himself. He’d gone down trying to beat his own creation! Finding a weak point probably wasn’t happening. Even if it didn’t have any, though, there were still other strategies, ways to fight it. I might be able to find something about that. Now, who knew about the armor? Atofe…wasn’t here. Which left Orsted. I’d have to ask him. If it turned out he didn’t know anything…","html":"We needed information before anything else. If the Fighting God Armor had a weak point, for example, that’d do nicely. Unfortunately, as the story told it, that armor was the strongest in existence, crafted by Laplace himself. He’d gone down trying to beat his own creation! Finding a weak point probably wasn’t happening. Even if it didn’t have any, though, there were still other strategies, ways to fight it. I might be able to find something about that. Now, who knew about the armor? Atofe…wasn’t here. Which left Orsted. I’d have to ask him. If it turned out he didn’t know anything…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0177","sourceIndex":177,"type":"narration","text":"I pondered in silence for a moment. Whether Orsted knew anything or not, I’d still have to fight this enemy, here and now. We’d lost Atofe, the Ogre God, and Sandor. There had to be a way to win.","html":"I pondered in silence for a moment. Whether Orsted knew anything or not, I’d still have to fight this enemy, here and now. We’d lost Atofe, the Ogre God, and Sandor. There had to be a way to win. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0178","sourceIndex":178,"type":"narration","text":"That said, I wanted to keep our casualties to a minimum. I didn’t want the Superd Village to get caught in the crossfire. Norn was there, too. I couldn’t let her fight.","html":"That said, I wanted to keep our casualties to a minimum. I didn’t want the Superd Village to get caught in the crossfire. Norn was there, too. I couldn’t let her fight. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0179","sourceIndex":179,"type":"narration","text":"There had to be a chance. There had to be. Even if it was only a fraction of a percent.","html":"There had to be a chance. There had to be. Even if it was only a fraction of a percent.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0180","sourceIndex":180,"type":"narration","text":"Then it came to me. That’s it!","html":"Then it came to me. That’s it!","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0181","sourceIndex":181,"type":"narration","text":"I still had one trump card in my hand, didn’t I? I had figured I’d use it much earlier.","html":"I still had one trump card in my hand, didn’t I? I had figured I’d use it much earlier.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0182","sourceIndex":182,"type":"speech","text":"At last, I said, “We’ll fall back to the forest to buy some time.”","html":"At last, I said, “We’ll fall back to the forest to buy some time.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0183","sourceIndex":183,"type":"narration","text":"I was going to stake everything on this.","html":"I was going to stake everything on this.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0184","sourceIndex":184,"type":"speech","text":"“Got it.” The others all nodded.","html":"“Got it.” The others all nodded.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0185","sourceIndex":185,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch01-p0186","sourceIndex":186,"type":"narration","text":"***","html":"***","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0187","sourceIndex":187,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch01-p0188","sourceIndex":188,"type":"narration","text":"We made our way back to the Superd Village. My trump card still hadn’t shown up. All things going to plan, I would’ve expected it to be here already… But maybe something had gone wrong.","html":"We made our way back to the Superd Village. My trump card still hadn’t shown up. All things going to plan, I would’ve expected it to be here already… But maybe something had gone wrong. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0189","sourceIndex":189,"type":"narration","text":"We didn’t have time to wait around for it. What to do…?","html":"We didn’t have time to wait around for it. What to do…?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0190","sourceIndex":190,"type":"narration","text":"Pushing aside my worries, I knelt in front of Orsted to report on what had happened up until yesterday.","html":"Pushing aside my worries, I knelt in front of Orsted to report on what had happened up until yesterday.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0191","sourceIndex":191,"type":"speech","text":"“That brings us up to speed,” I finished. “The Ogre God, Atofe, and Sandor are all missing.”","html":"“That brings us up to speed,” I finished. “The Ogre God, Atofe, and Sandor are all missing.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0192","sourceIndex":192,"type":"speech","text":"Orsted face was stormy. “Fighting God Badigadi, you say.”","html":"Orsted face was stormy. “Fighting God Badigadi, you say.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0193","sourceIndex":193,"type":"speech","text":"“Is there any strategy to beat him?”","html":"“Is there any strategy to beat him?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0194","sourceIndex":194,"type":"speech","text":"“No,” Orsted said at length. “The Fighting God Armor I know, but I have never fought Badigadi wearing it.”","html":"“No,” Orsted said at length. “The Fighting God Armor I know, but I have never fought Badigadi wearing it.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0195","sourceIndex":195,"type":"speech","text":"“Oh. I see.” It was the answer I’d expected, but I still couldn’t help but be disappointed—not that I’d let Orsted see that. “Then would you tell me what you know about the Fighting God Armor?”","html":"“Oh. I see.” It was the answer I’d expected, but I still couldn’t help but be disappointed—not that I’d let Orsted see that. “Then would you tell me what you know about the Fighting God Armor?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0196","sourceIndex":196,"type":"speech","text":"“It is the strongest armor ever created, forged by Laplace. It was buried in the depths of the Devil’s Cave in the middle of the Ringus Sea. The mana that radiates from its surface makes it glow gold, and it makes the wearer unstoppably powerful. Because of that abundance of mana, however, it possesses a mind of its own. It will possess anyone who wears it.”","html":"“It is the strongest armor ever created, forged by Laplace. It was buried in the depths of the Devil’s Cave in the middle of the Ringus Sea. The mana that radiates from its surface makes it glow gold, and it makes the wearer unstoppably powerful. Because of that abundance of mana, however, it possesses a mind of its own. It will possess anyone who wears it.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch01-p0197","sourceIndex":197,"type":"speech","text":"“Badigadi didn’t seem like he’d been possessed…” He’d looked like he was acting of his own free will, anyway. He acted exactly as I remembered. Of course, maybe he just appeared that way, and the armor was actually in control. He hadn’t given Atofe or Sandor the time of day, after all.","html":"“Badigadi didn’t seem like he’d been possessed…” He’d looked like he was acting of his own free will, anyway. He acted exactly as I remembered. Of course, maybe he just appeared that way, and the armor was actually in control. He hadn’t given Atofe or Sandor the time of day, after all. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0198","sourceIndex":198,"type":"speech","text":"“It takes time,” Orsted said slowly, “for the armor to possess the wearer. The longer they wear it, the stronger the armor’s hold on their mind becomes, until they cease to be able to tell right from wrong, craving nothing but to do battle. Although, Badigadi has an unusual immunity to the powers of the demon eyes, so it is possible that the armor will be unable to possess him.”","html":"“It takes time,” Orsted said slowly, “for the armor to possess the wearer. The longer they wear it, the stronger the armor’s hold on their mind becomes, until they cease to be able to tell right from wrong, craving nothing but to do battle. Although, Badigadi has an unusual immunity to the powers of the demon eyes, so it is possible that the armor will be unable to possess him.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0199","sourceIndex":199,"type":"narration","text":"Aha. Badigadi hadn’t been wearing the armor for all that long yet, then. I also had the feeling I’d heard of that kind of possession somewhere before…","html":"Aha. Badigadi hadn’t been wearing the armor for all that long yet, then. I also had the feeling I’d heard of that kind of possession somewhere before…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0200","sourceIndex":200,"type":"speech","text":"“Like your Magic Armor, the Fighting God Armor uses the mana of the wearer as fuel. Unlike yours, however, the wearer cannot take it off until the last of their life force has been exhausted. In Badigadi’s case, I expect it will keep operating almost indefinitely. The moment the wearer puts it on, it transforms to fit them—they can also generate their preferred weapon. The range is limited to that weapon’s typical range, but I doubt Badigadi will have chosen a long-range weapon. The golden light emitted from the surface of the armor neutralizes most magic…although it does have a threshold. If you hit it with the strongest Stone Cannon you can cast, it might get through.”","html":"“Like your Magic Armor, the Fighting God Armor uses the mana of the wearer as fuel. Unlike yours, however, the wearer cannot take it off until the last of their life force has been exhausted. In Badigadi’s case, I expect it will keep operating almost indefinitely. The moment the wearer puts it on, it transforms to fit them—they can also generate their preferred weapon. The range is limited to that weapon’s typical range, but I doubt Badigadi will have chosen a long-range weapon. The golden light emitted from the surface of the armor neutralizes most magic…although it does have a threshold. If you hit it with the strongest Stone Cannon you can cast, it might get through.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch01-p0201","sourceIndex":201,"type":"narration","text":"Orsted knew a lot. And he was being talkative for a change.","html":"Orsted knew a lot. And he was being talkative for a change.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0202","sourceIndex":202,"type":"narration","text":"Right, okay. So Stone Cannon would have been a more effective choice than Lightning. I’d messed that up, though I didn’t know that at the time.","html":"Right, okay. So Stone Cannon would have been a more effective choice than Lightning. I’d messed that up, though I didn’t know that at the time. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0203","sourceIndex":203,"type":"speech","text":"“Who was wearing it last time you fought it?” I asked.","html":"“Who was wearing it last time you fought it?” I asked.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0204","sourceIndex":204,"type":"speech","text":"“One of the Sea Merfolk. They ran out of mana and died quickly.”","html":"“One of the Sea Merfolk. They ran out of mana and died quickly.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch01-p0205","sourceIndex":205,"type":"speech","text":"“Were there any others?”","html":"“Were there any others?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0206","sourceIndex":206,"type":"speech","text":"“I have donned it myself several times. I have also seen one human wear it, and one demon.”","html":"“I have donned it myself several times. I have also seen one human wear it, and one demon.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch01-p0207","sourceIndex":207,"type":"narration","text":"Wow. I guess if he hadn’t tried it, he wouldn’t know all those details.","html":"Wow. I guess if he hadn’t tried it, he wouldn’t know all those details.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0208","sourceIndex":208,"type":"speech","text":"“Okay, so to get specific, how do I beat it?”","html":"“Okay, so to get specific, how do I beat it?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0209","sourceIndex":209,"type":"speech","text":"Orsted was silent for a moment, then said, “I do not know.”","html":"Orsted was silent for a moment, then said, “I do not know.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0210","sourceIndex":210,"type":"speech","text":"“You don’t?”","html":"“You don’t?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0211","sourceIndex":211,"type":"speech","text":"“When you wear the Fighting God Armor, you feel neither weariness nor pain. You are always fighting at your full potential. However, you are only ever moving it under your own physical power, and it has no ability to heal the wearer if they are wounded. Thus, if you have a way to damage it, a battle of attrition may prove effective. However…”","html":"“When you wear the Fighting God Armor, you feel neither weariness nor pain. You are always fighting at your full potential. However, you are only ever moving it under your own physical power, and it has no ability to heal the wearer if they are wounded. Thus, if you have a way to damage it, a battle of attrition may prove effective. However…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch01-p0212","sourceIndex":212,"type":"narration","text":"However, that was impossible against Badigadi. The Fighting God Armor kept going until the wearer died. And Badigadi was immortal. We had a perpetual motion machine on our hands.","html":"However, that was impossible against Badigadi. The Fighting God Armor kept going until the wearer died. And Badigadi was immortal. We had a perpetual motion machine on our hands.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0213","sourceIndex":213,"type":"speech","text":"“How did Laplace defeat it?”","html":"“How did Laplace defeat it?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0214","sourceIndex":214,"type":"speech","text":"“He hit it with an enormous output of magic that overshot its threshold, temporarily annihilating the wearer and separating them from the armor. It created a great rift in the continent that became the Ringus Sea.”","html":"“He hit it with an enormous output of magic that overshot its threshold, temporarily annihilating the wearer and separating them from the armor. It created a great rift in the continent that became the Ringus Sea.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch01-p0215","sourceIndex":215,"type":"speech","text":"“Oh.” So it was possible to do damage to it with a strong-enough attack. Badigadi would just regenerate afterward, instead of dying, but that did give me one idea…","html":"“Oh.” So it was possible to do damage to it with a strong-enough attack. Badigadi would just regenerate afterward, instead of dying, but that did give me one idea…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0216","sourceIndex":216,"type":"speech","text":"“I heard the wearer back then died,” Orsted remarked. “I imagine it must have been Badigadi all along.”","html":"“I heard the wearer back then died,” Orsted remarked. “I imagine it must have been Badigadi all along.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0217","sourceIndex":217,"type":"speech","text":"“You didn’t know?”","html":"“You didn’t know?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0218","sourceIndex":218,"type":"speech","text":"“They say even Laplace didn’t know who wore the armor during that battle. I heard they’d died and had no interest in finding out more. The Fighting God has never challenged me as an enemy like this before.”","html":"“They say even Laplace didn’t know who wore the armor during that battle. I heard they’d died and had no interest in finding out more. The Fighting God has never challenged me as an enemy like this before.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch01-p0219","sourceIndex":219,"type":"speech","text":"“Did you…did you hear that from Laplace himself, in a past loop?”","html":"“Did you…did you hear that from Laplace himself, in a past loop?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0220","sourceIndex":220,"type":"speech","text":"“Yes. That, and that I am the son of the first Dragon God, and that first Dragon God was the one to lay this curse upon me.”","html":"“Yes. That, and that I am the son of the first Dragon God, and that first Dragon God was the one to lay this curse upon me.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch01-p0221","sourceIndex":221,"type":"speech","text":"“And yet you have to kill Laplace.”","html":"“And yet you have to kill Laplace.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0222","sourceIndex":222,"type":"speech","text":"“Correct. To reach the Man-God, I must kill the five Dragon Generals and retrieve the sacred treasures.”","html":"“Correct. To reach the Man-God, I must kill the five Dragon Generals and retrieve the sacred treasures.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch01-p0223","sourceIndex":223,"type":"narration","text":"I fell silent. This had to be the first time I’d heard him say it flat out: he had to kill the Dragon Generals. So that was the deal. We couldn’t count on Perugius to send reinforcements, then. I wouldn’t want to ask for aid from someone I planned to stab in the back later. Continuing this line of question now wasn’t going to do me any good.","html":"I fell silent. This had to be the first time I’d heard him say it flat out: he had to kill the Dragon Generals. So that was the deal. We couldn’t count on Perugius to send reinforcements, then. I wouldn’t want to ask for aid from someone I planned to stab in the back later. Continuing this line of question now wasn’t going to do me any good.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0224","sourceIndex":224,"type":"speech","text":"“That’s an unpleasant subject for you, I expect,” Orsted said.","html":"“That’s an unpleasant subject for you, I expect,” Orsted said. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch01-p0225","sourceIndex":225,"type":"speech","text":"“Um, well…”","html":"“Um, well…” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0226","sourceIndex":226,"type":"narration","text":"Focus on what’s in front of us. First up: Badigadi.","html":"Focus on what’s in front of us. First up: Badigadi. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0227","sourceIndex":227,"type":"narration","text":"The Man-God acted based on what he saw in his own future. A free-spirited and rambunctious pawn like Badigadi would be tricky for him to control. Maybe this unpredictability was the Man-God’s true trump card, though? I’d just seen the Man-God for the first time in a long time, and he looked pretty haggard, like he was stuck in a tough spot. Fighting God Badigadi… If Badigadi had been the Man-God’s disciple all along, I didn’t know why the Man-God hadn’t made use of him in any previous loops. Let’s assume that this time, we’d dragged it out of him. If it didn’t happen in a previous loop, then odds were that the Man-God was reacting directly to me.","html":"The Man-God acted based on what he saw in his own future. A free-spirited and rambunctious pawn like Badigadi would be tricky for him to control. Maybe this unpredictability was the Man-God’s true trump card, though? I’d just seen the Man-God for the first time in a long time, and he looked pretty haggard, like he was stuck in a tough spot. Fighting God Badigadi… If Badigadi had been the Man-God’s disciple all along, I didn’t know why the Man-God hadn’t made use of him in any previous loops. Let’s assume that this time, we’d dragged it out of him. If it didn’t happen in a previous loop, then odds were that the Man-God was reacting directly to me.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0228","sourceIndex":228,"type":"speech","text":"“What are you going to do?”","html":"“What are you going to do?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0229","sourceIndex":229,"type":"speech","text":"“I’ll fight. There’s nowhere to run.”","html":"“I’ll fight. There’s nowhere to run.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0230","sourceIndex":230,"type":"speech","text":"“Very well. I shall join you. I have never fought this particular battle before, but I surely cannot lose,” Orsted said, then stood up. I moved to discourage him.","html":"“Very well. I shall join you. I have never fought this particular battle before, but I surely cannot lose,” Orsted said, then stood up. I moved to discourage him.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0231","sourceIndex":231,"type":"speech","text":"“Please, not so fast.”","html":"“Please, not so fast.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0232","sourceIndex":232,"type":"narration","text":"Orsted sat back down. I couldn’t see his face behind the helmet, but I knew he looked indignant.","html":"Orsted sat back down. I couldn’t see his face behind the helmet, but I knew he looked indignant. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0233","sourceIndex":233,"type":"speech","text":"“Sir Orsted, if you use up your mana, we might as well have lost. We’ll have wasted all the good progress we’ve made.”","html":"“Sir Orsted, if you use up your mana, we might as well have lost. We’ll have wasted all the good progress we’ve made.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0234","sourceIndex":234,"type":"speech","text":"“We also lose if you die here. A waste of good progress, as you say.”","html":"“We also lose if you die here. A waste of good progress, as you say.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch01-p0235","sourceIndex":235,"type":"speech","text":"“True…”","html":"“True…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch01-p0236","sourceIndex":236,"type":"narration","text":"Should we seize the day today, or tomorrow? We’d fought our way this far. I at least wanted to stick it out until it really seemed like all was lost.","html":"Should we seize the day today, or tomorrow? We’d fought our way this far. I at least wanted to stick it out until it really seemed like all was lost.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0237","sourceIndex":237,"type":"speech","text":"“Even if you do have to fight, I can at least soften the Fighting God up for you first,” I suggested.","html":"“Even if you do have to fight, I can at least soften the Fighting God up for you first,” I suggested.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0238","sourceIndex":238,"type":"speech","text":"“You’ll die.”","html":"“You’ll die.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch01-p0239","sourceIndex":239,"type":"speech","text":"“Then take care of my family for me.” I didn’t want to die. I wanted to live and go home. But this, I was sure, was where everything came to a head. The Fighting God was Geese and the Man-God’s final play. The Man-God might have something else up his sleeve, but we’d taken down the Abyssal King, the North God, and the Ogre God. His final disciple was out in the open. All his down cards were flipped. It’d have to hurt if we took the Fighting God out too. I had to stick it out, fight, and win.","html":"“Then take care of my family for me.” I didn’t want to die. I wanted to live and go home. But this, I was sure, was where everything came to a head. The Fighting God was Geese and the Man-God’s final play. The Man-God might have something else up his sleeve, but we’d taken down the Abyssal King, the North God, and the Ogre God. His final disciple was out in the open. All his down cards were flipped. It’d have to hurt if we took the Fighting God out too. I had to stick it out, fight, and win.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0240","sourceIndex":240,"type":"speech","text":"“Very well. But when you see you cannot win, you must not hesitate before retreating. Am I clear?”","html":"“Very well. But when you see you cannot win, you must not hesitate before retreating. Am I clear?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch01-p0241","sourceIndex":241,"type":"speech","text":"“Thank you.” I bowed, then stood up. “Also…any word from Roxy?”","html":"“Thank you.” I bowed, then stood up. “Also…any word from Roxy?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch01-p0242","sourceIndex":242,"type":"speech","text":"“Not yet.”","html":"“Not yet.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch01-p0243","sourceIndex":243,"type":"speech","text":"“All right. If you hear anything, please let me know. Right away.”","html":"“All right. If you hear anything, please let me know. Right away.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0244","sourceIndex":244,"type":"narration","text":"Orsted nodded, then I left the house.","html":"Orsted nodded, then I left the house.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0245","sourceIndex":245,"type":"narration","text":"Outside, the warriors were waiting for me: Eris, her eyes sharp and aura savage. Ruijerd, with his air of serenity. Cliff, a little worked up, nervous, and with fear in his eyes. Elinalise, watching Cliff with a protective look. Dohga, who’d heard that Sandor had fallen and seemed ready to cry. Zanoba, who was dressed in the Superd’s traditional garments after losing everything he had on him in the last battle. And finally, the Superd warriors, here to protect their village.","html":"Outside, the warriors were waiting for me: Eris, her eyes sharp and aura savage. Ruijerd, with his air of serenity. Cliff, a little worked up, nervous, and with fear in his eyes. Elinalise, watching Cliff with a protective look. Dohga, who’d heard that Sandor had fallen and seemed ready to cry. Zanoba, who was dressed in the Superd’s traditional garments after losing everything he had on him in the last battle. And finally, the Superd warriors, here to protect their village.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0246","sourceIndex":246,"type":"narration","text":"This was our lineup, and to be honest, it didn’t fill me with confidence. The gap left by Sandor, Atofe, and the Ogre God was massive. They were all on par with the Seven Great Powers, a class—even two classes—above our current members.","html":"This was our lineup, and to be honest, it didn’t fill me with confidence. The gap left by Sandor, Atofe, and the Ogre God was massive. They were all on par with the Seven Great Powers, a class—even two classes—above our current members.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0247","sourceIndex":247,"type":"narration","text":"Still, Dohga and Zanoba were a good substitute for the Ogre God, and they were still here. Badigadi favored close combat. Not a bad match up…except for how they had lost to the Ogre God, too. We were well-matched in power if you considered each of us individually and together—theoretically—but I wasn’t sure how much that would matter. Not all our cards are losers, that’s what it meant: no more, no less. Still, we might be able to hold the Fighting God off for a day or two. The chances of my trump card making it back before our bodies gave out weren’t good. Even if it did arrive, it was no guarantee of victory. I might just end up killing my allies for no reason.","html":"Still, Dohga and Zanoba were a good substitute for the Ogre God, and they were still here. Badigadi favored close combat. Not a bad match up…except for how they had lost to the Ogre God, too. We were well-matched in power if you considered each of us individually and together—theoretically—but I wasn’t sure how much that would matter. Not all our cards are losers, that’s what it meant: no more, no less. Still, we might be able to hold the Fighting God off for a day or two. The chances of my trump card making it back before our bodies gave out weren’t good. Even if it did arrive, it was no guarantee of victory. I might just end up killing my allies for no reason.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0248","sourceIndex":248,"type":"speech","text":"“Let’s go.”","html":"“Let’s go.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch01-p0249","sourceIndex":249,"type":"narration","text":"Even so, this was it. I had a plan, but the odds were all against me. I had no proof I’d read things correctly. I might have just enough time to set a trap, but we wouldn’t win against this opponent with parlor tricks.","html":"Even so, this was it. I had a plan, but the odds were all against me. I had no proof I’d read things correctly. I might have just enough time to set a trap, but we wouldn’t win against this opponent with parlor tricks.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch01-p0250","sourceIndex":250,"type":"narration","text":"No one said anything else. They just followed me. We were going into battle with the Fighting God.","html":"No one said anything else. They just followed me. We were going into battle with the Fighting God.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false}],"wordCount":3446,"speechCount":63,"speakers":["Eris","Orsted","Rudeus","Ruijerd","Sandor"]}],"images":[{"id":"ch01-img01","type":"image","src":"INTERIORIMAGES_01.jpg","alt":""}],"sequence":1,"cast":["Alex Rybak","Atofe","Badigadi","Cliff","Elinalise","Eris","Geese","Moore","Ogre God Marta","Orsted","Rudeus","Ruijerd","Sandor","Superd Warrior"],"sceneCount":4,"speechCount":104,"speakers":["Atofe","Badigadi","Cliff","Eris","Geese","Orsted","Rudeus","Ruijerd","Sandor"]},{"id":"ch02","number":2,"title":"The Trump Card","pov":"Rudeus","kind":"main","wordCount":6643,"scenes":[{"id":"ch02-s01","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The beach at the Third City of Heirelil, the day after the defeat","cast":["Atofe","Badigadi","Cliff","Eris","Geese","Ogre God Marta","Rudeus","Ruijerd","Sandor","Superd Warrior"],"blocks":[{"id":"ch02-p0002","sourceIndex":2,"type":"narration","text":"IT TOOK A FULL DAY for the Fighting God to appear. We had Atofe and the others to thank for that; they’d held him back. But they hadn’t come back. I doubted an immortal demon could die that easily, but Atofe must have taken enough damage to prevent her from pursuing the Fighting God. All the same, thanks to their sacrifice, we were fully prepared.","html":"IT TOOK A FULL DAY for the Fighting God to appear. We had Atofe and the others to thank for that; they’d held him back. But they hadn’t come back. I doubted an immortal demon could die that easily, but Atofe must have taken enough damage to prevent her from pursuing the Fighting God. All the same, thanks to their sacrifice, we were fully prepared. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0003","sourceIndex":3,"type":"narration","text":"The Fighting God came directly. He didn’t try to hide or to rush. He just strolled on in, Geese on his shoulder, as if to declare nothing could stop him.","html":"The Fighting God came directly. He didn’t try to hide or to rush. He just strolled on in, Geese on his shoulder, as if to declare nothing could stop him.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0004","sourceIndex":4,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":95,"speechCount":0,"speakers":[]},{"id":"ch02-s02","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The great earth wall at the entrance to the forest","cast":["Badigadi","Cliff","Geese","Rudeus","Superd Warrior"],"blocks":[{"id":"ch02-p0006","sourceIndex":6,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch02-p0007","sourceIndex":7,"type":"narration","text":"We commenced hostilities near the entrance to the forest. I stood on top of a towering wall, about ten meters high and two kilometers long, that I’d built to protect the forest. From up there, I rained magic down on what lay below—Stone Cannons, specifically. I wanted to at least knock Geese down, so I fired off as many shots as I could. The Eye of Distant Sight didn’t work against Badigadi. Orsted said even he didn’t know why, but it was probably safe to assume Badigadi was a Blessed Child with that power, or else that he’d done something in the past that had given him resistance to Demon Eyes.","html":"We commenced hostilities near the entrance to the forest. I stood on top of a towering wall, about ten meters high and two kilometers long, that I’d built to protect the forest. From up there, I rained magic down on what lay below—Stone Cannons, specifically. I wanted to at least knock Geese down, so I fired off as many shots as I could. The Eye of Distant Sight didn’t work against Badigadi. Orsted said even he didn’t know why, but it was probably safe to assume Badigadi was a Blessed Child with that power, or else that he’d done something in the past that had given him resistance to Demon Eyes.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0008","sourceIndex":8,"type":"narration","text":"He was far away, but you couldn’t miss the gold, and I’d been practicing Stone Cannon ever since I was born into this world. My hits were landing. For every ten shots I fired, one hit. Only, even at this distance, I could tell they weren’t doing much damage. When I got a direct hit, a hole opened in the gold armor, but it repaired itself straight away. I wasn’t piercing it, and I wasn’t slowing him down. The Fighting God walked towards us without even bothering to defend himself. My firepower must have been weakened by the distance. I had no choice but to hit him at point-blank range if I wanted to really get to him.","html":"He was far away, but you couldn’t miss the gold, and I’d been practicing Stone Cannon ever since I was born into this world. My hits were landing. For every ten shots I fired, one hit. Only, even at this distance, I could tell they weren’t doing much damage. When I got a direct hit, a hole opened in the gold armor, but it repaired itself straight away. I wasn’t piercing it, and I wasn’t slowing him down. The Fighting God walked towards us without even bothering to defend himself. My firepower must have been weakened by the distance. I had no choice but to hit him at point-blank range if I wanted to really get to him. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0009","sourceIndex":9,"type":"narration","text":"Oh, and I got one hit on Geese. It was hard to tell from this far away, but at the moment of impact he’d fallen off Badigadi’s shoulder. Seemed conclusive. Although, right after that he got back up like nothing had happened, so I’d apparently done almost no damage. He did move to stand behind Badigadi rather than get back up on his shoulder, like I’d woken him up, at least. A hit at closer range might have done enough damage to insta-kill him, but given I hadn’t taken him out with the lightning, it seemed safe to assume that Geese had given himself some sort of magical resistance.","html":"Oh, and I got one hit on Geese. It was hard to tell from this far away, but at the moment of impact he’d fallen off Badigadi’s shoulder. Seemed conclusive. Although, right after that he got back up like nothing had happened, so I’d apparently done almost no damage. He did move to stand behind Badigadi rather than get back up on his shoulder, like I’d woken him up, at least. A hit at closer range might have done enough damage to insta-kill him, but given I hadn’t taken him out with the lightning, it seemed safe to assume that Geese had given himself some sort of magical resistance.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0010","sourceIndex":10,"type":"narration","text":"In the end, I couldn’t manage anything close to slowing them down. Once the Fighting God got close enough, I used fire magic to burn the outer wall, then retreated into the forest. I wasn’t about to get any closer than I had to.","html":"In the end, I couldn’t manage anything close to slowing them down. Once the Fighting God got close enough, I used fire magic to burn the outer wall, then retreated into the forest. I wasn’t about to get any closer than I had to. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0011","sourceIndex":11,"type":"speech","text":"As I confirmed that the wall had been destroyed, I said to myself, “All according to plan. We’ve got this. We’ll be okay…”","html":"As I confirmed that the wall had been destroyed, I said to myself, “All according to plan. We’ve got this. We’ll be okay…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch02-p0012","sourceIndex":12,"type":"narration","text":"Yup. I knew this is how things would go. There was no way this’d be enough to stop them.","html":"Yup. I knew this is how things would go. There was no way this’d be enough to stop them.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0013","sourceIndex":13,"type":"narration","text":"When the Fighting God entered the trees, I cast a wide-area Deep Mist to cover the entire forest, then I added a Quagmire of the same size. Reconnaissance and guerrilla tactics I’d leave to Ruijerd and the Superd warriors. My Demon Eyes didn’t work, but Ruijerd and the other Superd’s eyes were definitely trained on the Fighting God.","html":"When the Fighting God entered the trees, I cast a wide-area Deep Mist to cover the entire forest, then I added a Quagmire of the same size. Reconnaissance and guerrilla tactics I’d leave to Ruijerd and the Superd warriors. My Demon Eyes didn’t work, but Ruijerd and the other Superd’s eyes were definitely trained on the Fighting God. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0014","sourceIndex":14,"type":"narration","text":"It worked. A report came that thanks to the Superd’s tactics combined with the Deep Mist, the Fighting God had become lost and spent several hours stumbling around in the fog. Hoping that he’d get so lost he ended up back at the edge of the forest again, I continued to cast Dense Mist and Quagmire over the whole area.","html":"It worked. A report came that thanks to the Superd’s tactics combined with the Deep Mist, the Fighting God had become lost and spent several hours stumbling around in the fog. Hoping that he’d get so lost he ended up back at the edge of the forest again, I continued to cast Dense Mist and Quagmire over the whole area.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0015","sourceIndex":15,"type":"narration","text":"Then, after a few hours, Ruijerd came with a ­report. “The Fighting God has settled on his direction of advance.” He was heading straight for the Ravine of the Earthwyrm. I bet that was Geese. Badigadi alone would’ve been one thing, but Geese seemed like the sort to know how to find his way in a forest under Dense Mist. I questioned whether pure know-how would be enough to actually do it, but it wasn’t hard to imagine he’d used some sort of magical implement or magic item. Although if he’d had a magic implement, they wouldn’t have wandered for hours in the first place. He probably took time and used old-school methods to determine their position and direction. Geese could probably manage that.","html":"Then, after a few hours, Ruijerd came with a ­report. “The Fighting God has settled on his direction of advance.” He was heading straight for the Ravine of the Earthwyrm. I bet that was Geese. Badigadi alone would’ve been one thing, but Geese seemed like the sort to know how to find his way in a forest under Dense Mist. I questioned whether pure know-how would be enough to actually do it, but it wasn’t hard to imagine he’d used some sort of magical implement or magic item. Although if he’d had a magic implement, they wouldn’t have wandered for hours in the first place. He probably took time and used old-school methods to determine their position and direction. Geese could probably manage that.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0016","sourceIndex":16,"type":"narration","text":"So with Deep Mist, Quagmire, and the Superd’s guerilla tactics, we’d managed to slow them down for a measly three hours. Three of our fighters were dead. The Fighting God had taken out the Superd warriors who had gotten too close to him, but their deaths weren’t in vain. They’d stopped him long enough for the sun to set. When that happened, the Fighting God stopped moving. He wasn’t solar-powered or anything, but he ceased ­activity at night even so.","html":"So with Deep Mist, Quagmire, and the Superd’s guerilla tactics, we’d managed to slow them down for a measly three hours. Three of our fighters were dead. The Fighting God had taken out the Superd warriors who had gotten too close to him, but their deaths weren’t in vain. They’d stopped him long enough for the sun to set. When that happened, the Fighting God stopped moving. He wasn’t solar-powered or anything, but he ceased ­activity at night even so.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0017","sourceIndex":17,"type":"narration","text":"Not me, though. I didn’t let up with Dense Mist or Quagmire, and the Superd never paused their campaign. I carried out long-range attacks with Blast Cannon. I wasn’t hoping to do any damage. The point was not to let them sleep, not to let them rest. It might not have much effect on Badigadi, but it would affect Geese.","html":"Not me, though. I didn’t let up with Dense Mist or Quagmire, and the Superd never paused their campaign. I carried out long-range attacks with Blast Cannon. I wasn’t hoping to do any damage. The point was not to let them sleep, not to let them rest. It might not have much effect on Badigadi, but it would affect Geese.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0018","sourceIndex":18,"type":"narration","text":"The first day ended.","html":"The first day ended.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0019","sourceIndex":19,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":810,"speechCount":1,"speakers":["Rudeus"]},{"id":"ch02-s03","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The barricade wall above the Ravine of the Earthwyrm","cast":["Badigadi","Cliff","Dohga","Elinalise","Eris","Geese","Rudeus","Ruijerd","Superd Warrior","Zanoba"],"blocks":[{"id":"ch02-p0021","sourceIndex":21,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch02-p0022","sourceIndex":22,"type":"narration","text":"On the second day, we carried on like we had on the first afternoon. We made the most of the full day to lure the Fighting God toward the Ravine of the Earthwyrm.","html":"On the second day, we carried on like we had on the first afternoon. We made the most of the full day to lure the Fighting God toward the Ravine of the Earthwyrm.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0023","sourceIndex":23,"type":"narration","text":"The third day dawned. I stood atop the barricading wall I’d built at the edge of the cliff on the other side of the ravine, keeping a close watch on the shadowy forest. Right beside me stood Ruijerd, also staring hard at the forest. The Ravine of the Earthwyrm was extremely well-suited to defense—it was almost a kilometer deep and, though I hadn’t realized the first time I’d crossed it, the cliff on the side of the Superd Village was slightly elevated. As a rule, the side with the high ground had an advantage in a fight. Height gave better visibility, and climbing took more energy than descending. Thanks, gravity. With that in mind, I’d used earth magic to build a barricade wall at the edge of the cliff on the Superd Village side. It was almost twenty meters tall, shorter than the one at the edge of the forest. Seeing as this was the only point that the ravine narrowed, that wasn’t a problem. I had made a hole in that defense when I’d made a bridge as a way in, but that hole had been filled when I brought the bridge down with me. With this, we wouldn’t have to deal with another episode like with the Ogre God, where we suddenly found ourselves fighting at close quarters after he cleared the gap with a running jump.","html":"The third day dawned. I stood atop the barricading wall I’d built at the edge of the cliff on the other side of the ravine, keeping a close watch on the shadowy forest. Right beside me stood Ruijerd, also staring hard at the forest. The Ravine of the Earthwyrm was extremely well-suited to defense—it was almost a kilometer deep and, though I hadn’t realized the first time I’d crossed it, the cliff on the side of the Superd Village was slightly elevated. As a rule, the side with the high ground had an advantage in a fight. Height gave better visibility, and climbing took more energy than descending. Thanks, gravity. With that in mind, I’d used earth magic to build a barricade wall at the edge of the cliff on the Superd Village side. It was almost twenty meters tall, shorter than the one at the edge of the forest. Seeing as this was the only point that the ravine narrowed, that wasn’t a problem. I had made a hole in that defense when I’d made a bridge as a way in, but that hole had been filled when I brought the bridge down with me. With this, we wouldn’t have to deal with another episode like with the Ogre God, where we suddenly found ourselves fighting at close quarters after he cleared the gap with a running jump.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0024","sourceIndex":24,"type":"narration","text":"Probably.","html":"Probably.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0025","sourceIndex":25,"type":"narration","text":"Not to underestimate the Fighting God’s powers, but this wall was the tallest and strongest I could make it in the short time I had. If he could still jump over it, we might as well just give up. Assuming he couldn’t, if he clung onto the cliff face, I could blast him with Stone Cannons from above. In this battle, I’d learned that even if he could neutralize magic, that didn’t extend to neutralizing changes in the landscape. The first battle had shown me that Stone Cannon was plenty effective. And Geese, well, he didn’t have any strength. If I hit him with a Stone Cannon while he clung to the cliff face, he’d fall to the bottom of the ravine. Even if knocking him off that way failed, I might be able to make him slip off by dropping a massive volume of water on him. Geese was a tricky guy, but he was useless in a head-on brawl.","html":"Not to underestimate the Fighting God’s powers, but this wall was the tallest and strongest I could make it in the short time I had. If he could still jump over it, we might as well just give up. Assuming he couldn’t, if he clung onto the cliff face, I could blast him with Stone Cannons from above. In this battle, I’d learned that even if he could neutralize magic, that didn’t extend to neutralizing changes in the landscape. The first battle had shown me that Stone Cannon was plenty effective. And Geese, well, he didn’t have any strength. If I hit him with a Stone Cannon while he clung to the cliff face, he’d fall to the bottom of the ravine. Even if knocking him off that way failed, I might be able to make him slip off by dropping a massive volume of water on him. Geese was a tricky guy, but he was useless in a head-on brawl. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0026","sourceIndex":26,"type":"narration","text":"Badi seemed like he’d have some tricks up his sleeve, though, and Geese was cunning. They were a perfect match. Risky as it was to lead them to the narrow point in the ravine, it was still better than having them cross without our noticing and then blindsiding us. I stood with Cliff, Ruijerd, and the Superd warriors above the ravine. The other Superd were positioned at regular intervals along the stretches not covered by the wall so that we’d be alerted right away if Badigadi crossed there. Eris stood by, directly behind the wall. Once Geese and Badigadi broke through, it’d be all-out war. We’d bought ourselves some time. What should have been a day’s journey, traveling in a straight line, had taken three. We’d earned an extra two days… But I still hadn’t heard anything from Roxy, so that extra time might have been for nothing. Still, I wouldn’t change my approach. I knew from the battle in the port town I couldn’t win a head-on fight. I wanted my trump card.","html":"Badi seemed like he’d have some tricks up his sleeve, though, and Geese was cunning. They were a perfect match. Risky as it was to lead them to the narrow point in the ravine, it was still better than having them cross without our noticing and then blindsiding us. I stood with Cliff, Ruijerd, and the Superd warriors above the ravine. The other Superd were positioned at regular intervals along the stretches not covered by the wall so that we’d be alerted right away if Badigadi crossed there. Eris stood by, directly behind the wall. Once Geese and Badigadi broke through, it’d be all-out war. We’d bought ourselves some time. What should have been a day’s journey, traveling in a straight line, had taken three. We’d earned an extra two days… But I still hadn’t heard anything from Roxy, so that extra time might have been for nothing. Still, I wouldn’t change my approach. I knew from the battle in the port town I couldn’t win a head-on fight. I wanted my trump card.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0027","sourceIndex":27,"type":"narration","text":"Night fell. I had no idea when they might come. The Superd were watching the forest with me, but wherever our enemy was camped was outside of their detection range.","html":"Night fell. I had no idea when they might come. The Superd were watching the forest with me, but wherever our enemy was camped was outside of their detection range.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0028","sourceIndex":28,"type":"narration","text":"Keep on your toes, I thought. Just then, I heard Ruijerd shout.","html":"Keep on your toes, I thought. Just then, I heard Ruijerd shout.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0029","sourceIndex":29,"type":"speech","text":"“They’re here!”","html":"“They’re here!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","speakerConfidence":"high"},{"id":"ch02-p0030","sourceIndex":30,"type":"narration","text":"I strained my eyes as hard as I could to look into the shadows of the forest. There they were. They were no bigger than a grain of rice, but there was someone standing in the trees. No golden sheen, though. This person wore a white robe. I’d seen a white robe like that before.","html":"I strained my eyes as hard as I could to look into the shadows of the forest. There they were. They were no bigger than a grain of rice, but there was someone standing in the trees. No golden sheen, though. This person wore a white robe. I’d seen a white robe like that before.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0031","sourceIndex":31,"type":"narration","text":"It was Geese. Well, it was possible it was someone else, but it looked like Geese.","html":"It was Geese. Well, it was possible it was someone else, but it looked like Geese.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0032","sourceIndex":32,"type":"speech","text":"“Who is it?”","html":"“Who is it?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch02-p0033","sourceIndex":33,"type":"speech","text":"“It’s him,” Ruijerd said with conviction. The distance between us and them was within the range of his third eye. It was unlikely Ruijerd was wrong. Geese appeared to be watching us, not from up close to the edge of the ravine, but from back in the forest, among the undergrowth. It was still too dark to see clearly, but it really did look like him. And I couldn’t spot the faintest sparkle of gold anywhere nearby. Geese was alone.","html":"“It’s him,” Ruijerd said with conviction. The distance between us and them was within the range of his third eye. It was unlikely Ruijerd was wrong. Geese appeared to be watching us, not from up close to the edge of the ravine, but from back in the forest, among the undergrowth. It was still too dark to see clearly, but it really did look like him. And I couldn’t spot the faintest sparkle of gold anywhere nearby. Geese was alone.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","mixed":true,"speakerConfidence":"high"},{"id":"ch02-p0034","sourceIndex":34,"type":"speech","text":"“Huh?”","html":"“Huh?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch02-p0035","sourceIndex":35,"type":"narration","text":"Alone? Was he scouting by himself? Geese, who knew the magic I could use, who knew I had the Eye of Distant Sight, who knew there were Superd here, was alone? Was he that confident? Or was Badigadi lying in wait nearby? The ravine was a hundred meters across at most; if Badigadi were close enough to come to Geese’s defense, Ruijerd would be able to see him.","html":"Alone? Was he scouting by himself? Geese, who knew the magic I could use, who knew I had the Eye of Distant Sight, who knew there were Superd here, was alone? Was he that confident? Or was Badigadi lying in wait nearby? The ravine was a hundred meters across at most; if Badigadi were close enough to come to Geese’s defense, Ruijerd would be able to see him. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0036","sourceIndex":36,"type":"narration","text":"An attack from me would take him down, wouldn’t it?","html":"An attack from me would take him down, wouldn’t it?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0037","sourceIndex":37,"type":"narration","text":"At this realization, my heart started racing. Stone Cannon would reach him. Geese was looking our way, but I had the feeling he couldn’t see me. I’d hit him. It was a hundred meters. Even considering height and ­position, the arc of a Stone Cannon, the shot couldn’t be more than two hundred. If I aimed carefully, that was a distance I could reliably hit from.","html":"At this realization, my heart started racing. Stone Cannon would reach him. Geese was looking our way, but I had the feeling he couldn’t see me. I’d hit him. It was a hundred meters. Even considering height and ­position, the arc of a Stone Cannon, the shot couldn’t be more than two hundred. If I aimed carefully, that was a distance I could reliably hit from.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0038","sourceIndex":38,"type":"narration","text":"I paused. Should I do it? What if it was someone else? Like, an adventurer in a white robe. Who’d just happened to get lost in the forest. In the middle of a battle.","html":"I paused. Should I do it? What if it was someone else? Like, an adventurer in a white robe. Who’d just happened to get lost in the forest. In the middle of a battle.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0039","sourceIndex":39,"type":"narration","text":"Yeah. No way.","html":"Yeah. No way.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0040","sourceIndex":40,"type":"narration","text":"After the Dense Mist and Quagmire of the previous day, the forest was a mess. No adventurer would have made it this far. Even if they’d already been close to the ravine when it began, the Superd’s radar would have picked them up.","html":"After the Dense Mist and Quagmire of the previous day, the forest was a mess. No adventurer would have made it this far. Even if they’d already been close to the ravine when it began, the Superd’s radar would have picked them up.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0041","sourceIndex":41,"type":"narration","text":"I could take out Geese right now. What should I do? It was one hundred percent a trap. What sort of trap? Right now, I could attack. What could he do? Was there some advantage he got by making me attack? Let’s say that whoever was over there looked like Geese but was actually someone else. Could they be one of my friends or family? No way. That was impossible. Up until yesterday, it had only been the two of them. They couldn’t have brought someone along out of nowhere.","html":"I could take out Geese right now. What should I do? It was one hundred percent a trap. What sort of trap? Right now, I could attack. What could he do? Was there some advantage he got by making me attack? Let’s say that whoever was over there looked like Geese but was actually someone else. Could they be one of my friends or family? No way. That was impossible. Up until yesterday, it had only been the two of them. They couldn’t have brought someone along out of nowhere.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0042","sourceIndex":42,"type":"narration","text":"In which case, was this an opening? Up until now, I’d been focused on buying time and hadn’t been actively ­attacking. They’d made rapid progress from the port town to here.","html":"In which case, was this an opening? Up until now, I’d been focused on buying time and hadn’t been actively ­attacking. They’d made rapid progress from the port town to here.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0043","sourceIndex":43,"type":"narration","text":"After a leisurely journey with Badigadi, maybe he was cocky about an easy victory. Couldn’t it be that he’d let his guard down and revealed himself to us? It’d be the easiest thing to attack, and the risk was low. No reason not to, right? It was also possible he’d somehow placed someone there who I didn’t want to see die. Strategically, what would the point of that be? What was the point of my not attacking now?","html":"After a leisurely journey with Badigadi, maybe he was cocky about an easy victory. Couldn’t it be that he’d let his guard down and revealed himself to us? It’d be the easiest thing to attack, and the risk was low. No reason not to, right? It was also possible he’d somehow placed someone there who I didn’t want to see die. Strategically, what would the point of that be? What was the point of my not attacking now?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0044","sourceIndex":44,"type":"narration","text":"I was getting muddled. It felt like a trap, but even so, I couldn’t think of any downsides to attacking.","html":"I was getting muddled. It felt like a trap, but even so, I couldn’t think of any downsides to attacking.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0045","sourceIndex":45,"type":"narration","text":"All right, let’s fire at him. Maybe it’s a trap, but there’s no downside to just shooting him.","html":"All right, let’s fire at him. Maybe it’s a trap, but there’s no downside to just shooting him.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0046","sourceIndex":46,"type":"narration","text":"If he responded, he responded.","html":"If he responded, he responded. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0047","sourceIndex":47,"type":"speech","text":"“I’m going to attack,” I said.","html":"“I’m going to attack,” I said.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch02-p0048","sourceIndex":48,"type":"speech","text":"“Understood.”","html":"“Understood.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","speakerConfidence":"high"},{"id":"ch02-p0049","sourceIndex":49,"type":"narration","text":"I concentrated magic in my right hand. I was more interested in accuracy than speed and power. I still couldn’t see Geese with the Eye of Distant Sight, but I used it to project the landscape while flicking the mana for the Eye of Foresight, predicting where my shot would land. In case it went wide, I decided to use Blast Cannon.","html":"I concentrated magic in my right hand. I was more interested in accuracy than speed and power. I still couldn’t see Geese with the Eye of Distant Sight, but I used it to project the landscape while flicking the mana for the Eye of Foresight, predicting where my shot would land. In case it went wide, I decided to use Blast Cannon. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0050","sourceIndex":50,"type":"narration","text":"I hesitated before I fired, just for a moment. That moment passed and a Stone Cannon burst from my fingers, hurtling towards the other side of the ravine on a dead straight trajectory.","html":"I hesitated before I fired, just for a moment. That moment passed and a Stone Cannon burst from my fingers, hurtling towards the other side of the ravine on a dead straight trajectory. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0051","sourceIndex":51,"type":"narration","text":"There was no sound. As it impacted, the figure on the other side collapsed like a puppet with its strings cut, then was still.","html":"There was no sound. As it impacted, the figure on the other side collapsed like a puppet with its strings cut, then was still.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0052","sourceIndex":52,"type":"narration","text":"The shot had hit, and it had gotten results. Time passed. It was surreal, like nothing had happened. The fallen figure didn’t move. In the light of the morning, all I could hear was the quiet rustling of the forest. Ten minutes passed. Then twenty. I wasn’t keeping track of the exact time, but it kept on slipping away.","html":"The shot had hit, and it had gotten results. Time passed. It was surreal, like nothing had happened. The fallen figure didn’t move. In the light of the morning, all I could hear was the quiet rustling of the forest. Ten minutes passed. Then twenty. I wasn’t keeping track of the exact time, but it kept on slipping away. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0053","sourceIndex":53,"type":"narration","text":"A feeling took root within me. I wanted to know. Whatever was lying on the ground over there after I’d hit it, I wanted to know what it was. Was it Geese, or something else? Was it alive or dead? I could hop on down there and be back again in a jiffy. Surely that would be fine.","html":"A feeling took root within me. I wanted to know. Whatever was lying on the ground over there after I’d hit it, I wanted to know what it was. Was it Geese, or something else? Was it alive or dead? I could hop on down there and be back again in a jiffy. Surely that would be fine.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0054","sourceIndex":54,"type":"narration","text":"But as that idea came to me, I realized what was ­going on. This was the trap. Geese’s plan wasn’t to make me ­attack but to make me feel what I felt now.","html":"But as that idea came to me, I realized what was ­going on. This was the trap. Geese’s plan wasn’t to make me ­attack but to make me feel what I felt now. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0055","sourceIndex":55,"type":"narration","text":"Maybe whoever lay down there really was Geese, on the verge of death, and all I had to do to win was strike the final blow. Maybe it was Sylphie—they’d captured her at some point, then come up with some way to deceive Ruijerd’s eye, and if I didn’t go to her aid right now she’d die. Even if either of those were true, if I went to look, the Fighting God would appear, and I’d die. I couldn’t go.","html":"Maybe whoever lay down there really was Geese, on the verge of death, and all I had to do to win was strike the final blow. Maybe it was Sylphie—they’d captured her at some point, then come up with some way to deceive Ruijerd’s eye, and if I didn’t go to her aid right now she’d die. Even if either of those were true, if I went to look, the Fighting God would appear, and I’d die. I couldn’t go.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0056","sourceIndex":56,"type":"narration","text":"An hour passed. I was on edge. Had I made some irreversible mistake? Should I not have shot the figure after all? Was their aim in making me shoot it to keep me locked down here?","html":"An hour passed. I was on edge. Had I made some irreversible mistake? Should I not have shot the figure after all? Was their aim in making me shoot it to keep me locked down here?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0057","sourceIndex":57,"type":"narration","text":"What if, even now, they were crossing the ravine at another point? Okay, no, I did have the Superd warriors guarding the ravine at least. I had to trust them.","html":"What if, even now, they were crossing the ravine at another point? Okay, no, I did have the Superd warriors guarding the ravine at least. I had to trust them.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0058","sourceIndex":58,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch02-p0059","sourceIndex":59,"type":"narration","text":"Two hours passed. Should I have gone to check after all? Might going down to check give me a clue as to Geese’s next move? Was I just avoiding finding out the truth for some reason?","html":"Two hours passed. Should I have gone to check after all? Might going down to check give me a clue as to Geese’s next move? Was I just avoiding finding out the truth for some reason?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0060","sourceIndex":60,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch02-p0061","sourceIndex":61,"type":"narration","text":"Three hours passed. Nothing moved. All sorts of patterns floated in and out of my mind. This wondering was starting to wear me out. If Geese’s plan was to make me exhausted, he was succeeding.","html":"Three hours passed. Nothing moved. All sorts of patterns floated in and out of my mind. This wondering was starting to wear me out. If Geese’s plan was to make me exhausted, he was succeeding. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0062","sourceIndex":62,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch02-p0063","sourceIndex":63,"type":"narration","text":"After four hours, I was certain. That was a corpse. It hadn’t moved for four hours, so it had to be a body. But whose? Was it really plausible that Geese was dead, and Badigadi hadn’t done anything? If Roxy were here, she might have had something constructive to say. When I asked Cliff, he just frowned and shook his head.","html":"After four hours, I was certain. That was a corpse. It hadn’t moved for four hours, so it had to be a body. But whose? Was it really plausible that Geese was dead, and Badigadi hadn’t done anything? If Roxy were here, she might have had something constructive to say. When I asked Cliff, he just frowned and shook his head.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0064","sourceIndex":64,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch02-p0065","sourceIndex":65,"type":"narration","text":"Six hours passed. I ate a quick lunch, then returned to watching the corpse. It didn’t move.","html":"Six hours passed. I ate a quick lunch, then returned to watching the corpse. It didn’t move.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0066","sourceIndex":66,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch02-p0067","sourceIndex":67,"type":"narration","text":"Eight hours passed. The afternoon was wearing on, and the sun was growing steadily lower in the sky. Maybe because I’d been on constant alert, I was only getting more tired. If the sun set below the horizon and still nothing happened, I’d go have a look.","html":"Eight hours passed. The afternoon was wearing on, and the sun was growing steadily lower in the sky. Maybe because I’d been on constant alert, I was only getting more tired. If the sun set below the horizon and still nothing happened, I’d go have a look.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0068","sourceIndex":68,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch02-p0069","sourceIndex":69,"type":"speech","text":"When the tenth hour passed, Ruijerd said abruptly, “Rudeus. He’s here.”","html":"When the tenth hour passed, Ruijerd said abruptly, “Rudeus. He’s here.” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","mixed":true,"speakerConfidence":"high"},{"id":"ch02-p0070","sourceIndex":70,"type":"narration","text":"With a start, I looked to the forest, just in time to see the shining golden armor step out from the trees. When the armor drew near, the corpse slowly got up. It put its face up to the armor for a while, as though it was saying something, then turned to look our way. I saw the shrug. That was Geese’s shrug, no doubt about it. Without any further fanfare, the two of them retreated into the depths of the forest. Silence fell once more.","html":"With a start, I looked to the forest, just in time to see the shining golden armor step out from the trees. When the armor drew near, the corpse slowly got up. It put its face up to the armor for a while, as though it was saying something, then turned to look our way. I saw the shrug. That was Geese’s shrug, no doubt about it. Without any further fanfare, the two of them retreated into the depths of the forest. Silence fell once more.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0071","sourceIndex":71,"type":"speech","text":"“Whew…”","html":"“Whew…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch02-p0072","sourceIndex":72,"type":"narration","text":"It had been a trap. The figure was Geese, but he had used himself as bait to try and lure me out. I’d been close to falling for it.","html":"It had been a trap. The figure was Geese, but he had used himself as bait to try and lure me out. I’d been close to falling for it.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0073","sourceIndex":73,"type":"narration","text":"Night was about to fall. I’d leave the Superd warriors on guard and catch a bit of sleep. My mind was fried. They might come back as the sun set, but I’d settle for just a nap.","html":"Night was about to fall. I’d leave the Superd warriors on guard and catch a bit of sleep. My mind was fried. They might come back as the sun set, but I’d settle for just a nap.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0074","sourceIndex":74,"type":"speech","text":"“I’m taking a break,” I said. I curled up in a blanket.","html":"“I’m taking a break,” I said. I curled up in a blanket.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch02-p0075","sourceIndex":75,"type":"narration","text":"The third day ended.","html":"The third day ended.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0076","sourceIndex":76,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":2061,"speechCount":9,"speakers":["Rudeus","Ruijerd"]},{"id":"ch02-s04","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The barricade wall above the Ravine of the Earthwyrm, at night","cast":["Badigadi","Geese","Rudeus","Superd Warrior"],"blocks":[{"id":"ch02-p0078","sourceIndex":78,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch02-p0079","sourceIndex":79,"type":"narration","text":"It was the third night. It seemed that after seeing our wall, Geese and Badigadi were struggling to work out an effective attack strategy. Badigadi couldn’t simply jump over the wall, and if he couldn’t do that, he couldn’t protect Geese. I’d been right on that count. Then there were the missiles that came hurtling at us from the other side of the valley. First came a massive boulder that hit the wall at hair-raising speed, knocking out a chunk of the wall. More boulders and tree trunks followed, coming one after another at terrifying speeds. I woke to the cacophony and intercepted them all, so they didn’t do any significant damage. Badigadi and Geese must have decided that unless they did something about the wall, they couldn’t get through. That would explain this attack. Based on what I’d seen of the Fighting God’s battle style, he could have smashed his way through if he were alone. It had to be Geese holding him back. If he left Geese behind and leaped over, he could get through…only then, if a pursuit came from the rear, Geese would be dead meat. Not that there weren’t any reinforcements coming from outside the forest… Well, except maybe Atofe, if she regenerated then came after us. Maybe they were afraid of something like that. A single Superd warrior on the forest side should be enough, to be fair…but it was possible the two of them had wisened up to the danger of leaving Geese behind after yesterday.","html":"It was the third night. It seemed that after seeing our wall, Geese and Badigadi were struggling to work out an effective attack strategy. Badigadi couldn’t simply jump over the wall, and if he couldn’t do that, he couldn’t protect Geese. I’d been right on that count. Then there were the missiles that came hurtling at us from the other side of the valley. First came a massive boulder that hit the wall at hair-raising speed, knocking out a chunk of the wall. More boulders and tree trunks followed, coming one after another at terrifying speeds. I woke to the cacophony and intercepted them all, so they didn’t do any significant damage. Badigadi and Geese must have decided that unless they did something about the wall, they couldn’t get through. That would explain this attack. Based on what I’d seen of the Fighting God’s battle style, he could have smashed his way through if he were alone. It had to be Geese holding him back. If he left Geese behind and leaped over, he could get through…only then, if a pursuit came from the rear, Geese would be dead meat. Not that there weren’t any reinforcements coming from outside the forest… Well, except maybe Atofe, if she regenerated then came after us. Maybe they were afraid of something like that. A single Superd warrior on the forest side should be enough, to be fair…but it was possible the two of them had wisened up to the danger of leaving Geese behind after yesterday.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0080","sourceIndex":80,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch02-p0081","sourceIndex":81,"type":"narration","text":"A guard could finish Geese off if he was by himself. I didn’t have to be there. It didn’t have to be me.","html":"A guard could finish Geese off if he was by himself. I didn’t have to be there. It didn’t have to be me.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0082","sourceIndex":82,"type":"narration","text":"It was getting to the point where the Fighting God might well run out of patience and jump over alone.","html":"It was getting to the point where the Fighting God might well run out of patience and jump over alone.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0083","sourceIndex":83,"type":"narration","text":"My trump card still hadn’t come.","html":"My trump card still hadn’t come.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0084","sourceIndex":84,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":302,"speechCount":0,"speakers":[]},{"id":"ch02-s05","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The barricade wall above the Ravine of the Earthwyrm, at dawn","cast":["Badigadi","Cliff","Dohga","Elinalise","Eris","Rudeus","Ruijerd","Superd Warrior","Zanoba"],"blocks":[{"id":"ch02-p0086","sourceIndex":86,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch02-p0087","sourceIndex":87,"type":"narration","text":"On the fourth day, the sun came up, and the Fighting God along with it. He was alone, as I’d predicted. He came over at a running jump, like the Ogre God, then stuck fast to a point a little below the wall. As I’d expected. Everything was as I’d planned. The moment I saw that Geese wasn’t on the Fighting God’s back, I released a spell at the other side of the ravine, casting Flashover over a wide area. The forest was swallowed by flames in an instant. I couldn’t tell if it got to him. I didn’t have time to scan the burning forest for a body. I kept the blaze of the burning trees in the corner of my eye, but I had an enemy in front of me who required my full attention. Using his six arms to climb like a spider, the Fighting God scaled the wall at a shocking pace. Cliff and I fired Stone Cannons and giant water bombs at him to try and knock him off, but it was like trying to hold back the tide. The Fighting God flew up the wall at blistering speed.","html":"On the fourth day, the sun came up, and the Fighting God along with it. He was alone, as I’d predicted. He came over at a running jump, like the Ogre God, then stuck fast to a point a little below the wall. As I’d expected. Everything was as I’d planned. The moment I saw that Geese wasn’t on the Fighting God’s back, I released a spell at the other side of the ravine, casting Flashover over a wide area. The forest was swallowed by flames in an instant. I couldn’t tell if it got to him. I didn’t have time to scan the burning forest for a body. I kept the blaze of the burning trees in the corner of my eye, but I had an enemy in front of me who required my full attention. Using his six arms to climb like a spider, the Fighting God scaled the wall at a shocking pace. Cliff and I fired Stone Cannons and giant water bombs at him to try and knock him off, but it was like trying to hold back the tide. The Fighting God flew up the wall at blistering speed.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0088","sourceIndex":88,"type":"speech","text":"“Cliff! It’s no good! Fall back! Ruijerd! Get us out of here!”","html":"“Cliff! It’s no good! Fall back! Ruijerd! Get us out of here!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch02-p0089","sourceIndex":89,"type":"speech","text":"“Understood!” Ruijerd grabbed me and Cliff and jumped down from the wall. We didn’t wait for the Fighting God to get over the wall—the moment we hit the ground, I used magic to send the towering wall crashing down into the ravine.","html":"“Understood!” Ruijerd grabbed me and Cliff and jumped down from the wall. We didn’t wait for the Fighting God to get over the wall—the moment we hit the ground, I used magic to send the towering wall crashing down into the ravine.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","mixed":true,"speakerConfidence":"high"},{"id":"ch02-p0090","sourceIndex":90,"type":"narration","text":"It did us no good. The wall began to crumble away with aching slowness, then exploded all at once as though by dynamite. Great hunks of rock flew through the air, and among them, a golden suit of armor. I used magic to clean up the boulders that came raining down on us, never taking my eyes off the Fighting God. He alighted at a point less than five meters away from me with a grunt. Then, he slowly turned to face me.","html":"It did us no good. The wall began to crumble away with aching slowness, then exploded all at once as though by dynamite. Great hunks of rock flew through the air, and among them, a golden suit of armor. I used magic to clean up the boulders that came raining down on us, never taking my eyes off the Fighting God. He alighted at a point less than five meters away from me with a grunt. Then, he slowly turned to face me.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0091","sourceIndex":91,"type":"speech","text":"“Let’s pick up where we left off,” he said. He folded his upper arms, put his lower hands on his hips, and pointed at me with the middle hand. Badigadi was looking at me. “I am Fighting God Badigadi! Friend to the Man-God, and heir to the name of fighting god! Rudeus Greyrat, I challenge you to a duel!”","html":"“Let’s pick up where we left off,” he said. He folded his upper arms, put his lower hands on his hips, and pointed at me with the middle hand. Badigadi was looking at me. “I am Fighting God Badigadi! Friend to the Man-God, and heir to the name of fighting god! Rudeus Greyrat, I challenge you to a duel!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch02-p0092","sourceIndex":92,"type":"speech","text":"“I have a question!” I shouted quickly. I knew he might just tell me not to waste my breath, but I said it anyway. “Your Majesty! Why have you joined forces with the Man-God? What do you mean you’re his friend?! Were you not deceived by him once before?”","html":"“I have a question!” I shouted quickly. I knew he might just tell me not to waste my breath, but I said it anyway. “Your Majesty! Why have you joined forces with the Man-God? What do you mean you’re his friend?! Were you not deceived by him once before?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch02-p0093","sourceIndex":93,"type":"speech","text":"“Indeed I was, boy! He tricked me saying it was to save Kishirika from dying at Laplace’s hand! I donned this armor, then I killed Laplace, but did Kishirika a mortal wound in the process!”","html":"“Indeed I was, boy! He tricked me saying it was to save Kishirika from dying at Laplace’s hand! I donned this armor, then I killed Laplace, but did Kishirika a mortal wound in the process!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch02-p0094","sourceIndex":94,"type":"speech","text":"“Then why?!”","html":"“Then why?!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch02-p0095","sourceIndex":95,"type":"speech","text":"“The Man-God came to me on his knees to say he was sorry for that! Not only that, but he begged I lend him my strength! I could not say no after that!”","html":"“The Man-God came to me on his knees to say he was sorry for that! Not only that, but he begged I lend him my strength! I could not say no after that!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch02-p0096","sourceIndex":96,"type":"narration","text":"The Man-God apologized? No way. That bastard would never apologize. Or if he did, he’d just smirk and be like, Tee hee, I’m sooo sorrrrry.","html":"The Man-God apologized? No way. That bastard would never apologize. Or if he did, he’d just smirk and be like, Tee hee, I’m sooo sorrrrry.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0097","sourceIndex":97,"type":"speech","text":"“He’s going to deceive you again!”","html":"“He’s going to deceive you again!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch02-p0098","sourceIndex":98,"type":"speech","text":"“I care not! Should it be so, he need only apologize, and I will forgive him! I am immortal, and Kishirika regenerated! If he apologizes, then I have no quarrel with him! What more could I ask for?”","html":"“I care not! Should it be so, he need only apologize, and I will forgive him! I am immortal, and Kishirika regenerated! If he apologizes, then I have no quarrel with him! What more could I ask for?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch02-p0099","sourceIndex":99,"type":"narration","text":"You’re too generous.","html":"You’re too generous.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0100","sourceIndex":100,"type":"narration","text":"He had a pretty good point, in my opinion. I thought you should forgive people for petty dishonesty, too. Only, I didn’t have the luxury of writing off the death of a family member as “petty.” I wasn’t an immortal demon. I saw the world differently. From Badigadi’s perspective, Kishirika was always going to regenerate.","html":"He had a pretty good point, in my opinion. I thought you should forgive people for petty dishonesty, too. Only, I didn’t have the luxury of writing off the death of a family member as “petty.” I wasn’t an immortal demon. I saw the world differently. From Badigadi’s perspective, Kishirika was always going to regenerate.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0101","sourceIndex":101,"type":"speech","text":"“Don’t suppose you’d betray him and come over to our side?”","html":"“Don’t suppose you’d betray him and come over to our side?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch02-p0102","sourceIndex":102,"type":"speech","text":"“Never! I was never an ally of the Dragon God. However, if you win this battle, I shall consider it!”","html":"“Never! I was never an ally of the Dragon God. However, if you win this battle, I shall consider it!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch02-p0103","sourceIndex":103,"type":"narration","text":"He was telling me to fight and take what I wanted. He and Atofe were alike in this area. Come to think of it, the first time I’d met this demon king had been at a dueling arena. Had I won back then or lost? It had ended with me earning Badigadi’s respect, in any case. That’d be why he treated me well. To a demon king, that had to be what it meant to fight.","html":"He was telling me to fight and take what I wanted. He and Atofe were alike in this area. Come to think of it, the first time I’d met this demon king had been at a dueling arena. Had I won back then or lost? It had ended with me earning Badigadi’s respect, in any case. That’d be why he treated me well. To a demon king, that had to be what it meant to fight.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0104","sourceIndex":104,"type":"speech","text":"“All right. I accept your challenge.”","html":"“All right. I accept your challenge.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch02-p0105","sourceIndex":105,"type":"narration","text":"The thing was, Badigadi had forgotten to say “single-combat” this time.","html":"The thing was, Badigadi had forgotten to say “single-combat” this time.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0106","sourceIndex":106,"type":"speech","text":"“All of us here will be your opponents.” From the bushes behind me emerged Eris, Elinalise, Zanoba, and Dohga. Joining them came the Superd who had been guarding the rest of the ravine. It was time for all-out war.","html":"“All of us here will be your opponents.” From the bushes behind me emerged Eris, Elinalise, Zanoba, and Dohga. Joining them came the Superd who had been guarding the rest of the ravine. It was time for all-out war.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch02-p0107","sourceIndex":107,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":799,"speechCount":13,"speakers":["Badigadi","Rudeus","Ruijerd"]},{"id":"ch02-s06","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The Ravine of the Earthwyrm, the battle with the Fighting God","cast":["Aisha","Badigadi","Cliff","Dohga","Elinalise","Eris","Ghislaine","Isolde","Julie","Norn","Orsted","Roxy","Rudeus","Ruijerd","Superd Warrior","Sylphiette","Zanoba"],"blocks":[{"id":"ch02-p0109","sourceIndex":109,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch02-p0110","sourceIndex":110,"type":"narration","text":"Frontline tanks: Dohga and Zanoba. Frontline attackers: Eris and Ruijerd. Middle supports: Elinalise and the Superd warriors. Backline attacker: me. Backline healer: Cliff. Standard party formation and standard tactics.","html":"Frontline tanks: Dohga and Zanoba. Frontline attackers: Eris and Ruijerd. Middle supports: Elinalise and the Superd warriors. Backline attacker: me. Backline healer: Cliff. Standard party formation and standard tactics. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0111","sourceIndex":111,"type":"narration","text":"The basic plan was that Dohga and Zanoba would take attacks while Eris and Ruijerd doled them out. Elinalise and the Superd warriors, who were outclassed in fighting power, would go around behind Badigadi from time to time to throw him off. For everyone except Zanoba and Dohga, a single hit was potentially fatal. Honestly, a direct hit would be potentially fatal even for those two, but they’d cover each other to avoid taking any. They might still break some bones or something along those lines, but Cliff and I would heal all of that. Cliff was our dedicated healer. I did some healing while firing off Stone Cannons here and there to deal damage to the Fighting God and divert his attacks. I couldn’t see Badigadi with the Eye of Foresight, but by cutting off mana to the Eye of Distant Sight, I could use the Eye of Foresight to watch my allies and predict their movements that way. I’d never done anything like this before. I’d never practiced it or drilled it.","html":"The basic plan was that Dohga and Zanoba would take attacks while Eris and Ruijerd doled them out. Elinalise and the Superd warriors, who were outclassed in fighting power, would go around behind Badigadi from time to time to throw him off. For everyone except Zanoba and Dohga, a single hit was potentially fatal. Honestly, a direct hit would be potentially fatal even for those two, but they’d cover each other to avoid taking any. They might still break some bones or something along those lines, but Cliff and I would heal all of that. Cliff was our dedicated healer. I did some healing while firing off Stone Cannons here and there to deal damage to the Fighting God and divert his attacks. I couldn’t see Badigadi with the Eye of Foresight, but by cutting off mana to the Eye of Distant Sight, I could use the Eye of Foresight to watch my allies and predict their movements that way. I’d never done anything like this before. I’d never practiced it or drilled it.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0112","sourceIndex":112,"type":"narration","text":"Yet for some reason, it worked. I felt like I was fighting with one eye closed, but I could still read Badigadi and my allies’ movements. If anything, it seemed like my movements were smoother than usual. Maybe that was because my primary role here was providing support, or maybe it was because Badigadi’s movements were so straightforward. He certainly didn’t have Alexander’s technique; Alexander had fought Eris, Ruijerd, and Sandor three-on-one and barely taken a hit. Not Badigadi, though—beyond just being outnumbered, he was also taking practically every hit. This was good. My opponent’s movements were clearly telegraphed and I caught every last one.","html":"Yet for some reason, it worked. I felt like I was fighting with one eye closed, but I could still read Badigadi and my allies’ movements. If anything, it seemed like my movements were smoother than usual. Maybe that was because my primary role here was providing support, or maybe it was because Badigadi’s movements were so straightforward. He certainly didn’t have Alexander’s technique; Alexander had fought Eris, Ruijerd, and Sandor three-on-one and barely taken a hit. Not Badigadi, though—beyond just being outnumbered, he was also taking practically every hit. This was good. My opponent’s movements were clearly telegraphed and I caught every last one.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0113","sourceIndex":113,"type":"narration","text":"Only, I couldn’t see how to end it.","html":"Only, I couldn’t see how to end it.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0114","sourceIndex":114,"type":"narration","text":"Badigadi was taking all our attacks, so at a glance, it might look like we were winning. It might look like we were dealing decent damage. But it only looked that way. Every time Eris cut him apart or Ruijerd stabbed him through, the wounds repaired right away. The gold armor writhed like a living thing to cover the holes as soon as they appeared. He was probably recovering inside the armor too. In other words, he’d taken no damage, and he wasn’t tired. We wouldn’t have a situation like with Alexander where he looked like he was winning easily while, in reality, he was getting more and more tired. The battle was only going to turn further against us as it went on. There was no hope of winning, but we could hang on. So long as our formation held and no one went down suddenly, we could hang on. Who knew where that would get us? But it was all we could do.","html":"Badigadi was taking all our attacks, so at a glance, it might look like we were winning. It might look like we were dealing decent damage. But it only looked that way. Every time Eris cut him apart or Ruijerd stabbed him through, the wounds repaired right away. The gold armor writhed like a living thing to cover the holes as soon as they appeared. He was probably recovering inside the armor too. In other words, he’d taken no damage, and he wasn’t tired. We wouldn’t have a situation like with Alexander where he looked like he was winning easily while, in reality, he was getting more and more tired. The battle was only going to turn further against us as it went on. There was no hope of winning, but we could hang on. So long as our formation held and no one went down suddenly, we could hang on. Who knew where that would get us? But it was all we could do.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0115","sourceIndex":115,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch02-p0116","sourceIndex":116,"type":"narration","text":"And that meager amount proved too much. The first to go down were, of course, the Superd warriors. They weren’t weak by any means, but they were a few levels below Ruijerd, and they hadn’t fought in a real battle for the past few hundred years. Some of them might not even have been born at the time of the Laplace War. The warriors who’d only ever hunted Invisible Wolves couldn’t keep up in a battle with the Fighting God. One after another, they dropped out of the battle in rapid succession. Some had clearly died instantly, others were badly wounded but would still fight if healed. Others, I couldn’t tell. There had been ten of them when the fight began, but now they were down to three.","html":"And that meager amount proved too much. The first to go down were, of course, the Superd warriors. They weren’t weak by any means, but they were a few levels below Ruijerd, and they hadn’t fought in a real battle for the past few hundred years. Some of them might not even have been born at the time of the Laplace War. The warriors who’d only ever hunted Invisible Wolves couldn’t keep up in a battle with the Fighting God. One after another, they dropped out of the battle in rapid succession. Some had clearly died instantly, others were badly wounded but would still fight if healed. Others, I couldn’t tell. There had been ten of them when the fight began, but now they were down to three.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0117","sourceIndex":117,"type":"narration","text":"We lost Elinalise next. She certainly wasn’t weak ­either. As far as technique went, she was in the top ranks of adventurers. She was good enough to frontline in an S-Rank labyrinth, and her defensive skill with a shield was unmatched. That ranking was against other adventurers, though. Her specialty was aggro-control, ­skillfully deflecting attacks with her shield, then piling on low-damage attacks. But she had lost her trusty shield. I’d made her a backup with earth magic, but Fighting God Badigadi’s attack easily broke through her deflection technique, throwing her through the air so she went crashing into a large tree. She blacked out. After that, it all fell apart. Cliff was thrown when Elinalise went down, and in that moment of distraction, he was caught by the Fighting God’s charge. He went flying like he’d been hit by a truck and disappeared into the bushes. Whether he was dead or just critically injured I couldn’t tell, but he didn’t come back. At minimum, he’d been knocked out.","html":"We lost Elinalise next. She certainly wasn’t weak ­either. As far as technique went, she was in the top ranks of adventurers. She was good enough to frontline in an S-Rank labyrinth, and her defensive skill with a shield was unmatched. That ranking was against other adventurers, though. Her specialty was aggro-control, ­skillfully deflecting attacks with her shield, then piling on low-damage attacks. But she had lost her trusty shield. I’d made her a backup with earth magic, but Fighting God Badigadi’s attack easily broke through her deflection technique, throwing her through the air so she went crashing into a large tree. She blacked out. After that, it all fell apart. Cliff was thrown when Elinalise went down, and in that moment of distraction, he was caught by the Fighting God’s charge. He went flying like he’d been hit by a truck and disappeared into the bushes. Whether he was dead or just critically injured I couldn’t tell, but he didn’t come back. At minimum, he’d been knocked out.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0118","sourceIndex":118,"type":"narration","text":"With Cliff unconscious, Zanoba and Dohga, who he’d been healing, were unable to hold on any longer. Between my support with Stone Cannon and Elinalise’s cover, we’d made sure they were only taking one of every few attacks. Now, they were taking almost every single one. With my healing magic, they were enduring it, but no more than that. Running over to them every time the Fighting God sent them flying, healing them, and sending them back into the fray was impossible for me on my own. If I’d even had the Magic Armor Version Two, maybe I could have done it, but in my own body? Unable to don a battle aura? No matter how much I sped myself along with wind magic I was still too slow. Always one step behind. Our timing got more and more out of sync until both Zanoba and Dohga were sent flying as a pair. At the same moment, the Fighting God targeted Eris. Ruijerd covered her, but that put him out of the battle. I rushed to heal Dohga, then ran to Zanoba’s side, but I was too slow. Our line was in shambles. Dohga was sent flying, then, as I was healing Zanoba, I saw the fighting God hit Eris straight on with his fist. She collapsed, coughing up blood. She’s fatally wounded! screamed a voice in my head. You have to heal her right now or it’ll be too late! But I was too slow. The Fighting God was closing in on me and Zanoba.","html":"With Cliff unconscious, Zanoba and Dohga, who he’d been healing, were unable to hold on any longer. Between my support with Stone Cannon and Elinalise’s cover, we’d made sure they were only taking one of every few attacks. Now, they were taking almost every single one. With my healing magic, they were enduring it, but no more than that. Running over to them every time the Fighting God sent them flying, healing them, and sending them back into the fray was impossible for me on my own. If I’d even had the Magic Armor Version Two, maybe I could have done it, but in my own body? Unable to don a battle aura? No matter how much I sped myself along with wind magic I was still too slow. Always one step behind. Our timing got more and more out of sync until both Zanoba and Dohga were sent flying as a pair. At the same moment, the Fighting God targeted Eris. Ruijerd covered her, but that put him out of the battle. I rushed to heal Dohga, then ran to Zanoba’s side, but I was too slow. Our line was in shambles. Dohga was sent flying, then, as I was healing Zanoba, I saw the fighting God hit Eris straight on with his fist. She collapsed, coughing up blood. She’s fatally wounded! screamed a voice in my head. You have to heal her right now or it’ll be too late! But I was too slow. The Fighting God was closing in on me and Zanoba.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0119","sourceIndex":119,"type":"speech","text":"“Rroooaaaah!” Zanoba howled.","html":"“Rroooaaaah!” Zanoba howled.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Zanoba","mixed":true,"speakerConfidence":"high"},{"id":"ch02-p0120","sourceIndex":120,"type":"narration","text":"He blocked the Fighting God’s right upper punch, then his left. He took a punch from one of the lower arms in the gut, doubling over. Next, a punch from the middle arms got him in the temple, and he was thrown off to one side. Next, the Fighting God rounded on me. By the time I’d thought, Oh, shit!, it was too late. The punch caught me as I was trying to cast Shock Wave to push myself back. It was one of the middle arms. I immediately tried to block it with my arm, but it was a pointless gesture. The impact was so intense I thought my upper body would be torn apart—and I sailed into the air myself. I’m not sure if it was good luck or bad that I didn’t lose consciousness. I could feel that all my bones from my shoulder down to my ribs were broken, and maybe my spine, too, because I couldn’t feel my legs. I couldn’t move. Possibly the shock had been so great that my brain had cut out all pain signals. I’d simply lost all sensation.","html":"He blocked the Fighting God’s right upper punch, then his left. He took a punch from one of the lower arms in the gut, doubling over. Next, a punch from the middle arms got him in the temple, and he was thrown off to one side. Next, the Fighting God rounded on me. By the time I’d thought, Oh, shit!, it was too late. The punch caught me as I was trying to cast Shock Wave to push myself back. It was one of the middle arms. I immediately tried to block it with my arm, but it was a pointless gesture. The impact was so intense I thought my upper body would be torn apart—and I sailed into the air myself. I’m not sure if it was good luck or bad that I didn’t lose consciousness. I could feel that all my bones from my shoulder down to my ribs were broken, and maybe my spine, too, because I couldn’t feel my legs. I couldn’t move. Possibly the shock had been so great that my brain had cut out all pain signals. I’d simply lost all sensation.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0121","sourceIndex":121,"type":"narration","text":"Gasping, I immediately cast healing magic on myself, then stood up. The sight that greeted me was like a scene out of hell. Not a single person was left standing. After I’d gone down, the Fighting God had done away with the remaining Superd warriors. It was sheer carnage. I’d made the wrong call on when to pull out, and now, we couldn’t even retreat. Thinking back, we should have fallen back the moment Elinalise went down. I should have seen that we couldn’t hold out any longer and gone back to the Superd village. Then, I should have left the rest to Orsted. But it was too late for regrets.","html":"Gasping, I immediately cast healing magic on myself, then stood up. The sight that greeted me was like a scene out of hell. Not a single person was left standing. After I’d gone down, the Fighting God had done away with the remaining Superd warriors. It was sheer carnage. I’d made the wrong call on when to pull out, and now, we couldn’t even retreat. Thinking back, we should have fallen back the moment Elinalise went down. I should have seen that we couldn’t hold out any longer and gone back to the Superd village. Then, I should have left the rest to Orsted. But it was too late for regrets.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0122","sourceIndex":122,"type":"narration","text":"The Fighting God stood to confront me, the last one standing.","html":"The Fighting God stood to confront me, the last one standing.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0123","sourceIndex":123,"type":"speech","text":"“Any final words?”","html":"“Any final words?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch02-p0124","sourceIndex":124,"type":"speech","text":"“Honestly, I’d like to beg for my life.”","html":"“Honestly, I’d like to beg for my life.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch02-p0125","sourceIndex":125,"type":"speech","text":"“You may try, though I would not hold out hope that your pleas will be heard. The Man-God desires your death.”","html":"“You may try, though I would not hold out hope that your pleas will be heard. The Man-God desires your death.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch02-p0126","sourceIndex":126,"type":"narration","text":"I want to find a moment to heal Eris, I thought groggily. It didn’t look like I was going to be granted that. Wasn’t there another way?","html":"I want to find a moment to heal Eris, I thought groggily. It didn’t look like I was going to be granted that. Wasn’t there another way?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0127","sourceIndex":127,"type":"narration","text":"If I kept Badigadi distracted for five minutes—hell, three would do—just time enough to dash to Eris’s side. I’d settle for Cliff waking up and healing someone. Wasn’t there something, anything, I could do?","html":"If I kept Badigadi distracted for five minutes—hell, three would do—just time enough to dash to Eris’s side. I’d settle for Cliff waking up and healing someone. Wasn’t there something, anything, I could do?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0128","sourceIndex":128,"type":"speech","text":"“Okay, you can have my life. In exchange…would you please spare my family?”","html":"“Okay, you can have my life. In exchange…would you please spare my family?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch02-p0129","sourceIndex":129,"type":"speech","text":"“Oho? Family, you say?”","html":"“Oho? Family, you say?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch02-p0130","sourceIndex":130,"type":"speech","text":"“I don’t think your Majesty is aware, but I have children now. All four of them healthy.”","html":"“I don’t think your Majesty is aware, but I have children now. All four of them healthy.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch02-p0131","sourceIndex":131,"type":"speech","text":"“Children are a fine thing. I’d like some of my own with Kishirika one day.” Badigadi nodded. “Very well. But know that if any of them rises against me, I shall show no mercy.”","html":"“Children are a fine thing. I’d like some of my own with Kishirika one day.” Badigadi nodded. “Very well. But know that if any of them rises against me, I shall show no mercy.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch02-p0132","sourceIndex":132,"type":"speech","text":"“Of course.”","html":"“Of course.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch02-p0133","sourceIndex":133,"type":"narration","text":"After I was dead, the Man-God would go after my children, but now, he wouldn’t have Badigadi helping him. Getting that promise from him would have to do for now. Even if it might not mean anything in the end…","html":"After I was dead, the Man-God would go after my children, but now, he wouldn’t have Badigadi helping him. Getting that promise from him would have to do for now. Even if it might not mean anything in the end…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0134","sourceIndex":134,"type":"narration","text":"This was my final job.","html":"This was my final job.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0135","sourceIndex":135,"type":"speech","text":"“Fwahahaha, haaahahahahahahaha!” Badigadi cackled, raising his fist. “Farewell, then, boy!”","html":"“Fwahahaha, haaahahahahahahaha!” Badigadi cackled, raising his fist. “Farewell, then, boy!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch02-p0136","sourceIndex":136,"type":"narration","text":"At this, I raised both of my hands. As my final act, I could at least hit him with the strongest Stone Cannon I could—","html":"At this, I raised both of my hands. As my final act, I could at least hit him with the strongest Stone Cannon I could—","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0137","sourceIndex":137,"type":"speech","text":"“Get down!”","html":"“Get down!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch02-p0138","sourceIndex":138,"type":"narration","text":"I threw myself down on all fours like a dog. Something even lower to the ground than I was passed by in the corner of my vision. It shot between the Fighting God’s legs, then stopped behind him. It had gray skin, animal ears, and a cat-like tail. A black wolf. It had sliced through the Fighting God’s legs around the knees, and for a moment, his balance faltered—but only for a moment. The armor repaired itself straight away, and his fist came down undeterred.","html":"I threw myself down on all fours like a dog. Something even lower to the ground than I was passed by in the corner of my vision. It shot between the Fighting God’s legs, then stopped behind him. It had gray skin, animal ears, and a cat-like tail. A black wolf. It had sliced through the Fighting God’s legs around the knees, and for a moment, his balance faltered—but only for a moment. The armor repaired itself straight away, and his fist came down undeterred. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0139","sourceIndex":139,"type":"narration","text":"Just then, a long skirt fluttered above me. I was being straddled.","html":"Just then, a long skirt fluttered above me. I was being straddled.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0140","sourceIndex":140,"type":"speech","text":"“Hmph!” As the Fighting God swung his fist down, he disappeared from my view. I felt something large get blasted away into the sky somewhere behind me. A little later there was a rumble as something hit the ground. What had happened? All I could see was the inside of this long skirt, and, above me, a pair of pale blue panties. The owner of said panties seemed familiar, though I couldn’t place them. But the other one, the wolf? I knew that wolf. I’d seen them before. As if I could forget! That way of moving, that sandy hair, that red-brown skin—plus the waving tail and animal ears.","html":"“Hmph!” As the Fighting God swung his fist down, he disappeared from my view. I felt something large get blasted away into the sky somewhere behind me. A little later there was a rumble as something hit the ground. What had happened? All I could see was the inside of this long skirt, and, above me, a pair of pale blue panties. The owner of said panties seemed familiar, though I couldn’t place them. But the other one, the wolf? I knew that wolf. I’d seen them before. As if I could forget! That way of moving, that sandy hair, that red-brown skin—plus the waving tail and animal ears.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Isolde","mixed":true,"attributionNote":"The long-skirted rescuer straddling Rudeus; Ghislaine is the wolf.","speakerConfidence":"medium"},{"id":"ch02-p0141","sourceIndex":141,"type":"speech","text":"“Ghislaine!” I cried. That meant the one with black hair had to be Isolde! Water Emperor Isolde! Ghislaine and Isolde had been working together!","html":"“Ghislaine!” I cried. That meant the one with black hair had to be Isolde! Water Emperor Isolde! Ghislaine and Isolde had been working together!","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch02-p0142","sourceIndex":142,"type":"speech","text":"“Sylphie!”","html":"“Sylphie!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","speakerConfidence":"high"},{"id":"ch02-p0143","sourceIndex":143,"type":"narration","text":"Sylphie came darting onto the battlefield like a mouse. She went over to the fallen and simply laid her hands on them. It only took that much for their wounds to heal. Before I knew it, she’d healed Dohga and Zanoba. She was using unvoiced casting. Until now, I hadn’t really considered that it had this advantage—I hadn’t had the chance. Now I saw it, it was clear as day. She was crazy fast. Faster than me and Cliff together. As I watched, Eris and Ruijerd emerged from the bushes and returned to the battlefield, and before I knew it, our line of battle was back on its feet. Isolde took the main shield position with Dohga and Zanoba relegated to sub-shields. Eris, Ghislaine, and Ruijerd were our attackers. And now, we had Sylphie and her unvoiced healing magic as our healer. Our battle line was standing.","html":"Sylphie came darting onto the battlefield like a mouse. She went over to the fallen and simply laid her hands on them. It only took that much for their wounds to heal. Before I knew it, she’d healed Dohga and Zanoba. She was using unvoiced casting. Until now, I hadn’t really considered that it had this advantage—I hadn’t had the chance. Now I saw it, it was clear as day. She was crazy fast. Faster than me and Cliff together. As I watched, Eris and Ruijerd emerged from the bushes and returned to the battlefield, and before I knew it, our line of battle was back on its feet. Isolde took the main shield position with Dohga and Zanoba relegated to sub-shields. Eris, Ghislaine, and Ruijerd were our attackers. And now, we had Sylphie and her unvoiced healing magic as our healer. Our battle line was standing.","className":"P_Prose_Formatting__And__Page_Break","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0144","sourceIndex":144,"type":"narration","text":"We’d made it out of hell.","html":"We’d made it out of hell.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0145","sourceIndex":145,"type":"speech","text":"“Rudy!” Sylphie called. “I’ll hold him down here, so you get to the village! Roxy’s waiting for you there!”","html":"“Rudy!” Sylphie called. “I’ll hold him down here, so you get to the village! Roxy’s waiting for you there!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","mixed":true,"speakerConfidence":"high"},{"id":"ch02-p0146","sourceIndex":146,"type":"speech","text":"“Got it!” With that, I set off running for the Superd village at an all-out sprint. I ran harder than I ever had in my life.","html":"“Got it!” With that, I set off running for the Superd village at an all-out sprint. I ran harder than I ever had in my life.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch02-p0147","sourceIndex":147,"type":"narration","text":"Sylphie had come. Even though I’d brought the bridge over the ravine down, she was here. That meant she must have come from the village, and that meant that the card I’d been keeping in reserve had arrived at last. Jumping over tree roots and plunging on through the trees, I finally made it back to the Superd Village. What I saw there filled me with joy. The moment I entered the village, there it was, in the distance. The thing I’d been holding out for sat on top of the teleportation circle I’d drawn up in preparation in the back of the village. I kept running as fast as I could.","html":"Sylphie had come. Even though I’d brought the bridge over the ravine down, she was here. That meant she must have come from the village, and that meant that the card I’d been keeping in reserve had arrived at last. Jumping over tree roots and plunging on through the trees, I finally made it back to the Superd Village. What I saw there filled me with joy. The moment I entered the village, there it was, in the distance. The thing I’d been holding out for sat on top of the teleportation circle I’d drawn up in preparation in the back of the village. I kept running as fast as I could.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0148","sourceIndex":148,"type":"speech","text":"“Big Brother!”","html":"“Big Brother!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Norn","attributionNote":"Norn or Julie calling out; Norn is the likelier of the two.","speakerConfidence":"medium"},{"id":"ch02-p0149","sourceIndex":149,"type":"speech","text":"“Grand Master!”","html":"“Grand Master!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Aisha","speakerConfidence":"high"},{"id":"ch02-p0150","sourceIndex":150,"type":"speech","text":"“Oh, Big Bro…”","html":"“Oh, Big Bro…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Julie","attributionNote":"The second 'Big Brother' call; Norn and Julie both use it.","speakerConfidence":"medium"},{"id":"ch02-p0151","sourceIndex":151,"type":"narration","text":"On the way, I passed Norn, Julie, and Aisha, but I ignored them. I just kept running until I reached it. A girl sat on the ground near the broken teleportation circle. She looked exhausted.","html":"On the way, I passed Norn, Julie, and Aisha, but I ignored them. I just kept running until I reached it. A girl sat on the ground near the broken teleportation circle. She looked exhausted.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0152","sourceIndex":152,"type":"speech","text":"“Roxy!” I cried.","html":"“Roxy!” I cried.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch02-p0153","sourceIndex":153,"type":"narration","text":"She looked up at me. “Oh, Rudy.” There were dark rings under her eyes, like she was out of mana or hadn’t slept in days. “I’m so sorry. I messed up the procedure. I dug it out, then after I’d gotten it up, I started working on the teleportation circle. If I’d drawn the teleportation circle first, then had you dig it up, I wouldn’t have been so late…”","html":"She looked up at me. “Oh, Rudy.” There were dark rings under her eyes, like she was out of mana or hadn’t slept in days. “I’m so sorry. I messed up the procedure. I dug it out, then after I’d gotten it up, I started working on the teleportation circle. If I’d drawn the teleportation circle first, then had you dig it up, I wouldn’t have been so late…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Roxy","embeddedDialogue":true,"attributionNote":"Narration with Roxy's apology.","speakerConfidence":"high"},{"id":"ch02-p0154","sourceIndex":154,"type":"speech","text":"“That’s fine! It’s all fine! You got here in time!”","html":"“That’s fine! It’s all fine! You got here in time!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch02-p0155","sourceIndex":155,"type":"narration","text":"Behind her was a giant set of armor.","html":"Behind her was a giant set of armor.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0156","sourceIndex":156,"type":"narration","text":"Three meters tall and dark blue, its right hand was equipped with the Gatling gun and its left with a shotgun. Besides that, there was a magic sword with the power to ignore all defenses clenched in its fist. The armor was as thick and hefty as a sumo wrestler’s body; it was lying face down. It didn’t look that different from the Version One, but this was not the Version One. This armor, gotten ready just in case of an occasion such as this, was my honest-to-god trump card. It was a weapon for short, decisive battles. Increasing its mana consumption several times over gave it massively improved mobility and ­armor. In concept, it was the inverse of the Version Three, and so we’d named it—","html":"Three meters tall and dark blue, its right hand was equipped with the Gatling gun and its left with a shotgun. Besides that, there was a magic sword with the power to ignore all defenses clenched in its fist. The armor was as thick and hefty as a sumo wrestler’s body; it was lying face down. It didn’t look that different from the Version One, but this was not the Version One. This armor, gotten ready just in case of an occasion such as this, was my honest-to-god trump card. It was a weapon for short, decisive battles. Increasing its mana consumption several times over gave it massively improved mobility and ­armor. In concept, it was the inverse of the Version Three, and so we’d named it—","className":"P_Prose_Formatting__And__Page_Break","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0157","sourceIndex":157,"type":"speech","text":"“This is the Magic Armor Version Zero,” Roxy said.","html":"“This is the Magic Armor Version Zero,” Roxy said.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Roxy","speakerConfidence":"high"},{"id":"ch02-p0158","sourceIndex":158,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch02-p0159","sourceIndex":159,"type":"narration","text":"This was my ace up my sleeve. My trump card. If I couldn’t win with this… Scratch that. Useless way of thinking about it. The odds were against me regardless.","html":"This was my ace up my sleeve. My trump card. If I couldn’t win with this… Scratch that. Useless way of thinking about it. The odds were against me regardless.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0160","sourceIndex":160,"type":"speech","text":"“I’ll be back soon, Roxy!”","html":"“I’ll be back soon, Roxy!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch02-p0161","sourceIndex":161,"type":"speech","text":"“Good luck in the battle, Rudy!”","html":"“Good luck in the battle, Rudy!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Roxy","speakerConfidence":"high"},{"id":"ch02-p0162","sourceIndex":162,"type":"narration","text":"I got into the Version Zero. The sensation of so much mana being drawn out of me made me a little dizzy as I stood up. Then, I saw Orsted standing in the center of the village. He was holding a gigantic sword.","html":"I got into the Version Zero. The sensation of so much mana being drawn out of me made me a little dizzy as I stood up. Then, I saw Orsted standing in the center of the village. He was holding a gigantic sword.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0163","sourceIndex":163,"type":"speech","text":"“Rudeus! Use it!” he shouted, then tossed the great blade to me like it weighed nothing at all. I caught it. It was just the right size for a three-meter-tall suit of armor. Even I, with my clumsy swordsmanship, could feel the awesome power it contained just by holding it.","html":"“Rudeus! Use it!” he shouted, then tossed the great blade to me like it weighed nothing at all. I caught it. It was just the right size for a three-meter-tall suit of armor. Even I, with my clumsy swordsmanship, could feel the awesome power it contained just by holding it.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","mixed":true,"speakerConfidence":"high"},{"id":"ch02-p0164","sourceIndex":164,"type":"narration","text":"This was the King Dragon Blade, Kajakut.","html":"This was the King Dragon Blade, Kajakut.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch02-p0165","sourceIndex":165,"type":"speech","text":"“Sir Orsted! I’ll be back soon!” I called. Orsted didn’t reply, only nodded.","html":"“Sir Orsted! I’ll be back soon!” I called. Orsted didn’t reply, only nodded.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch02-p0166","sourceIndex":166,"type":"narration","text":"Pushing the Version Zero as hard as it would go, I sped back to the battlefield.","html":"Pushing the Version Zero as hard as it would go, I sped back to the battlefield.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false}],"wordCount":2571,"speechCount":26,"speakers":["Aisha","Badigadi","Isolde","Julie","Norn","Orsted","Roxy","Rudeus","Sylphiette","Zanoba"]}],"images":[{"id":"ch02-img01","type":"image","src":"INTERIORIMAGES_02.jpg","alt":""},{"id":"ch02-img02","type":"image","src":"INTERIORIMAGES_03.jpg","alt":""}],"sequence":2,"cast":["Aisha","Atofe","Badigadi","Cliff","Dohga","Elinalise","Eris","Geese","Ghislaine","Isolde","Julie","Norn","Ogre God Marta","Orsted","Roxy","Rudeus","Ruijerd","Sandor","Superd Warrior","Sylphiette","Zanoba"],"sceneCount":6,"speechCount":49,"speakers":["Aisha","Badigadi","Isolde","Julie","Norn","Orsted","Roxy","Rudeus","Ruijerd","Sylphiette","Zanoba"]},{"id":"ch03","number":3,"title":"The Fifth Turning Point","pov":"Rudeus","kind":"main","wordCount":8657,"scenes":[{"id":"ch03-s01","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The forest near the Ravine of the Earthwyrm, the second round with the Fighting God","cast":["Badigadi","Cliff","Dohga","Eris","Geese","Ghislaine","Isolde","Rudeus","Ruijerd","Sylphiette","Zanoba"],"blocks":[{"id":"ch03-p0002","sourceIndex":2,"type":"narration","text":"WHEN I GOT BACK, Eris and the others were holding up just fine. They’d lost me and the Superd warriors, and Cliff and Elinalise were still not there, but things had stabilized. Ghislaine dashed about the battlefield, practically on all fours. The sweet spot of the Fighting God’s fist was high—he was a tall guy—so she kept low to the ground to avoid the range of the blast of wind it generated, slashing at him from the front, side, and back to assist the others. Ghislaine didn’t have enough offensive power, but from the way the Fighting God was waving his arms around, she was giving him a hard time.","html":"WHEN I GOT BACK, Eris and the others were holding up just fine. They’d lost me and the Superd warriors, and Cliff and Elinalise were still not there, but things had stabilized. Ghislaine dashed about the battlefield, practically on all fours. The sweet spot of the Fighting God’s fist was high—he was a tall guy—so she kept low to the ground to avoid the range of the blast of wind it generated, slashing at him from the front, side, and back to assist the others. Ghislaine didn’t have enough offensive power, but from the way the Fighting God was waving his arms around, she was giving him a hard time. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0003","sourceIndex":3,"type":"narration","text":"Sylphie’s presence was similarly massive. The situation called for faster recovery, so her unvoiced healing magic was a perfect fit. When the Fighting God sent Zanoba or Cliff flying, she’d be at their side and have them back on their feet in an instant. Sylphie had been off active duty for a long time now, so I thought she’d struggle to keep up with the physical demand, but she was single-handedly doing as much healing as Cliff and I had combined.","html":"Sylphie’s presence was similarly massive. The situation called for faster recovery, so her unvoiced healing magic was a perfect fit. When the Fighting God sent Zanoba or Cliff flying, she’d be at their side and have them back on their feet in an instant. Sylphie had been off active duty for a long time now, so I thought she’d struggle to keep up with the physical demand, but she was single-handedly doing as much healing as Cliff and I had combined. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0004","sourceIndex":4,"type":"narration","text":"I suppose I should give special mention to Isolde. She was out in front of the rest, deflecting all the Fighting God’s attacks against her and striking back with her own. She moved with grace and precision. Her technique made the Fighting God’s violent blows—any one of which could’ve been lethal—look like a child’s tantrum.","html":"I suppose I should give special mention to Isolde. She was out in front of the rest, deflecting all the Fighting God’s attacks against her and striking back with her own. She moved with grace and precision. Her technique made the Fighting God’s violent blows—any one of which could’ve been lethal—look like a child’s tantrum. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0005","sourceIndex":5,"type":"narration","text":"Obviously, she wasn’t going to defeat him like that. No matter how many flowing strikes she hit back at the Fighting God with or how many times she sliced into his arms or his legs, she didn’t do any damage. In a one-on-one battle, she might have given him a good fight, but she’d never have won. At some point, she’d get tired, and then it’d be over.","html":"Obviously, she wasn’t going to defeat him like that. No matter how many flowing strikes she hit back at the Fighting God with or how many times she sliced into his arms or his legs, she didn’t do any damage. In a one-on-one battle, she might have given him a good fight, but she’d never have won. At some point, she’d get tired, and then it’d be over.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0006","sourceIndex":6,"type":"narration","text":"When it came to buying time until I made it back, though, her presence was worth its weight in gold.","html":"When it came to buying time until I made it back, though, her presence was worth its weight in gold. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0007","sourceIndex":7,"type":"speech","text":"“Sorry for taking so long!” I called out to Sylphie.","html":"“Sorry for taking so long!” I called out to Sylphie.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0008","sourceIndex":8,"type":"speech","text":"“Rudy…! All of you, fall back!” At her signal, they all put distance between themselves and the Fighting God.","html":"“Rudy…! All of you, fall back!” At her signal, they all put distance between themselves and the Fighting God.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0009","sourceIndex":9,"type":"speech","text":"“Well, well.” Badigadi didn’t try to follow them, didn’t even spare them a glance. His eyes were on me.","html":"“Well, well.” Badigadi didn’t try to follow them, didn’t even spare them a glance. His eyes were on me. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0010","sourceIndex":10,"type":"narration","text":"We were about the same size. The Fighting God Armor was about two and a half meters tall. The Magic Armor was about three meters tall. Those few dozen centimeters meant I was only a little taller, and because I’d stopped to stand about ten meters away from him, it wasn’t enough to look down on him.","html":"We were about the same size. The Fighting God Armor was about two and a half meters tall. The Magic Armor was about three meters tall. Those few dozen centimeters meant I was only a little taller, and because I’d stopped to stand about ten meters away from him, it wasn’t enough to look down on him.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0011","sourceIndex":11,"type":"speech","text":"“That must be the Magic Armor that my dear sister bestowed upon the Dragon God in recognition of his worth!”","html":"“That must be the Magic Armor that my dear sister bestowed upon the Dragon God in recognition of his worth!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch03-p0012","sourceIndex":12,"type":"speech","text":"“Um…” I said hesitantly. “You saw the Version Once back at the port town, right?”","html":"“Um…” I said hesitantly. “You saw the Version Once back at the port town, right?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0013","sourceIndex":13,"type":"speech","text":"“Did I now?”","html":"“Did I now?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch03-p0014","sourceIndex":14,"type":"speech","text":"“Yup, only then you smashed it to pieces in a single blow.”","html":"“Yup, only then you smashed it to pieces in a single blow.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0015","sourceIndex":15,"type":"narration","text":"I thought back on that single blow. I’d taken the full impact because I’d overestimated my defenses, but still, it was amazing that Eris and Ruijerd were still alive after taking hits like that. It had to be the difference having a battle aura made to your defensive strength…though in that case, I had to worry about Cliff. He hadn’t taken a direct punch, but it wasn’t like he could cloak himself in the protection of a battle aura in the event that he did.","html":"I thought back on that single blow. I’d taken the full impact because I’d overestimated my defenses, but still, it was amazing that Eris and Ruijerd were still alive after taking hits like that. It had to be the difference having a battle aura made to your defensive strength…though in that case, I had to worry about Cliff. He hadn’t taken a direct punch, but it wasn’t like he could cloak himself in the protection of a battle aura in the event that he did.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0016","sourceIndex":16,"type":"speech","text":"“You said ‘Version One’. I take that to mean that this armor is different?”","html":"“You said ‘Version One’. I take that to mean that this armor is different?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch03-p0017","sourceIndex":17,"type":"speech","text":"“That’s for me to know and you to find out,” I said, looking around me. The others were standing around watching me from afar. Though there was a solid distance between us, they could still get caught in the crossfire.","html":"“That’s for me to know and you to find out,” I said, looking around me. The others were standing around watching me from afar. Though there was a solid distance between us, they could still get caught in the crossfire. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0018","sourceIndex":18,"type":"narration","text":"Oh, right. Sylphie was going around the remaining wounded.","html":"Oh, right. Sylphie was going around the remaining wounded.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0019","sourceIndex":19,"type":"narration","text":"I’d trust her with Cliff for now.","html":"I’d trust her with Cliff for now.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0020","sourceIndex":20,"type":"speech","text":"“Shall we get this show on the road?”","html":"“Shall we get this show on the road?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch03-p0021","sourceIndex":21,"type":"narration","text":"The battle commenced.","html":"The battle commenced.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0022","sourceIndex":22,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":655,"speechCount":10,"speakers":["Badigadi","Rudeus","Sylphiette"]},{"id":"ch03-s02","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The forest near the Ravine of the Earthwyrm, the duel with the Fighting God","cast":["Badigadi","Cliff","Dohga","Eris","Ghislaine","Isolde","Rudeus","Ruijerd","Sylphiette","Zanoba"],"blocks":[{"id":"ch03-p0024","sourceIndex":24,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch03-p0025","sourceIndex":25,"type":"narration","text":"My Stone Cannon stood in for a starting bell to kick off the fight. I backed away, shooting Stone Cannons, with Badigadi hot on my heels. I was following the same pattern as my fight with Orsted: retreat and fire off Stone Cannons indiscriminately. Honestly, I’d thought it’d be a struggle to pull off that much, but the lumbering bulk of the Version Zero moved like a dream when I fed mana into the King Dragon Blade. This was what gravity manipulation felt like, huh? I felt like I could do anything with the sword in my hand—only, seeing as I hadn’t trained with it, I’d settle right now for making myself lighter.","html":"My Stone Cannon stood in for a starting bell to kick off the fight. I backed away, shooting Stone Cannons, with Badigadi hot on my heels. I was following the same pattern as my fight with Orsted: retreat and fire off Stone Cannons indiscriminately. Honestly, I’d thought it’d be a struggle to pull off that much, but the lumbering bulk of the Version Zero moved like a dream when I fed mana into the King Dragon Blade. This was what gravity manipulation felt like, huh? I felt like I could do anything with the sword in my hand—only, seeing as I hadn’t trained with it, I’d settle right now for making myself lighter.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0026","sourceIndex":26,"type":"speech","text":"“Fwahahahaha! I’ve had worse mosquito bites!” The Fighting God came after me, splintering trees and gouging holes in the earth. It was plain to see that my attacks weren’t doing much. Even at this close range, the Fighting God didn’t bother to dodge or deflect the Stone Cannons. They plunged straight into him then fell out of his back. He hadn’t taken any damage, or at least, that was how it looked. Orsted had said Stone Cannon might work, but it was doing nothing.","html":"“Fwahahahaha! I’ve had worse mosquito bites!” The Fighting God came after me, splintering trees and gouging holes in the earth. It was plain to see that my attacks weren’t doing much. Even at this close range, the Fighting God didn’t bother to dodge or deflect the Stone Cannons. They plunged straight into him then fell out of his back. He hadn’t taken any damage, or at least, that was how it looked. Orsted had said Stone Cannon might work, but it was doing nothing.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0027","sourceIndex":27,"type":"speech","text":"“Turning tail and running away, are you?” Badigadi called after me.","html":"“Turning tail and running away, are you?” Badigadi called after me.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0028","sourceIndex":28,"type":"narration","text":"I had some other things in mind. Once I’d led him where I wanted him, I aimed the shotgun at his feet, leaving a giant crater in the ground under his next step.","html":"I had some other things in mind. Once I’d led him where I wanted him, I aimed the shotgun at his feet, leaving a giant crater in the ground under his next step.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0029","sourceIndex":29,"type":"narration","text":"Badigadi stumbled. For a split second, he lost his balance. That’s when I closed.","html":"Badigadi stumbled. For a split second, he lost his balance. That’s when I closed.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0030","sourceIndex":30,"type":"speech","text":"“Guh?!”","html":"“Guh?!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch03-p0031","sourceIndex":31,"type":"narration","text":"I emptied the Gatling gun, then struck with the sword mounted on the back of my right hand. It sliced through the armor like a hot knife through butter, exposing black flesh.","html":"I emptied the Gatling gun, then struck with the sword mounted on the back of my right hand. It sliced through the armor like a hot knife through butter, exposing black flesh.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0032","sourceIndex":32,"type":"speech","text":"“Shotgun Trigger!” I bellowed, then fired. The blast sent Badigadi’s arm flying clean off.","html":"“Shotgun Trigger!” I bellowed, then fired. The blast sent Badigadi’s arm flying clean off. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0033","sourceIndex":33,"type":"speech","text":"“Fwahahaha! Payback time!”","html":"“Fwahahaha! Payback time!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","attributionNote":"Rudeus mimics Badigadi's laugh after the shot.","speakerConfidence":"medium"},{"id":"ch03-p0034","sourceIndex":34,"type":"narration","text":"I’d taken four hits myself. The Magic Armor shook all over from each impact, and I slid around ten meters back.","html":"I’d taken four hits myself. The Magic Armor shook all over from each impact, and I slid around ten meters back.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0035","sourceIndex":35,"type":"narration","text":"But I was okay. I’d managed to withstand a direct hit.","html":"But I was okay. I’d managed to withstand a direct hit.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0036","sourceIndex":36,"type":"speech","text":"“Oof!” Straight away, I wheeled around and went to retrieve Badigadi’s arm. It pulsated inside the golden gauntlet. I tossed it away.","html":"“Oof!” Straight away, I wheeled around and went to retrieve Badigadi’s arm. It pulsated inside the golden gauntlet. I tossed it away.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0037","sourceIndex":37,"type":"speech","text":"“Fwahahaha! Futile, all futile!” Badigadi’s arm regrew, popping right out of his shoulder…like a certain race of green aliens. “Hmph.”","html":"“Fwahahaha! Futile, all futile!” Badigadi’s arm regrew, popping right out of his shoulder…like a certain race of green aliens. “Hmph.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0038","sourceIndex":38,"type":"narration","text":"Oh, but it hadn’t been futile. His new arm was bare—it wasn’t covered by the armor.","html":"Oh, but it hadn’t been futile. His new arm was bare—it wasn’t covered by the armor.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0039","sourceIndex":39,"type":"speech","text":"“Oho! That’s how we’re doing this, are we? You’ve thought this through, boy!”","html":"“Oho! That’s how we’re doing this, are we? You’ve thought this through, boy!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch03-p0040","sourceIndex":40,"type":"narration","text":"Now, on the ground where I’d thrown the arm, there was a magic circle ready to go. The arm and the armor lay there and didn’t start regenerating. Maybe it was my imagination, but Badigadi looked like he’d shrunk.","html":"Now, on the ground where I’d thrown the arm, there was a magic circle ready to go. The arm and the armor lay there and didn’t start regenerating. Maybe it was my imagination, but Badigadi looked like he’d shrunk. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0041","sourceIndex":41,"type":"narration","text":"I hadn’t thought this through. I’d just guessed.","html":"I hadn’t thought this through. I’d just guessed.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0042","sourceIndex":42,"type":"narration","text":"The power of the Fighting God Armor made Badigadi faster and stronger, but he wasn’t that much faster than the master sword fighters I’d met. Orsted could outpace him, and maybe Alec, too. He was way faster than me usually, but I was wearing the Magic Armor; he wasn’t so fast that I couldn’t handle him. I was making good use of the experience I’d built up training with Orsted and Eris.","html":"The power of the Fighting God Armor made Badigadi faster and stronger, but he wasn’t that much faster than the master sword fighters I’d met. Orsted could outpace him, and maybe Alec, too. He was way faster than me usually, but I was wearing the Magic Armor; he wasn’t so fast that I couldn’t handle him. I was making good use of the experience I’d built up training with Orsted and Eris.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0043","sourceIndex":43,"type":"narration","text":"It was his extremely strong defense and durability that were frustrating me. The Fighting God Armor was hard. It might have been tougher than the Magic Armor—it was at least tough enough that Eris and the others might scratch it if they attacked with all their strength, but they had no chance of cutting off his head or limbs. The armor restored itself instantly and went on fighting like nothing had happened. Under normal circumstances, the person inside the armor would go on taking damage…but Immortal Demon King Badigadi couldn’t die.","html":"It was his extremely strong defense and durability that were frustrating me. The Fighting God Armor was hard. It might have been tougher than the Magic Armor—it was at least tough enough that Eris and the others might scratch it if they attacked with all their strength, but they had no chance of cutting off his head or limbs. The armor restored itself instantly and went on fighting like nothing had happened. Under normal circumstances, the person inside the armor would go on taking damage…but Immortal Demon King Badigadi couldn’t die.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0044","sourceIndex":44,"type":"narration","text":"The damage from Eris’s sword and Ruijerd’s spear should have penetrated the armor, but they did nothing against Badigadi. Whether they slashed, stabbed, or struck him, Badigadi healed instantly. Before long, the attackers would grow tired and then, they’d be easy pickings for the destructive power of those six arms.","html":"The damage from Eris’s sword and Ruijerd’s spear should have penetrated the armor, but they did nothing against Badigadi. Whether they slashed, stabbed, or struck him, Badigadi healed instantly. Before long, the attackers would grow tired and then, they’d be easy pickings for the destructive power of those six arms. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0045","sourceIndex":45,"type":"narration","text":"How were we going to beat him? Atofe had given me a hint. The figure of Immortal Demon King Atofe, rising again to stand against her foes no matter how many times she was struck down, stood for all the demon kings of the Demon Continent as a symbol of fear. There were two ways to beat her. The first was to cut all her limbs off and seal them so that they didn’t regenerate. This was the most conventional method. She’d been brought down twice this way in the past. It would take some heavy-duty barrier magic if you wanted to keep her sealed away for centuries, but simply fencing her in with advanced-level magic barriers would prevent her from coming back.","html":"How were we going to beat him? Atofe had given me a hint. The figure of Immortal Demon King Atofe, rising again to stand against her foes no matter how many times she was struck down, stood for all the demon kings of the Demon Continent as a symbol of fear. There were two ways to beat her. The first was to cut all her limbs off and seal them so that they didn’t regenerate. This was the most conventional method. She’d been brought down twice this way in the past. It would take some heavy-duty barrier magic if you wanted to keep her sealed away for centuries, but simply fencing her in with advanced-level magic barriers would prevent her from coming back. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0046","sourceIndex":46,"type":"narration","text":"The second way was to make her admit defeat. Immortal Demon King Atofe had her own rules that she usually fought by, and when she saw she’d lost by those rules, she’d surrender. Unfortunately, I didn’t see Badigadi giving up so easily. I decided we’d go with the first method.","html":"The second way was to make her admit defeat. Immortal Demon King Atofe had her own rules that she usually fought by, and when she saw she’d lost by those rules, she’d surrender. Unfortunately, I didn’t see Badigadi giving up so easily. I decided we’d go with the first method.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0047","sourceIndex":47,"type":"narration","text":"I had Cliff set up barrier magic circles throughout the forest in advance. They’d activate when I threw one of Badigadi’s limbs into them. I’d been worried that they wouldn’t work on the Fighting God Armor, but it hadn’t been a problem. My plan was to use this defense-negating sword to cut through the armor, tear his arms off, then seal them away. When I’d taken care of all six arms, I’d make Badigadi admit defeat. What I really wanted was to seal his whole body…but without Cliff, I couldn’t use that Magic Circle.","html":"I had Cliff set up barrier magic circles throughout the forest in advance. They’d activate when I threw one of Badigadi’s limbs into them. I’d been worried that they wouldn’t work on the Fighting God Armor, but it hadn’t been a problem. My plan was to use this defense-negating sword to cut through the armor, tear his arms off, then seal them away. When I’d taken care of all six arms, I’d make Badigadi admit defeat. What I really wanted was to seal his whole body…but without Cliff, I couldn’t use that Magic Circle. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0048","sourceIndex":48,"type":"speech","text":"“Gaaaah!” I bellowed, charging. I no longer cared about dealing damage. I didn’t know how much longer the Version Zero would keep running at full power. Maybe the King Dragon Blade had extended its uptime a little, but it still could power down at any moment. I had to keep this battle short and decisive.","html":"“Gaaaah!” I bellowed, charging. I no longer cared about dealing damage. I didn’t know how much longer the Version Zero would keep running at full power. Maybe the King Dragon Blade had extended its uptime a little, but it still could power down at any moment. I had to keep this battle short and decisive.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0049","sourceIndex":49,"type":"speech","text":"“Come, then, champion!” The Fighting God spread his arms wide as I closed in on him, sending his fist swinging around to meet me. I thrust my sword out in response to the incoming fist, meaning to counter. The agility of those six arms was mind-boggling, but after the last battle, I sort of knew what to expect. Today, I was on form.","html":"“Come, then, champion!” The Fighting God spread his arms wide as I closed in on him, sending his fist swinging around to meet me. I thrust my sword out in response to the incoming fist, meaning to counter. The agility of those six arms was mind-boggling, but after the last battle, I sort of knew what to expect. Today, I was on form.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0050","sourceIndex":50,"type":"narration","text":"I could dodge them.","html":"I could dodge them.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0051","sourceIndex":51,"type":"narration","text":"I cut into his lower left arm, jamming the barrel of the shotgun into the incision as I did so. I fired, and the arm was blasted off. Unfortunately, I couldn’t help leaving myself open for a split second. As the arm tore away, another fist plowed into me, and I went shooting back.","html":"I cut into his lower left arm, jamming the barrel of the shotgun into the incision as I did so. I fired, and the arm was blasted off. Unfortunately, I couldn’t help leaving myself open for a split second. As the arm tore away, another fist plowed into me, and I went shooting back.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0052","sourceIndex":52,"type":"speech","text":"“Ngh!”","html":"“Ngh!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0053","sourceIndex":53,"type":"narration","text":"A crack split the front of the Magic Armor. In the end, it couldn’t withstand the fists of the Fighting God. Still, I could ignore the unarmored arms.","html":"A crack split the front of the Magic Armor. In the end, it couldn’t withstand the fists of the Fighting God. Still, I could ignore the unarmored arms.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0054","sourceIndex":54,"type":"narration","text":"Four more to go. My armor only had to last until I’d taken them all off.","html":"Four more to go. My armor only had to last until I’d taken them all off.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0055","sourceIndex":55,"type":"narration","text":"I started. Something else had caught my eye.","html":"I started. Something else had caught my eye.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0056","sourceIndex":56,"type":"narration","text":"The barrier. In our last exchange of blows, the aftermath of the battle had scraped the magic circle off the ground. It had happened so easily I couldn’t believe it hadn’t occurred to me. Some magic circles remained, but I didn’t know how many or where they were.","html":"The barrier. In our last exchange of blows, the aftermath of the battle had scraped the magic circle off the ground. It had happened so easily I couldn’t believe it hadn’t occurred to me. Some magic circles remained, but I didn’t know how many or where they were.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0057","sourceIndex":57,"type":"speech","text":"“Damnit!” I choked out, then quickly hurled the arm as far as I could throw it. It sailed off down into the Earthwyrm Ravine. It had taken Atofe a while to recover after she’d been cut into pieces. By putting distance between Badigadi and his severed limbs, he wouldn’t be able to restore them right away. They’d come back eventually… But it had to be worth something to make that feat take longer.","html":"“Damnit!” I choked out, then quickly hurled the arm as far as I could throw it. It sailed off down into the Earthwyrm Ravine. It had taken Atofe a while to recover after she’d been cut into pieces. By putting distance between Badigadi and his severed limbs, he wouldn’t be able to restore them right away. They’d come back eventually… But it had to be worth something to make that feat take longer.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0058","sourceIndex":58,"type":"narration","text":"Hm? For some reason, the armor wasn’t regenerating. Did it become nonoperative when separated from the wearer, even if it wasn’t sealed? Had long years of disuse even caused the Fighting Armor to lose some of its performance? Lousy excuse for regeneration, if so.","html":"Hm? For some reason, the armor wasn’t regenerating. Did it become nonoperative when separated from the wearer, even if it wasn’t sealed? Had long years of disuse even caused the Fighting Armor to lose some of its performance? Lousy excuse for regeneration, if so.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0059","sourceIndex":59,"type":"narration","text":"Or was this all Badigadi’s ruse?","html":"Or was this all Badigadi’s ruse?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0060","sourceIndex":60,"type":"narration","text":"Never mind. Now wasn’t the time for pointless worrying. His failure to regenerate was an opportunity. The only thing to think about was cutting off the rest of those arms.","html":"Never mind. Now wasn’t the time for pointless worrying. His failure to regenerate was an opportunity. The only thing to think about was cutting off the rest of those arms.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0061","sourceIndex":61,"type":"speech","text":"“Grr…” Badigadi grumbled, but no new arm sprouted from the stump. Instead, the arm he’d regenerated earlier retracted into the armor like a turtle going into its shell.","html":"“Grr…” Badigadi grumbled, but no new arm sprouted from the stump. Instead, the arm he’d regenerated earlier retracted into the armor like a turtle going into its shell.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0062","sourceIndex":62,"type":"speech","text":"“Eh?!”","html":"“Eh?!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0063","sourceIndex":63,"type":"narration","text":"What’s going on?","html":"What’s going on? ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0064","sourceIndex":64,"type":"narration","text":"In a second, two of the remaining four arms disappeared into the body of the armor, gauntlets and all. Then, the last two arms grew thicker. There was a straining metal noise as they swelled.","html":"In a second, two of the remaining four arms disappeared into the body of the armor, gauntlets and all. Then, the last two arms grew thicker. There was a straining metal noise as they swelled. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0065","sourceIndex":65,"type":"narration","text":"Okay, the last two arms were bigger now. Too difficult to cut? No, I could manage it. This sword hit more effectively against tougher targets. The Fighting God could strengthen his arms and reinforce his defenses all he liked and it wouldn’t matter.","html":"Okay, the last two arms were bigger now. Too difficult to cut? No, I could manage it. This sword hit more effectively against tougher targets. The Fighting God could strengthen his arms and reinforce his defenses all he liked and it wouldn’t matter. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0066","sourceIndex":66,"type":"narration","text":"Making a split-second decision, I kicked off and charged at the Fighting God. An alarm bell was ringing somewhere in my mind, but I ignored it. Whatever Badigadi did now, I’d already laid my trump card on the table. My mana was getting closer to zero with every passing moment. Unless I attacked, I couldn’t win.","html":"Making a split-second decision, I kicked off and charged at the Fighting God. An alarm bell was ringing somewhere in my mind, but I ignored it. Whatever Badigadi did now, I’d already laid my trump card on the table. My mana was getting closer to zero with every passing moment. Unless I attacked, I couldn’t win.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0067","sourceIndex":67,"type":"speech","text":"“Gaaaah!”","html":"“Gaaaah!” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0068","sourceIndex":68,"type":"narration","text":"I yelled. Shouting helped generate power. I squashed my fear and uncertainty and let a little courage show on my face. It was the little bit of courage I needed to plunge in further. It enabled me to charge in, like Eris did, toward victory.","html":"I yelled. Shouting helped generate power. I squashed my fear and uncertainty and let a little courage show on my face. It was the little bit of courage I needed to plunge in further. It enabled me to charge in, like Eris did, toward victory.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0069","sourceIndex":69,"type":"narration","text":"I rammed into the Fighting God. He absorbed the impact, but he stumbled. I swung my right fist. It bit into his left arm and out the other side. Then, I stabbed with my left, pushing the shotgun into the gash.","html":"I rammed into the Fighting God. He absorbed the impact, but he stumbled. I swung my right fist. It bit into his left arm and out the other side. Then, I stabbed with my left, pushing the shotgun into the gash.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0070","sourceIndex":70,"type":"speech","text":"“Shotgun Trigger!” I shouted, and Badigadi’s Fighting Armor-encased arm went flying. Only, I was knocked back too. Badigadi had punched me with his one remaining arm. The front surface of my armor was smashed to pieces, and the impact had penetrated through it. I felt like my body was going to be crushed flat. I fell backward.","html":"“Shotgun Trigger!” I shouted, and Badigadi’s Fighting Armor-encased arm went flying. Only, I was knocked back too. Badigadi had punched me with his one remaining arm. The front surface of my armor was smashed to pieces, and the impact had penetrated through it. I felt like my body was going to be crushed flat. I fell backward.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0071","sourceIndex":71,"type":"speech","text":"“Hurgh…rghh…” Blood bubbled up from my throat. My heart was screaming, Not yet! But it was no good. He’d outplayed me. I hadn’t seen it coming. He’d merged his arms together to make his attacks stronger. Lose an arm, win the war, so to speak. He’d driven his fist into the crack in the Magic Armor with unerring precision and shattered it. Why hadn’t that occurred to me when I saw his arms get thicker? Was I a moron?","html":"“Hurgh…rghh…” Blood bubbled up from my throat. My heart was screaming, Not yet! But it was no good. He’d outplayed me. I hadn’t seen it coming. He’d merged his arms together to make his attacks stronger. Lose an arm, win the war, so to speak. He’d driven his fist into the crack in the Magic Armor with unerring precision and shattered it. Why hadn’t that occurred to me when I saw his arms get thicker? Was I a moron?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0072","sourceIndex":72,"type":"narration","text":"No, you’re fine. This is okay. You’d have done the same thing even if you’d seen it coming.","html":"No, you’re fine. This is okay. You’d have done the same thing even if you’d seen it coming. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0073","sourceIndex":73,"type":"narration","text":"I charged in thoughtlessly and I’d ended up cutting one arm off.","html":"I charged in thoughtlessly and I’d ended up cutting one arm off.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0074","sourceIndex":74,"type":"narration","text":"I’d taken some heavy damage…but it wasn’t over yet. There was still one arm left.","html":"I’d taken some heavy damage…but it wasn’t over yet. There was still one arm left.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0075","sourceIndex":75,"type":"narration","text":"Then, to my shock, I realized I wasn’t moving. The Magic Armor felt heavy. And my wounds weren’t healing. Right next to where my body sat in the Magic Armor, there was a part that was essentially its core. Breaking that would cause the armor to lose mobility. It wouldn’t stop moving entirely, mind. It wasn’t so simple a machine. Still, it would be massively limited. Fatal in a battle like this.","html":"Then, to my shock, I realized I wasn’t moving. The Magic Armor felt heavy. And my wounds weren’t healing. Right next to where my body sat in the Magic Armor, there was a part that was essentially its core. Breaking that would cause the armor to lose mobility. It wouldn’t stop moving entirely, mind. It wasn’t so simple a machine. Still, it would be massively limited. Fatal in a battle like this.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0076","sourceIndex":76,"type":"narration","text":"Panicking, I sent out mana. Right, I had mana left. I could still move, I wasn’t fully drained. I could fight. So why wasn’t I moving?","html":"Panicking, I sent out mana. Right, I had mana left. I could still move, I wasn’t fully drained. I could fight. So why wasn’t I moving?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0077","sourceIndex":77,"type":"speech","text":"“A good plan, and such spirit…” While I lay there, unable to move, Badigadi approached. “And you gave me a good fight. Farewell, Rudeus. Not even Laplace dreamed of such an elaborate scheme.”","html":"“A good plan, and such spirit…” While I lay there, unable to move, Badigadi approached. “And you gave me a good fight. Farewell, Rudeus. Not even Laplace dreamed of such an elaborate scheme.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0078","sourceIndex":78,"type":"narration","text":"He raised his cannon-like fist above his head, then brought it swinging—","html":"He raised his cannon-like fist above his head, then brought it swinging—","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0079","sourceIndex":79,"type":"speech","text":"“Guh!” Badigadi grunted as something red rammed into him from the side. Whatever-it was slashed at his arm, severing it at the shoulder and sending it flying off through the air.","html":"“Guh!” Badigadi grunted as something red rammed into him from the side. Whatever-it was slashed at his arm, severing it at the shoulder and sending it flying off through the air.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0080","sourceIndex":80,"type":"speech","text":"“Grr!”","html":"“Grr!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Eris","speakerConfidence":"high"},{"id":"ch03-p0081","sourceIndex":81,"type":"narration","text":"There was only one red something in this forest: Eris. Could it be? Had she followed me? Had she been at my side this whole time—here with me?","html":"There was only one red something in this forest: Eris. Could it be? Had she followed me? Had she been at my side this whole time—here with me?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0082","sourceIndex":82,"type":"narration","text":"I didn’t know. No other support arrived. Eris had come charging in alone. A moment later, I noticed something off. It was her sword. Eris’s sword was broken. The famed Phoenix Dragon Sword had snapped off at the hilt. Of course. Up until now, any damage we’d done to the outside of the armor hadn’t been enough to cut Badigadi’s arms off. She’d forced her sword to cut straight through. Any sword would break.","html":"I didn’t know. No other support arrived. Eris had come charging in alone. A moment later, I noticed something off. It was her sword. Eris’s sword was broken. The famed Phoenix Dragon Sword had snapped off at the hilt. Of course. Up until now, any damage we’d done to the outside of the armor hadn’t been enough to cut Badigadi’s arms off. She’d forced her sword to cut straight through. Any sword would break.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0083","sourceIndex":83,"type":"speech","text":"“Gyaaaah!” Her sword broken, Eris refused to stop. She faced down the Fighting God as though she hadn’t even noticed, howling all the way. Looking around, I saw she wasn’t alone. Following her out of the forest, one after another, came Sylphie, Ruijerd, Ghislaine, and Isolde. But they were too slow.","html":"“Gyaaaah!” Her sword broken, Eris refused to stop. She faced down the Fighting God as though she hadn’t even noticed, howling all the way. Looking around, I saw she wasn’t alone. Following her out of the forest, one after another, came Sylphie, Ruijerd, Ghislaine, and Isolde. But they were too slow.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Eris","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0084","sourceIndex":84,"type":"speech","text":"“Only a fool would dare to stand in my way alone!” Badigadi said, advancing on Eris. There was no one to protect her. Without hesitation, I activated the escape circuits and ejected from the Magic Armor. Strapped on its back was a sword.","html":"“Only a fool would dare to stand in my way alone!” Badigadi said, advancing on Eris. There was no one to protect her. Without hesitation, I activated the escape circuits and ejected from the Magic Armor. Strapped on its back was a sword. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0085","sourceIndex":85,"type":"narration","text":"The moment I gripped the hilt, a feeling of awesome, unlimited power rushed through my body. The sword contained a staggering volume of mana. It was a sword crafted specifically to make a person into a hero. I poured yet more mana into it, trying to wring out every last drop I had left.","html":"The moment I gripped the hilt, a feeling of awesome, unlimited power rushed through my body. The sword contained a staggering volume of mana. It was a sword crafted specifically to make a person into a hero. I poured yet more mana into it, trying to wring out every last drop I had left. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0086","sourceIndex":86,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch03-p0087","sourceIndex":87,"type":"narration","text":"I doubted I could use it myself. But a member of my family was standing in front of me with a broken sword raised before her, growling with her teeth bared, and all to protect me.","html":"I doubted I could use it myself. But a member of my family was standing in front of me with a broken sword raised before her, growling with her teeth bared, and all to protect me. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0088","sourceIndex":88,"type":"narration","text":"I threw the blade to her.","html":"I threw the blade to her.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0089","sourceIndex":89,"type":"speech","text":"“Eris!” The magic sword flew in a lazy curve through the air to where Eris turned and caught it.","html":"“Eris!” The magic sword flew in a lazy curve through the air to where Eris turned and caught it. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0090","sourceIndex":90,"type":"narration","text":"It was the King Dragon Blade Kajukut, renowned for being the most powerful sword in the world, and the greatest of the magic swords forged by the great demon bladesmith Julian Harisco.","html":"It was the King Dragon Blade Kajukut, renowned for being the most powerful sword in the world, and the greatest of the magic swords forged by the great demon bladesmith Julian Harisco.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0091","sourceIndex":91,"type":"narration","text":"Eris raised it high above her head.","html":"Eris raised it high above her head.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0092","sourceIndex":92,"type":"speech","text":"“Gyaaaaaah!”","html":"“Gyaaaaaah!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Eris","speakerConfidence":"high"},{"id":"ch03-p0093","sourceIndex":93,"type":"speech","text":"“Hrm? Surely not…!”","html":"“Hrm? Surely not…!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch03-p0094","sourceIndex":94,"type":"narration","text":"She brought the blade down. In the split second before it made contact, the Fighting God’s body floated into the air.","html":"She brought the blade down. In the split second before it made contact, the Fighting God’s body floated into the air.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0095","sourceIndex":95,"type":"narration","text":"The blade sliced into him with a flash of light that blotted out my vision. The ensuing explosion blew out my eardrums.","html":"The blade sliced into him with a flash of light that blotted out my vision. The ensuing explosion blew out my eardrums.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0096","sourceIndex":96,"type":"narration","text":"We were at the mercy of an overwhelming force.","html":"We were at the mercy of an overwhelming force.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0097","sourceIndex":97,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch03-p0098","sourceIndex":98,"type":"narration","text":"Destruction blossomed.","html":"Destruction blossomed.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0099","sourceIndex":99,"type":"narration","text":"There was no blast wave, no shock wave. Only silence. The destruction was all directed inward. All that mana driven into the blade became a sphere that enveloped Badigadi. The sword had released not only Eris’s strength, but all the mana I had put into it.","html":"There was no blast wave, no shock wave. Only silence. The destruction was all directed inward. All that mana driven into the blade became a sphere that enveloped Badigadi. The sword had released not only Eris’s strength, but all the mana I had put into it.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0100","sourceIndex":100,"type":"narration","text":"I looked into the sphere of mana as it destroyed everything within it while it rose slowly into the air. I watched cracks appear in the Fighting God Armor. It fell to pieces. Badigadi was compressed within the mass of energy and then faded into dust without even a murmur.","html":"I looked into the sphere of mana as it destroyed everything within it while it rose slowly into the air. I watched cracks appear in the Fighting God Armor. It fell to pieces. Badigadi was compressed within the mass of energy and then faded into dust without even a murmur.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0101","sourceIndex":101,"type":"narration","text":"I think he struggled, but there was nothing he could do. The Fighting God Armor didn’t function, and Badigadi was crushed even as he tried to regenerate.","html":"I think he struggled, but there was nothing he could do. The Fighting God Armor didn’t function, and Badigadi was crushed even as he tried to regenerate.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0102","sourceIndex":102,"type":"narration","text":"The sphere vanished. The broken remains of the armor fell into the Earthwyrm Ravine. There were some clangs and clatters as they fell away, bouncing off the cliff walls, and the King Dragon Blade, still impaled in the metal, went with them.","html":"The sphere vanished. The broken remains of the armor fell into the Earthwyrm Ravine. There were some clangs and clatters as they fell away, bouncing off the cliff walls, and the King Dragon Blade, still impaled in the metal, went with them.","className":"P_Prose_Formatting__And__Page_Break","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0103","sourceIndex":103,"type":"narration","text":"All that remained was the armor. All traces of Badigadi’s black flesh had vanished.","html":"All that remained was the armor. All traces of Badigadi’s black flesh had vanished.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0104","sourceIndex":104,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch03-p0105","sourceIndex":105,"type":"narration","text":"For a good while, I stared. I stared both at the now silent ravine, and after the Fighting God Armor that had since vanished from sight. Badigadi’s arm lay nearby. It didn’t move or even twitch. It definitely didn’t look like it was about to start regenerating. Was he dead? Did we win, or was something else coming? Any moment now, was I going to hear a “Fwahaha!” as Badigadi returned?","html":"For a good while, I stared. I stared both at the now silent ravine, and after the Fighting God Armor that had since vanished from sight. Badigadi’s arm lay nearby. It didn’t move or even twitch. It definitely didn’t look like it was about to start regenerating. Was he dead? Did we win, or was something else coming? Any moment now, was I going to hear a “Fwahaha!” as Badigadi returned?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0106","sourceIndex":106,"type":"narration","text":"I stared down into the ravine, wondering. Nothing happened. I saw no sign of anything coming back up. All that was left was silence.","html":"I stared down into the ravine, wondering. Nothing happened. I saw no sign of anything coming back up. All that was left was silence. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0107","sourceIndex":107,"type":"narration","text":"I heard a thud from behind me and turned. Eris had fallen to her knees, her face pale. I rushed over to her. Was she injured? Had Badigadi got in a counterstrike? I reached out my hand, thinking I had to heal her right away, but then I sank to my knees as well.","html":"I heard a thud from behind me and turned. Eris had fallen to her knees, her face pale. I rushed over to her. Was she injured? Had Badigadi got in a counterstrike? I reached out my hand, thinking I had to heal her right away, but then I sank to my knees as well.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0108","sourceIndex":108,"type":"speech","text":"“Ohh…” It wasn’t an injury. I recognized this sensation, as well as the look of Eris’s face. This was mana drain. Sucking out all my mana hadn’t been enough to satiate the King Dragon Blade Kajakut. It had used up Eris’s mana as well. Eris probably hadn’t experienced mana drain since childhood. She sank back, blinking.","html":"“Ohh…” It wasn’t an injury. I recognized this sensation, as well as the look of Eris’s face. This was mana drain. Sucking out all my mana hadn’t been enough to satiate the King Dragon Blade Kajakut. It had used up Eris’s mana as well. Eris probably hadn’t experienced mana drain since childhood. She sank back, blinking.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0109","sourceIndex":109,"type":"speech","text":"“Eris.”","html":"“Eris.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Eris","speakerConfidence":"high"},{"id":"ch03-p0110","sourceIndex":110,"type":"speech","text":"“Rudeus…” she said. “Your hair’s gotten whiter.”","html":"“Rudeus…” she said. “Your hair’s gotten whiter.” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Eris","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0111","sourceIndex":111,"type":"narration","text":"I put a hand to my head, although I couldn’t tell myself. But returning her regard, I saw that one lock of her hair had turned white as well, like she’d put a streak in it.","html":"I put a hand to my head, although I couldn’t tell myself. But returning her regard, I saw that one lock of her hair had turned white as well, like she’d put a streak in it.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0112","sourceIndex":112,"type":"speech","text":"“Yours too, Eris.”","html":"“Yours too, Eris.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0113","sourceIndex":113,"type":"speech","text":"“Huh… Then I guess we match,” she said, then toppled forward. She hadn’t fainted. She was only weak after using up all her strength. I wanted to fall on top of her, but I held myself firmly back.","html":"“Huh… Then I guess we match,” she said, then toppled forward. She hadn’t fainted. She was only weak after using up all her strength. I wanted to fall on top of her, but I held myself firmly back.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Eris","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0114","sourceIndex":114,"type":"speech","text":"“Rudy!” Sylphie was peering at us, worry in her eyes. She wasn’t alone, either. Ruijerd, Ghislaine, Isolde…they were all here.","html":"“Rudy!” Sylphie was peering at us, worry in her eyes. She wasn’t alone, either. Ruijerd, Ghislaine, Isolde…they were all here.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0115","sourceIndex":115,"type":"speech","text":"“Sylphie, where’s Cliff?!”","html":"“Sylphie, where’s Cliff?!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0116","sourceIndex":116,"type":"speech","text":"“Um, well, someone else healed his wounds, then Zanoba and Dohga carried him back to the village. All of us here came straight after you, but then I didn’t want to get in the way, so I hesitated… But Eris ran in alone—huh?” Sylphie had laid a hand on Eris’s prone body, and now she looked puzzled. She’d probably cast a healing spell on sheer reflex. But Eris wasn’t wounded, so she didn’t get up.","html":"“Um, well, someone else healed his wounds, then Zanoba and Dohga carried him back to the village. All of us here came straight after you, but then I didn’t want to get in the way, so I hesitated… But Eris ran in alone—huh?” Sylphie had laid a hand on Eris’s prone body, and now she looked puzzled. She’d probably cast a healing spell on sheer reflex. But Eris wasn’t wounded, so she didn’t get up.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0117","sourceIndex":117,"type":"speech","text":"“I think it’s mana drain. That sword consumes the mana of whoever wields it.”","html":"“I think it’s mana drain. That sword consumes the mana of whoever wields it.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0118","sourceIndex":118,"type":"speech","text":"“Oh. All right, then.”","html":"“Oh. All right, then.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","speakerConfidence":"high"},{"id":"ch03-p0119","sourceIndex":119,"type":"speech","text":"“Anyway, Sylphie, those arms over there—get them to an undamaged magic circle. Then get Eris back to the village. I need you to tell Sir Orsted what happened, then bring Cliff here.”","html":"“Anyway, Sylphie, those arms over there—get them to an undamaged magic circle. Then get Eris back to the village. I need you to tell Sir Orsted what happened, then bring Cliff here.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0120","sourceIndex":120,"type":"narration","text":"I stood up. The Version Zero was in ruins, and my mana was practically exhausted…but I could still move. I didn’t know how much time it would take Badigadi to restore himself. After being crushed by that much mana, the way he’d disappeared looked like he’d been annihilated. And that was practically an understatement. The arms showed no signs of starting to regenerate, so I wanted to believe we had a while. Maybe that was naive. Wishful thinking. Most importantly, the Version Zero was destroyed, and the Version One was gone, too. I was on the verge of mana drain and Cliff, who could cast barrier magic, wasn’t here. Badigadi had fallen into the ravine, and we had no way of sealing him. If we went down there in this state and found him waiting for us, our chances of victory were close to nonexistent. There’d be nothing for it but to ask Orsted to take to the field. I wanted to get through this without him using any mana, but I might not have a choice.","html":"I stood up. The Version Zero was in ruins, and my mana was practically exhausted…but I could still move. I didn’t know how much time it would take Badigadi to restore himself. After being crushed by that much mana, the way he’d disappeared looked like he’d been annihilated. And that was practically an understatement. The arms showed no signs of starting to regenerate, so I wanted to believe we had a while. Maybe that was naive. Wishful thinking. Most importantly, the Version Zero was destroyed, and the Version One was gone, too. I was on the verge of mana drain and Cliff, who could cast barrier magic, wasn’t here. Badigadi had fallen into the ravine, and we had no way of sealing him. If we went down there in this state and found him waiting for us, our chances of victory were close to nonexistent. There’d be nothing for it but to ask Orsted to take to the field. I wanted to get through this without him using any mana, but I might not have a choice. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0121","sourceIndex":121,"type":"narration","text":"I wasn’t strong enough.","html":"I wasn’t strong enough. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0122","sourceIndex":122,"type":"narration","text":"Still, I’d driven Badigadi into a tight spot. I’d done everything I could. Whether Badigadi was up and about down there in the ravine, I didn’t know, but surely I’d brought him as low as it was possible for him to go.","html":"Still, I’d driven Badigadi into a tight spot. I’d done everything I could. Whether Badigadi was up and about down there in the ravine, I didn’t know, but surely I’d brought him as low as it was possible for him to go.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0123","sourceIndex":123,"type":"narration","text":"I felt disgust at my own weakness.","html":"I felt disgust at my own weakness.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0124","sourceIndex":124,"type":"speech","text":"“Ruijerd, Ghislaine, and you too, Isolde. Come with me, please.”","html":"“Ruijerd, Ghislaine, and you too, Isolde. Come with me, please.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0125","sourceIndex":125,"type":"speech","text":"“Rudy? Where are you going?”","html":"“Rudy? Where are you going?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","speakerConfidence":"high"},{"id":"ch03-p0126","sourceIndex":126,"type":"narration","text":"I thought I’d done everything I could, but there was still something else I had to finish. Even with my mana close to exhausted, I had to do it.","html":"I thought I’d done everything I could, but there was still something else I had to finish. Even with my mana close to exhausted, I had to do it.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0127","sourceIndex":127,"type":"speech","text":"“I’m going after Geese.”","html":"“I’m going after Geese.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0128","sourceIndex":128,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":3277,"speechCount":39,"speakers":["Badigadi","Eris","Rudeus","Sylphiette"]},{"id":"ch03-s03","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The burnt forest near the Ravine of the Earthwyrm, where Geese lies","cast":["Geese","Ghislaine","Isolde","Rudeus","Ruijerd"],"blocks":[{"id":"ch03-p0130","sourceIndex":130,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch03-p0131","sourceIndex":131,"type":"narration","text":"We found him straight away. Next to no effort. I didn’t even have to use what little mana I had left, it was that easy. The moment we crossed the ravine and entered the flame-blackened forest, there, in the shadow cast by the charred remains of a great tree, we found Geese lying on the ground. His whole body was charred dark by terrible burns. When I’d cast Flashover, it had burnt the forest and him with it. When I first saw him, I thought he was dead. He was so still he looked like a black boulder. But luckily Ruijerd had found him first, and he’d used his third eye to probe further. Geese wasn’t dead.","html":"We found him straight away. Next to no effort. I didn’t even have to use what little mana I had left, it was that easy. The moment we crossed the ravine and entered the flame-blackened forest, there, in the shadow cast by the charred remains of a great tree, we found Geese lying on the ground. His whole body was charred dark by terrible burns. When I’d cast Flashover, it had burnt the forest and him with it. When I first saw him, I thought he was dead. He was so still he looked like a black boulder. But luckily Ruijerd had found him first, and he’d used his third eye to probe further. Geese wasn’t dead.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0132","sourceIndex":132,"type":"speech","text":"“Geese,” I said.","html":"“Geese,” I said.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0133","sourceIndex":133,"type":"speech","text":"“Hey, boss.”","html":"“Hey, boss.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","speakerConfidence":"high"},{"id":"ch03-p0134","sourceIndex":134,"type":"narration","text":"He wasn’t dead, but it was clear he would be soon, and I wasn’t about to heal him. I was here to do the opposite…although I didn’t want to finish him off straight away, either.","html":"He wasn’t dead, but it was clear he would be soon, and I wasn’t about to heal him. I was here to do the opposite…although I didn’t want to finish him off straight away, either. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0135","sourceIndex":135,"type":"speech","text":"“Heh heh. Water magic, earth magic, the Magic Armor… I thought up ways to counter all of ’em, only for this to be what gets me. Didn’t know you had a knack for fire magic too, boss. Never once saw you use it.”","html":"“Heh heh. Water magic, earth magic, the Magic Armor… I thought up ways to counter all of ’em, only for this to be what gets me. Didn’t know you had a knack for fire magic too, boss. Never once saw you use it.” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","speakerConfidence":"high"},{"id":"ch03-p0136","sourceIndex":136,"type":"narration","text":"Geese had all sorts of items on him. He wore a blue vest with a brown band around his middle and something that looked like chainmail. It was hard to tell now, when they were practically burnt to a crisp, but they were presumably precautions against all kinds of magic. I guessed it hadn’t been the Fighting God Armor’s power that allowed him to survive Electric back in the Third City of Heirulil.","html":"Geese had all sorts of items on him. He wore a blue vest with a brown band around his middle and something that looked like chainmail. It was hard to tell now, when they were practically burnt to a crisp, but they were presumably precautions against all kinds of magic. I guessed it hadn’t been the Fighting God Armor’s power that allowed him to survive Electric back in the Third City of Heirulil.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0137","sourceIndex":137,"type":"speech","text":"“And now you’re here, boss, which I reckon must mean my final plan fizzled…” Geese’s scorched cheeks twisted. His final plan? I guess that depended on whether you called sending Badigadi out alone counted as a “plan.”","html":"“And now you’re here, boss, which I reckon must mean my final plan fizzled…” Geese’s scorched cheeks twisted. His final plan? I guess that depended on whether you called sending Badigadi out alone counted as a “plan.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0138","sourceIndex":138,"type":"speech","text":"“If any of ’em, the Sword God or the North God, the Ogre God, the Abyssal King…if there’d been just one more, things might’ve been different… None of ’em listened to me, y’know.”","html":"“If any of ’em, the Sword God or the North God, the Ogre God, the Abyssal King…if there’d been just one more, things might’ve been different… None of ’em listened to me, y’know.”","className":"P_Prose_Formatting__And__Page_Break","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","speakerConfidence":"high"},{"id":"ch03-p0139","sourceIndex":139,"type":"speech","text":"“Well, none of them were the best listeners,” I replied. Geese seemed half delirious.","html":"“Well, none of them were the best listeners,” I replied. Geese seemed half delirious.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0140","sourceIndex":140,"type":"speech","text":"“Hah, you’re one to talk. Eris, Atofe. That Ghislaine I see over there? You’re surrounded by folks who don’t know how to listen, yerself.”","html":"“Hah, you’re one to talk. Eris, Atofe. That Ghislaine I see over there? You’re surrounded by folks who don’t know how to listen, yerself.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","speakerConfidence":"high"},{"id":"ch03-p0141","sourceIndex":141,"type":"speech","text":"“Yeah, well… I guess I was lucky.”","html":"“Yeah, well… I guess I was lucky.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0142","sourceIndex":142,"type":"speech","text":"“Nah, that ain’t it. It’s ’cause you did things the right way. Told ’em what was goin’ on, won their trust, and then worked hard to make honest allies of ’em all. And that’s why, when push came to shove, they listened right and followed your orders right.”","html":"“Nah, that ain’t it. It’s ’cause you did things the right way. Told ’em what was goin’ on, won their trust, and then worked hard to make honest allies of ’em all. And that’s why, when push came to shove, they listened right and followed your orders right.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","speakerConfidence":"high"},{"id":"ch03-p0143","sourceIndex":143,"type":"narration","text":"He might’ve had a point. Atofe and the Ogre God, who I’d only joined forces with because I’d had to at the time, hardly listened to me at all. Sandor and Dohga were exceptions, but Ariel fit the pattern. If I hadn’t been able to build trust with everyone, there would have been more who refused to listen to me.","html":"He might’ve had a point. Atofe and the Ogre God, who I’d only joined forces with because I’d had to at the time, hardly listened to me at all. Sandor and Dohga were exceptions, but Ariel fit the pattern. If I hadn’t been able to build trust with everyone, there would have been more who refused to listen to me. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0144","sourceIndex":144,"type":"speech","text":"“Turns out just twistin’ things to make a reason to fight, scroungin’ people together, stirring ’em up, then sneakin’ around nudging ’em behind their backs just doesn’t work…”","html":"“Turns out just twistin’ things to make a reason to fight, scroungin’ people together, stirring ’em up, then sneakin’ around nudging ’em behind their backs just doesn’t work…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","speakerConfidence":"high"},{"id":"ch03-p0145","sourceIndex":145,"type":"narration","text":"Neither the Sword God nor the North God had followed Geese’s instructions. At the end of the day, they put their own interests first. That was why I was alive.","html":"Neither the Sword God nor the North God had followed Geese’s instructions. At the end of the day, they put their own interests first. That was why I was alive.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0146","sourceIndex":146,"type":"speech","text":"“I thought I knew what was what, but I was wrong. Still, I thought I’d pull it off somehow. Only then it turned the one who really didn’t know…wasn’t me.” Geese laughed. “The Man-God, y’know. He was throwin’ a real tantrum a little while ago. ‘Why?! Why?! It’s all your fault! Ya stupid ape!’” Geese flashed a careless, mocking smile. “I mean, what’d he expect? Who’s gonna lend an honest hand to a bastard who tricks and sneers at the folks that work their hardest for him?”","html":"“I thought I knew what was what, but I was wrong. Still, I thought I’d pull it off somehow. Only then it turned the one who really didn’t know…wasn’t me.” Geese laughed. “The Man-God, y’know. He was throwin’ a real tantrum a little while ago. ‘Why?! Why?! It’s all your fault! Ya stupid ape!’” Geese flashed a careless, mocking smile. “I mean, what’d he expect? Who’s gonna lend an honest hand to a bastard who tricks and sneers at the folks that work their hardest for him?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0147","sourceIndex":147,"type":"speech","text":"“Then…does that mean you cut corners too, Geese?”","html":"“Then…does that mean you cut corners too, Geese?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0148","sourceIndex":148,"type":"speech","text":"“Is that what you think, eh? Was it that easy for you? I gave it my all, I’ll have you know.” Geese coughed and something black like soot trickled from his mouth. “See, Badigadi and I, we’re unusually softhearted. Who else’d help out a guy who screams at his allies for bein’ useless even now? Softies is who.”","html":"“Is that what you think, eh? Was it that easy for you? I gave it my all, I’ll have you know.” Geese coughed and something black like soot trickled from his mouth. “See, Badigadi and I, we’re unusually softhearted. Who else’d help out a guy who screams at his allies for bein’ useless even now? Softies is who.” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0149","sourceIndex":149,"type":"narration","text":"The black soot we saw now was like a representation of Geese’s soul. I could tell he was growing weaker.","html":"The black soot we saw now was like a representation of Geese’s soul. I could tell he was growing weaker. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0150","sourceIndex":150,"type":"speech","text":"“Thing is though, boss. Even after all that, the Man-God saved me. Yeah, he did some nasty stuff to me too, but when you add it all up, he saved me.”","html":"“Thing is though, boss. Even after all that, the Man-God saved me. Yeah, he did some nasty stuff to me too, but when you add it all up, he saved me.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","speakerConfidence":"high"},{"id":"ch03-p0151","sourceIndex":151,"type":"narration","text":"When I didn’t say anything, Geese went on. “You wouldn’t get that, eh, boss? You can do anythin’, go anywhere in the world, all on your own. You wouldn’t get what it’s like when you just can’t do nothin’.”","html":"When I didn’t say anything, Geese went on. “You wouldn’t get that, eh, boss? You can do anythin’, go anywhere in the world, all on your own. You wouldn’t get what it’s like when you just can’t do nothin’.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","embeddedDialogue":true,"attributionNote":"Narration with Geese's continued speech.","speakerConfidence":"high"},{"id":"ch03-p0152","sourceIndex":152,"type":"narration","text":"I did get it. Or at least, I thought I did. I understood what it was like not to be able to do what everyone else could. Geese was…me. Me as I’d been long ago, only there was one difference. Back then, I hadn’t even tried. When I came up against a wall, I just ran away. Geese, on the other hand, really didn’t have the ability. In this world dominated by monsters and violence, the most important power was the power to fight, and he didn’t have it. He’d learned how to do everything else, but he couldn’t survive.","html":"I did get it. Or at least, I thought I did. I understood what it was like not to be able to do what everyone else could. Geese was…me. Me as I’d been long ago, only there was one difference. Back then, I hadn’t even tried. When I came up against a wall, I just ran away. Geese, on the other hand, really didn’t have the ability. In this world dominated by monsters and violence, the most important power was the power to fight, and he didn’t have it. He’d learned how to do everything else, but he couldn’t survive.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0153","sourceIndex":153,"type":"speech","text":"“No, Geese, you’re wrong…” I could say he was wrong, but no more than that. I couldn’t say that I understood. I didn’t want to give him an answer. All I could do was deny it.","html":"“No, Geese, you’re wrong…” I could say he was wrong, but no more than that. I couldn’t say that I understood. I didn’t want to give him an answer. All I could do was deny it. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0154","sourceIndex":154,"type":"speech","text":"“Heh. Hey, Rudeus. If you’re gonna tell me I’m wrong, take some pride in it. You won, y’know? Ya beat me. The world says it’s winners who get to be right and losers are wrong. So stand up straight and tell me, ‘That’s wrong, Geese. That ain’t how it is.’ Then, see, you go on and give me a lecture, seein’ as I’m about to die. ‘Ya shoulda done it like this, ya shoulda stuck with me and never gone over to the Man-God.’ That sorta thing.” With that, the strength seemed to go out of him, and he said, his face empty, “Me, Badigadi, and the Abyssal King are all gone. The Man-God’s got no one left who’ll go outta their way to help him out. He lost. Ain’t no one left in this world who can mess with Rudeus Greyrat. In fact, he said himself that if this was a dud, there’d be nothin’ he could do to ya. So I reckon he’ll quiet down, at least ’til you take him out. Count on it: He’ll be sneakin’ about behind the scenes, though.”","html":"“Heh. Hey, Rudeus. If you’re gonna tell me I’m wrong, take some pride in it. You won, y’know? Ya beat me. The world says it’s winners who get to be right and losers are wrong. So stand up straight and tell me, ‘That’s wrong, Geese. That ain’t how it is.’ Then, see, you go on and give me a lecture, seein’ as I’m about to die. ‘Ya shoulda done it like this, ya shoulda stuck with me and never gone over to the Man-God.’ That sorta thing.” With that, the strength seemed to go out of him, and he said, his face empty, “Me, Badigadi, and the Abyssal King are all gone. The Man-God’s got no one left who’ll go outta their way to help him out. He lost. Ain’t no one left in this world who can mess with Rudeus Greyrat. In fact, he said himself that if this was a dud, there’d be nothin’ he could do to ya. So I reckon he’ll quiet down, at least ’til you take him out. Count on it: He’ll be sneakin’ about behind the scenes, though.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","speakerConfidence":"high"},{"id":"ch03-p0155","sourceIndex":155,"type":"speech","text":"“You’re joking, right?” I said, butting it without thinking. Geese didn’t smile.","html":"“You’re joking, right?” I said, butting it without thinking. Geese didn’t smile.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0156","sourceIndex":156,"type":"speech","text":"“If that’s how ya wanna think, I ain’t gonna stop you. I’m only guessing that he’ll quiet down, no more. Go on wavin’ that ‘Down with the Man-God!’ flag if you like. It’ll be bad for him but not for you, eh?”","html":"“If that’s how ya wanna think, I ain’t gonna stop you. I’m only guessing that he’ll quiet down, no more. Go on wavin’ that ‘Down with the Man-God!’ flag if you like. It’ll be bad for him but not for you, eh?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","speakerConfidence":"high"},{"id":"ch03-p0157","sourceIndex":157,"type":"narration","text":"I wasn’t laughing either.","html":"I wasn’t laughing either. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0158","sourceIndex":158,"type":"speech","text":"“Hey, now, what’s the glum look for? You’re Paul’s son, aren’t ya? Paul’d look a bit more cheerful if he were around. Maybe not right before he died, though. He really got older while I wasn’t lookin’… But anyways, take some pride in this already! Rejoice a bit, even if it don’t last. How d’ya think I feel when you don’t? Makes me look like a real moron, after I went all over the world gettin’ the Sword God and the North God and the Ogre God to join me, then getting ’em fired up like, ‘Let’s take him down!’ only for it to all fall to pieces. All ’cause I couldn’t control ’em. At the end I took a risk and sent Badi. Look where that got me. At least remember me as a strong opponent, yeah? That’s how I wanna be remembered.” Before I knew it, Geese was crying. Tears were streaming down his soot-stained face. When I saw that, I knew for sure that he hadn’t held anything back.","html":"“Hey, now, what’s the glum look for? You’re Paul’s son, aren’t ya? Paul’d look a bit more cheerful if he were around. Maybe not right before he died, though. He really got older while I wasn’t lookin’… But anyways, take some pride in this already! Rejoice a bit, even if it don’t last. How d’ya think I feel when you don’t? Makes me look like a real moron, after I went all over the world gettin’ the Sword God and the North God and the Ogre God to join me, then getting ’em fired up like, ‘Let’s take him down!’ only for it to all fall to pieces. All ’cause I couldn’t control ’em. At the end I took a risk and sent Badi. Look where that got me. At least remember me as a strong opponent, yeah? That’s how I wanna be remembered.” Before I knew it, Geese was crying. Tears were streaming down his soot-stained face. When I saw that, I knew for sure that he hadn’t held anything back.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","speakerConfidence":"high"},{"id":"ch03-p0159","sourceIndex":159,"type":"speech","text":"“Okay. You were strong, Geese. True, I’m standing here now, but if just one thing had gone awry, I’m pretty sure our places would be reversed. This was the hardest, most brutal fight of my life.”","html":"“Okay. You were strong, Geese. True, I’m standing here now, but if just one thing had gone awry, I’m pretty sure our places would be reversed. This was the hardest, most brutal fight of my life.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0160","sourceIndex":160,"type":"speech","text":"“Heh… Heh heh. Cheers, Rudeus.”","html":"“Heh… Heh heh. Cheers, Rudeus.” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","speakerConfidence":"high"},{"id":"ch03-p0161","sourceIndex":161,"type":"narration","text":"He had been strong, all right. It had taken me a year to defeat him. For a whole year, I’d prepared…not to mention everything I’d brought to the fight that had been built up over a much longer period. No one could call him weak after all that.","html":"He had been strong, all right. It had taken me a year to defeat him. For a whole year, I’d prepared…not to mention everything I’d brought to the fight that had been built up over a much longer period. No one could call him weak after all that.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0162","sourceIndex":162,"type":"speech","text":"“Geese.” Suddenly, Ghislaine stepped forward. She looked down at Geese. Her bangs hid her face so that I couldn’t read her expression.","html":"“Geese.” Suddenly, Ghislaine stepped forward. She looked down at Geese. Her bangs hid her face so that I couldn’t read her expression.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ghislaine","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0163","sourceIndex":163,"type":"speech","text":"“Hey, Ghislaine. Been a while.”","html":"“Hey, Ghislaine. Been a while.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","speakerConfidence":"high"},{"id":"ch03-p0164","sourceIndex":164,"type":"speech","text":"“It has.”","html":"“It has.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ghislaine","speakerConfidence":"high"},{"id":"ch03-p0165","sourceIndex":165,"type":"speech","text":"“I’m headin’ on.”","html":"“I’m headin’ on.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ghislaine","speakerConfidence":"high"},{"id":"ch03-p0166","sourceIndex":166,"type":"speech","text":"“Yes. Say hello to Paul for me.”","html":"“Yes. Say hello to Paul for me.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","speakerConfidence":"high"},{"id":"ch03-p0167","sourceIndex":167,"type":"speech","text":"“Gotcha… Maybe, when it’s your time, we can get a drink. I wanna see Paul get drunk again, then stickin’ his face into ya chest and makin’ Zenith sulk…”","html":"“Gotcha… Maybe, when it’s your time, we can get a drink. I wanna see Paul get drunk again, then stickin’ his face into ya chest and makin’ Zenith sulk…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ghislaine","speakerConfidence":"high"},{"id":"ch03-p0168","sourceIndex":168,"type":"speech","text":"“Zenith won’t be going anywhere for a while yet. My time will probably come first.”","html":"“Zenith won’t be going anywhere for a while yet. My time will probably come first.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Geese","speakerConfidence":"high"},{"id":"ch03-p0169","sourceIndex":169,"type":"speech","text":"“Heh, yeah, I know… Anyway…’til we all…meet…ag…”","html":"“Heh, yeah, I know… Anyway…’til we all…meet…ag…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ghislaine","speakerConfidence":"high"},{"id":"ch03-p0170","sourceIndex":170,"type":"narration","text":"Geese fell still. Just like that, something in him was gone, suddenly, even though he hadn’t finished talking.","html":"Geese fell still. Just like that, something in him was gone, suddenly, even though he hadn’t finished talking.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0171","sourceIndex":171,"type":"speech","text":"Ghislaine’s ears twitched, then her tail drooped. “He’s dead,” she said.","html":"Ghislaine’s ears twitched, then her tail drooped. “He’s dead,” she said.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ghislaine","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0172","sourceIndex":172,"type":"narration","text":"Dead. Geese was dead.","html":"Dead. Geese was dead.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0173","sourceIndex":173,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":1560,"speechCount":30,"speakers":["Geese","Ghislaine","Rudeus"]},{"id":"ch03-s04","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The edge of the Ravine of the Earthwyrm","cast":["Alexander","Ghislaine","Isolde","Rudeus","Ruijerd"],"blocks":[{"id":"ch03-p0175","sourceIndex":175,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch03-p0176","sourceIndex":176,"type":"narration","text":"I beat Geese. I could think that now, but as I’d expected, it didn’t make me happy. I was aware I was in shock. There was something about seeing someone I knew die in front of me that I couldn’t process. He was my enemy, and I’d known I had to take him down…but it wasn’t like I’d loathed Geese with every fiber of my being or anything. If we’d lost the battle and they’d killed Eris or someone close to me, I might have ended up loathing him. I might have felt like this was justice. I took down the bastard. I got my revenge. That sort of thing. But…","html":"I beat Geese. I could think that now, but as I’d expected, it didn’t make me happy. I was aware I was in shock. There was something about seeing someone I knew die in front of me that I couldn’t process. He was my enemy, and I’d known I had to take him down…but it wasn’t like I’d loathed Geese with every fiber of my being or anything. If we’d lost the battle and they’d killed Eris or someone close to me, I might have ended up loathing him. I might have felt like this was justice. I took down the bastard. I got my revenge. That sort of thing. But…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0177","sourceIndex":177,"type":"narration","text":"I couldn’t deal with it. All I knew was that I was able to numbly ruminate the way I was because I hadn’t lost a single person in the battle who was important to me. I’d met my victory conditions. I’d wiped out the disciples and kept Orsted in reserve. It’d been a hard fight and there’d been missteps but despite that, it was a perfect victory—rare, for me. Maybe I was trying to use the way Geese had died to mess it up a bit. Perhaps some part of me thought that, if I’d been cleverer, Geese might have come back over to my side.","html":"I couldn’t deal with it. All I knew was that I was able to numbly ruminate the way I was because I hadn’t lost a single person in the battle who was important to me. I’d met my victory conditions. I’d wiped out the disciples and kept Orsted in reserve. It’d been a hard fight and there’d been missteps but despite that, it was a perfect victory—rare, for me. Maybe I was trying to use the way Geese had died to mess it up a bit. Perhaps some part of me thought that, if I’d been cleverer, Geese might have come back over to my side.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0178","sourceIndex":178,"type":"narration","text":"Thinking about it wasn’t doing any good. At the very least, though, I could take his bones home and make him a grave. Next to Paul’s. That’d be good. He’d said something about being together.","html":"Thinking about it wasn’t doing any good. At the very least, though, I could take his bones home and make him a grave. Next to Paul’s. That’d be good. He’d said something about being together. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0179","sourceIndex":179,"type":"narration","text":"Those were the thoughts running through my head as I watched Geese’s body burn. Ghislaine stared intently at the cremation proceedings. Maybe it was my imagination, but when it was over and we’d recovered the bones, her ears and tail seemed limp.","html":"Those were the thoughts running through my head as I watched Geese’s body burn. Ghislaine stared intently at the cremation proceedings. Maybe it was my imagination, but when it was over and we’d recovered the bones, her ears and tail seemed limp. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0180","sourceIndex":180,"type":"speech","text":"“Let’s go home.”","html":"“Let’s go home.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0181","sourceIndex":181,"type":"speech","text":"“Yeah.”","html":"“Yeah.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ghislaine","attributionNote":"Short answer to Rudeus's 'Let's go home.'","speakerConfidence":"medium"},{"id":"ch03-p0182","sourceIndex":182,"type":"narration","text":"We crossed the ravine.","html":"We crossed the ravine. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0183","sourceIndex":183,"type":"narration","text":"Whatever else aside, it was really over this time. I was worn out. I barely had any mana left; I was physically exhausted. If I lay down I’d be out like a light. Not that I could afford to sleep until Badigadi was sealed…","html":"Whatever else aside, it was really over this time. I was worn out. I barely had any mana left; I was physically exhausted. If I lay down I’d be out like a light. Not that I could afford to sleep until Badigadi was sealed…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0184","sourceIndex":184,"type":"narration","text":"I was eager to get back to Sharia, anyway. I wanted to get a good night’s sleep in my own bed and then wake up to eat. I’d have rice for breakfast… Yeah—here in the Biheiril Kingdom, they had soy sauce. I could make a perfect tamagokake gohan bowl. When I got back, I’d eat. I’d eat until I burst. Then, of course, it’d be time for some sexy shenanigans. Rudeus the Celibate had died with Geese. Sylphie…or Roxy…or Eris…who to pick? Scratch that, how about all three at once? Eris wouldn’t like it, but surely it’d be all right to ask her, just this once. Chances like this didn’t come along every day, right? Right.","html":"I was eager to get back to Sharia, anyway. I wanted to get a good night’s sleep in my own bed and then wake up to eat. I’d have rice for breakfast… Yeah—here in the Biheiril Kingdom, they had soy sauce. I could make a perfect tamagokake gohan bowl. When I got back, I’d eat. I’d eat until I burst. Then, of course, it’d be time for some sexy shenanigans. Rudeus the Celibate had died with Geese. Sylphie…or Roxy…or Eris…who to pick? Scratch that, how about all three at once? Eris wouldn’t like it, but surely it’d be all right to ask her, just this once. Chances like this didn’t come along every day, right? Right.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0185","sourceIndex":185,"type":"narration","text":"The post-mortem for this battle could wait until later. For now, I’d forget what Geese had said. Now, it was time to rest. I was exhausted.","html":"The post-mortem for this battle could wait until later. For now, I’d forget what Geese had said. Now, it was time to rest. I was exhausted.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0186","sourceIndex":186,"type":"speech","text":"“Rudeus.” As I walked, dragging myself wearily along with every step, I heard a voice from behind me. It was Ruijerd. He was walking at the back of our group and had turned to look behind him. Back at the ravine.","html":"“Rudeus.” As I walked, dragging myself wearily along with every step, I heard a voice from behind me. It was Ruijerd. He was walking at the back of our group and had turned to look behind him. Back at the ravine.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0187","sourceIndex":187,"type":"speech","text":"“What’s the matter?”","html":"“What’s the matter?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0188","sourceIndex":188,"type":"speech","text":"“An enemy.”","html":"“An enemy.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","speakerConfidence":"high"},{"id":"ch03-p0189","sourceIndex":189,"type":"speech","text":"“What?”","html":"“What?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0190","sourceIndex":190,"type":"narration","text":"There was a hand clinging to the edge of the ravine. A hand. A hand. Something was climbing up out of the ravine. But what? Never mind, there was no point wasting words on it. The hand shone gold. It wore a golden gauntlet.","html":"There was a hand clinging to the edge of the ravine. A hand. A hand. Something was climbing up out of the ravine. But what? Never mind, there was no point wasting words on it. The hand shone gold. It wore a golden gauntlet.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0191","sourceIndex":191,"type":"speech","text":"“You’re kidding.”","html":"“You’re kidding.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0192","sourceIndex":192,"type":"narration","text":"It was Badigadi.","html":"It was Badigadi.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0193","sourceIndex":193,"type":"narration","text":"Surely this was too soon. Wasn’t it? Thinking back, I’d thrown a few of his arms into the ravine, then his body after them. His body had appeared to be practically annihilated, but there could have been a few larger chunks here and there…maybe by pulling together the bits that remained, no matter how minute, he’d been able to fast-track his regeneration. Were immortal demon kings that immortal…?","html":"Surely this was too soon. Wasn’t it? Thinking back, I’d thrown a few of his arms into the ravine, then his body after them. His body had appeared to be practically annihilated, but there could have been a few larger chunks here and there…maybe by pulling together the bits that remained, no matter how minute, he’d been able to fast-track his regeneration. Were immortal demon kings that immortal…?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0194","sourceIndex":194,"type":"narration","text":"As we stood frozen, the armor rose out of the ravine. Only, it looked different now. It only had two arms, which was how it had been when I’d defeated it, but the overall design had changed. The helmet was a different shape, and it was shorter, not even two meters tall. It was also holding a sword. An enormous sword. The world’s greatest sword, forged from the King Dragon King.","html":"As we stood frozen, the armor rose out of the ravine. Only, it looked different now. It only had two arms, which was how it had been when I’d defeated it, but the overall design had changed. The helmet was a different shape, and it was shorter, not even two meters tall. It was also holding a sword. An enormous sword. The world’s greatest sword, forged from the King Dragon King. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0195","sourceIndex":195,"type":"narration","text":"No. It isn’t him. That isn’t Badigadi.","html":"No. It isn’t him. That isn’t Badigadi.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0196","sourceIndex":196,"type":"speech","text":"“No matter how desperate he becomes, a hero always rises again and turns the tides. That is what I have achieved!”","html":"“No matter how desperate he becomes, a hero always rises again and turns the tides. That is what I have achieved!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","speakerConfidence":"high"},{"id":"ch03-p0197","sourceIndex":197,"type":"thought","text":"That voice. The way he said “hero.” There was no way I could mistake that calling card.","html":"That voice. The way he said “hero.” There was no way I could mistake that calling card.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","attributionNote":"Inner narration; no dialogue is spoken.","speakerConfidence":"high"},{"id":"ch03-p0198","sourceIndex":198,"type":"speech","text":"“I am North God Kalman III, Alexander Rybak!”","html":"“I am North God Kalman III, Alexander Rybak!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","speakerConfidence":"high"},{"id":"ch03-p0199","sourceIndex":199,"type":"narration","text":"He was alive. Huh! I’d really thought he was dead. His body hadn’t so much as twitched back when I sent him down here, and yet here he was. He’d survived.","html":"He was alive. Huh! I’d really thought he was dead. His body hadn’t so much as twitched back when I sent him down here, and yet here he was. He’d survived. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0200","sourceIndex":200,"type":"narration","text":"Ah, of course. He had immortal demon blood too. Given time, he could regenerate like Badigadi.","html":"Ah, of course. He had immortal demon blood too. Given time, he could regenerate like Badigadi. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0201","sourceIndex":201,"type":"narration","text":"Except—no. A shiver ran up my spine as it all clicked. This was the “final plan” Geese had talked about. Had this been his plan from the start? Or had he changed tack partway through? I’d thought something was off. I’d thought it was strange when the armor didn’t regenerate. He’d deliberately prevented it from regenerating. Then, Alec had put it on at the bottom of the ravine and restored himself. Maybe yesterday, when Geese was playing dead, he’d been preparing to drop the Fighting God Armor and part of Badigadi into the ravine and resurrect Alec…","html":"Except—no. A shiver ran up my spine as it all clicked. This was the “final plan” Geese had talked about. Had this been his plan from the start? Or had he changed tack partway through? I’d thought something was off. I’d thought it was strange when the armor didn’t regenerate. He’d deliberately prevented it from regenerating. Then, Alec had put it on at the bottom of the ravine and restored himself. Maybe yesterday, when Geese was playing dead, he’d been preparing to drop the Fighting God Armor and part of Badigadi into the ravine and resurrect Alec…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0202","sourceIndex":202,"type":"narration","text":"Dammit. There was still more I had to do. There was another battle I had to fight. I was sick of this. Couldn’t it just be over? Like, give me a break already! An opponent I already beat once coming back for a second round?","html":"Dammit. There was still more I had to do. There was another battle I had to fight. I was sick of this. Couldn’t it just be over? Like, give me a break already! An opponent I already beat once coming back for a second round?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0203","sourceIndex":203,"type":"narration","text":"Maybe it was my fault. I hadn’t made sure that Alec was dead. I’d beaten him and thought that meant I’d finished him off for good, only to leave him there. I could have burned him, at the very least! But no, I’d left him there, and now here we were. What else should I have done in that situation, though? What more could I have given than what I already had?","html":"Maybe it was my fault. I hadn’t made sure that Alec was dead. I’d beaten him and thought that meant I’d finished him off for good, only to leave him there. I could have burned him, at the very least! But no, I’d left him there, and now here we were. What else should I have done in that situation, though? What more could I have given than what I already had?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0204","sourceIndex":204,"type":"narration","text":"Well…whatever. What was done was done. What was I going to do now? The Version Zero was gone. I had no backup. Ghislaine, Isolde, and Ruijerd, and I remained, with me teetering on the verge of mana drain. I had no weapon and no armor. My hand was empty. There was no hope of winning.","html":"Well…whatever. What was done was done. What was I going to do now? The Version Zero was gone. I had no backup. Ghislaine, Isolde, and Ruijerd, and I remained, with me teetering on the verge of mana drain. I had no weapon and no armor. My hand was empty. There was no hope of winning.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0205","sourceIndex":205,"type":"narration","text":"What should I do? How was I supposed to beat North God Kalman III wearing the Fighting God Armor?","html":"What should I do? How was I supposed to beat North God Kalman III wearing the Fighting God Armor?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0206","sourceIndex":206,"type":"narration","text":"Was it time to ask Orsted to step in? As if. What was any of this for?","html":"Was it time to ask Orsted to step in? As if. What was any of this for?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0207","sourceIndex":207,"type":"narration","text":"I had to at least weaken him…but how?","html":"I had to at least weaken him…but how?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0208","sourceIndex":208,"type":"narration","text":"As I gaped at him, Alec looked back at me. He didn’t seem at all surprised that I was here. It was like he’d expected me to be waiting for him.","html":"As I gaped at him, Alec looked back at me. He didn’t seem at all surprised that I was here. It was like he’d expected me to be waiting for him. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0209","sourceIndex":209,"type":"speech","text":"“Rudeus Greyrat…” he said. “I apologize for calling you useless. You are a formidable warrior. I would not have thought it from your appearance, but you are a worthy opponent for me. Thanks to you, I have ascended to a new level of power. You have my gratitude.”","html":"“Rudeus Greyrat…” he said. “I apologize for calling you useless. You are a formidable warrior. I would not have thought it from your appearance, but you are a worthy opponent for me. Thanks to you, I have ascended to a new level of power. You have my gratitude.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0210","sourceIndex":210,"type":"narration","text":"I turned my weary body toward the golden armor. If I ran, he’d only catch me. I didn’t even have enough strength to buy time. I’d go down fighting, then. I’d struggle with everything I had left. Focusing only on that thought, I stepped forward—","html":"I turned my weary body toward the golden armor. If I ran, he’d only catch me. I didn’t even have enough strength to buy time. I’d go down fighting, then. I’d struggle with everything I had left. Focusing only on that thought, I stepped forward—","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0211","sourceIndex":211,"type":"speech","text":"“Uh?” I was sprawled on the ground.","html":"“Uh?” I was sprawled on the ground.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0212","sourceIndex":212,"type":"speech","text":"“I am invincible now,” Alec said. It was seeing the other three fallen around me—Ruijerd, Ghislaine, and Isolde—that made me realize Alex had thrown us all down. He’d knocked us all down in one hit.","html":"“I am invincible now,” Alec said. It was seeing the other three fallen around me—Ruijerd, Ghislaine, and Isolde—that made me realize Alex had thrown us all down. He’d knocked us all down in one hit.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0213","sourceIndex":213,"type":"speech","text":"“This is my thanks to you for making me stronger, Rudeus. I will let you live.”","html":"“This is my thanks to you for making me stronger, Rudeus. I will let you live.” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","speakerConfidence":"high"},{"id":"ch03-p0214","sourceIndex":214,"type":"narration","text":"Searing pain shot through me at last. My legs were broken. He was too fast. I hadn’t seen it coming. I hadn’t had the Eye of Foresight open, but still. I hadn’t been able to react at all. Neither had any of the other three. The Eye of Foresight wouldn’t have made any difference. Maybe this was the true power of the Fighting God Armor. When the wearer was stronger, it built upon their strength… Never mind, that wasn’t right. It wasn’t like Badigadi had been weak. He was plenty strong too. It was simply that when the wearer changed, the armor’s performance changed as well. It changed its form to align itself with them… It really was the ultimate armor.","html":"Searing pain shot through me at last. My legs were broken. He was too fast. I hadn’t seen it coming. I hadn’t had the Eye of Foresight open, but still. I hadn’t been able to react at all. Neither had any of the other three. The Eye of Foresight wouldn’t have made any difference. Maybe this was the true power of the Fighting God Armor. When the wearer was stronger, it built upon their strength… Never mind, that wasn’t right. It wasn’t like Badigadi had been weak. He was plenty strong too. It was simply that when the wearer changed, the armor’s performance changed as well. It changed its form to align itself with them… It really was the ultimate armor.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0215","sourceIndex":215,"type":"speech","text":"“Farewell,” Alec said, walking away.","html":"“Farewell,” Alec said, walking away. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0216","sourceIndex":216,"type":"narration","text":"There was no time to be shocked. I immediately said a spell to heal the other three. They were unconscious. Near death, but not yet dead. Was this Alec’s idea of mercy? Damn it all. He still didn’t take me seriously. But hey, that wasn’t a bad thing. After healing the other three, I cast Earth Fortress to cover them, then went after Alec. I had no plan for what I’d do when I caught him. Had Sylphie made it back to the village? What was Orsted going to do? I didn’t have any answers, but Alec was heading toward people I had to protect. Toward Eris, Sylphie, Norn, and all the Superd. I couldn’t allow them to be slaughtered. I had no reason not to go after him.","html":"There was no time to be shocked. I immediately said a spell to heal the other three. They were unconscious. Near death, but not yet dead. Was this Alec’s idea of mercy? Damn it all. He still didn’t take me seriously. But hey, that wasn’t a bad thing. After healing the other three, I cast Earth Fortress to cover them, then went after Alec. I had no plan for what I’d do when I caught him. Had Sylphie made it back to the village? What was Orsted going to do? I didn’t have any answers, but Alec was heading toward people I had to protect. Toward Eris, Sylphie, Norn, and all the Superd. I couldn’t allow them to be slaughtered. I had no reason not to go after him. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0217","sourceIndex":217,"type":"narration","text":"My legs weren’t cooperating too well. They trembled, refusing to respond how I wanted them to. But even then, I managed to run. I kept going, following the golden armor.","html":"My legs weren’t cooperating too well. They trembled, refusing to respond how I wanted them to. But even then, I managed to run. I kept going, following the golden armor.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0218","sourceIndex":218,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":1603,"speechCount":14,"speakers":["Alexander","Ghislaine","Rudeus","Ruijerd"]},{"id":"ch03-s05","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The Superd Village","cast":["Alexander","Orsted","Rudeus"],"blocks":[{"id":"ch03-p0220","sourceIndex":220,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch03-p0221","sourceIndex":221,"type":"narration","text":"The Superd village was too quiet. It was so quiet I wondered when I arrived if everything was already over.","html":"The Superd village was too quiet. It was so quiet I wondered when I arrived if everything was already over. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0222","sourceIndex":222,"type":"speech","text":"“Why?! Why is there no one here?!” Alec bawled. I passed through the palisade gate and into the village and found it empty. The Superd were gone, as were Julie and Aisha, and Cliff and the others who’d been carried back here for their wounds. Even Sylphie, who was supposed to have been relaying my message to Orsted, was gone. Eris, too. There wasn’t a trace of any of them. All the people had vanished into thin air.","html":"“Why?! Why is there no one here?!” Alec bawled. I passed through the palisade gate and into the village and found it empty. The Superd were gone, as were Julie and Aisha, and Cliff and the others who’d been carried back here for their wounds. Even Sylphie, who was supposed to have been relaying my message to Orsted, was gone. Eris, too. There wasn’t a trace of any of them. All the people had vanished into thin air. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0223","sourceIndex":223,"type":"speech","text":"“How can this be?! Isn’t this what Rudeus was defending?!”","html":"“How can this be?! Isn’t this what Rudeus was defending?!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","speakerConfidence":"high"},{"id":"ch03-p0224","sourceIndex":224,"type":"narration","text":"It was. I was defending this place.","html":"It was. I was defending this place. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0225","sourceIndex":225,"type":"narration","text":"This was bizarre. Everyone had been here, right before I left! It had been…how much time had passed? It was about three hours from here to the ravine. I’d used the Version Zero to get there, and I’d been in a big hurry, so it had only taken an hour. Then we’d fought Badigadi, searched for Geese, and come back…so five, maybe six hours? Five or six hours ago, everyone had been here. Being in a hurry I hadn’t looked around much, but I was sure they’d all been here.","html":"This was bizarre. Everyone had been here, right before I left! It had been…how much time had passed? It was about three hours from here to the ravine. I’d used the Version Zero to get there, and I’d been in a big hurry, so it had only taken an hour. Then we’d fought Badigadi, searched for Geese, and come back…so five, maybe six hours? Five or six hours ago, everyone had been here. Being in a hurry I hadn’t looked around much, but I was sure they’d all been here. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0226","sourceIndex":226,"type":"narration","text":"Except—hold up. Hadn’t there been…too many people? Hadn’t there been some people who had no place being here?","html":"Except—hold up. Hadn’t there been…too many people? Hadn’t there been some people who had no place being here?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0227","sourceIndex":227,"type":"speech","text":"“Curses… You had me completely fooled…” Alec turned around. “Rudeus Greyrat!” Fury radiated from him in waves.","html":"“Curses… You had me completely fooled…” Alec turned around. “Rudeus Greyrat!” Fury radiated from him in waves. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0228","sourceIndex":228,"type":"narration","text":"You’ve got it wrong. I don’t know any more than you.","html":"You’ve got it wrong. I don’t know any more than you. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0229","sourceIndex":229,"type":"narration","text":"Why would I have come chasing after such a dangerous opponent if Orsted wasn’t even here? That’d be moronic. I’d have run away into the forest, counting my blessings that he’d let me live.","html":"Why would I have come chasing after such a dangerous opponent if Orsted wasn’t even here? That’d be moronic. I’d have run away into the forest, counting my blessings that he’d let me live. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0230","sourceIndex":230,"type":"speech","text":"“Orsted and the Superd were never here, were they?”","html":"“Orsted and the Superd were never here, were they?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","speakerConfidence":"high"},{"id":"ch03-p0231","sourceIndex":231,"type":"speech","text":"“Um, no, the Superd were… You saw Ruijerd before, didn’t you?” Getting the feeling he might attack at any moment, I backed away. I had no idea what was going on now. Maybe this was all a bad dream. Maybe the Abyssal King had survived or something, and everything since we’d defeated Badigadi had been a dream.","html":"“Um, no, the Superd were… You saw Ruijerd before, didn’t you?” Getting the feeling he might attack at any moment, I backed away. I had no idea what was going on now. Maybe this was all a bad dream. Maybe the Abyssal King had survived or something, and everything since we’d defeated Badigadi had been a dream.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0232","sourceIndex":232,"type":"speech","text":"“I was going to let you live. No longer. If you are so desperate to fight me to the last, I shall grant your wish…”","html":"“I was going to let you live. No longer. If you are so desperate to fight me to the last, I shall grant your wish…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","speakerConfidence":"high"},{"id":"ch03-p0233","sourceIndex":233,"type":"narration","text":"Crap. What’s going on? I had to run. I had no reason to fight, I had to run. I was about to turn around—then, ice ran down my spine.","html":"Crap. What’s going on? I had to run. I had no reason to fight, I had to run. I was about to turn around—then, ice ran down my spine. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0234","sourceIndex":234,"type":"narration","text":"My feet stopped moving. Had Alec done something? No, that wasn’t it. He was rooted to the spot too.","html":"My feet stopped moving. Had Alec done something? No, that wasn’t it. He was rooted to the spot too. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0235","sourceIndex":235,"type":"speech","text":"“Wh-what’s this, this cold?” He sounded scared. He was looking around wildly. He had the Fighting God Armor. Why was he so scared?","html":"“Wh-what’s this, this cold?” He sounded scared. He was looking around wildly. He had the Fighting God Armor. Why was he so scared?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0236","sourceIndex":236,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch03-p0237","sourceIndex":237,"type":"narration","text":"Why?","html":"Why?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0238","sourceIndex":238,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch03-p0239","sourceIndex":239,"type":"narration","text":"Well, because it was a curse. A curse to inspire fear. A curse that specifically didn’t work on me. Only, I could tell that the source of the curse was currently seething with murderous rage, and that rage was tied up in some major trauma for me. That scared me.","html":"Well, because it was a curse. A curse to inspire fear. A curse that specifically didn’t work on me. Only, I could tell that the source of the curse was currently seething with murderous rage, and that rage was tied up in some major trauma for me. That scared me.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0240","sourceIndex":240,"type":"narration","text":"That murderous rage took shape as it emerged from the back of the village. Silver hair, and those awful eyes, the whites shining beneath the gold of his irises. He came walking toward us slowly with a terrifying look on his face.","html":"That murderous rage took shape as it emerged from the back of the village. Silver hair, and those awful eyes, the whites shining beneath the gold of his irises. He came walking toward us slowly with a terrifying look on his face. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0241","sourceIndex":241,"type":"speech","text":"“Rudeus.”","html":"“Rudeus.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch03-p0242","sourceIndex":242,"type":"speech","text":"“Sir Orsted…why…?”","html":"“Sir Orsted…why…?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0243","sourceIndex":243,"type":"narration","text":"It was Orsted. He had his helmet in one hand and tossed it to me now. I hurried to catch it.","html":"It was Orsted. He had his helmet in one hand and tossed it to me now. I hurried to catch it. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0244","sourceIndex":244,"type":"speech","text":"“When Sylphiette informed me what had happened, Cliff Grimor was already close to full mana drain. I saw that he would be unable to seal Badigadi and the Fighting God, so I went and begged another man’s aid. Hence, my arrival was delayed. Forgive me.”","html":"“When Sylphiette informed me what had happened, Cliff Grimor was already close to full mana drain. I saw that he would be unable to seal Badigadi and the Fighting God, so I went and begged another man’s aid. Hence, my arrival was delayed. Forgive me.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch03-p0245","sourceIndex":245,"type":"narration","text":"No, not that, I wasn’t asking why you’re late. I want to know why there’s no one here.","html":"No, not that, I wasn’t asking why you’re late. I want to know why there’s no one here.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0246","sourceIndex":246,"type":"speech","text":"“This, however… This, I did not anticipate,” Orsted said, then looked at Alec, North God Kalman III, who stood there in the Fighting God Armor. “I shall handle the rest.” He stepped forward, and Alec took a frightened step back. I had no idea what was happening. I only called after Orsted.","html":"“This, however… This, I did not anticipate,” Orsted said, then looked at Alec, North God Kalman III, who stood there in the Fighting God Armor. “I shall handle the rest.” He stepped forward, and Alec took a frightened step back. I had no idea what was happening. I only called after Orsted.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0247","sourceIndex":247,"type":"speech","text":"“But Sir Orsted, your mana…”","html":"“But Sir Orsted, your mana…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0248","sourceIndex":248,"type":"speech","text":"“Enough. There has been enough of that,” Orsted said, shaking his head. “I too have made up my mind.”","html":"“Enough. There has been enough of that,” Orsted said, shaking his head. “I too have made up my mind.” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0249","sourceIndex":249,"type":"speech","text":"“Made up your mind…? About what…?”","html":"“Made up your mind…? About what…?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch03-p0250","sourceIndex":250,"type":"speech","text":"He looked at me. His mouth quirked in the thinnest shadow of a smile, then set with almost imperceptible determination. With the most terrifying face in the world, he said, “I wish to see for myself what it is like to fight alongside trusted friends.”","html":"He looked at me. His mouth quirked in the thinnest shadow of a smile, then set with almost imperceptible determination. With the most terrifying face in the world, he said, “I wish to see for myself what it is like to fight alongside trusted friends.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","embeddedDialogue":true,"attributionNote":"Narration with Orsted's declaration.","speakerConfidence":"high"},{"id":"ch03-p0251","sourceIndex":251,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch03-p0252","sourceIndex":252,"type":"narration","text":"I hadn’t quite followed the beginning and end of the conversation, but for some reason, his words struck me. I understood he’d resolved himself to this battle.","html":"I hadn’t quite followed the beginning and end of the conversation, but for some reason, his words struck me. I understood he’d resolved himself to this battle. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0253","sourceIndex":253,"type":"speech","text":"“Okay,” I said at last. “Then I’ll leave you to deal with the rest.” I stepped back. There was nothing more for me to say. I was supposed to be thinking that I couldn’t allow Orsted to fight, and yet I could feel a little smile tugging at my mouth. I’d misjudged a little. Not one thing in particular, exactly. It was just that Orsted had let me in more than I’d thought. He thought of me as his ally on an emotional level, not just in his calculations. He wanted to fight alongside his friends. Not allies. Friends. From now on, he would not be alone, but with me. He wouldn’t use me, but rather stand at my side. Now I knew we couldn’t lose. I’d thought I’d failed to achieve a goal, but I’d won something else.","html":"“Okay,” I said at last. “Then I’ll leave you to deal with the rest.” I stepped back. There was nothing more for me to say. I was supposed to be thinking that I couldn’t allow Orsted to fight, and yet I could feel a little smile tugging at my mouth. I’d misjudged a little. Not one thing in particular, exactly. It was just that Orsted had let me in more than I’d thought. He thought of me as his ally on an emotional level, not just in his calculations. He wanted to fight alongside his friends. Not allies. Friends. From now on, he would not be alone, but with me. He wouldn’t use me, but rather stand at my side. Now I knew we couldn’t lose. I’d thought I’d failed to achieve a goal, but I’d won something else.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0254","sourceIndex":254,"type":"speech","text":"“Now then, North God Kalman III, Alexander Rybak.”","html":"“Now then, North God Kalman III, Alexander Rybak.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch03-p0255","sourceIndex":255,"type":"speech","text":"“So it’s you… You’re Dragon God Orsted.” When Orsted called his name, Alec raised the King Dragon Blade Kajakut. He was wielding both the Fighting God Armor and the King Dragon Blade. They made for a devastatingly powerful combo. He wouldn’t consider tossing just one of them to the side, would he? Was there anything I could do here?","html":"“So it’s you… You’re Dragon God Orsted.” When Orsted called his name, Alec raised the King Dragon Blade Kajakut. He was wielding both the Fighting God Armor and the King Dragon Blade. They made for a devastatingly powerful combo. He wouldn’t consider tossing just one of them to the side, would he? Was there anything I could do here?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0256","sourceIndex":256,"type":"speech","text":"“Perfect.” Orsted, it seemed, thought differently. As Alec raised his blade, a smile of confidence flashed across his face. That smile was terrifying enough to turn everything around it to ice.","html":"“Perfect.” Orsted, it seemed, thought differently. As Alec raised his blade, a smile of confidence flashed across his face. That smile was terrifying enough to turn everything around it to ice. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0257","sourceIndex":257,"type":"speech","text":"“With both the Fighting God Armor and the King Dragon Blade, there’ll be no excuses when you lose, will there?”","html":"“With both the Fighting God Armor and the King Dragon Blade, there’ll be no excuses when you lose, will there?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch03-p0258","sourceIndex":258,"type":"speech","text":"“You—!” Alec was out for blood now. “Do you mock me?!”","html":"“You—!” Alec was out for blood now. “Do you mock me?!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0259","sourceIndex":259,"type":"speech","text":"“I do not.” Orsted put his hands together and then slowly drew them apart. Something emerged from the palm of his left hand: it was a sword, and when I saw it, my knees began to knock together. I’d only seen that sword once before. Orsted had only called it the Dragon Blade. All I knew was that it consumed a massive volume of mana.","html":"“I do not.” Orsted put his hands together and then slowly drew them apart. Something emerged from the palm of his left hand: it was a sword, and when I saw it, my knees began to knock together. I’d only seen that sword once before. Orsted had only called it the Dragon Blade. All I knew was that it consumed a massive volume of mana.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0260","sourceIndex":260,"type":"speech","text":"“My sole desire is to beat you down utterly and to break you.” He held the sword out, pointing it at Alec’s eyes.","html":"“My sole desire is to beat you down utterly and to break you.” He held the sword out, pointing it at Alec’s eyes. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0261","sourceIndex":261,"type":"narration","text":"Alec’s fury rose to the surface, the air crackling with his wish to see Orsted dead. He raised the King Dragon Blade.","html":"Alec’s fury rose to the surface, the air crackling with his wish to see Orsted dead. He raised the King Dragon Blade.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0262","sourceIndex":262,"type":"speech","text":"“Try it, then!” he shouted.","html":"“Try it, then!” he shouted. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0263","sourceIndex":263,"type":"narration","text":"Dragon God Orsted faced off against North God Alexander in the Fighting God Armor. The true and actual final battle had begun.","html":"Dragon God Orsted faced off against North God Alexander in the Fighting God Armor. The true and actual final battle had begun.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0264","sourceIndex":264,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":1186,"speechCount":24,"speakers":["Alexander","Orsted","Rudeus"]},{"id":"ch03-s06","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The Superd Village, after Orsted's battle","cast":["Alexander","Orsted","Rudeus"],"blocks":[{"id":"ch03-p0266","sourceIndex":266,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch03-p0267","sourceIndex":267,"type":"narration","text":"About ten minutes later, around a quarter of the forest around the Ravine of the Earthwyrm was gone. Amid the now scorched and barren wasteland, scattered with mounds of splintered trees, there knelt a boy missing both his arms. A sword pressed into this throat. The boy looked up at its wielder in blank shock. A man with silver hair and distinctive eyes stared back. He didn’t have a scratch on him. Looking at him standing there unscathed, you’d think there hadn’t been a battle at all. The only clue was a spattering of dirt on his clothing.","html":"About ten minutes later, around a quarter of the forest around the Ravine of the Earthwyrm was gone. Amid the now scorched and barren wasteland, scattered with mounds of splintered trees, there knelt a boy missing both his arms. A sword pressed into this throat. The boy looked up at its wielder in blank shock. A man with silver hair and distinctive eyes stared back. He didn’t have a scratch on him. Looking at him standing there unscathed, you’d think there hadn’t been a battle at all. The only clue was a spattering of dirt on his clothing.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0268","sourceIndex":268,"type":"speech","text":"“Choose. Become my follower or die.”","html":"“Choose. Become my follower or die.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch03-p0269","sourceIndex":269,"type":"narration","text":"The Dragon God against the North God in the Fighting God Armor.","html":"The Dragon God against the North God in the Fighting God Armor.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0270","sourceIndex":270,"type":"narration","text":"That match-up could have been a truly legendary battle. A pair of opponents of that caliber could have gone down in history for good. Sadly, the actual battle was nothing so grand. It was too devastatingly one-sided for that. Honestly? It was tough for me to put it into words. I watched it, getting caught in the melee and narrowly escaping death as I did so, but they moved so fast I could hardly see anything. Even with the Eye of Foresight, I couldn’t tell what either of them were doing. The only thing I saw for sure was that Orsted always had the upper hand. I could tell that every time Alec tried to turn things around, Orsted smashed him into utter submission. He was completely outmatched. Even with the Fighting God Armor and the King Dragon Blade, he couldn’t touch a hair on Orsted’s head. The armor was smashed to pieces, which were now beginning to regenerate, but they had detached from Alec’s body. The King Dragon Blade lay on the ground nearby along with his arm.","html":"That match-up could have been a truly legendary battle. A pair of opponents of that caliber could have gone down in history for good. Sadly, the actual battle was nothing so grand. It was too devastatingly one-sided for that. Honestly? It was tough for me to put it into words. I watched it, getting caught in the melee and narrowly escaping death as I did so, but they moved so fast I could hardly see anything. Even with the Eye of Foresight, I couldn’t tell what either of them were doing. The only thing I saw for sure was that Orsted always had the upper hand. I could tell that every time Alec tried to turn things around, Orsted smashed him into utter submission. He was completely outmatched. Even with the Fighting God Armor and the King Dragon Blade, he couldn’t touch a hair on Orsted’s head. The armor was smashed to pieces, which were now beginning to regenerate, but they had detached from Alec’s body. The King Dragon Blade lay on the ground nearby along with his arm. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0271","sourceIndex":271,"type":"narration","text":"Alec had long since lost all will to fight. He looked up at Orsted, his face petrified with fear. Tears streamed from his defeated eyes, and his mouth hung half open. The boy who’d boasted of becoming a hero was gone. In his place was a whimpering puppy, its spirit entirely broken.","html":"Alec had long since lost all will to fight. He looked up at Orsted, his face petrified with fear. Tears streamed from his defeated eyes, and his mouth hung half open. The boy who’d boasted of becoming a hero was gone. In his place was a whimpering puppy, its spirit entirely broken.","className":"P_Prose_Formatting__And__Page_Break","italic":false,"bold":false,"dropCap":false},{"id":"ch03-p0272","sourceIndex":272,"type":"speech","text":"After a long silence, at last he spoke. “I will become your follower,” he said.","html":"After a long silence, at last he spoke. “I will become your follower,” he said.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","mixed":true,"speakerConfidence":"high"},{"id":"ch03-p0273","sourceIndex":273,"type":"narration","text":"And now, this time, the battle really was over.","html":"And now, this time, the battle really was over. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false}],"wordCount":371,"speechCount":2,"speakers":["Alexander","Orsted"]}],"images":[{"id":"ch03-img01","type":"image","src":"INTERIORIMAGES_04.jpg","alt":""},{"id":"ch03-img02","type":"image","src":"INTERIORIMAGES_05.jpg","alt":""},{"id":"ch03-img03","type":"image","src":"INTERIORIMAGES_06.jpg","alt":""}],"sequence":3,"cast":["Alexander","Badigadi","Cliff","Dohga","Eris","Geese","Ghislaine","Isolde","Orsted","Rudeus","Ruijerd","Sylphiette","Zanoba"],"sceneCount":6,"speechCount":119,"speakers":["Alexander","Badigadi","Eris","Geese","Ghislaine","Orsted","Rudeus","Ruijerd","Sylphiette"]},{"id":"ch04","number":4,"title":"The End of the Battle","pov":"Rudeus","kind":"main","wordCount":7430,"scenes":[{"id":"ch04-s01","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The rebuilding of the Superd Village, one month after the battle","cast":["Aisha","Cliff","Dohga","Elinalise","Ghislaine","Isolde","Linia","Mercenary","Norn","Perugius","Pursena","Rudeus","Ruijerd","Sandor"],"blocks":[{"id":"ch04-p0002","sourceIndex":2,"type":"narration","text":"A MONTH PASSED.","html":"A MONTH PASSED.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0003","sourceIndex":3,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch04-p0004","sourceIndex":4,"type":"narration","text":"I was standing near the edge of the forest in which lay the Ravine of the Earthwyrm. Around me stood simply constructed wooden houses. In a clearing where the trees had been cut down, a jumble of people walked this way and that. There were Superd, human carpenters and laborers hired from the Biheiril Kingdom, woodcutters…and the Ruquag Mercenaries.","html":"I was standing near the edge of the forest in which lay the Ravine of the Earthwyrm. Around me stood simply constructed wooden houses. In a clearing where the trees had been cut down, a jumble of people walked this way and that. There were Superd, human carpenters and laborers hired from the Biheiril Kingdom, woodcutters…and the Ruquag Mercenaries.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0005","sourceIndex":5,"type":"speech","text":"“Hey, Big Bro, could I get you to clear a few trees over on the eastern side of the forest?”","html":"“Hey, Big Bro, could I get you to clear a few trees over on the eastern side of the forest?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Aisha","speakerConfidence":"high"},{"id":"ch04-p0006","sourceIndex":6,"type":"narration","text":"Naturally, Aisha was there too. She strode about the village and issued instructions to everyone. After getting her orders, the mercenaries were then under the command of Linia and Pursena. Watching this, you’d be hard-pressed to say who the real company leader was.","html":"Naturally, Aisha was there too. She strode about the village and issued instructions to everyone. After getting her orders, the mercenaries were then under the command of Linia and Pursena. Watching this, you’d be hard-pressed to say who the real company leader was.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0007","sourceIndex":7,"type":"speech","text":"“Yeah, no problem.” I was working alongside them to rebuild the Superd Village. I cleared trees with magic. Then, I used earth magic to build foundations for houses and a road from the village to the Earthwyrm Ravine. There was lots to be done.","html":"“Yeah, no problem.” I was working alongside them to rebuild the Superd Village. I cleared trees with magic. Then, I used earth magic to build foundations for houses and a road from the village to the Earthwyrm Ravine. There was lots to be done.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0008","sourceIndex":8,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch04-p0009","sourceIndex":9,"type":"narration","text":"I’m sure you’re burning to know why Aisha and the Ruquag Mercenary Band were wandering around here, and why, when Alec showed up, no one was to be found except Orsted.","html":"I’m sure you’re burning to know why Aisha and the Ruquag Mercenary Band were wandering around here, and why, when Alec showed up, no one was to be found except Orsted.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0010","sourceIndex":10,"type":"narration","text":"I guess I’d better explain.","html":"I guess I’d better explain.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0011","sourceIndex":11,"type":"narration","text":"It’s a short story: it was all Aisha’s scheme. Okay, well, scheme sounds like she was getting up to mischief, so let’s call it work—it was all Aisha’s work. When the teleportation circles and communication tablets stopped working, she and the mercenary company had been thrown into chaos. With their lines of contact with far-off nations cut off, unease, then panic set in. Not for Aisha, though. She stayed calm and coolly assessed the situation. They were close to the border. If the fighting had already begun, they wouldn’t get there in time, and there wouldn’t be much they could do. She concluded that, as there was a strong possibility that Geese might flee the scene, they would work on getting the teleportation circles running again—in other words, restoring infrastructure.","html":"It’s a short story: it was all Aisha’s scheme. Okay, well, scheme sounds like she was getting up to mischief, so let’s call it work—it was all Aisha’s work. When the teleportation circles and communication tablets stopped working, she and the mercenary company had been thrown into chaos. With their lines of contact with far-off nations cut off, unease, then panic set in. Not for Aisha, though. She stayed calm and coolly assessed the situation. They were close to the border. If the fighting had already begun, they wouldn’t get there in time, and there wouldn’t be much they could do. She concluded that, as there was a strong possibility that Geese might flee the scene, they would work on getting the teleportation circles running again—in other words, restoring infrastructure. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0012","sourceIndex":12,"type":"narration","text":"The trouble was that in addition to the teleportation circles, all the magic circles back at the office that corresponded to the spare magic circles she had on her had been destroyed. There was nothing she could do. I’d have given up there, in her shoes. I mean, I did give up. But see, Aisha had a brainwave. Her genius brain remembered that a certain individual had a secret technique. This technique allowed one to draw a new magic circle corresponding to a teleportation circle whose pair had been destroyed, and thereby travel to where you wanted to go.","html":"The trouble was that in addition to the teleportation circles, all the magic circles back at the office that corresponded to the spare magic circles she had on her had been destroyed. There was nothing she could do. I’d have given up there, in her shoes. I mean, I did give up. But see, Aisha had a brainwave. Her genius brain remembered that a certain individual had a secret technique. This technique allowed one to draw a new magic circle corresponding to a teleportation circle whose pair had been destroyed, and thereby travel to where you wanted to go.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0013","sourceIndex":13,"type":"narration","text":"The individual in question…c’mon, you know the answer. It was none other than Armored Dragon King Perugius Dola.","html":"The individual in question…c’mon, you know the answer. It was none other than Armored Dragon King Perugius Dola.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0014","sourceIndex":14,"type":"narration","text":"To request his aid, Aisha had hunted down a monument to the Seven Great Powers that stood near the border. When she found it, she used Perugius’s flute to travel to the floating fortress. Perugius, knowing that we wanted to help demons, was reluctant, but something about Aisha convinced him.","html":"To request his aid, Aisha had hunted down a monument to the Seven Great Powers that stood near the border. When she found it, she used Perugius’s flute to travel to the floating fortress. Perugius, knowing that we wanted to help demons, was reluctant, but something about Aisha convinced him.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0015","sourceIndex":15,"type":"speech","text":"“I’ll link up one for you,” he said.","html":"“I’ll link up one for you,” he said.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","recollection":true,"attributionNote":"Recounted line from Perugius during Aisha's errand.","speakerConfidence":"high"},{"id":"ch04-p0016","sourceIndex":16,"type":"narration","text":"Aisha chose to link the magic circle near the border with the teleportation circle that led to the Superd Village.","html":"Aisha chose to link the magic circle near the border with the teleportation circle that led to the Superd Village.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0017","sourceIndex":17,"type":"narration","text":"And so, here we were.","html":"And so, here we were.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0018","sourceIndex":18,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch04-p0019","sourceIndex":19,"type":"speech","text":"“I’m impressed you got Lord Perugius to agree.”","html":"“I’m impressed you got Lord Perugius to agree.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","recollection":true,"attributionNote":"Recounted exchange with Aisha about Perugius.","speakerConfidence":"high"},{"id":"ch04-p0020","sourceIndex":20,"type":"speech","text":"“Yeah, he really didn’t want to. But then I told him Orsted would owe him a favor for this battle and he softened up.”","html":"“Yeah, he really didn’t want to. But then I told him Orsted would owe him a favor for this battle and he softened up.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Aisha","recollection":true,"attributionNote":"Recounted exchange with Aisha about Perugius.","speakerConfidence":"high"},{"id":"ch04-p0021","sourceIndex":21,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch04-p0022","sourceIndex":22,"type":"narration","text":"After that, while I was busy fighting, she’d traveled to the Superd Village. After hearing what was going on, she used the teleportation circle to evacuate the residents and others to the town near the border… It was a close one. If Roxy, after returning to Sharia, had prioritized the ­ordinary teleportation circles rather than summoning the Magic Armor Version Zero, it would all have been for nothing. Luckily enough, Aisha had ended up covering Roxy’s mistake.","html":"After that, while I was busy fighting, she’d traveled to the Superd Village. After hearing what was going on, she used the teleportation circle to evacuate the residents and others to the town near the border… It was a close one. If Roxy, after returning to Sharia, had prioritized the ­ordinary teleportation circles rather than summoning the Magic Armor Version Zero, it would all have been for nothing. Luckily enough, Aisha had ended up covering Roxy’s mistake. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0023","sourceIndex":23,"type":"narration","text":"It was just how the cards had fallen. Roxy was still mortified about it.","html":"It was just how the cards had fallen. Roxy was still mortified about it.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0024","sourceIndex":24,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch04-p0025","sourceIndex":25,"type":"speech","text":"“Around here?”","html":"“Around here?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0026","sourceIndex":26,"type":"speech","text":"“Yeah, just chop ’em all down. Better to make more space than less, right?”","html":"“Yeah, just chop ’em all down. Better to make more space than less, right?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Aisha","speakerConfidence":"high"},{"id":"ch04-p0027","sourceIndex":27,"type":"speech","text":"“Fair enough. I’m on it.”","html":"“Fair enough. I’m on it.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0028","sourceIndex":28,"type":"speech","text":"“Call me when you’re done, okay? I’ll get the mercenaries to cart the wood away.”","html":"“Call me when you’re done, okay? I’ll get the mercenaries to cart the wood away.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Aisha","speakerConfidence":"high"},{"id":"ch04-p0029","sourceIndex":29,"type":"speech","text":"“Yes, sir.”","html":"“Yes, sir.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0030","sourceIndex":30,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch04-p0031","sourceIndex":31,"type":"narration","text":"It had been a month since the battle. I’d stayed on alert, ready to fight, but the next battle never came. There wouldn’t be another one. So, I’d had Roxy, Sylphie, Zanoba, and everyone else head back to Sharia. Eris was also kind enough to accompany their party under the title of “bodyguard.” The magic circle for summoning the Version Zero and the one used in the evacuation had both been destroyed in Orsted’s battle with Alec, so I’d asked Perugius to send a decent portion of the party back again. Those who returned would work on rebuilding the office and restoring the communication tablets and teleportation circles. Apparently, nothing had happened in Sharia. Even the elf girl was safe and sound. The worst of the damage was that the weapons and armor kept under the office were buried, along with the detailed documents Orsted had written out every day. The evacuated Superd villagers connected back up with the magic circle in the Second City of Irelil and returned from near the border. After that, the Biheiril Kingdom officially welcomed the Superd. The kingdom was happy to accept them as citizens. It probably helped that after losing the Third City and the Ogre God, they weren’t in a position to say no. They did set one condition, which was that to facilitate taking the Superd into the country, a minimum of three Superd be sent from the village to serve the kingdom. This was how it had been when establishing peace with the ogres, reportedly. Those three envoys had been chosen and were now working toward restoring the village. If the restoration continued without any problems, the Superd would have a home in the Biheiril Kingdom before long.","html":"It had been a month since the battle. I’d stayed on alert, ready to fight, but the next battle never came. There wouldn’t be another one. So, I’d had Roxy, Sylphie, Zanoba, and everyone else head back to Sharia. Eris was also kind enough to accompany their party under the title of “bodyguard.” The magic circle for summoning the Version Zero and the one used in the evacuation had both been destroyed in Orsted’s battle with Alec, so I’d asked Perugius to send a decent portion of the party back again. Those who returned would work on rebuilding the office and restoring the communication tablets and teleportation circles. Apparently, nothing had happened in Sharia. Even the elf girl was safe and sound. The worst of the damage was that the weapons and armor kept under the office were buried, along with the detailed documents Orsted had written out every day. The evacuated Superd villagers connected back up with the magic circle in the Second City of Irelil and returned from near the border. After that, the Biheiril Kingdom officially welcomed the Superd. The kingdom was happy to accept them as citizens. It probably helped that after losing the Third City and the Ogre God, they weren’t in a position to say no. They did set one condition, which was that to facilitate taking the Superd into the country, a minimum of three Superd be sent from the village to serve the kingdom. This was how it had been when establishing peace with the ogres, reportedly. Those three envoys had been chosen and were now working toward restoring the village. If the restoration continued without any problems, the Superd would have a home in the Biheiril Kingdom before long. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0032","sourceIndex":32,"type":"narration","text":"We had defeated the disciples and made the Superd, the ogres, and the Biheiril Kingdom our allies. We’d won. But could this really be called victory?","html":"We had defeated the disciples and made the Superd, the ogres, and the Biheiril Kingdom our allies. We’d won. But could this really be called victory?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0033","sourceIndex":33,"type":"speech","text":"“Master Rudeus.”","html":"“Master Rudeus.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","speakerConfidence":"high"},{"id":"ch04-p0034","sourceIndex":34,"type":"speech","text":"“Oh, Sandor.” While cutting down trees, lost in my thoughts, Sandor appeared behind me. He wasn’t alone, either. Ghislaine, Isolde, and Dohga were with him.","html":"“Oh, Sandor.” While cutting down trees, lost in my thoughts, Sandor appeared behind me. He wasn’t alone, either. Ghislaine, Isolde, and Dohga were with him. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0035","sourceIndex":35,"type":"narration","text":"Sandor had come back around ten days after the battle ended. Not only had the Fighting God dealt him a mortal wound, he’d also been thrown into the ocean. He somehow managed to drift to Ogre Island, where he took some time to recover. It was impressive that he’d taken on the Fighting God and made it back alive. Only, when I saw him again, he looked uncomfortable. I guess maybe, when you went by the name of North God Kalman, losing in and of itself was an embarrassment. Or wait, maybe it had nothing to do with that, and he was embarrassed because he’d been acting like such a big shot all the time…","html":"Sandor had come back around ten days after the battle ended. Not only had the Fighting God dealt him a mortal wound, he’d also been thrown into the ocean. He somehow managed to drift to Ogre Island, where he took some time to recover. It was impressive that he’d taken on the Fighting God and made it back alive. Only, when I saw him again, he looked uncomfortable. I guess maybe, when you went by the name of North God Kalman, losing in and of itself was an embarrassment. Or wait, maybe it had nothing to do with that, and he was embarrassed because he’d been acting like such a big shot all the time…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0036","sourceIndex":36,"type":"speech","text":"“Hey. What do you need?”","html":"“Hey. What do you need?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","speakerConfidence":"high"},{"id":"ch04-p0037","sourceIndex":37,"type":"speech","text":"“Oh, nothing—we’re planning on returning to Asura soon, you see. So we came to say our farewells.”","html":"“Oh, nothing—we’re planning on returning to Asura soon, you see. So we came to say our farewells.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","speakerConfidence":"high"},{"id":"ch04-p0038","sourceIndex":38,"type":"speech","text":"“Ah. Right.”","html":"“Ah. Right.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0039","sourceIndex":39,"type":"narration","text":"Their work here was over. They were Ariel’s subjects at the end of the day, so if there was no fighting to be done, they had to go home.","html":"Their work here was over. They were Ariel’s subjects at the end of the day, so if there was no fighting to be done, they had to go home.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0040","sourceIndex":40,"type":"speech","text":"“Sandor, thank you,” I said. “We’d never have made it this far if not for you.”","html":"“Sandor, thank you,” I said. “We’d never have made it this far if not for you.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0041","sourceIndex":41,"type":"speech","text":"“Please, it’s Queen Ariel you owe your thanks to.”","html":"“Please, it’s Queen Ariel you owe your thanks to.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","speakerConfidence":"high"},{"id":"ch04-p0042","sourceIndex":42,"type":"speech","text":"“Sure thing. Please tell Her Majesty to let me know right away if she ever runs into trouble. Tell her I won’t hesitate to help.”","html":"“Sure thing. Please tell Her Majesty to let me know right away if she ever runs into trouble. Tell her I won’t hesitate to help.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0043","sourceIndex":43,"type":"speech","text":"“Very well.”","html":"“Very well.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","speakerConfidence":"high"},{"id":"ch04-p0044","sourceIndex":44,"type":"narration","text":"Sandor, Dohga, Ghislaine, and Isolde. Each of them was at least a King-tier sword fighter. I couldn’t thank Ariel enough for sending me such a powerful lineup.","html":"Sandor, Dohga, Ghislaine, and Isolde. Each of them was at least a King-tier sword fighter. I couldn’t thank Ariel enough for sending me such a powerful lineup.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0045","sourceIndex":45,"type":"speech","text":"“Thank you too, Ghislaine.”","html":"“Thank you too, Ghislaine.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0046","sourceIndex":46,"type":"speech","text":"“Don’t thank me. By the way…I’m thinking I’ll come pay a visit to the grave.”","html":"“Don’t thank me. By the way…I’m thinking I’ll come pay a visit to the grave.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ghislaine","speakerConfidence":"high"},{"id":"ch04-p0047","sourceIndex":47,"type":"speech","text":"“Understood. I’ll be waiting.”","html":"“Understood. I’ll be waiting.” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0048","sourceIndex":48,"type":"narration","text":"Ghislaine left it at that.","html":"Ghislaine left it at that.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0049","sourceIndex":49,"type":"speech","text":"“And you, Dohga. I’d have died after falling into the ravine if you hadn’t been there, so thank you.”","html":"“And you, Dohga. I’d have died after falling into the ravine if you hadn’t been there, so thank you.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0050","sourceIndex":50,"type":"speech","text":"“Uh-huh.”","html":"“Uh-huh.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Dohga","speakerConfidence":"high"},{"id":"ch04-p0051","sourceIndex":51,"type":"speech","text":"“If you ever have a personal favor I can do for you, please let me know. I want to pay you back for saving my life.”","html":"“If you ever have a personal favor I can do for you, please let me know. I want to pay you back for saving my life.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0052","sourceIndex":52,"type":"speech","text":"“Uh-huh!”","html":"“Uh-huh!” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Dohga","speakerConfidence":"high"},{"id":"ch04-p0053","sourceIndex":53,"type":"speech","text":"All Dohga said was “Uh-huh,” but he seemed a little sad to be parting.","html":"All Dohga said was “Uh-huh,” but he seemed a little sad to be parting. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Dohga","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0054","sourceIndex":54,"type":"speech","text":"“And thank you, Isolde. If you hadn’t stood between me and the Fighting God, I’d be dead.”","html":"“And thank you, Isolde. If you hadn’t stood between me and the Fighting God, I’d be dead.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0055","sourceIndex":55,"type":"speech","text":"“Not at all! It was a highly educational battle. I should be thanking you.” Isolde bowed gracefully, then grinned. From her face to the way she held herself, she was as beautiful as ever. It made me wonder what the men of Asura were thinking if this woman were still single.","html":"“Not at all! It was a highly educational battle. I should be thanking you.” Isolde bowed gracefully, then grinned. From her face to the way she held herself, she was as beautiful as ever. It made me wonder what the men of Asura were thinking if this woman were still single. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Isolde","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0056","sourceIndex":56,"type":"speech","text":"“And please give my best to the medical team,” I said.","html":"“And please give my best to the medical team,” I said.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0057","sourceIndex":57,"type":"speech","text":"“I will. If that is all…we will take our leave.” Sandor bowed, then turned. As he did so, however, I remembered something I’d forgotten to say and called it out after his back.","html":"“I will. If that is all…we will take our leave.” Sandor bowed, then turned. As he did so, however, I remembered something I’d forgotten to say and called it out after his back.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0058","sourceIndex":58,"type":"speech","text":"“About Lady Atofe—I’m sorry.”","html":"“About Lady Atofe—I’m sorry.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0059","sourceIndex":59,"type":"narration","text":"Sandor had come back, but he was the only one. Atofe was still missing. She must have been swept away by the ocean. She wouldn’t be found for centuries, and the same was true for Moore.","html":"Sandor had come back, but he was the only one. Atofe was still missing. She must have been swept away by the ocean. She wouldn’t be found for centuries, and the same was true for Moore.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0060","sourceIndex":60,"type":"speech","text":"“You needn’t worry about my mother,” Sandor said at last. “One of these days she’ll pop up where you least expect it. It’s the Ogre God I really feel bad for.”","html":"“You needn’t worry about my mother,” Sandor said at last. “One of these days she’ll pop up where you least expect it. It’s the Ogre God I really feel bad for.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0061","sourceIndex":61,"type":"speech","text":"“Yes… True.”","html":"“Yes… True.” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0062","sourceIndex":62,"type":"narration","text":"The Ogre God had been confirmed dead. He had fought well against the Fighting God, but he wasn’t an immortal demon. In the end, his strength had failed, and he had died. And after we’d managed to reconcile. It really was too bad.","html":"The Ogre God had been confirmed dead. He had fought well against the Fighting God, but he wasn’t an immortal demon. In the end, his strength had failed, and he had died. And after we’d managed to reconcile. It really was too bad. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0063","sourceIndex":63,"type":"speech","text":"“Still, it does no good to lament the dead.”","html":"“Still, it does no good to lament the dead.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0064","sourceIndex":64,"type":"speech","text":"“I agree. We have to look forward.”","html":"“I agree. We have to look forward.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","speakerConfidence":"high"},{"id":"ch04-p0065","sourceIndex":65,"type":"narration","text":"I’d made the Ogre God a promise. If he died, I would protect the surviving ogres. They weren’t in any danger at the moment, but even if it was only a promise, I wanted to keep my word if a threat reared its ugly head.","html":"I’d made the Ogre God a promise. If he died, I would protect the surviving ogres. They weren’t in any danger at the moment, but even if it was only a promise, I wanted to keep my word if a threat reared its ugly head.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0066","sourceIndex":66,"type":"speech","text":"“Farewell, then,” Sandor said.","html":"“Farewell, then,” Sandor said.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","speakerConfidence":"high"},{"id":"ch04-p0067","sourceIndex":67,"type":"speech","text":"“Yes. Thank you for everything.”","html":"“Yes. Thank you for everything.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0068","sourceIndex":68,"type":"speech","text":"“Ah, one more thing… Watch out for Alec for me.”","html":"“Ah, one more thing… Watch out for Alec for me.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sandor","speakerConfidence":"high"},{"id":"ch04-p0069","sourceIndex":69,"type":"speech","text":"At length, I said, “I will.”","html":"At length, I said, “I will.” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0070","sourceIndex":70,"type":"narration","text":"Sandor left. No sooner had he gone than I saw Cliff walking up. Elinalise was with him.","html":"Sandor left. No sooner had he gone than I saw Cliff walking up. Elinalise was with him.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0071","sourceIndex":71,"type":"speech","text":"“Rudeus.”","html":"“Rudeus.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Cliff","speakerConfidence":"high"},{"id":"ch04-p0072","sourceIndex":72,"type":"speech","text":"“Cliff.”","html":"“Cliff.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0073","sourceIndex":73,"type":"speech","text":"“Are they going home, too?”","html":"“Are they going home, too?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Cliff","speakerConfidence":"high"},{"id":"ch04-p0074","sourceIndex":74,"type":"speech","text":"“They are. Are you leaving as well, Cliff?”","html":"“They are. Are you leaving as well, Cliff?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0075","sourceIndex":75,"type":"speech","text":"“Yeah. Seeing as everything seems to have wrapped up… We never did get to the bottom of what caused the plague, but seeing as a month has passed without any further outbreaks, and they’ve changed where they live…I’m ­going home, for now.”","html":"“Yeah. Seeing as everything seems to have wrapped up… We never did get to the bottom of what caused the plague, but seeing as a month has passed without any further outbreaks, and they’ve changed where they live…I’m ­going home, for now.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Cliff","speakerConfidence":"high"},{"id":"ch04-p0076","sourceIndex":76,"type":"narration","text":"I was just as indebted to Cliff as the others. We couldn’t have cured the plague without him…even if it was technically the work of the Abyssal King rather than a true plague.","html":"I was just as indebted to Cliff as the others. We couldn’t have cured the plague without him…even if it was technically the work of the Abyssal King rather than a true plague. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0077","sourceIndex":77,"type":"speech","text":"“Thank you, Cliff. I don’t know what would have happened if you hadn’t come…”","html":"“Thank you, Cliff. I don’t know what would have happened if you hadn’t come…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0078","sourceIndex":78,"type":"speech","text":"“It’s you we’re talking about. I’m sure you’d have worked something out yourself. Call me if there’s another outbreak.”","html":"“It’s you we’re talking about. I’m sure you’d have worked something out yourself. Call me if there’s another outbreak.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Cliff","speakerConfidence":"high"},{"id":"ch04-p0079","sourceIndex":79,"type":"speech","text":"“I will… Cliff, I’ve done nothing but rely on you. I don’t even know to best thank you.”","html":"“I will… Cliff, I’ve done nothing but rely on you. I don’t even know to best thank you.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0080","sourceIndex":80,"type":"speech","text":"“I can only leave Lise and Clyde to go do my best work in Millis because your family are there to look after them in Sharia. It’s mutual, Rudeus.”","html":"“I can only leave Lise and Clyde to go do my best work in Millis because your family are there to look after them in Sharia. It’s mutual, Rudeus.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Cliff","speakerConfidence":"high"},{"id":"ch04-p0081","sourceIndex":81,"type":"narration","text":"It was kind of him to say that.","html":"It was kind of him to say that.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0082","sourceIndex":82,"type":"speech","text":"“Anyway, I’ll be seeing you… Oh, but first, I plan on stopping off at your house on the way home. Anything you want me to pass on?”","html":"“Anyway, I’ll be seeing you… Oh, but first, I plan on stopping off at your house on the way home. Anything you want me to pass on?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Cliff","speakerConfidence":"high"},{"id":"ch04-p0083","sourceIndex":83,"type":"speech","text":"“Tell them I’ll be home really soon.”","html":"“Tell them I’ll be home really soon.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0084","sourceIndex":84,"type":"speech","text":"“Got it,” Cliff said.","html":"“Got it,” Cliff said. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Cliff","speakerConfidence":"high"},{"id":"ch04-p0085","sourceIndex":85,"type":"narration","text":"They left with that. Elinalise shot me a wink before she took off after Cliff. She’d helped out plenty too, but I hadn’t been able to say anything to her…but then, she was a neighbor. I could show my thanks through actions.","html":"They left with that. Elinalise shot me a wink before she took off after Cliff. She’d helped out plenty too, but I hadn’t been able to say anything to her…but then, she was a neighbor. I could show my thanks through actions. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0086","sourceIndex":86,"type":"narration","text":"I really had received a lot help this time. Take Cliff: without him, the Superd might have been wiped out by the plague. Without Sandor and Dohga, I wouldn’t be standing here. Atofe’s timing had been utterly godly. First the Atofe Hand, then that perfectly timed attack on Ogre Island. You could say I owed my life to her as well.","html":"I really had received a lot help this time. Take Cliff: without him, the Superd might have been wiped out by the plague. Without Sandor and Dohga, I wouldn’t be standing here. Atofe’s timing had been utterly godly. First the Atofe Hand, then that perfectly timed attack on Ogre Island. You could say I owed my life to her as well. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0087","sourceIndex":87,"type":"narration","text":"Leaving her missing felt so ungrateful that, once things had settled down, I wanted to go out to sea and search for her.","html":"Leaving her missing felt so ungrateful that, once things had settled down, I wanted to go out to sea and search for her. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0088","sourceIndex":88,"type":"narration","text":"The fight ended, and everyone went home. It was an empty feeling, like when a big event wraps up and everyone drifts away from it.","html":"The fight ended, and everyone went home. It was an empty feeling, like when a big event wraps up and everyone drifts away from it. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0089","sourceIndex":89,"type":"speech","text":"“All right.” I’d finished clearing the trees during my musing. Before me spread a pristine stretch of land. After pulling the trees out by their roots, I’d piled them up neatly using earth magic. A job well done, if I do say so myself.","html":"“All right.” I’d finished clearing the trees during my musing. Before me spread a pristine stretch of land. After pulling the trees out by their roots, I’d piled them up neatly using earth magic. A job well done, if I do say so myself.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0090","sourceIndex":90,"type":"speech","text":"“Cool, so now Aisha will… Oh?” I turned around just as Ruijerd and Norn came walking up.","html":"“Cool, so now Aisha will… Oh?” I turned around just as Ruijerd and Norn came walking up.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0091","sourceIndex":91,"type":"speech","text":"“There you are, Big Brother.”","html":"“There you are, Big Brother.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Norn","speakerConfidence":"high"},{"id":"ch04-p0092","sourceIndex":92,"type":"speech","text":"“Norn! Perfect timing. Could I get you to go and tell Aisha that I’m done clearing the trees?”","html":"“Norn! Perfect timing. Could I get you to go and tell Aisha that I’m done clearing the trees?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0093","sourceIndex":93,"type":"speech","text":"“Yes, of course,” Norn replied. She turned at once and ran back toward the village.","html":"“Yes, of course,” Norn replied. She turned at once and ran back toward the village.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Norn","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0094","sourceIndex":94,"type":"narration","text":"Ruijerd drew closer. “Rudeus.”","html":"Ruijerd drew closer. “Rudeus.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","embeddedDialogue":true,"attributionNote":"Narration with Ruijerd's greeting.","speakerConfidence":"high"},{"id":"ch04-p0095","sourceIndex":95,"type":"speech","text":"“Ruijerd.”","html":"“Ruijerd.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0096","sourceIndex":96,"type":"speech","text":"“Sorry to put you through all this.”","html":"“Sorry to put you through all this.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","speakerConfidence":"high"},{"id":"ch04-p0097","sourceIndex":97,"type":"speech","text":"“Hey now,” I shot back, “we promised not to talk like that, Mister.”","html":"“Hey now,” I shot back, “we promised not to talk like that, Mister.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0098","sourceIndex":98,"type":"speech","text":"“I made no such promise.”","html":"“I made no such promise.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","speakerConfidence":"high"},{"id":"ch04-p0099","sourceIndex":99,"type":"speech","text":"“No, I guess you didn’t.”","html":"“No, I guess you didn’t.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0100","sourceIndex":100,"type":"narration","text":"Ruijerd was working on the village’s recovery. After that, he’d probably frequent our office, or else take a role negotiating with the Biheiril Kingdom. Norn followed him around everywhere. It looked like she planned on staying and helping him out, at least until the village was rebuilt.","html":"Ruijerd was working on the village’s recovery. After that, he’d probably frequent our office, or else take a role negotiating with the Biheiril Kingdom. Norn followed him around everywhere. It looked like she planned on staying and helping him out, at least until the village was rebuilt.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0101","sourceIndex":101,"type":"speech","text":"“Please come and visit Sharia again once the village is finished.”","html":"“Please come and visit Sharia again once the village is finished.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0102","sourceIndex":102,"type":"speech","text":"“I will. I want to meet your children.”","html":"“I will. I want to meet your children.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","speakerConfidence":"high"},{"id":"ch04-p0103","sourceIndex":103,"type":"speech","text":"“They’re super cute.”","html":"“They’re super cute.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0104","sourceIndex":104,"type":"speech","text":"“All parents say that about their children,” Ruijerd said, smiling. Then, he looked at me. We were practically the same height. “You really got stronger,” he said. “I never thought you’d go as far as becoming one of the Seven Great Powers.”","html":"“All parents say that about their children,” Ruijerd said, smiling. Then, he looked at me. We were practically the same height. “You really got stronger,” he said. “I never thought you’d go as far as becoming one of the Seven Great Powers.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0105","sourceIndex":105,"type":"speech","text":"“You could become one right now if you wanted. One punch from you, Ruijerd, and I’m down. One punch.”","html":"“You could become one right now if you wanted. One punch from you, Ruijerd, and I’m down. One punch.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0106","sourceIndex":106,"type":"speech","text":"“Don’t joke.”","html":"“Don’t joke.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","speakerConfidence":"high"},{"id":"ch04-p0107","sourceIndex":107,"type":"speech","text":"“Still, it’s a fact that I didn’t get here through my own strength alone.”","html":"“Still, it’s a fact that I didn’t get here through my own strength alone.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0108","sourceIndex":108,"type":"speech","text":"“Perhaps that is your strength.”","html":"“Perhaps that is your strength.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","speakerConfidence":"high"},{"id":"ch04-p0109","sourceIndex":109,"type":"speech","text":"“Maybe so.”","html":"“Maybe so.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0110","sourceIndex":110,"type":"narration","text":"After watching me for a little while, Ruijerd smiled. He took the pendant that hung around his neck and held it out to me. It was Roxy’s pendant.","html":"After watching me for a little while, Ruijerd smiled. He took the pendant that hung around his neck and held it out to me. It was Roxy’s pendant.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0111","sourceIndex":111,"type":"speech","text":"“It’s time for me to return this.”","html":"“It’s time for me to return this.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","speakerConfidence":"high"},{"id":"ch04-p0112","sourceIndex":112,"type":"speech","text":"“But this is…”","html":"“But this is…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0113","sourceIndex":113,"type":"speech","text":"“It should be yours after all.” I’d given this pendant to Ruijerd when we parted for the first time. Roxy’s pendant, the one that seemed to have at some point become my mark. This very pendant had first inspired me to go out into this world.","html":"“It should be yours after all.” I’d given this pendant to Ruijerd when we parted for the first time. Roxy’s pendant, the one that seemed to have at some point become my mark. This very pendant had first inspired me to go out into this world.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0114","sourceIndex":114,"type":"speech","text":"“Thank you,” I said, and accepted it. When I gave it to him back then, it had been for a silly reason. When we’d parted I hadn’t needed him to give it back, I’d just wanted him to take it with him. Maybe I wanted a connection with him. Now, he had given it back. Because we were already like brothers. We wouldn’t be parting again for a long while.","html":"“Thank you,” I said, and accepted it. When I gave it to him back then, it had been for a silly reason. When we’d parted I hadn’t needed him to give it back, I’d just wanted him to take it with him. Maybe I wanted a connection with him. Now, he had given it back. Because we were already like brothers. We wouldn’t be parting again for a long while. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0115","sourceIndex":115,"type":"speech","text":"“Ruijerd, you’ll have my back, right?”","html":"“Ruijerd, you’ll have my back, right?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0116","sourceIndex":116,"type":"speech","text":"“I will, though it might be beyond me.”","html":"“I will, though it might be beyond me.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","speakerConfidence":"high"},{"id":"ch04-p0117","sourceIndex":117,"type":"speech","text":"“We can each be what the other lacks.”","html":"“We can each be what the other lacks.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0118","sourceIndex":118,"type":"narration","text":"Ruijerd chuckled. “That we can.”","html":"Ruijerd chuckled. “That we can.” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ruijerd","embeddedDialogue":true,"attributionNote":"Narration with Ruijerd's amused reply.","speakerConfidence":"high"},{"id":"ch04-p0119","sourceIndex":119,"type":"narration","text":"I smiled, and Ruijerd smiled back.","html":"I smiled, and Ruijerd smiled back.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0120","sourceIndex":120,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":2545,"speechCount":78,"speakers":["Aisha","Cliff","Dohga","Ghislaine","Isolde","Norn","Rudeus","Ruijerd","Sandor"]},{"id":"ch04-s02","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The Superd Village, by the magic circles","cast":["Alexander","Orsted","Rudeus"],"blocks":[{"id":"ch04-p0122","sourceIndex":122,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch04-p0123","sourceIndex":123,"type":"narration","text":"Norn brought the mercenaries along with her, and Ruijerd went back to the village. I left the construction sites and walked to the magic circles. I thought it was about time to head back to Sharia for a bit.","html":"Norn brought the mercenaries along with her, and Ruijerd went back to the village. I left the construction sites and walked to the magic circles. I thought it was about time to head back to Sharia for a bit.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0124","sourceIndex":124,"type":"narration","text":"Then, with a start, I noticed another person coming the other way. It was Orsted wearing his black helmet as usual, and he wasn’t alone. A black-haired boy trailed after him like a retainer. It reminded me of Atofe and Moore, or Perugius and Sylvaril. Like he’d been in this role for a hundred years. As much as I wanted to point out that I’d been here first, if it came to blows I’d lose. I kept my mouth shut.","html":"Then, with a start, I noticed another person coming the other way. It was Orsted wearing his black helmet as usual, and he wasn’t alone. A black-haired boy trailed after him like a retainer. It reminded me of Atofe and Moore, or Perugius and Sylvaril. Like he’d been in this role for a hundred years. As much as I wanted to point out that I’d been here first, if it came to blows I’d lose. I kept my mouth shut. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0125","sourceIndex":125,"type":"narration","text":"Still, whenever I saw him, my teeth were on edge.","html":"Still, whenever I saw him, my teeth were on edge.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0126","sourceIndex":126,"type":"speech","text":"“Is something the matter?”","html":"“Is something the matter?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","speakerConfidence":"high"},{"id":"ch04-p0127","sourceIndex":127,"type":"speech","text":"“No,” I muttered.","html":"“No,” I muttered.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0128","sourceIndex":128,"type":"speech","text":"“If I have done anything to offend you, please let me know. I’ll be sure not to repeat it.”","html":"“If I have done anything to offend you, please let me know. I’ll be sure not to repeat it.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","speakerConfidence":"high"},{"id":"ch04-p0129","sourceIndex":129,"type":"narration","text":"My wariness notwithstanding, Alec had grown submissive since that day. He was so earnest it made me wonder if it wasn’t a cover for something else. Orsted demanded absolute obedience from me as well, though, so I knew it was genuine.","html":"My wariness notwithstanding, Alec had grown submissive since that day. He was so earnest it made me wonder if it wasn’t a cover for something else. Orsted demanded absolute obedience from me as well, though, so I knew it was genuine.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0130","sourceIndex":130,"type":"speech","text":"“I understand why you are wary, but after the battle the other day, I know my place. I understand now how inexperienced and insignificant I am. I hope to devote myself to study under Sir Orsted and you, Sir Rudeus, during which time I will seek to understand what it means to be a hero, and what it means to be North God. I have had my sword hand sealed—as you can see here—as both proof of my intentions and as a warning to myself.” Alec raised his right arm to show me. It was severed cleanly at the wrist with a pattern carved into the stump. Orsted had cast that seal. Because of his immortal demon blood, Alec regenerated even when cut to pieces. He couldn’t do it as speedily as Badigadi or Atofe, but it would inevitably happen after enough time. That was why, after cutting his right hand off, he’d asked Orsted to put a seal on it to stop it from growing back. It was proof of his loyalty.","html":"“I understand why you are wary, but after the battle the other day, I know my place. I understand now how inexperienced and insignificant I am. I hope to devote myself to study under Sir Orsted and you, Sir Rudeus, during which time I will seek to understand what it means to be a hero, and what it means to be North God. I have had my sword hand sealed—as you can see here—as both proof of my intentions and as a warning to myself.” Alec raised his right arm to show me. It was severed cleanly at the wrist with a pattern carved into the stump. Orsted had cast that seal. Because of his immortal demon blood, Alec regenerated even when cut to pieces. He couldn’t do it as speedily as Badigadi or Atofe, but it would inevitably happen after enough time. That was why, after cutting his right hand off, he’d asked Orsted to put a seal on it to stop it from growing back. It was proof of his loyalty.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0131","sourceIndex":131,"type":"narration","text":"I supplied the mana to the sealing magic circle, by the way.","html":"I supplied the mana to the sealing magic circle, by the way.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0132","sourceIndex":132,"type":"speech","text":"“I’m hardly a threat with only my left hand, am I?” Alec continued.","html":"“I’m hardly a threat with only my left hand, am I?” Alec continued.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0133","sourceIndex":133,"type":"speech","text":"“I think you could kill me with both arms missing, actually. With a headbutt or something.”","html":"“I think you could kill me with both arms missing, actually. With a headbutt or something.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0134","sourceIndex":134,"type":"speech","text":"“You needn’t worry…but then, such modesty is to be praised, I suppose. I look forward to your continued advice and guidance.”","html":"“You needn’t worry…but then, such modesty is to be praised, I suppose. I look forward to your continued advice and guidance.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","speakerConfidence":"high"},{"id":"ch04-p0135","sourceIndex":135,"type":"speech","text":"“R-right… I really do think that, you know.”","html":"“R-right… I really do think that, you know.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0136","sourceIndex":136,"type":"narration","text":"Orsted apparently trusted Alec, for he didn’t say anything about letting him stay close. I, meanwhile, had the feeling Alec was going to knife me in the back one day. Put plainly, he scared me. Even knowing that he wasn’t the sharpest tool in the box, scary’s still scary.","html":"Orsted apparently trusted Alec, for he didn’t say anything about letting him stay close. I, meanwhile, had the feeling Alec was going to knife me in the back one day. Put plainly, he scared me. Even knowing that he wasn’t the sharpest tool in the box, scary’s still scary.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0137","sourceIndex":137,"type":"speech","text":"“So, uh, if you ever find yourself thinking, ‘Gee, I really want to be in the Seven Great Powers again,’ let me know? I’ll give it back any time.”","html":"“So, uh, if you ever find yourself thinking, ‘Gee, I really want to be in the Seven Great Powers again,’ let me know? I’ll give it back any time.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0138","sourceIndex":138,"type":"speech","text":"“Oh! About that, once I believe I’ve gained sufficient experience, I will ask you again.”","html":"“Oh! About that, once I believe I’ve gained sufficient experience, I will ask you again.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","speakerConfidence":"high"},{"id":"ch04-p0139","sourceIndex":139,"type":"speech","text":"“You will ask me, right? Sneak attacks from behind are against the rules.”","html":"“You will ask me, right? Sneak attacks from behind are against the rules.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0140","sourceIndex":140,"type":"speech","text":"“It may be that I challenge the Sword God and not you, Master Rudeus. Though rest assured that if I do challenge you, I shall do it with honor!”","html":"“It may be that I challenge the Sword God and not you, Master Rudeus. Though rest assured that if I do challenge you, I shall do it with honor!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","speakerConfidence":"high"},{"id":"ch04-p0141","sourceIndex":141,"type":"speech","text":"“And no sharp edges, okay? I don’t want to fight to the death.”","html":"“And no sharp edges, okay? I don’t want to fight to the death.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0142","sourceIndex":142,"type":"speech","text":"“Understood!”","html":"“Understood!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","speakerConfidence":"high"},{"id":"ch04-p0143","sourceIndex":143,"type":"narration","text":"At present, the Seven Great Powers stood as follows:","html":"At present, the Seven Great Powers stood as follows:","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0144","sourceIndex":144,"type":"narration","text":"Number One: Technique God Laplace.","html":"Number One: Technique God Laplace.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0145","sourceIndex":145,"type":"narration","text":"Number Two: Dragon God Orsted.","html":"Number Two: Dragon God Orsted.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0146","sourceIndex":146,"type":"narration","text":"Number Three: Fighting God Badigadi.","html":"Number Three: Fighting God Badigadi.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0147","sourceIndex":147,"type":"narration","text":"Number Four: Demon God Laplace.","html":"Number Four: Demon God Laplace.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0148","sourceIndex":148,"type":"narration","text":"Number Five: Death God Randolph.","html":"Number Five: Death God Randolph.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0149","sourceIndex":149,"type":"narration","text":"Number Six: Sword God Gino Britz.","html":"Number Six: Sword God Gino Britz.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0150","sourceIndex":150,"type":"narration","text":"Number Seven: Quagmire Rudeus Greyrat.","html":"Number Seven: Quagmire Rudeus Greyrat.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0151","sourceIndex":151,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch04-p0152","sourceIndex":152,"type":"narration","text":"I was the only one who looked ridiculously out of place, and I didn’t like it. It also really got me down thinking that I’d have to put up with idiots coming and attacking me to try and win a spot in the lineup.","html":"I was the only one who looked ridiculously out of place, and I didn’t like it. It also really got me down thinking that I’d have to put up with idiots coming and attacking me to try and win a spot in the lineup. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0153","sourceIndex":153,"type":"narration","text":"My mark was the mark of the Migurds, which I’d rarely shown off up until now. Even after Ruijerd had returned Roxy’s pendant to me, I didn’t plan to start waving it around for anyone to see. No one should know who the Great Power actually was. My name wasn’t especially well-known either, so that should keep the challengers at bay.","html":"My mark was the mark of the Migurds, which I’d rarely shown off up until now. Even after Ruijerd had returned Roxy’s pendant to me, I didn’t plan to start waving it around for anyone to see. No one should know who the Great Power actually was. My name wasn’t especially well-known either, so that should keep the challengers at bay.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0154","sourceIndex":154,"type":"narration","text":"Yeah, I’d stick with “Number Seven: Identity Unknown” for a while.","html":"Yeah, I’d stick with “Number Seven: Identity Unknown” for a while. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0155","sourceIndex":155,"type":"narration","text":"In case you’re interested, the Fighting God’s rank didn’t change in the last battle. Orsted said that it wouldn’t change unless the Fighting God Armor was totally annihilated.","html":"In case you’re interested, the Fighting God’s rank didn’t change in the last battle. Orsted said that it wouldn’t change unless the Fighting God Armor was totally annihilated. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0156","sourceIndex":156,"type":"narration","text":"I turned my gaze away from the fired-up and antsy Alec toward Orsted.","html":"I turned my gaze away from the fired-up and antsy Alec toward Orsted.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0157","sourceIndex":157,"type":"speech","text":"“Sir Orsted, ah…how are you feeling these days?” I asked. He had been listening in silence to our conversation.","html":"“Sir Orsted, ah…how are you feeling these days?” I asked. He had been listening in silence to our conversation.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0158","sourceIndex":158,"type":"speech","text":"“Not bad. Using a little mana doesn’t worsen things especially, anyway.”","html":"“Not bad. Using a little mana doesn’t worsen things especially, anyway.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch04-p0159","sourceIndex":159,"type":"narration","text":"Orsted had used mana in the last fight, and a lot of it. He said it had taken about half of his total. The fight had looked like an easy victory from where I was standing, and given he’d finished with full HP and only used half his MP, you couldn’t say it hadn’t been. Things looked different when he couldn’t recover any of that MP, though. He had used the mana he’d been saving for Laplace and the Man-God. We’d won, but the Man-God had satisfied one of his own victory conditions. Would it still count as a victory for us?","html":"Orsted had used mana in the last fight, and a lot of it. He said it had taken about half of his total. The fight had looked like an easy victory from where I was standing, and given he’d finished with full HP and only used half his MP, you couldn’t say it hadn’t been. Things looked different when he couldn’t recover any of that MP, though. He had used the mana he’d been saving for Laplace and the Man-God. We’d won, but the Man-God had satisfied one of his own victory conditions. Would it still count as a victory for us?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0160","sourceIndex":160,"type":"speech","text":"“Our allies are more numerous and our enemies fewer. I will have still less reason for using magic from here on out.”","html":"“Our allies are more numerous and our enemies fewer. I will have still less reason for using magic from here on out.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch04-p0161","sourceIndex":161,"type":"narration","text":"Orsted didn’t seem bothered by it. Maybe he was trying to be optimistic.","html":"Orsted didn’t seem bothered by it. Maybe he was trying to be optimistic.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0162","sourceIndex":162,"type":"speech","text":"“I sure hope so,” I said.","html":"“I sure hope so,” I said.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0163","sourceIndex":163,"type":"speech","text":"“Even if it does not turn out so, this time was different to all that came before. Thus, we need only continue along a different path to before. I am already resolved to that.”","html":"“Even if it does not turn out so, this time was different to all that came before. Thus, we need only continue along a different path to before. I am already resolved to that.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch04-p0164","sourceIndex":164,"type":"narration","text":"Orsted was counting on me. Even if he used up the mana he was keeping for Laplace and the Man-God, it didn’t matter to him because I was fighting alongside him.","html":"Orsted was counting on me. Even if he used up the mana he was keeping for Laplace and the Man-God, it didn’t matter to him because I was fighting alongside him.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0165","sourceIndex":165,"type":"narration","text":"It seemed that to him, this had been a perfect victory. If he thought it was a win, it was. To be sure, there had been hardly any deaths—the Ogre God, several Superd, and several of Atofe’s personal guard. That was the extent of the casualties. Orsted’s mana was the only area where I felt like we’d been defeated.","html":"It seemed that to him, this had been a perfect victory. If he thought it was a win, it was. To be sure, there had been hardly any deaths—the Ogre God, several Superd, and several of Atofe’s personal guard. That was the extent of the casualties. Orsted’s mana was the only area where I felt like we’d been defeated. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0166","sourceIndex":166,"type":"speech","text":"“Oh, yes. What did you need me for?”","html":"“Oh, yes. What did you need me for?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0167","sourceIndex":167,"type":"speech","text":"“I will be returning to Sharia.”","html":"“I will be returning to Sharia.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch04-p0168","sourceIndex":168,"type":"speech","text":"“Understood. I was thinking about going back myself… Oh, but I didn’t think the office had been rebuilt yet?”","html":"“Understood. I was thinking about going back myself… Oh, but I didn’t think the office had been rebuilt yet?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0169","sourceIndex":169,"type":"speech","text":"“No matter. There will be somewhere I can sleep.”","html":"“No matter. There will be somewhere I can sleep.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch04-p0170","sourceIndex":170,"type":"narration","text":"The basement with the teleportation circles had been dug out to a bare minimum with earth magic, but with the restoration work continuing, it would need to be expanded. I also had to come up with a countermeasure to stop something like the Ogre God’s destructive rampage from happening to it again. Admittedly, I was fresh out of good ideas on that score. It might be better to not have magic circles for any nations outside the principle ones. It was shocking that I’d never considered the possibility of an enemy using them to break in before.","html":"The basement with the teleportation circles had been dug out to a bare minimum with earth magic, but with the restoration work continuing, it would need to be expanded. I also had to come up with a countermeasure to stop something like the Ogre God’s destructive rampage from happening to it again. Admittedly, I was fresh out of good ideas on that score. It might be better to not have magic circles for any nations outside the principle ones. It was shocking that I’d never considered the possibility of an enemy using them to break in before.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0171","sourceIndex":171,"type":"speech","text":"“But first, I will go and see him one last time.”","html":"“But first, I will go and see him one last time.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch04-p0172","sourceIndex":172,"type":"narration","text":"Oh. Him.","html":"Oh. Him.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0173","sourceIndex":173,"type":"speech","text":"“I’ll accompany you,” I said.","html":"“I’ll accompany you,” I said. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0174","sourceIndex":174,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":1244,"speechCount":25,"speakers":["Alexander","Orsted","Rudeus"]},{"id":"ch04-s03","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The bottom of the Ravine of the Earthwyrm, Badigadi's seal","cast":["Alexander","Badigadi","Orsted","Rudeus"],"blocks":[{"id":"ch04-p0176","sourceIndex":176,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch04-p0177","sourceIndex":177,"type":"narration","text":"That night, Orsted and I went to the Ravine of the Earthwyrm—to the bottom of the ravine. We went down the level path surrounded by blue mushrooms and lichen, to a little hole carved so it was concealed in the wall. It was about a meter tall; due to its slight curvature, it looked from the outside like it ran straight into a dead end. If you followed it ten meters or so down, it let out into a large cavern. In the cavern was a vast, glowing magic circle with a sword at its center. Maybe vast was overstating it. It was five meters in radius at most. Within it lay a reclining man.","html":"That night, Orsted and I went to the Ravine of the Earthwyrm—to the bottom of the ravine. We went down the level path surrounded by blue mushrooms and lichen, to a little hole carved so it was concealed in the wall. It was about a meter tall; due to its slight curvature, it looked from the outside like it ran straight into a dead end. If you followed it ten meters or so down, it let out into a large cavern. In the cavern was a vast, glowing magic circle with a sword at its center. Maybe vast was overstating it. It was five meters in radius at most. Within it lay a reclining man.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0178","sourceIndex":178,"type":"speech","text":"“So, you have come.”","html":"“So, you have come.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch04-p0179","sourceIndex":179,"type":"narration","text":"It was Fighting God Badigadi. His body had been split into five pieces, each of which was sealed in a different location in the ravine. His main body was here. This barrier couldn’t be broken unless the other four seals were broken first. It operated using the mana from Badigadi’s own body and was amplified—and therefore, sustained—by the King Dragon Blade and the Fighting God Armor. It would go on operating almost in perpetuity. It was a custom-made barrier magic circle, a Perugius specialty. It was Divine-tier barrier magic, created to seal the Demon God. The sealed subject served as the medium and the magical implements as vectors, and the more powerful each were, the stronger the barrier became. This one used both the Fighting God Armor and the King Dragon Blade, meaning the barrier it generated was so powerful that even Orsted would be helpless to escape it. Using two Divine-tier pieces of equipment as one part of a barrier might have been overdoing it a tad. But that equipment was far more formidable in the hands of our enemies than used by us. Given that just the other day our enemies had used our teleportation circles against us, this wasn’t out of proportion to the threat. As long as the seal on Badigadi remained intact, it effectively rendered the Magic Armor and King Dragon Blade sealed as well.","html":"It was Fighting God Badigadi. His body had been split into five pieces, each of which was sealed in a different location in the ravine. His main body was here. This barrier couldn’t be broken unless the other four seals were broken first. It operated using the mana from Badigadi’s own body and was amplified—and therefore, sustained—by the King Dragon Blade and the Fighting God Armor. It would go on operating almost in perpetuity. It was a custom-made barrier magic circle, a Perugius specialty. It was Divine-tier barrier magic, created to seal the Demon God. The sealed subject served as the medium and the magical implements as vectors, and the more powerful each were, the stronger the barrier became. This one used both the Fighting God Armor and the King Dragon Blade, meaning the barrier it generated was so powerful that even Orsted would be helpless to escape it. Using two Divine-tier pieces of equipment as one part of a barrier might have been overdoing it a tad. But that equipment was far more formidable in the hands of our enemies than used by us. Given that just the other day our enemies had used our teleportation circles against us, this wasn’t out of proportion to the threat. As long as the seal on Badigadi remained intact, it effectively rendered the Magic Armor and King Dragon Blade sealed as well.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0180","sourceIndex":180,"type":"narration","text":"If anyone broke through this, we might as well just give up there and then. That was the reasoning.","html":"If anyone broke through this, we might as well just give up there and then. That was the reasoning.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0181","sourceIndex":181,"type":"narration","text":"Orsted had gone to Perugius to request the base for the barrier. He had bowed his head and asked Perugius for his aid, and Perugius had agreed. It wasn’t just about the barrier: Perugius was Orsted’s ally now. They were joined by a bond of fellowship. But Orsted would later have to kill Perugius. He had chosen the path of betrayal.","html":"Orsted had gone to Perugius to request the base for the barrier. He had bowed his head and asked Perugius for his aid, and Perugius had agreed. It wasn’t just about the barrier: Perugius was Orsted’s ally now. They were joined by a bond of fellowship. But Orsted would later have to kill Perugius. He had chosen the path of betrayal.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0182","sourceIndex":182,"type":"narration","text":"I was indebted to Perugius and Orsted both, so my personal feelings about it were complicated. I knew that Orsted hadn’t wanted to do it this way. That he had chosen it anyway meant that it wasn’t for me to say anything about it. If only, I thought, there was a way to get to the Man-God without using the Dragon Tribe’s sacred treasures, but I knew it wasn’t a problem you could solve with wishes and a little time in a library.","html":"I was indebted to Perugius and Orsted both, so my personal feelings about it were complicated. I knew that Orsted hadn’t wanted to do it this way. That he had chosen it anyway meant that it wasn’t for me to say anything about it. If only, I thought, there was a way to get to the Man-God without using the Dragon Tribe’s sacred treasures, but I knew it wasn’t a problem you could solve with wishes and a little time in a library.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0183","sourceIndex":183,"type":"narration","text":"Ah, well. Maybe it wasn’t something I ought to be thinking about. I had the guy in front of me to worry about right now.","html":"Ah, well. Maybe it wasn’t something I ought to be thinking about. I had the guy in front of me to worry about right now.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0184","sourceIndex":184,"type":"speech","text":"“I am terribly sorry, Your Majesty, but as you’re a disciple of the Man-God, we had no choice.”","html":"“I am terribly sorry, Your Majesty, but as you’re a disciple of the Man-God, we had no choice.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0185","sourceIndex":185,"type":"speech","text":"“I am cramped,” Badigadi said pompously as he lay there like a reclining Buddha. “I should like a little more freedom of movement.”","html":"“I am cramped,” Badigadi said pompously as he lay there like a reclining Buddha. “I should like a little more freedom of movement.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0186","sourceIndex":186,"type":"narration","text":"I had my own relationship with jail cells, but I think even I would have found the sealed barrier cramped. Having said that, I hated the idea of killing him. Kishirika had also asked us not to.","html":"I had my own relationship with jail cells, but I think even I would have found the sealed barrier cramped. Having said that, I hated the idea of killing him. Kishirika had also asked us not to.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0187","sourceIndex":187,"type":"speech","text":"“I really am sorry, but this is as much as I can do.”","html":"“I really am sorry, but this is as much as I can do.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0188","sourceIndex":188,"type":"speech","text":"“Humph. Then so it must be!” Badigadi said, adding a little fwahaha of laughter.","html":"“Humph. Then so it must be!” Badigadi said, adding a little fwahaha of laughter.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0189","sourceIndex":189,"type":"narration","text":"He had two arms, and his body was smaller than it had been before. That was the result of the seal.","html":"He had two arms, and his body was smaller than it had been before. That was the result of the seal.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0190","sourceIndex":190,"type":"speech","text":"“Now! What brings you here, pray tell? I assume you have not come to drink and make merry while basking in my sultry allure?”","html":"“Now! What brings you here, pray tell? I assume you have not come to drink and make merry while basking in my sultry allure?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch04-p0191","sourceIndex":191,"type":"speech","text":"“Sir Orsted has something to speak with you about,” I said, then stepped aside for Orsted.","html":"“Sir Orsted has something to speak with you about,” I said, then stepped aside for Orsted.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0192","sourceIndex":192,"type":"speech","text":"“Demon King Badigadi,” he intoned.","html":"“Demon King Badigadi,” he intoned.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch04-p0193","sourceIndex":193,"type":"speech","text":"“Good evening to you, Master Dragon God. And how may I be of assistance?”","html":"“Good evening to you, Master Dragon God. And how may I be of assistance?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch04-p0194","sourceIndex":194,"type":"speech","text":"“Leave the Man-God and submit to me.”","html":"“Leave the Man-God and submit to me.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch04-p0195","sourceIndex":195,"type":"narration","text":"For a moment, Badigadi gaped at him. But then, he burst out in raucous laughter. “Fwahahahahahaha!” It echoed around the cavern.","html":"For a moment, Badigadi gaped at him. But then, he burst out in raucous laughter. “Fwahahahahahaha!” It echoed around the cavern.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0196","sourceIndex":196,"type":"speech","text":"“The pariah of the dragon tribe dares command me, an immortal demon, to bow down to him?”","html":"“The pariah of the dragon tribe dares command me, an immortal demon, to bow down to him?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch04-p0197","sourceIndex":197,"type":"speech","text":"“There was a time when we were enemies, but you are a friend of Rudeus’s. Alex, Alexander, and Atofe have all allied themselves with me. There is surely room for you to consider it.”","html":"“There was a time when we were enemies, but you are a friend of Rudeus’s. Alex, Alexander, and Atofe have all allied themselves with me. There is surely room for you to consider it.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch04-p0198","sourceIndex":198,"type":"speech","text":"“There is not!” Badigadi said defiantly.","html":"“There is not!” Badigadi said defiantly.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0199","sourceIndex":199,"type":"speech","text":"“But why, Great-Uncle?” Alec, who had been standing near the entrance to the cavern, stepped forward. “You’re defeated, are you not? In accordance with the laws of the immortal demons—”","html":"“But why, Great-Uncle?” Alec, who had been standing near the entrance to the cavern, stepped forward. “You’re defeated, are you not? In accordance with the laws of the immortal demons—”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0200","sourceIndex":200,"type":"speech","text":"“Alec, do not misunderstand. That is not a rule across all of immortal demonkind. It is an Atofe rule.”","html":"“Alec, do not misunderstand. That is not a rule across all of immortal demonkind. It is an Atofe rule.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch04-p0201","sourceIndex":201,"type":"speech","text":"““Have you pledged your loyalty to the Man-God then, Great-Uncle?”","html":"““Have you pledged your loyalty to the Man-God then, Great-Uncle?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","speakerConfidence":"high"},{"id":"ch04-p0202","sourceIndex":202,"type":"speech","text":"“I have not.” Badigadi sat up and shook his head. Then he folded his only pair of arms and crossed his legs. “I was not one for fighting, originally. What I liked was to travel, to drink and be merry, seducing passing women, bedding them, on occasion. Taking a beating from a jilted fiancé, making friends and drinking, laughing, and singing, then looking around at the worn-out faces, sleeping and satisfied. The Man-God came to me, head bowed, and asked me to fight, and so I did. That is all it was. ‘I want you to kill Dragon God Orsted and Rudeus Greyrat, no matter what,’ he said. ‘Who do you have to thank that you and Kishirika are alive in the same era?’ he said. And he asked me to remember four thousand two hundred years back and repay the debt I owed him. As a result, I agreed to help him this one time.” He paused for a moment. “That one time has passed. Now, I ally myself to no one! If my choice is to fight or to be sealed in this place, then I choose to remain sealed.”","html":"“I have not.” Badigadi sat up and shook his head. Then he folded his only pair of arms and crossed his legs. “I was not one for fighting, originally. What I liked was to travel, to drink and be merry, seducing passing women, bedding them, on occasion. Taking a beating from a jilted fiancé, making friends and drinking, laughing, and singing, then looking around at the worn-out faces, sleeping and satisfied. The Man-God came to me, head bowed, and asked me to fight, and so I did. That is all it was. ‘I want you to kill Dragon God Orsted and Rudeus Greyrat, no matter what,’ he said. ‘Who do you have to thank that you and Kishirika are alive in the same era?’ he said. And he asked me to remember four thousand two hundred years back and repay the debt I owed him. As a result, I agreed to help him this one time.” He paused for a moment. “That one time has passed. Now, I ally myself to no one! If my choice is to fight or to be sealed in this place, then I choose to remain sealed.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0203","sourceIndex":203,"type":"narration","text":"That made me think that maybe we could let him go. Though he was still a disciple of the Man-God, so we couldn’t just blindly let him loose after nothing more than a bout of smooth talk.","html":"That made me think that maybe we could let him go. Though he was still a disciple of the Man-God, so we couldn’t just blindly let him loose after nothing more than a bout of smooth talk.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0204","sourceIndex":204,"type":"speech","text":"“Either way,” Badigadi went on, grinning at me as I pondered, “You’ll release me when your fight against the Man-God concludes, will you not?”","html":"“Either way,” Badigadi went on, grinning at me as I pondered, “You’ll release me when your fight against the Man-God concludes, will you not?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0205","sourceIndex":205,"type":"speech","text":"“Yes,” Orsted said. I looked at him, and that’s when I realized.","html":"“Yes,” Orsted said. I looked at him, and that’s when I realized. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0206","sourceIndex":206,"type":"narration","text":"It wouldn’t happen during my lifetime, but if Orsted won his battle with the Man-God, there’d be no need to keep Badigadi chained up any longer.","html":"It wouldn’t happen during my lifetime, but if Orsted won his battle with the Man-God, there’d be no need to keep Badigadi chained up any longer.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0207","sourceIndex":207,"type":"speech","text":"“It will be a hundred years hence.”","html":"“It will be a hundred years hence.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch04-p0208","sourceIndex":208,"type":"speech","text":"“Not so soon then. I shall be patient,” Badigadi said, then lay back down. With a nod, Orsted turned to leave. It looked like the discussion was over. That was quick.","html":"“Not so soon then. I shall be patient,” Badigadi said, then lay back down. With a nod, Orsted turned to leave. It looked like the discussion was over. That was quick.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0209","sourceIndex":209,"type":"speech","text":"“Your Majesty, I…I know this might not be the best circumstances to say it, but I wanted to thank you for everything at the Magic University.”","html":"“Your Majesty, I…I know this might not be the best circumstances to say it, but I wanted to thank you for everything at the Magic University.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0210","sourceIndex":210,"type":"speech","text":"“Listen well, Rudeus. This may be the last time we meet, so I shall say it now: congratulations.”","html":"“Listen well, Rudeus. This may be the last time we meet, so I shall say it now: congratulations.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch04-p0211","sourceIndex":211,"type":"speech","text":"“Congra…tulations?”","html":"“Congra…tulations?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0212","sourceIndex":212,"type":"speech","text":"“You were victorious, thus, I congratulate you.”","html":"“You were victorious, thus, I congratulate you.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch04-p0213","sourceIndex":213,"type":"speech","text":"“I’m not sure if I was, though…”","html":"“I’m not sure if I was, though…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0214","sourceIndex":214,"type":"narration","text":"That was exactly what I was worried about. In the end, Orsted had used his mana. I’d slipped up at the very last moment.","html":"That was exactly what I was worried about. In the end, Orsted had used his mana. I’d slipped up at the very last moment.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0215","sourceIndex":215,"type":"narration","text":"But Badigadi didn’t mention that.","html":"But Badigadi didn’t mention that.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0216","sourceIndex":216,"type":"speech","text":"“You have given the Man-God a taste of defeat.”","html":"“You have given the Man-God a taste of defeat.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch04-p0217","sourceIndex":217,"type":"speech","text":"“I gave him…what?”","html":"“I gave him…what?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0218","sourceIndex":218,"type":"speech","text":"“You have made him think that, no matter what he might try, he cannot kill you. He has lost all will to try. Indeed, it is hard to describe how he looked when I saw him last, except that he looked the very image of defeat. What else to call the one who fought him but victorious?”","html":"“You have made him think that, no matter what he might try, he cannot kill you. He has lost all will to try. Indeed, it is hard to describe how he looked when I saw him last, except that he looked the very image of defeat. What else to call the one who fought him but victorious?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch04-p0219","sourceIndex":219,"type":"speech","text":"“Is that really true?” I asked.","html":"“Is that really true?” I asked.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0220","sourceIndex":220,"type":"speech","text":"“You need only take off that bracelet and pay him a visit yourself to verify it.” He pointed at me, and my hand unconsciously went to cover the bracelet.","html":"“You need only take off that bracelet and pay him a visit yourself to verify it.” He pointed at me, and my hand unconsciously went to cover the bracelet.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0221","sourceIndex":221,"type":"speech","text":"“I…don’t think I will, thanks.”","html":"“I…don’t think I will, thanks.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0222","sourceIndex":222,"type":"speech","text":"“No? Well. As you like it!”","html":"“No? Well. As you like it!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch04-p0223","sourceIndex":223,"type":"narration","text":"I wasn’t falling for that one. I never wanted to see the Man-God again, though he had seemed pretty desperate when I’d last seen him at the bottom of the ravine. Maybe he really had taken this last battle as a heavy defeat. I still didn’t trust Badigadi when he said the Man-God had lost the will to try any more, though.","html":"I wasn’t falling for that one. I never wanted to see the Man-God again, though he had seemed pretty desperate when I’d last seen him at the bottom of the ravine. Maybe he really had taken this last battle as a heavy defeat. I still didn’t trust Badigadi when he said the Man-God had lost the will to try any more, though.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0224","sourceIndex":224,"type":"speech","text":"“Is that all?”","html":"“Is that all?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0225","sourceIndex":225,"type":"speech","text":"“Yes, from me, at least.”","html":"“Yes, from me, at least.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch04-p0226","sourceIndex":226,"type":"speech","text":"“Then keep yourself well, Rudeus.”","html":"“Then keep yourself well, Rudeus.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch04-p0227","sourceIndex":227,"type":"narration","text":"I turned and followed after Orsted. As I did so, Alec ran forward, looking anguished.","html":"I turned and followed after Orsted. As I did so, Alec ran forward, looking anguished.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0228","sourceIndex":228,"type":"speech","text":"“Great-Uncle…I…”","html":"“Great-Uncle…I…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","speakerConfidence":"high"},{"id":"ch04-p0229","sourceIndex":229,"type":"speech","text":"“Listen well, young Alexander. If you seek to be a hero, find your true foe. That was something your father never did. You will surpass him when you strike down that foe.”","html":"“Listen well, young Alexander. If you seek to be a hero, find your true foe. That was something your father never did. You will surpass him when you strike down that foe.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch04-p0230","sourceIndex":230,"type":"speech","text":"“Thank you,” Alec replied, and he, too, turned to leave.","html":"“Thank you,” Alec replied, and he, too, turned to leave.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Alexander","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0231","sourceIndex":231,"type":"narration","text":"This would probably be my final farewell to Badigadi in this life. Nothing stopped me from dropping by once a year or so, but talking to him I might weaken and end up breaking the seal. Better not to come at all. I hadn’t told any of the others from the Magic University that Badigadi was sealed here either. Only five people knew: me, Orsted, Ruijerd, Alec, and Perugius. We’d already ­decided that Ruijerd would watch from the village to make sure no one visited the ravine. Not many could make it to the bottom of the ravine or make it back up again. And a hundred years shouldn’t be long enough for the seal to spontaneously fail.","html":"This would probably be my final farewell to Badigadi in this life. Nothing stopped me from dropping by once a year or so, but talking to him I might weaken and end up breaking the seal. Better not to come at all. I hadn’t told any of the others from the Magic University that Badigadi was sealed here either. Only five people knew: me, Orsted, Ruijerd, Alec, and Perugius. We’d already ­decided that Ruijerd would watch from the village to make sure no one visited the ravine. Not many could make it to the bottom of the ravine or make it back up again. And a hundred years shouldn’t be long enough for the seal to spontaneously fail.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0232","sourceIndex":232,"type":"narration","text":"And then—","html":"And then—","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0233","sourceIndex":233,"type":"speech","text":"“Rudeus, the entrance.”","html":"“Rudeus, the entrance.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch04-p0234","sourceIndex":234,"type":"speech","text":"“Understood.”","html":"“Understood.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0235","sourceIndex":235,"type":"narration","text":"I would fill in the narrow entrance. Anyone who came after would have to dig it out if they wanted to find it again. This was goodbye.","html":"I would fill in the narrow entrance. Anyone who came after would have to dig it out if they wanted to find it again. This was goodbye.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0236","sourceIndex":236,"type":"narration","text":"At the end, ever so faintly, I thought I heard Badigadi’s voice.","html":"At the end, ever so faintly, I thought I heard Badigadi’s voice.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0237","sourceIndex":237,"type":"speech","text":"“May it be that your curse is lifted, young Dragon God.”","html":"“May it be that your curse is lifted, young Dragon God.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Badigadi","speakerConfidence":"high"},{"id":"ch04-p0238","sourceIndex":238,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":1705,"speechCount":42,"speakers":["Alexander","Badigadi","Orsted","Rudeus"]},{"id":"ch04-s04","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The Greyrat house in Sharia","cast":["Byt","Dillo","Lilia","Lucie","Rudeus","Zanoba","Zenith"],"blocks":[{"id":"ch04-p0240","sourceIndex":240,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch04-p0241","sourceIndex":241,"type":"narration","text":"Early the next morning, before the sun rose, I returned to Sharia. Between the new office currently under construction and rubble left from the old, there was a makeshift accommodation where Zanoba—our acting director of construction—and the others were sleeping all packed together. Zanoba! He’d been a big help, too. I hoped we could go on being the sort of friends who always had each other’s backs.","html":"Early the next morning, before the sun rose, I returned to Sharia. Between the new office currently under construction and rubble left from the old, there was a makeshift accommodation where Zanoba—our acting director of construction—and the others were sleeping all packed together. Zanoba! He’d been a big help, too. I hoped we could go on being the sort of friends who always had each other’s backs.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0242","sourceIndex":242,"type":"speech","text":"“Goodbye, Rudeus,” he ushered me onward. “Until next time.”","html":"“Goodbye, Rudeus,” he ushered me onward. “Until next time.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Zanoba","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0243","sourceIndex":243,"type":"narration","text":"The same went for Orsted. On the outskirts of the town, we parted ways. I walked on through the streets in the morning mist. I was carrying presents from the Biheiril Kingdom—largely soy sauce. So long as I had this soy sauce, I’d never be at a loss for what to eat again. Soy sauce goes with everything.","html":"The same went for Orsted. On the outskirts of the town, we parted ways. I walked on through the streets in the morning mist. I was carrying presents from the Biheiril Kingdom—largely soy sauce. So long as I had this soy sauce, I’d never be at a loss for what to eat again. Soy sauce goes with everything. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0244","sourceIndex":244,"type":"narration","text":"Well, everything might be an overstatement.","html":"Well, everything might be an overstatement.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0245","sourceIndex":245,"type":"narration","text":"I looked around. Sharia was just as I remembered it. The people were the same—farmers heading off to their fields, adventurers training in inn courtyards, and a man in a robe who might have been a professor at the university. Snowdrifts lined the road I walked on as I passed each traveler, heading toward home. I went through the central square to the residential district. Seeing it made me feel somehow nostalgic. It was a street I walked down practically every day, and yet seeing it felt like I was coming home for the first time in my life.","html":"I looked around. Sharia was just as I remembered it. The people were the same—farmers heading off to their fields, adventurers training in inn courtyards, and a man in a robe who might have been a professor at the university. Snowdrifts lined the road I walked on as I passed each traveler, heading toward home. I went through the central square to the residential district. Seeing it made me feel somehow nostalgic. It was a street I walked down practically every day, and yet seeing it felt like I was coming home for the first time in my life. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0246","sourceIndex":246,"type":"narration","text":"From the street, I turned down a back alley. This alley, too narrow for carts, provided a tiny shortcut that I’d used often. Coming out of the alley, I could see my house. Byt was coiled tightly around the gatepost and opened the gate for me as I drew closer. I passed the garden and the slightly neglected garden. Dillo the armadillo spotted me and came to rub himself against my legs. I crouched down to rub his head, at which he rolled over to show me his belly. As I rubbed his tummy, he purred happily. He was a cute little guy.","html":"From the street, I turned down a back alley. This alley, too narrow for carts, provided a tiny shortcut that I’d used often. Coming out of the alley, I could see my house. Byt was coiled tightly around the gatepost and opened the gate for me as I drew closer. I passed the garden and the slightly neglected garden. Dillo the armadillo spotted me and came to rub himself against my legs. I crouched down to rub his head, at which he rolled over to show me his belly. As I rubbed his tummy, he purred happily. He was a cute little guy.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0247","sourceIndex":247,"type":"narration","text":"Then, I heard a loud noise from the entrance to the house.","html":"Then, I heard a loud noise from the entrance to the house.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0248","sourceIndex":248,"type":"speech","text":"“Dada!” A little girl with hair the same color as mine came running out. It was Lucie. She came sprinting over like she was going to tackle me around the knees, so I crouched down to meet her. With a sizable thud, a ball of softness and warmth threw itself into my arms. This was unusual—she was always hiding behind Sylphie.","html":"“Dada!” A little girl with hair the same color as mine came running out. It was Lucie. She came sprinting over like she was going to tackle me around the knees, so I crouched down to meet her. With a sizable thud, a ball of softness and warmth threw itself into my arms. This was unusual—she was always hiding behind Sylphie.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lucie","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0249","sourceIndex":249,"type":"speech","text":"“I’m home, Lucie.”","html":"“I’m home, Lucie.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0250","sourceIndex":250,"type":"speech","text":"“Welcome back,” she said eventually.","html":"“Welcome back,” she said eventually.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lucie","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0251","sourceIndex":251,"type":"speech","text":"“Have you been a good girl?”","html":"“Have you been a good girl?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0252","sourceIndex":252,"type":"speech","text":"“Yes! I’ve been looking after Lara and Arus and Sieg!”","html":"“Yes! I’ve been looking after Lara and Arus and Sieg!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lucie","speakerConfidence":"high"},{"id":"ch04-p0253","sourceIndex":253,"type":"speech","text":"“Have you really? You’re a real big sister now, aren’t you?” I said. Lucie’s arms squeezed even tighter around me, spurring me to pick her up. I walked up to the house with her in my arms. From inside came a smell that somehow put me at ease—the familiar smell that hung around our house. Since we’d first bought this house, the number of inhabitants had increased. As we’d lived in it, it had changed, but I was so used to it that I didn’t notice how it smelled. But now, coming back after a long time away, and from a brush with death, no less, I felt all the tension drain out of me. My heart was at ease. It was a smell that let me know I was home.","html":"“Have you really? You’re a real big sister now, aren’t you?” I said. Lucie’s arms squeezed even tighter around me, spurring me to pick her up. I walked up to the house with her in my arms. From inside came a smell that somehow put me at ease—the familiar smell that hung around our house. Since we’d first bought this house, the number of inhabitants had increased. As we’d lived in it, it had changed, but I was so used to it that I didn’t notice how it smelled. But now, coming back after a long time away, and from a brush with death, no less, I felt all the tension drain out of me. My heart was at ease. It was a smell that let me know I was home.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0254","sourceIndex":254,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch04-p0255","sourceIndex":255,"type":"speech","text":"“Hello, Lilia. Hello, Mother.” As I stood filling my lungs with the smell of home, I saw Lilia and Zenith in front of the stairs.","html":"“Hello, Lilia. Hello, Mother.” As I stood filling my lungs with the smell of home, I saw Lilia and Zenith in front of the stairs. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0256","sourceIndex":256,"type":"speech","text":"Lilia bowed deeply when she saw me. “Welcome home, Master.”","html":"Lilia bowed deeply when she saw me. “Welcome home, Master.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lilia","speakerConfidence":"high"},{"id":"ch04-p0257","sourceIndex":257,"type":"speech","text":"“Thank you for looking after the house while I was gone, Lilia.”","html":"“Thank you for looking after the house while I was gone, Lilia.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0258","sourceIndex":258,"type":"speech","text":"“Not at all, Master. I’m so glad to see you safely home.”","html":"“Not at all, Master. I’m so glad to see you safely home.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lilia","speakerConfidence":"high"},{"id":"ch04-p0259","sourceIndex":259,"type":"speech","text":"“It will be a little longer before Norn and Aisha come back.”","html":"“It will be a little longer before Norn and Aisha come back.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lilia","speakerConfidence":"high"},{"id":"ch04-p0260","sourceIndex":260,"type":"speech","text":"“Thank you for letting me know. Oh, but I am glad you’re safe… When the Dragon God’s residence on the outskirts of the city was attacked, I was beside myself with worry. I am so glad, so very glad…” Lilia made normal conversation for a while, but it wasn’t long before she put her hand to her mouth as though she couldn’t hold it back any longer. Her shoulders shook. She started weeping.","html":"“Thank you for letting me know. Oh, but I am glad you’re safe… When the Dragon God’s residence on the outskirts of the city was attacked, I was beside myself with worry. I am so glad, so very glad…” Lilia made normal conversation for a while, but it wasn’t long before she put her hand to her mouth as though she couldn’t hold it back any longer. Her shoulders shook. She started weeping.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lilia","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0261","sourceIndex":261,"type":"speech","text":"“I’m sorry I made you worry…”","html":"“I’m sorry I made you worry…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0262","sourceIndex":262,"type":"narration","text":"I’d had no means of contacting her, so there was nothing I could have done. It did make sense that, after the company I was working for was crushed by a rival company, she would have been beside herself. And in truth, things could easily have turned out as she’d feared. And not only for me; any of the others might have failed to come back from that fight. I had done everything I could to ensure everyone did come home, but it was a miracle that none of the people I cared most about had died.","html":"I’d had no means of contacting her, so there was nothing I could have done. It did make sense that, after the company I was working for was crushed by a rival company, she would have been beside herself. And in truth, things could easily have turned out as she’d feared. And not only for me; any of the others might have failed to come back from that fight. I had done everything I could to ensure everyone did come home, but it was a miracle that none of the people I cared most about had died. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0263","sourceIndex":263,"type":"narration","text":"On the other hand, I couldn’t honestly say that I could stop anything like this from happening again.","html":"On the other hand, I couldn’t honestly say that I could stop anything like this from happening again.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0264","sourceIndex":264,"type":"speech","text":"“There shouldn’t be another big battle like this one for a while, so please, don’t worry anymore.”","html":"“There shouldn’t be another big battle like this one for a while, so please, don’t worry anymore.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0265","sourceIndex":265,"type":"speech","text":"“That’s good,” Lilia said. “I’m so very sorry you had to see me go to pieces like this.”","html":"“That’s good,” Lilia said. “I’m so very sorry you had to see me go to pieces like this.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lilia","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0266","sourceIndex":266,"type":"narration","text":"I realized that Zenith was rubbing Lilia’s back. Had I made Zenith worry too? She seemed to have lost her negative emotions, but I thought she’d at least worry about me. She was that sort of person.","html":"I realized that Zenith was rubbing Lilia’s back. Had I made Zenith worry too? She seemed to have lost her negative emotions, but I thought she’d at least worry about me. She was that sort of person.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0267","sourceIndex":267,"type":"narration","text":"Anyway.","html":"Anyway.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0268","sourceIndex":268,"type":"speech","text":"“I’m home,” I said. I took a step into the house. It ­finally felt real that my long battle with Geese was over.","html":"“I’m home,” I said. I took a step into the house. It ­finally felt real that my long battle with Geese was over.","className":"P_Prose_Formatting__And__Page_Break","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0269","sourceIndex":269,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":931,"speechCount":17,"speakers":["Lilia","Lucie","Rudeus","Zanoba"]},{"id":"ch04-s05","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The Greyrat house in Sharia, the morning after the battle","cast":["Arus","Christina","Eris","Lara","Leo","Lilia","Lily","Lucie","Roxy","Rudeus","Sieg","Sylphiette","Zenith"],"blocks":[{"id":"ch04-p0271","sourceIndex":271,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch04-p0272","sourceIndex":272,"type":"narration","text":"It was the day after the end of the battle had really sunk in, and I couldn’t relax. The battle with Geese was over, which was to say, the contract I’d made with myself was over, too.","html":"It was the day after the end of the battle had really sunk in, and I couldn’t relax. The battle with Geese was over, which was to say, the contract I’d made with myself was over, too. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0273","sourceIndex":273,"type":"narration","text":"Look. You know what that meant.","html":"Look. You know what that meant.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0274","sourceIndex":274,"type":"narration","text":"The battle had gone on for so long that this way of life had started to feel natural to me, but early that morning, my little guy had started reasserting himself. Talk about an insistent reminder.","html":"The battle had gone on for so long that this way of life had started to feel natural to me, but early that morning, my little guy had started reasserting himself. Talk about an insistent reminder. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0275","sourceIndex":275,"type":"narration","text":"My name was Rudeus Greyrat, son of Paul Greyrat, which meant treachery from below my belt was part of my DNA. I’d put Rudeus Jr. through a long period of hardship and endurance. That was what had enabled me to do my best. As the first Rudeus, it was my duty to see he was repaid. He’d fulfilled his side of the contract.","html":"My name was Rudeus Greyrat, son of Paul Greyrat, which meant treachery from below my belt was part of my DNA. I’d put Rudeus Jr. through a long period of hardship and endurance. That was what had enabled me to do my best. As the first Rudeus, it was my duty to see he was repaid. He’d fulfilled his side of the contract.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0276","sourceIndex":276,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch04-p0277","sourceIndex":277,"type":"narration","text":"Before the sun had risen, I got out of bed, went downstairs, and headed for the front door. There, I found Leo and Eris.","html":"Before the sun had risen, I got out of bed, went downstairs, and headed for the front door. There, I found Leo and Eris.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0278","sourceIndex":278,"type":"speech","text":"“Rudeus! You’re up early today.”","html":"“Rudeus! You’re up early today.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Eris","speakerConfidence":"high"},{"id":"ch04-p0279","sourceIndex":279,"type":"speech","text":"“Morning, Eris. Where is everyone?”","html":"“Morning, Eris. Where is everyone?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0280","sourceIndex":280,"type":"speech","text":"“All safe.”","html":"“All safe.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Eris","speakerConfidence":"high"},{"id":"ch04-p0281","sourceIndex":281,"type":"speech","text":"“Not that. I mean what are they doing?”","html":"“Not that. I mean what are they doing?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0282","sourceIndex":282,"type":"speech","text":"Eris thought for a moment. “Lilia and Sylphie are making breakfast, and Roxy and the children and your mother are still asleep. I just finished training, so I was about to go for a run.”","html":"Eris thought for a moment. “Lilia and Sylphie are making breakfast, and Roxy and the children and your mother are still asleep. I just finished training, so I was about to go for a run.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Eris","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0283","sourceIndex":283,"type":"speech","text":"“Right,” I said softly, taking Eris’s hand. She squeezed my fingers. Maybe because she’d just been training, but her hand was warm. I noticed her face was also a little flushed.","html":"“Right,” I said softly, taking Eris’s hand. She squeezed my fingers. Maybe because she’d just been training, but her hand was warm. I noticed her face was also a little flushed.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0284","sourceIndex":284,"type":"speech","text":"“Wh-what?” she said.","html":"“Wh-what?” she said.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Eris","speakerConfidence":"high"},{"id":"ch04-p0285","sourceIndex":285,"type":"speech","text":"“Eris, let’s take today off.”","html":"“Eris, let’s take today off.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0286","sourceIndex":286,"type":"speech","text":"“R-right! Okay!” The way she said “okay” sounded like she’d guessed exactly what I had in mind. Maybe it showed on my face.","html":"“R-right! Okay!” The way she said “okay” sounded like she’d guessed exactly what I had in mind. Maybe it showed on my face.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Eris","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0287","sourceIndex":287,"type":"narration","text":"She was right on the money.","html":"She was right on the money.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0288","sourceIndex":288,"type":"speech","text":"“Sorry, Leo, but no walk for now.”","html":"“Sorry, Leo, but no walk for now.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0289","sourceIndex":289,"type":"speech","text":"“Ruff.” Leo looked a bit disappointed, but he gave my hand a little lick, then went back into the house.","html":"“Ruff.” Leo looked a bit disappointed, but he gave my hand a little lick, then went back into the house. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Leo","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0290","sourceIndex":290,"type":"narration","text":"I followed him inside, still holding Eris’s hand, and headed for the kitchen. Lilia and Sylphie stood beside each other cooking.","html":"I followed him inside, still holding Eris’s hand, and headed for the kitchen. Lilia and Sylphie stood beside each other cooking.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0291","sourceIndex":291,"type":"speech","text":"“Sylphie,” I said.","html":"“Sylphie,” I said.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0292","sourceIndex":292,"type":"speech","text":"“Oh, good morning, Rudy. You’re up early.”","html":"“Oh, good morning, Rudy. You’re up early.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","speakerConfidence":"high"},{"id":"ch04-p0293","sourceIndex":293,"type":"speech","text":"“Good morning, Master.” Both women smiled at me like they always did. I turned to Sylphie then, with a smile so natural I surprised myself, said, “Sylphie, let’s take today off.”","html":"“Good morning, Master.” Both women smiled at me like they always did. I turned to Sylphie then, with a smile so natural I surprised myself, said, “Sylphie, let’s take today off.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lilia","mixed":true,"attributionNote":"Block holds Lilia's greeting and Rudeus's reply.","speakerConfidence":"high"},{"id":"ch04-p0294","sourceIndex":294,"type":"speech","text":"“What? I don’t mind, but when you say ‘day off’…” She looked at me quizzically. But Lilia seemed to catch on right away.","html":"“What? I don’t mind, but when you say ‘day off’…” She looked at me quizzically. But Lilia seemed to catch on right away.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0295","sourceIndex":295,"type":"speech","text":"“Very well. I’ll finish up breakfast, Miss Sylphie.”","html":"“Very well. I’ll finish up breakfast, Miss Sylphie.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lilia","speakerConfidence":"high"},{"id":"ch04-p0296","sourceIndex":296,"type":"speech","text":"“Oh…” Sylphie said, her face going red. “That’s what you mean.” She smiled shyly, then took the hand Eris wasn’t holding. Maybe it was because she’d wet her hands while cooking, but her fingers were a little cold.","html":"“Oh…” Sylphie said, her face going red. “That’s what you mean.” She smiled shyly, then took the hand Eris wasn’t holding. Maybe it was because she’d wet her hands while cooking, but her fingers were a little cold. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0297","sourceIndex":297,"type":"speech","text":"“When you said it, Rudy, the look on your face was so normal that I didn’t realize. Did you see it straight away, Eris?”","html":"“When you said it, Rudy, the look on your face was so normal that I didn’t realize. Did you see it straight away, Eris?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","speakerConfidence":"high"},{"id":"ch04-p0298","sourceIndex":298,"type":"speech","text":"“I just sort of knew!”","html":"“I just sort of knew!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Eris","speakerConfidence":"high"},{"id":"ch04-p0299","sourceIndex":299,"type":"speech","text":"As the other two chatted, I turned to Lilia. “Lilia, please watch the children until lunchtime. Oh, and let’s all go out to eat tonight.”","html":"As the other two chatted, I turned to Lilia. “Lilia, please watch the children until lunchtime. Oh, and let’s all go out to eat tonight.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0300","sourceIndex":300,"type":"speech","text":"“Very well, Master.” She smiled like she’d seen right through my plans, though she also seemed a little embarrassed.","html":"“Very well, Master.” She smiled like she’d seen right through my plans, though she also seemed a little embarrassed.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lilia","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0301","sourceIndex":301,"type":"narration","text":"Well, it was a bit late for that.","html":"Well, it was a bit late for that.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0302","sourceIndex":302,"type":"narration","text":"Holding hands with Sylphie and Eris, we headed for the children’s bedroom. I quietly opened the door and peeked inside. The four kids were sound asleep. Lucie, Lara, Arus, and Sieg. Leo was curled up in a corner of the room, watching over them.","html":"Holding hands with Sylphie and Eris, we headed for the children’s bedroom. I quietly opened the door and peeked inside. The four kids were sound asleep. Lucie, Lara, Arus, and Sieg. Leo was curled up in a corner of the room, watching over them.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0303","sourceIndex":303,"type":"narration","text":"In the battle, I’d worried so much about my family. Despite my fears, all was peaceful here. Unless some battle had taken place at the house, unbeknownst to me, and Leo had protected them…","html":"In the battle, I’d worried so much about my family. Despite my fears, all was peaceful here. Unless some battle had taken place at the house, unbeknownst to me, and Leo had protected them…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0304","sourceIndex":304,"type":"narration","text":"Anyway, after checking that the children were all well, I softly shut the door again. Then, we went upstairs to Roxy’s room. In the interests of good manners, I knocked.","html":"Anyway, after checking that the children were all well, I softly shut the door again. Then, we went upstairs to Roxy’s room. In the interests of good manners, I knocked.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0305","sourceIndex":305,"type":"narration","text":"There was a pause for a few seconds, then, “Yes?”","html":"There was a pause for a few seconds, then, “Yes?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0306","sourceIndex":306,"type":"narration","text":"I opened the door and saw Roxy, her eyes bleary with sleep. Her hair was rumpled and there were drool marks around her mouth. Her nightgown hung open at the front, so that I could almost see inside. Very sexy.","html":"I opened the door and saw Roxy, her eyes bleary with sleep. Her hair was rumpled and there were drool marks around her mouth. Her nightgown hung open at the front, so that I could almost see inside. Very sexy.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0307","sourceIndex":307,"type":"speech","text":"“Oh…Rudy. Good morning. It’s so early, did something…?”","html":"“Oh…Rudy. Good morning. It’s so early, did something…?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Roxy","speakerConfidence":"high"},{"id":"ch04-p0308","sourceIndex":308,"type":"speech","text":"“Good morning, Roxy. I thought we’d take a day off. What do you think?”","html":"“Good morning, Roxy. I thought we’d take a day off. What do you think?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch04-p0309","sourceIndex":309,"type":"narration","text":"Roxy stared blankly at me, then she seemed to work out what “day off” meant. Toying with her sleep-tousled bangs, her cheeks turning pink, she said, “Well, I don’t mind, but…” I followed her gaze to one of the two women holding my hands. “Did Eris agree to this?”","html":"Roxy stared blankly at me, then she seemed to work out what “day off” meant. Toying with her sleep-tousled bangs, her cheeks turning pink, she said, “Well, I don’t mind, but…” I followed her gaze to one of the two women holding my hands. “Did Eris agree to this?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Roxy","embeddedDialogue":true,"attributionNote":"Narration with Roxy's sleepy answer.","speakerConfidence":"high"},{"id":"ch04-p0310","sourceIndex":310,"type":"narration","text":"I looked at Eris. Her face was red, and she looked a bit shell shocked.","html":"I looked at Eris. Her face was red, and she looked a bit shell shocked.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0311","sourceIndex":311,"type":"speech","text":"“I was just about to ask her.” Turning to face Eris properly, I said, “Eris, I’d like to go back to my bedroom with the four of us. Is that okay with you?”","html":"“I was just about to ask her.” Turning to face Eris properly, I said, “Eris, I’d like to go back to my bedroom with the four of us. Is that okay with you?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0312","sourceIndex":312,"type":"narration","text":"Eris seemed to understand what I meant. Her face went even redder, and she pursed her lips. She probably would have struck her favorite pose if she’d had both hands free.","html":"Eris seemed to understand what I meant. Her face went even redder, and she pursed her lips. She probably would have struck her favorite pose if she’d had both hands free.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0313","sourceIndex":313,"type":"speech","text":"“Well, I suppose, if you really want to…”","html":"“Well, I suppose, if you really want to…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Eris","speakerConfidence":"high"},{"id":"ch04-p0314","sourceIndex":314,"type":"narration","text":"Sorry, Eris. I just wanted to treat myself a little today. And bid farewell to Rudeus the Celibate.","html":"Sorry, Eris. I just wanted to treat myself a little today. And bid farewell to Rudeus the Celibate.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0315","sourceIndex":315,"type":"speech","text":"“Thank you,” I said. I didn’t just say it because Eris had given her permission. I was thanking all three of them for everything they’d done to support me up to this moment. I was so thankful I hadn’t lost any of them.","html":"“Thank you,” I said. I didn’t just say it because Eris had given her permission. I was thanking all three of them for everything they’d done to support me up to this moment. I was so thankful I hadn’t lost any of them. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch04-p0316","sourceIndex":316,"type":"narration","text":"Geese and Badigadi had both said it was over now. That the Man-God wouldn’t bother me anymore. I didn’t believe a word of it: the Man-God would be my enemy for as long as I lived. But today, I’d relax and do absolutely nothing. Not a thing. Rest. Get my strength back for tomorrow, and spend a day in peace. To remind myself that I could still laugh, and—","html":"Geese and Badigadi had both said it was over now. That the Man-God wouldn’t bother me anymore. I didn’t believe a word of it: the Man-God would be my enemy for as long as I lived. But today, I’d relax and do absolutely nothing. Not a thing. Rest. Get my strength back for tomorrow, and spend a day in peace. To remind myself that I could still laugh, and—","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0317","sourceIndex":317,"type":"narration","text":"Nah, I’m messing with you. I was gonna get laid. From today on, I was Rudeus the Free. Felt good.","html":"Nah, I’m messing with you. I was gonna get laid. From today on, I was Rudeus the Free. Felt good.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch04-p0318","sourceIndex":318,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch04-p0319","sourceIndex":319,"type":"narration","text":"With that, we headed for the bedroom.","html":"With that, we headed for the bedroom.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false}],"wordCount":1001,"speechCount":26,"speakers":["Eris","Leo","Lilia","Roxy","Rudeus","Sylphiette"]}],"images":[{"id":"ch04-img01","type":"image","src":"INTERIORIMAGES_07.jpg","alt":""}],"sequence":4,"cast":["Aisha","Alexander","Arus","Badigadi","Byt","Christina","Cliff","Dillo","Dohga","Elinalise","Eris","Ghislaine","Isolde","Lara","Leo","Lilia","Lily","Linia","Lucie","Mercenary","Norn","Orsted","Perugius","Pursena","Roxy","Rudeus","Ruijerd","Sandor","Sieg","Sylphiette","Zanoba","Zenith"],"sceneCount":5,"speechCount":188,"speakers":["Aisha","Alexander","Badigadi","Cliff","Dohga","Eris","Ghislaine","Isolde","Leo","Lilia","Lucie","Norn","Orsted","Roxy","Rudeus","Ruijerd","Sandor","Sylphiette","Zanoba"]},{"id":"ch05","number":1,"title":"Story 1: The Final Dream","pov":"Rudeus","kind":"story","wordCount":2873,"scenes":[{"id":"ch05-s01","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The Man-God's white space, in Rudeus's dream","cast":["Lara","Orsted","Perugius","Rudeus"],"blocks":[{"id":"ch05-p0002","sourceIndex":2,"type":"narration","text":"THE PLACE I FOUND myself was all white. The same white place as always. I could count the number of times I’d been here since being reincarnated in this world on my fingers, but every time, without fail, it was still the same white, empty place I keep coming back to.","html":"THE PLACE I FOUND myself was all white. The same white place as always. I could count the number of times I’d been here since being reincarnated in this world on my fingers, but every time, without fail, it was still the same white, empty place I keep coming back to. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0003","sourceIndex":3,"type":"narration","text":"When I came here, I always looked as I had in my past life, with a potbelly and rolls of flab. My body felt heavy and powerless. Strangely enough, it didn’t disgust me anymore. I didn’t feel frustration welling up in the depths of my chest. Being like this didn’t seem so bad. Maybe that was because I hadn’t been back here for such a long time.","html":"When I came here, I always looked as I had in my past life, with a potbelly and rolls of flab. My body felt heavy and powerless. Strangely enough, it didn’t disgust me anymore. I didn’t feel frustration welling up in the depths of my chest. Being like this didn’t seem so bad. Maybe that was because I hadn’t been back here for such a long time.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0004","sourceIndex":4,"type":"narration","text":"Unless…","html":"Unless…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0005","sourceIndex":5,"type":"speech","text":"“Wait, what?”","html":"“Wait, what?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0006","sourceIndex":6,"type":"narration","text":"That was weird. Sure, it had been a long time, but I didn’t remember taking my bracelet off. I never took it off.","html":"That was weird. Sure, it had been a long time, but I didn’t remember taking my bracelet off. I never took it off. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0007","sourceIndex":7,"type":"narration","text":"Why was I here?","html":"Why was I here?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0008","sourceIndex":8,"type":"narration","text":"Hold on. What was I even doing before I came here? I couldn’t remember what I’d been doing before I fell asleep. I think it was probably, you know, something along the lines of baby-making…No scratch that, I hadn’t done anything like that for a long time. I’d been neglecting it for around ten years now.","html":"Hold on. What was I even doing before I came here? I couldn’t remember what I’d been doing before I fell asleep. I think it was probably, you know, something along the lines of baby-making…No scratch that, I hadn’t done anything like that for a long time. I’d been neglecting it for around ten years now. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0009","sourceIndex":9,"type":"narration","text":"My memory was hazy, for some reason.","html":"My memory was hazy, for some reason.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0010","sourceIndex":10,"type":"speech","text":"“Hey.”","html":"“Hey.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0011","sourceIndex":11,"type":"narration","text":"Dazed as my memory was, my vision was sharp. As usual, he was here in this white place. That pixelated blob. The Man-God.","html":"Dazed as my memory was, my vision was sharp. As usual, he was here in this white place. That pixelated blob. The Man-God. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0012","sourceIndex":12,"type":"narration","text":"But what was this? He looked strange. His body was in pieces, with each of his four limbs held in place by something that looked like a magic circle and bound by some sort of translucent chain.","html":"But what was this? He looked strange. His body was in pieces, with each of his four limbs held in place by something that looked like a magic circle and bound by some sort of translucent chain.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0013","sourceIndex":13,"type":"narration","text":"He looked like the final boss in an RPG. It was like, I dunno, unless you hit him in the right leg, he’d use a restoration spell to return to full health. A giant pain in the ass.","html":"He looked like the final boss in an RPG. It was like, I dunno, unless you hit him in the right leg, he’d use a restoration spell to return to full health. A giant pain in the ass.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0014","sourceIndex":14,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch05-p0015","sourceIndex":15,"type":"narration","text":"What happened to you? Cosplaying Exodia the Forbidden One or something?","html":"What happened to you? Cosplaying Exodia the Forbidden One or something?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0016","sourceIndex":16,"type":"speech","text":"“They got me.”","html":"“They got me.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch05-p0017","sourceIndex":17,"type":"narration","text":"Who?","html":"Who?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0018","sourceIndex":18,"type":"speech","text":"“You’re asking me that?”","html":"“You’re asking me that?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch05-p0019","sourceIndex":19,"type":"narration","text":"I don’t see anyone else asking. What, is there someone here other than me?","html":"I don’t see anyone else asking. What, is there someone here other than me?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0020","sourceIndex":20,"type":"speech","text":"“…Take a look over there.”","html":"“…Take a look over there.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch05-p0021","sourceIndex":21,"type":"narration","text":"I turned around and saw a crowd of people. They were standing with their backs to me. No one there I knew. Unfamiliar men and unfamiliar women, demons, humans.","html":"I turned around and saw a crowd of people. They were standing with their backs to me. No one there I knew. Unfamiliar men and unfamiliar women, demons, humans.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0022","sourceIndex":22,"type":"narration","text":"There were about eight of them. One of them, I knew. It was Orsted. He was the same as ever, but a few things had changed. He didn’t have his black helmet, and there was a sizable scar on his face that made him look more fearsome than ever. Yet the people around him were all smiling at him. Orsted’s face was as terrifying as it’d ever been, but there was a slight softness to his expression. I couldn’t make out what they were talking about, but I could see the trust between them.","html":"There were about eight of them. One of them, I knew. It was Orsted. He was the same as ever, but a few things had changed. He didn’t have his black helmet, and there was a sizable scar on his face that made him look more fearsome than ever. Yet the people around him were all smiling at him. Orsted’s face was as terrifying as it’d ever been, but there was a slight softness to his expression. I couldn’t make out what they were talking about, but I could see the trust between them.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0023","sourceIndex":23,"type":"narration","text":"The one speaking…was a boy. He looked seventeen or eighteen years old, with short hair and the kind of good looks that made me think he’d be good at sports. A normie sort of face, and Asian, going off his features. He had a nice smile. I guess Orsted’s curse didn’t affect him.","html":"The one speaking…was a boy. He looked seventeen or eighteen years old, with short hair and the kind of good looks that made me think he’d be good at sports. A normie sort of face, and Asian, going off his features. He had a nice smile. I guess Orsted’s curse didn’t affect him.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0024","sourceIndex":24,"type":"narration","text":"As I was watching the boy, a woman in the group stood up. Sitting, she’d been hidden by the others. Really, she was more a girl than a woman. She had blue hair and at her side was a giant white wolf.","html":"As I was watching the boy, a woman in the group stood up. Sitting, she’d been hidden by the others. Really, she was more a girl than a woman. She had blue hair and at her side was a giant white wolf.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0025","sourceIndex":25,"type":"narration","text":"Ah, I’d seen her somewhere before. She looked like Roxy, but not Roxy. She was definitely a Migurd, but I’d never mistake someone else for Roxy. So…who was she?","html":"Ah, I’d seen her somewhere before. She looked like Roxy, but not Roxy. She was definitely a Migurd, but I’d never mistake someone else for Roxy. So…who was she?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0026","sourceIndex":26,"type":"narration","text":"Could…could she be Lara?","html":"Could…could she be Lara?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0027","sourceIndex":27,"type":"narration","text":"Just then, the girl turned and waved at me. It couldn’t be at me. She had to be waving at the Man-God.","html":"Just then, the girl turned and waved at me. It couldn’t be at me. She had to be waving at the Man-God.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0028","sourceIndex":28,"type":"narration","text":"A man near her said something to her, probably asking what she was doing. She said something in reply, and he looked my way in surprise. He looked Asian, too. There weren’t many people in this world with that sort of face. He could have been Japanese. I’d have put him in his twenties, no older than thirty. He turned to me and bowed—a Japanese gesture. Maybe he was Japanese?","html":"A man near her said something to her, probably asking what she was doing. She said something in reply, and he looked my way in surprise. He looked Asian, too. There weren’t many people in this world with that sort of face. He could have been Japanese. I’d have put him in his twenties, no older than thirty. He turned to me and bowed—a Japanese gesture. Maybe he was Japanese?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0029","sourceIndex":29,"type":"narration","text":"Then, the whole group turned my way. I saw faces both young and old. What I’d first thought was eight people was actually a much larger group, but they were hazy, making them hard to see. The only face I recognized was Orsted’s, but…oh, but was that Eris? A sword fighter with braided red hair was looking this way. No, she didn’t quite look how I remembered Eris, though…","html":"Then, the whole group turned my way. I saw faces both young and old. What I’d first thought was eight people was actually a much larger group, but they were hazy, making them hard to see. The only face I recognized was Orsted’s, but…oh, but was that Eris? A sword fighter with braided red hair was looking this way. No, she didn’t quite look how I remembered Eris, though…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0030","sourceIndex":30,"type":"narration","text":"They all looked our way and made gestures of gratitude. Were they thanking the Man-God? Probably not, their manner wasn’t quite right for that. Who, then?","html":"They all looked our way and made gestures of gratitude. Were they thanking the Man-God? Probably not, their manner wasn’t quite right for that. Who, then?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0031","sourceIndex":31,"type":"narration","text":"As I watched, wondering, they all stepped onto a magic circle drawn by Lara and disappeared somewhere. Just like that, they were all gone. The magic circle remained, glowing pale blue, but after a while, the glow faded, and the magic circle itself disappeared. Everything was gone.","html":"As I watched, wondering, they all stepped onto a magic circle drawn by Lara and disappeared somewhere. Just like that, they were all gone. The magic circle remained, glowing pale blue, but after a while, the glow faded, and the magic circle itself disappeared. Everything was gone.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0032","sourceIndex":32,"type":"speech","text":"“That lot ganged up on me and went to town. Then they cut me up like this and sealed me here. Said if I died, the last remaining human world might be destroyed.”","html":"“That lot ganged up on me and went to town. Then they cut me up like this and sealed me here. Said if I died, the last remaining human world might be destroyed.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch05-p0033","sourceIndex":33,"type":"narration","text":"Would it be destroyed?","html":"Would it be destroyed?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0034","sourceIndex":34,"type":"speech","text":"“How should I know? It’s not like I’ve died before.”","html":"“How should I know? It’s not like I’ve died before.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch05-p0035","sourceIndex":35,"type":"narration","text":"Right, fair point. No one knows what happens when they die.","html":"Right, fair point. No one knows what happens when they die.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0036","sourceIndex":36,"type":"speech","text":"“So, are you happy now?”","html":"“So, are you happy now?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch05-p0037","sourceIndex":37,"type":"narration","text":"With what?","html":"With what?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0038","sourceIndex":38,"type":"speech","text":"“This is the ending you wanted. Me, living here alone with all my powers sealed away. I’m living only to keep the world in existence. I can’t see it anymore. I can’t speak to anyone. I’ll just go on staring into this empty, white void.”","html":"“This is the ending you wanted. Me, living here alone with all my powers sealed away. I’m living only to keep the world in existence. I can’t see it anymore. I can’t speak to anyone. I’ll just go on staring into this empty, white void.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch05-p0039","sourceIndex":39,"type":"narration","text":"I dunno. It’s hard to say if that makes me happy or not. My goal was never to do anything to you. I just wanted a happy life with Sylphie, Roxy, and Eris. Go to work, earn a living, come home to eat dinner with my family, do some sweet, sweet baby-making at night. A normal…no, a happy life like that.","html":"I dunno. It’s hard to say if that makes me happy or not. My goal was never to do anything to you. I just wanted a happy life with Sylphie, Roxy, and Eris. Go to work, earn a living, come home to eat dinner with my family, do some sweet, sweet baby-making at night. A normal…no, a happy life like that.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0040","sourceIndex":40,"type":"narration","text":"A normal life—the happiest life I could possibly imagine.","html":"A normal life—the happiest life I could possibly imagine.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0041","sourceIndex":41,"type":"speech","text":"“Your happiness is my misery.”","html":"“Your happiness is my misery.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch05-p0042","sourceIndex":42,"type":"narration","text":"Yeah? All right, I’m satisfied then. I mean, you look about as miserable as it’s possible to be right now, so I must be happy.","html":"Yeah? All right, I’m satisfied then. I mean, you look about as miserable as it’s possible to be right now, so I must be happy.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0043","sourceIndex":43,"type":"speech","text":"“You…you can’t seriously… You disgust me!”","html":"“You…you can’t seriously… You disgust me!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch05-p0044","sourceIndex":44,"type":"narration","text":"I couldn’t read the Man-God’s expression, but his voice wasn’t hateful. It was simply full of sadness. He sounded like he might cry.","html":"I couldn’t read the Man-God’s expression, but his voice wasn’t hateful. It was simply full of sadness. He sounded like he might cry.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0045","sourceIndex":45,"type":"speech","text":"“I hate you.”","html":"“I hate you.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch05-p0046","sourceIndex":46,"type":"narration","text":"Okay. Well, you—","html":"Okay. Well, you—","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0047","sourceIndex":47,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch05-p0048","sourceIndex":48,"type":"narration","text":"I lost consciousness.","html":"I lost consciousness.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0049","sourceIndex":49,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":1081,"speechCount":12,"speakers":["Perugius","Rudeus"]},{"id":"ch05-s02","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"Rudeus's bedroom in Sharia, fifty years later","cast":["Feris","Orsted","Roxy","Rudeus","Sylphiette"],"blocks":[{"id":"ch05-p0051","sourceIndex":51,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch05-p0052","sourceIndex":52,"type":"narration","text":"When I awoke, I was in bed. It was a truly massive bed, big enough that three people could have slept comfortably in it, and it was soft. My back was a little damp, which I didn’t love, but it was pleasant otherwise. There was no one sleeping beside me. I could move my eyes and my neck, but not so much my body. It was like the blanket was too heavy. I moved just my eyes to look away from the bed and saw a girl with red hair sitting there. She had single-fold eyelids and a determined line to her chin—the spitting image of Eris, although she wore her hair in an unassuming braid and was far smaller. Both in terms of height and cup size. I expected that much: she looked about five years old.","html":"When I awoke, I was in bed. It was a truly massive bed, big enough that three people could have slept comfortably in it, and it was soft. My back was a little damp, which I didn’t love, but it was pleasant otherwise. There was no one sleeping beside me. I could move my eyes and my neck, but not so much my body. It was like the blanket was too heavy. I moved just my eyes to look away from the bed and saw a girl with red hair sitting there. She had single-fold eyelids and a determined line to her chin—the spitting image of Eris, although she wore her hair in an unassuming braid and was far smaller. Both in terms of height and cup size. I expected that much: she looked about five years old. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0053","sourceIndex":53,"type":"narration","text":"When her eyes met mine, she dropped what she was holding and leapt to her feet. The chair fell over with a crash and she looked like she might fall with it. Right away, I propped her up. How did I prop her up when my body wouldn’t move? I couldn’t tell you myself. She just put her hands out and caught herself in mid-air, then righted herself. No sooner had she planted her feet on the ground once more than she left the room.","html":"When her eyes met mine, she dropped what she was holding and leapt to her feet. The chair fell over with a crash and she looked like she might fall with it. Right away, I propped her up. How did I prop her up when my body wouldn’t move? I couldn’t tell you myself. She just put her hands out and caught herself in mid-air, then righted herself. No sooner had she planted her feet on the ground once more than she left the room.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0054","sourceIndex":54,"type":"speech","text":"“Mama! Mama! Great-Grandpa’s awake!” Listening to the patter of running feet, I looked at the item she’d been holding. It was a bracelet engraved with the Dragon God’s emblem. I didn’t remember taking it off, but—ah, yes, I suppose she must have taken it off while I was asleep. I reached for the bracelet, my arms trembling. It was so heavy. No, scratch that. It wasn’t heavy. I was weak. My arm had grown so thin that I couldn’t even pick up a bracelet.","html":"“Mama! Mama! Great-Grandpa’s awake!” Listening to the patter of running feet, I looked at the item she’d been holding. It was a bracelet engraved with the Dragon God’s emblem. I didn’t remember taking it off, but—ah, yes, I suppose she must have taken it off while I was asleep. I reached for the bracelet, my arms trembling. It was so heavy. No, scratch that. It wasn’t heavy. I was weak. My arm had grown so thin that I couldn’t even pick up a bracelet. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Feris","mixed":true,"speakerConfidence":"high"},{"id":"ch05-p0055","sourceIndex":55,"type":"narration","text":"Just then, my eyes found the mirror in a corner of the room, and I saw an old man slumped in bed who looked like he might die at any moment. He had a white beard, white hair, and deep wrinkles. The shadow of death was visible in every line of his face.","html":"Just then, my eyes found the mirror in a corner of the room, and I saw an old man slumped in bed who looked like he might die at any moment. He had a white beard, white hair, and deep wrinkles. The shadow of death was visible in every line of his face.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0056","sourceIndex":56,"type":"narration","text":"Ahh, I remember now. I turn seventy-four this year.","html":"Ahh, I remember now. I turn seventy-four this year.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0057","sourceIndex":57,"type":"narration","text":"There was something odd about thinking that. Everything else, I couldn’t really remember. It was like a fog hung over my memories. Had there been a room like this in my house…?","html":"There was something odd about thinking that. Everything else, I couldn’t really remember. It was like a fog hung over my memories. Had there been a room like this in my house…?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0058","sourceIndex":58,"type":"speech","text":"“Rudy?!” A white-haired woman who looked about forty came bursting into the room. A proper middle-aged lady. When our eyes met, she came straight to my side and gripped my hand that lay on top of the blankets.","html":"“Rudy?!” A white-haired woman who looked about forty came bursting into the room. A proper middle-aged lady. When our eyes met, she came straight to my side and gripped my hand that lay on top of the blankets.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","mixed":true,"speakerConfidence":"high"},{"id":"ch05-p0059","sourceIndex":59,"type":"speech","text":"“Sylphie…?”","html":"“Sylphie…?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0060","sourceIndex":60,"type":"speech","text":"“Yes… That’s right, Rudy. It’s Sylphiette,” she told me gently. “Do you know who I am?”","html":"“Yes… That’s right, Rudy. It’s Sylphiette,” she told me gently. “Do you know who I am?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","speakerConfidence":"high"},{"id":"ch05-p0061","sourceIndex":61,"type":"speech","text":"“Yeah… Yeah, I know you. What…happened to me?”","html":"“Yeah… Yeah, I know you. What…happened to me?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0062","sourceIndex":62,"type":"speech","text":"“Nothing happened. It’s just, you were asleep for a long time.”","html":"“Nothing happened. It’s just, you were asleep for a long time.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","speakerConfidence":"high"},{"id":"ch05-p0063","sourceIndex":63,"type":"narration","text":"So I was just asleep. Right. I did feel sleepy.","html":"So I was just asleep. Right. I did feel sleepy.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0064","sourceIndex":64,"type":"speech","text":"“But why can’t I move?”","html":"“But why can’t I move?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0065","sourceIndex":65,"type":"speech","text":"“Yes, well… Yes…” Sylphie didn’t answer me. She just stroked my hand sympathetically. Like she was humoring a forgetful old man…","html":"“Yes, well… Yes…” Sylphie didn’t answer me. She just stroked my hand sympathetically. Like she was humoring a forgetful old man…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","mixed":true,"speakerConfidence":"high"},{"id":"ch05-p0066","sourceIndex":66,"type":"narration","text":"Wait, you don’t mean… Am I senile? Is that why I have no memories? What?","html":"Wait, you don’t mean… Am I senile? Is that why I have no memories? What?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0067","sourceIndex":67,"type":"narration","text":"Seventy-four shouldn’t be old enough for that…but was I actually seventy-four? Maybe I’d aged a lot more. Maybe I’d been senile for much longer.","html":"Seventy-four shouldn’t be old enough for that…but was I actually seventy-four? Maybe I’d aged a lot more. Maybe I’d been senile for much longer.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0068","sourceIndex":68,"type":"narration","text":"Just how long had I been in this bed for, anyway?","html":"Just how long had I been in this bed for, anyway?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0069","sourceIndex":69,"type":"speech","text":"“I’m scared…” I said.","html":"“I’m scared…” I said.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0070","sourceIndex":70,"type":"speech","text":"“You’re okay. I’m here with you.” Sylphie squeezed my hand harder. Just that was enough to relieve some of my fear. But not all of it.","html":"“You’re okay. I’m here with you.” Sylphie squeezed my hand harder. Just that was enough to relieve some of my fear. But not all of it. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","mixed":true,"speakerConfidence":"high"},{"id":"ch05-p0071","sourceIndex":71,"type":"narration","text":"In the next instant a torrent of people poured into the room. I saw a redheaded child, a blue-haired child, a blonde child. Some of them were young, some middle-aged, some elderly, and they all came to stand around my bed. They looked like people I knew.","html":"In the next instant a torrent of people poured into the room. I saw a redheaded child, a blue-haired child, a blonde child. Some of them were young, some middle-aged, some elderly, and they all came to stand around my bed. They looked like people I knew.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0072","sourceIndex":72,"type":"speech","text":"“Look, Rudy. Everyone’s here to see you.”","html":"“Look, Rudy. Everyone’s here to see you.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","speakerConfidence":"high"},{"id":"ch05-p0073","sourceIndex":73,"type":"speech","text":"“Yeah…”","html":"“Yeah…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0074","sourceIndex":74,"type":"narration","text":"For some reason, I couldn’t remember a single one of their names. Ah, one of them I knew. The one who came in slowly behind everyone else, then shut the door behind her. It was a small girl with blue hair. She wore it in braids, just as she always had.","html":"For some reason, I couldn’t remember a single one of their names. Ah, one of them I knew. The one who came in slowly behind everyone else, then shut the door behind her. It was a small girl with blue hair. She wore it in braids, just as she always had.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0075","sourceIndex":75,"type":"speech","text":"“Roxy.”","html":"“Roxy.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0076","sourceIndex":76,"type":"speech","text":"“Rudy.” When I said her name, she looked for a moment like she might cry. But she came straight to stand beside Sylphie, then gently stroked my head.","html":"“Rudy.” When I said her name, she looked for a moment like she might cry. But she came straight to stand beside Sylphie, then gently stroked my head.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Roxy","mixed":true,"speakerConfidence":"high"},{"id":"ch05-p0077","sourceIndex":77,"type":"speech","text":"“Rudy.”","html":"“Rudy.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Roxy","speakerConfidence":"high"},{"id":"ch05-p0078","sourceIndex":78,"type":"speech","text":"“Thank you, Roxy…” Then, the word slipping out of my mouth, I said, “Master.”","html":"“Thank you, Roxy…” Then, the word slipping out of my mouth, I said, “Master.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch05-p0079","sourceIndex":79,"type":"narration","text":"Tears spilled from Roxy’s eyes. She hastily wiped them away and tried to look cheerful, but her mouth only twisted, unable to form a full smile.","html":"Tears spilled from Roxy’s eyes. She hastily wiped them away and tried to look cheerful, but her mouth only twisted, unable to form a full smile.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0080","sourceIndex":80,"type":"narration","text":"A question struck me.","html":"A question struck me.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0081","sourceIndex":81,"type":"speech","text":"“What about Eris? Isn’t she here?”","html":"“What about Eris? Isn’t she here?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0082","sourceIndex":82,"type":"narration","text":"Usually, she’d have been rushing in first, but I saw no sign of her.","html":"Usually, she’d have been rushing in first, but I saw no sign of her.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0083","sourceIndex":83,"type":"speech","text":"“Oh, Rudy. Eris already…she went on ahead.”","html":"“Oh, Rudy. Eris already…she went on ahead.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","speakerConfidence":"high"},{"id":"ch05-p0084","sourceIndex":84,"type":"speech","text":"“Went on where?”","html":"“Went on where?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0085","sourceIndex":85,"type":"speech","text":"“She’s waiting for you, Rudy.”","html":"“She’s waiting for you, Rudy.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","speakerConfidence":"high"},{"id":"ch05-p0086","sourceIndex":86,"type":"narration","text":"Oh, now I see. I see.","html":"Oh, now I see. I see.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0087","sourceIndex":87,"type":"speech","text":"“Was I there for her?”","html":"“Was I there for her?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0088","sourceIndex":88,"type":"speech","text":"“Yes, don’t worry. You cried for three days straight, but you got through it.”","html":"“Yes, don’t worry. You cried for three days straight, but you got through it.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","speakerConfidence":"high"},{"id":"ch05-p0089","sourceIndex":89,"type":"narration","text":"That’s right. It was hazy, but the memory was coming back to me.","html":"That’s right. It was hazy, but the memory was coming back to me.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0090","sourceIndex":90,"type":"narration","text":"Eris had kept on training hard past seventy. But then one day, after going for a run and doing her sword drills, she’d come home, fallen into bed, and that was it. She never got up again. By the time I realized, she was already dead. I’d cried because I thought perhaps if I’d noticed sooner and used healing magic on her, maybe I could have made her better.","html":"Eris had kept on training hard past seventy. But then one day, after going for a run and doing her sword drills, she’d come home, fallen into bed, and that was it. She never got up again. By the time I realized, she was already dead. I’d cried because I thought perhaps if I’d noticed sooner and used healing magic on her, maybe I could have made her better.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0091","sourceIndex":91,"type":"narration","text":"I’d even forgotten that. That meant I couldn’t have long either…","html":"I’d even forgotten that. That meant I couldn’t have long either…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0092","sourceIndex":92,"type":"speech","text":"“Sorry,” I mumbled. “You’re all here for me, but I don’t know who’s who.”","html":"“Sorry,” I mumbled. “You’re all here for me, but I don’t know who’s who.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0093","sourceIndex":93,"type":"speech","text":"“I know, don’t worry. Let’s see… From over there, we have our grandchildren—that’s Lucie’s son, Roland, see? And beside him—” Sylphie went through pointing at each of them and telling me their names. They were almost all my grandchildren and great-grandchildren. Where were my kids? Ah, that’s right, they’d all left the nest and moved to live far away.","html":"“I know, don’t worry. Let’s see… From over there, we have our grandchildren—that’s Lucie’s son, Roland, see? And beside him—” Sylphie went through pointing at each of them and telling me their names. They were almost all my grandchildren and great-grandchildren. Where were my kids? Ah, that’s right, they’d all left the nest and moved to live far away.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","mixed":true,"speakerConfidence":"high"},{"id":"ch05-p0094","sourceIndex":94,"type":"speech","text":"“And over there, with the red hair, the girl who looks just like Eris. That’s Arus’s granddaughter—your great-granddaughter—Feris.”","html":"“And over there, with the red hair, the girl who looks just like Eris. That’s Arus’s granddaughter—your great-granddaughter—Feris.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","speakerConfidence":"high"},{"id":"ch05-p0095","sourceIndex":95,"type":"speech","text":"“Ah, the girl who woke me up.”","html":"“Ah, the girl who woke me up.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0096","sourceIndex":96,"type":"narration","text":"The red-haired girl looked a little embarrassed. Probably nervous that she’d get a scolding for trying to pinch my bracelet. I had the feeling I’d seen here somewhere before.","html":"The red-haired girl looked a little embarrassed. Probably nervous that she’d get a scolding for trying to pinch my bracelet. I had the feeling I’d seen here somewhere before.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0097","sourceIndex":97,"type":"narration","text":"Right. She’d been in my dream about the Man-God. I was pretty sure she’d been in that group of people. Yeah, that was it. It had been her, for sure. She’d been a good deal older than she was now, but I knew it was her.","html":"Right. She’d been in my dream about the Man-God. I was pretty sure she’d been in that group of people. Yeah, that was it. It had been her, for sure. She’d been a good deal older than she was now, but I knew it was her.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0098","sourceIndex":98,"type":"speech","text":"“Come here,” I said, and she obeyed, tears prickling her eyes.","html":"“Come here,” I said, and she obeyed, tears prickling her eyes.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch05-p0099","sourceIndex":99,"type":"speech","text":"“Did you take this off my arm?” I pointed at the bracelet. Tears began to pour down her cheeks. I guess now that she knew getting in trouble was inevitable, she was trying to cry her way out of it.","html":"“Did you take this off my arm?” I pointed at the bracelet. Tears began to pour down her cheeks. I guess now that she knew getting in trouble was inevitable, she was trying to cry her way out of it.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch05-p0100","sourceIndex":100,"type":"speech","text":"“I’m sorry,” she said. “It’s just so pretty.”","html":"“I’m sorry,” she said. “It’s just so pretty.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Feris","speakerConfidence":"high"},{"id":"ch05-p0101","sourceIndex":101,"type":"speech","text":"“Is it now? Well, then, you keep it.”","html":"“Is it now? Well, then, you keep it.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0102","sourceIndex":102,"type":"narration","text":"She gaped at me. “Really?”","html":"She gaped at me. “Really?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Feris","embeddedDialogue":true,"attributionNote":"Narration with Feris's hopeful question.","speakerConfidence":"high"},{"id":"ch05-p0103","sourceIndex":103,"type":"speech","text":"“In return, you’re not to take people’s things without asking ever again.”","html":"“In return, you’re not to take people’s things without asking ever again.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0104","sourceIndex":104,"type":"speech","text":"“I promise.”","html":"“I promise.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Feris","speakerConfidence":"high"},{"id":"ch05-p0105","sourceIndex":105,"type":"speech","text":"“Good girl.” I reached out slowly and patted her head. She might get scolded later, but ah, well. It wouldn’t be my fault if she turned out spoiled.","html":"“Good girl.” I reached out slowly and patted her head. She might get scolded later, but ah, well. It wouldn’t be my fault if she turned out spoiled. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch05-p0106","sourceIndex":106,"type":"speech","text":"“They all look healthy.”","html":"“They all look healthy.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0107","sourceIndex":107,"type":"speech","text":"“Yeah, they are.”","html":"“Yeah, they are.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","speakerConfidence":"high"},{"id":"ch05-p0108","sourceIndex":108,"type":"narration","text":"That put me at ease. Everyone had to be doing well if I had this many grandchildren and great-grandchildren.","html":"That put me at ease. Everyone had to be doing well if I had this many grandchildren and great-grandchildren.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0109","sourceIndex":109,"type":"speech","text":"“Glad to hear it. All that work was worth it…”","html":"“Glad to hear it. All that work was worth it…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Sylphiette","speakerConfidence":"high"},{"id":"ch05-p0110","sourceIndex":110,"type":"narration","text":"As my strength faded, my hand slid from Feris’s head. There was murmuring around me.","html":"As my strength faded, my hand slid from Feris’s head. There was murmuring around me.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0111","sourceIndex":111,"type":"narration","text":"Relax. I’m not going to snuff it quite yet. I plan on staying a bedridden old man for a while yet.","html":"Relax. I’m not going to snuff it quite yet. I plan on staying a bedridden old man for a while yet.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0112","sourceIndex":112,"type":"narration","text":"Someone came into the room. He was tall, with silver hair and a scowl on his face.","html":"Someone came into the room. He was tall, with silver hair and a scowl on his face.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0113","sourceIndex":113,"type":"speech","text":"“Rudeus,” he said.","html":"“Rudeus,” he said.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch05-p0114","sourceIndex":114,"type":"speech","text":"“Sir Orsted.” The moment he appeared, the mood of the room changed. Was it tension? Fear? But no, it was more relaxed. It was reassurance, and trust.","html":"“Sir Orsted.” The moment he appeared, the mood of the room changed. Was it tension? Fear? But no, it was more relaxed. It was reassurance, and trust. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch05-p0115","sourceIndex":115,"type":"speech","text":"“You don’t need to wear the helmet?”","html":"“You don’t need to wear the helmet?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0116","sourceIndex":116,"type":"speech","text":"“No. Your grandchildren cry when I put it on.” Laughter broke out around him, along with calls of “I won’t cry anymore,” and “Man, I really bawled back then.”","html":"“No. Your grandchildren cry when I put it on.” Laughter broke out around him, along with calls of “I won’t cry anymore,” and “Man, I really bawled back then.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","mixed":true,"speakerConfidence":"high"},{"id":"ch05-p0117","sourceIndex":117,"type":"speech","text":"“People don’t fear your face anymore?”","html":"“People don’t fear your face anymore?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0118","sourceIndex":118,"type":"speech","text":"“No, the curse remains. Only your children and grandchildren are unaffected.”","html":"“No, the curse remains. Only your children and grandchildren are unaffected.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch05-p0119","sourceIndex":119,"type":"narration","text":"Orsted’s expression was much softer than it had been when I’d first met him. He was still scowling, but I suppose you could say he was relaxed.","html":"Orsted’s expression was much softer than it had been when I’d first met him. He was still scowling, but I suppose you could say he was relaxed. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0120","sourceIndex":120,"type":"speech","text":"“Actually, Sir Orsted, that reminds me,” I said.","html":"“Actually, Sir Orsted, that reminds me,” I said.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0121","sourceIndex":121,"type":"speech","text":"“What is it?”","html":"“What is it?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch05-p0122","sourceIndex":122,"type":"speech","text":"“Just before, when Feris took the bracelet from me, I dreamed of the Man-God.”","html":"“Just before, when Feris took the bracelet from me, I dreamed of the Man-God.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0123","sourceIndex":123,"type":"narration","text":"There was a pause. “Are you a disciple now?”","html":"There was a pause. “Are you a disciple now?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","embeddedDialogue":true,"attributionNote":"Narration with Orsted's question.","speakerConfidence":"high"},{"id":"ch05-p0124","sourceIndex":124,"type":"speech","text":"“Well, I dunno about that. It might’ve just been an ­ordinary dream…” I said. “If I had become a disciple, what would you do? Would you kill me like you did all the others?”","html":"“Well, I dunno about that. It might’ve just been an ­ordinary dream…” I said. “If I had become a disciple, what would you do? Would you kill me like you did all the others?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch05-p0125","sourceIndex":125,"type":"speech","text":"“Naturally. I do not suffer traitors,” Orsted said, dead serious. Despite that, I immediately picked up that he was joking. Everyone around him laughed, for one thing, and I didn’t feel any hostility coming off him. It felt like poor taste to say that sort of thing in front of a bedridden old man on death’s door…but maybe it was one of those surefire lines that always got a laugh.","html":"“Naturally. I do not suffer traitors,” Orsted said, dead serious. Despite that, I immediately picked up that he was joking. Everyone around him laughed, for one thing, and I didn’t feel any hostility coming off him. It felt like poor taste to say that sort of thing in front of a bedridden old man on death’s door…but maybe it was one of those surefire lines that always got a laugh.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","mixed":true,"speakerConfidence":"high"},{"id":"ch05-p0126","sourceIndex":126,"type":"speech","text":"“In the dream, you’d defeated the Man-God. He was bound with magic.”","html":"“In the dream, you’d defeated the Man-God. He was bound with magic.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0127","sourceIndex":127,"type":"speech","text":"“A good dream, then.”","html":"“A good dream, then.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch05-p0128","sourceIndex":128,"type":"speech","text":"“Yeah, really good.”","html":"“Yeah, really good.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0129","sourceIndex":129,"type":"narration","text":"Could that dream have shown future events? It felt real, but then, dreams always did.","html":"Could that dream have shown future events? It felt real, but then, dreams always did. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0130","sourceIndex":130,"type":"speech","text":"“I hope you’ll do your best to make it come true,” I said. Orsted gave a solemn nod.","html":"“I hope you’ll do your best to make it come true,” I said. Orsted gave a solemn nod.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch05-p0131","sourceIndex":131,"type":"narration","text":"As you’d expect, after fifty years of knowing him, I could read his expressions incredibly accurately.","html":"As you’d expect, after fifty years of knowing him, I could read his expressions incredibly accurately.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0132","sourceIndex":132,"type":"speech","text":"“You lived well. May you rest in peace.”","html":"“You lived well. May you rest in peace.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Orsted","speakerConfidence":"high"},{"id":"ch05-p0133","sourceIndex":133,"type":"speech","text":"“Ha ha… It’s a bit early for resting.”","html":"“Ha ha… It’s a bit early for resting.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0134","sourceIndex":134,"type":"narration","text":"I wanted to stay awake a bit longer. I felt okay. While I couldn’t really move, the sunlight on me was warm and pleasant.","html":"I wanted to stay awake a bit longer. I felt okay. While I couldn’t really move, the sunlight on me was warm and pleasant.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0135","sourceIndex":135,"type":"speech","text":"“I’ll stay a little longer. Just a little longer…”","html":"“I’ll stay a little longer. Just a little longer…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0136","sourceIndex":136,"type":"narration","text":"It wasn’t like there was anything I really wanted to do. I just wanted to look at all the faces around me for a little longer. That was all. I suppose you could say I was a little sad to be leaving them. I just wanted another hour or two with them—even another ten minutes would be enough.","html":"It wasn’t like there was anything I really wanted to do. I just wanted to look at all the faces around me for a little longer. That was all. I suppose you could say I was a little sad to be leaving them. I just wanted another hour or two with them—even another ten minutes would be enough.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0137","sourceIndex":137,"type":"narration","text":"I didn’t have anything I needed to say. I didn’t have any lingering regrets. Right now just felt nice in a small way. That was all.","html":"I didn’t have anything I needed to say. I didn’t have any lingering regrets. Right now just felt nice in a small way. That was all.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0138","sourceIndex":138,"type":"speech","text":"“Just a little…”","html":"“Just a little…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch05-p0139","sourceIndex":139,"type":"narration","text":"My eyelids began to close, drooping down little by little. The last thing I saw was the girl who looked just like Eris, and Sylphie and Roxy’s faces.","html":"My eyelids began to close, drooping down little by little. The last thing I saw was the girl who looked just like Eris, and Sylphie and Roxy’s faces.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0140","sourceIndex":140,"type":"narration","text":"Then my eyes closed.","html":"Then my eyes closed. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch05-p0141","sourceIndex":141,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch05-p0142","sourceIndex":142,"type":"narration","text":"And just like that, I was gone.","html":"And just like that, I was gone.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false}],"wordCount":1791,"speechCount":55,"speakers":["Feris","Orsted","Roxy","Rudeus","Sylphiette"]}],"images":[],"sequence":5,"cast":["Feris","Lara","Orsted","Perugius","Roxy","Rudeus","Sylphiette"],"sceneCount":2,"speechCount":67,"speakers":["Feris","Orsted","Perugius","Roxy","Rudeus","Sylphiette"]},{"id":"ch06","number":2,"title":"Story 2: Thirty-Four Years Old","pov":"Rudeus","kind":"story","wordCount":2731,"scenes":[{"id":"ch06-s01","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The Greyrat house in Sharia, ten years after the battle","cast":["Lara","Leo","Rudeus"],"blocks":[{"id":"ch06-p0002","sourceIndex":2,"type":"narration","text":"I WOKE UP. I had the feeling I’d had a strange dream. Like, a happy dream. Sylphie and Roxy were there. Eris wasn’t, but there was a child who looked just like her. The dream was hazy, but I remembered it perfectly. In the dream, I died. Somehow, I knew that I’d never wake up again after that dream. But I didn’t feel bad. It was actually my second time dying, and it was far better than the first.","html":"I WOKE UP. I had the feeling I’d had a strange dream. Like, a happy dream. Sylphie and Roxy were there. Eris wasn’t, but there was a child who looked just like her. The dream was hazy, but I remembered it perfectly. In the dream, I died. Somehow, I knew that I’d never wake up again after that dream. But I didn’t feel bad. It was actually my second time dying, and it was far better than the first. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0003","sourceIndex":3,"type":"speech","text":"“Huh?” I realized a girl was holding my hand and standing stock-still. She had blue hair tied back in a single ponytail. She held my hand in her right and a bracelet in her left, and had a look on her face like a deer in headlights.","html":"“Huh?” I realized a girl was holding my hand and standing stock-still. She had blue hair tied back in a single ponytail. She held my hand in her right and a bracelet in her left, and had a look on her face like a deer in headlights.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch06-p0004","sourceIndex":4,"type":"speech","text":"“…I’m sorry,” she said suddenly. She must have been taught to apologize when she did something wrong.","html":"“…I’m sorry,” she said suddenly. She must have been taught to apologize when she did something wrong.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lara","mixed":true,"speakerConfidence":"high"},{"id":"ch06-p0005","sourceIndex":5,"type":"speech","text":"“Did you want it?”","html":"“Did you want it?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch06-p0006","sourceIndex":6,"type":"speech","text":"“…No. My big sister said there was a super amazing crest hidden under your bracelet, Dad.”","html":"“…No. My big sister said there was a super amazing crest hidden under your bracelet, Dad.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lara","speakerConfidence":"high"},{"id":"ch06-p0007","sourceIndex":7,"type":"speech","text":"“Did she now?”","html":"“Did she now?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch06-p0008","sourceIndex":8,"type":"narration","text":"There was no hidden crest. I wasn’t the chosen one, after all.","html":"There was no hidden crest. I wasn’t the chosen one, after all.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0009","sourceIndex":9,"type":"narration","text":"But looking past the girl holding the bracelet, I saw a brush resting on the bedside table. That definitely hadn’t been there before I fell asleep.","html":"But looking past the girl holding the bracelet, I saw a brush resting on the bedside table. That definitely hadn’t been there before I fell asleep.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0010","sourceIndex":10,"type":"speech","text":"“Were you going to draw it?”","html":"“Were you going to draw it?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch06-p0011","sourceIndex":11,"type":"speech","text":"“…I’m sorry.”","html":"“…I’m sorry.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lara","speakerConfidence":"high"},{"id":"ch06-p0012","sourceIndex":12,"type":"narration","text":"She was driven enough to try and turn a lie into reality. Should I praise her, or scold her? Okay, no, this was a scolding situation. It’s a father’s responsibility to educate his daughter, so… Yeah.","html":"She was driven enough to try and turn a lie into reality. Should I praise her, or scold her? Okay, no, this was a scolding situation. It’s a father’s responsibility to educate his daughter, so… Yeah.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0013","sourceIndex":13,"type":"speech","text":"“Lara, you mustn’t tell lies. Go say sorry to your sister.”","html":"“Lara, you mustn’t tell lies. Go say sorry to your sister.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch06-p0014","sourceIndex":14,"type":"speech","text":"“Okay…”","html":"“Okay…” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lara","speakerConfidence":"high"},{"id":"ch06-p0015","sourceIndex":15,"type":"narration","text":"I patted her on the head, and she left the room, dejected. After she left, I caught sight of a big ball of white fur. Leo must have been keeping watch outside the door. I was about to put the bracelet back on, but then the brush caught my eye. I used it to paint the Migurd crest on my arm, then got out of bed.","html":"I patted her on the head, and she left the room, dejected. After she left, I caught sight of a big ball of white fur. Leo must have been keeping watch outside the door. I was about to put the bracelet back on, but then the brush caught my eye. I used it to paint the Migurd crest on my arm, then got out of bed.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0016","sourceIndex":16,"type":"speech","text":"“Oof, that’s a nasty headache… I drank too much.”","html":"“Oof, that’s a nasty headache… I drank too much.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch06-p0017","sourceIndex":17,"type":"narration","text":"I cradled my head in my hands. Maybe it was the party the previous night, or maybe it was the dream I’d just had, but it hurt like hell.","html":"I cradled my head in my hands. Maybe it was the party the previous night, or maybe it was the dream I’d just had, but it hurt like hell.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0018","sourceIndex":18,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":364,"speechCount":10,"speakers":["Lara","Rudeus"]},{"id":"ch06-s02","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"Sharia, ten years after the battle","cast":["Aisha","Ariel","Cliff","Eris","Lilia","Luke","Nanahoshi","Norn","Roxy","Rudeus","Sylphiette","Zanoba","Zenith"],"blocks":[{"id":"ch06-p0020","sourceIndex":20,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch06-p0021","sourceIndex":21,"type":"narration","text":"Ten years had passed since the battle in the Biheiril Kingdom. This year, I would be thirty-four. These ten years had been peaceful thanks to the absence of the Man-God. After that battle, it really had just stopped. I hadn’t seen so much of a pixel of him for a few years now. Not that I had let my guard down! While constantly on the lookout for suspicious attacks, I went on preparing to confront Laplace, just as I had before. Things went much more smoothly without the Man-God sticking his nose in.","html":"Ten years had passed since the battle in the Biheiril Kingdom. This year, I would be thirty-four. These ten years had been peaceful thanks to the absence of the Man-God. After that battle, it really had just stopped. I hadn’t seen so much of a pixel of him for a few years now. Not that I had let my guard down! While constantly on the lookout for suspicious attacks, I went on preparing to confront Laplace, just as I had before. Things went much more smoothly without the Man-God sticking his nose in. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0022","sourceIndex":22,"type":"narration","text":"In the first five years, I finished calling in on all the nations of the world. Some of them were nonstarters, but by and large, they all pledged to work with us to prepare for the coming war with Laplace.","html":"In the first five years, I finished calling in on all the nations of the world. Some of them were nonstarters, but by and large, they all pledged to work with us to prepare for the coming war with Laplace.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0023","sourceIndex":23,"type":"narration","text":"Now, I was working on research and teaching unvoiced magic at the Magic University in the Asuran Kingdom while also leading the militaries of the world to develop counter-strategies to Laplace’s most likely moves.","html":"Now, I was working on research and teaching unvoiced magic at the Magic University in the Asuran Kingdom while also leading the militaries of the world to develop counter-strategies to Laplace’s most likely moves. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0024","sourceIndex":24,"type":"narration","text":"For that work, I put away the name Rudeus and started to work under the name “Silent Sevenstar.” The theory Nanahoshi had once put forward might be accurate or it might not be, but she’d said, “I want you to make my name a clue, just in case a friend from our old world ever comes here.” I took her words to heart and spread her name around. I was also giving her quite a reputation, but so what? No harm, no foul. For the time being, awareness was the priority, and a person from another world would surely understand the meaning behind what I’d tried to do in her name.","html":"For that work, I put away the name Rudeus and started to work under the name “Silent Sevenstar.” The theory Nanahoshi had once put forward might be accurate or it might not be, but she’d said, “I want you to make my name a clue, just in case a friend from our old world ever comes here.” I took her words to heart and spread her name around. I was also giving her quite a reputation, but so what? No harm, no foul. For the time being, awareness was the priority, and a person from another world would surely understand the meaning behind what I’d tried to do in her name.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0025","sourceIndex":25,"type":"narration","text":"Lately, I’d been researching mana recovery to improve Orsted’s mana recovery rate. I’d managed to create a ­potion that restored mana, but for some reason it didn’t work on Orsted. Possibly human mana and dragon mana was different? It might have been something else. I was going to press on with the research a little longer, but I couldn’t shake the feeling I was going down a dead end. The potion had been a smash hit in its own way, so it hadn’t been entirely for nothing. There were lots of other things I still needed to do, besides. I couldn’t rest yet.","html":"Lately, I’d been researching mana recovery to improve Orsted’s mana recovery rate. I’d managed to create a ­potion that restored mana, but for some reason it didn’t work on Orsted. Possibly human mana and dragon mana was different? It might have been something else. I was going to press on with the research a little longer, but I couldn’t shake the feeling I was going down a dead end. The potion had been a smash hit in its own way, so it hadn’t been entirely for nothing. There were lots of other things I still needed to do, besides. I couldn’t rest yet. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0026","sourceIndex":26,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch06-p0027","sourceIndex":27,"type":"narration","text":"My children had grown up. Lucie was seventeen. Lara was fifteen, and Arus was thirteen. Sieg was…eleven, I think? They were all thriving. We’d also had two more children: Lily Greyrat, with Roxy, and Christina Greyrat, with Eris. Both girls. With six children, we were a big family. When Lucie turned seven we had a family meeting to roughly decide our education policy for her: things like sending her to the magic university from the age of seven, then scheduling her coming-of-age ceremony for after graduation, and then having her attend the national university in Asura for three years. My personal philosophy was that it was better not to drive your children too hard. Still, I thought we ought to decide where they’d be educated and provide some guideposts for the path they ought to take.","html":"My children had grown up. Lucie was seventeen. Lara was fifteen, and Arus was thirteen. Sieg was…eleven, I think? They were all thriving. We’d also had two more children: Lily Greyrat, with Roxy, and Christina Greyrat, with Eris. Both girls. With six children, we were a big family. When Lucie turned seven we had a family meeting to roughly decide our education policy for her: things like sending her to the magic university from the age of seven, then scheduling her coming-of-age ceremony for after graduation, and then having her attend the national university in Asura for three years. My personal philosophy was that it was better not to drive your children too hard. Still, I thought we ought to decide where they’d be educated and provide some guideposts for the path they ought to take.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0028","sourceIndex":28,"type":"narration","text":"It was Ariel’s express wish that I send my children to the Asuran National University. I owed her a massive debt. If she’d said, “Give one to me as a husband so that we can be joined as blood relatives!” I would have refused—duh—but a little thing like asking me to send my kids to her university? I could hardly refuse that. I wanted to gradually pay down my debt to her.","html":"It was Ariel’s express wish that I send my children to the Asuran National University. I owed her a massive debt. If she’d said, “Give one to me as a husband so that we can be joined as blood relatives!” I would have refused—duh—but a little thing like asking me to send my kids to her university? I could hardly refuse that. I wanted to gradually pay down my debt to her. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0029","sourceIndex":29,"type":"narration","text":"Ariel, by the by, had a baby of her own after the Biheiril Kingdom Battle. She hadn’t married the father so as not to give him too much power. Apparently, she kept a sizable harem of men. Ariel had five children now, but it wasn’t clear who had fathered four of them…or so Luke had told me, pale-faced and cradling his head in his hands. At the time, I’d wondered how he’d worked out who one of them was. Now that I think of it, it’s possible the one he knew was Luke himself.","html":"Ariel, by the by, had a baby of her own after the Biheiril Kingdom Battle. She hadn’t married the father so as not to give him too much power. Apparently, she kept a sizable harem of men. Ariel had five children now, but it wasn’t clear who had fathered four of them…or so Luke had told me, pale-faced and cradling his head in his hands. At the time, I’d wondered how he’d worked out who one of them was. Now that I think of it, it’s possible the one he knew was Luke himself.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0030","sourceIndex":30,"type":"narration","text":"Ariel was reportedly scheming to pair up one of my children with one of those five. I didn’t much like the idea of my children being used as political pawns, but once they were of age, if they were both okay with the match, I’d permit it.","html":"Ariel was reportedly scheming to pair up one of my children with one of those five. I didn’t much like the idea of my children being used as political pawns, but once they were of age, if they were both okay with the match, I’d permit it.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0031","sourceIndex":31,"type":"narration","text":"My children were still young, but I knew that with each passing year, they’d grow up. Lucie in particular was already a proper adult with a mind of her own. Not that the grown-ups around her had matured all that much; I honestly couldn’t tell if I’d changed. Whenever I thought I’d improved some bad trait, another one would crop up. Sometimes the bad traits I’d fixed relapsed, too. It felt like I was just making the same ­mistakes over and over as the years ticked away. The only real visible sign of my growth was how my face aged with the passing years. I’d even gotten a few laugh lines. Sylphie told me, “I like that about you as well,” but it made me feel sort of guilty when she still looked young. You could tell she was aging, but the changes were slight considering we were the same age. That meant she’d be thirty-four this year, but she still looked around twenty. Her skin glowed with youth and even though she’d had two children, her butt was still tight, and she felt as good to hold as ever.","html":"My children were still young, but I knew that with each passing year, they’d grow up. Lucie in particular was already a proper adult with a mind of her own. Not that the grown-ups around her had matured all that much; I honestly couldn’t tell if I’d changed. Whenever I thought I’d improved some bad trait, another one would crop up. Sometimes the bad traits I’d fixed relapsed, too. It felt like I was just making the same ­mistakes over and over as the years ticked away. The only real visible sign of my growth was how my face aged with the passing years. I’d even gotten a few laugh lines. Sylphie told me, “I like that about you as well,” but it made me feel sort of guilty when she still looked young. You could tell she was aging, but the changes were slight considering we were the same age. That meant she’d be thirty-four this year, but she still looked around twenty. Her skin glowed with youth and even though she’d had two children, her butt was still tight, and she felt as good to hold as ever.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0032","sourceIndex":32,"type":"narration","text":"The only thing was, on the inside, she’d totally turned into…uh, a mom, so she’d started to nag me a lot. Roxy never changed. She looked the same and acted pretty much the same too. She’d get mad if I told her that, but I meant it as praise. She was still my master, as always, so whenever I did something wrong she corrected me. Her clumsiness never lessened over the years, but she always picked herself up again. Failure is a wonderful teacher, as they say.","html":"The only thing was, on the inside, she’d totally turned into…uh, a mom, so she’d started to nag me a lot. Roxy never changed. She looked the same and acted pretty much the same too. She’d get mad if I told her that, but I meant it as praise. She was still my master, as always, so whenever I did something wrong she corrected me. Her clumsiness never lessened over the years, but she always picked herself up again. Failure is a wonderful teacher, as they say.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0033","sourceIndex":33,"type":"narration","text":"Going by looks, Eris had changed the most. Like me, she looked her age. Only, maybe because she didn’t skip a day of training, she looked way younger than me. She still had the skin of a woman in her late twenties. Having a second child seemed to have mellowed her out a bit, but she still pounced on me from time to time. She’d hardly changed at all on the inside—the opposite of Sylphie—but I did feel like she’d gotten less violent since she’d started teaching sword fighting to the kids. She’d learned to grin and bear it when her temper flared. She still punched me if I touched her butt or her breasts without permission, but that was only natural.","html":"Going by looks, Eris had changed the most. Like me, she looked her age. Only, maybe because she didn’t skip a day of training, she looked way younger than me. She still had the skin of a woman in her late twenties. Having a second child seemed to have mellowed her out a bit, but she still pounced on me from time to time. She’d hardly changed at all on the inside—the opposite of Sylphie—but I did feel like she’d gotten less violent since she’d started teaching sword fighting to the kids. She’d learned to grin and bear it when her temper flared. She still punched me if I touched her butt or her breasts without permission, but that was only natural. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0034","sourceIndex":34,"type":"narration","text":"Lilia and Zenith looked older. They were both still healthy, but Lilia, maybe because her leg had always given her trouble, had started getting back pain and stiff shoulders. Healing magic would make it go away, but give it three months, and it would come back. A perfect cure seemed like it would be challenging to develop.","html":"Lilia and Zenith looked older. They were both still healthy, but Lilia, maybe because her leg had always given her trouble, had started getting back pain and stiff shoulders. Healing magic would make it go away, but give it three months, and it would come back. A perfect cure seemed like it would be challenging to develop.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0035","sourceIndex":35,"type":"narration","text":"Everyone else was aging well alongside us. Zanoba and Cliff were old dudes now, both busy with their jobs and their families. They were there for one another when they got into binds.","html":"Everyone else was aging well alongside us. Zanoba and Cliff were old dudes now, both busy with their jobs and their families. They were there for one another when they got into binds.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0036","sourceIndex":36,"type":"narration","text":"Norn and Aisha had both gotten married and moved out. Their partners were both a little…complicated, as people, but then, I’d had a good talk with both of them and been convinced they were worthy, so it wasn’t my place to comment on it now.","html":"Norn and Aisha had both gotten married and moved out. Their partners were both a little…complicated, as people, but then, I’d had a good talk with both of them and been convinced they were worthy, so it wasn’t my place to comment on it now.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0037","sourceIndex":37,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch06-p0038","sourceIndex":38,"type":"narration","text":"I was really turning thirty-four years old. It was an age that had some significance for me.","html":"I was really turning thirty-four years old. It was an age that had some significance for me.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0039","sourceIndex":39,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":1281,"speechCount":0,"speakers":[]},{"id":"ch06-s03","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The noble graveyard in the Magic City of Sharia","cast":["Geese","Grave Keeper","Paul","Rudeus"],"blocks":[{"id":"ch06-p0041","sourceIndex":41,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch06-p0042","sourceIndex":42,"type":"narration","text":"Around midday on that day, I went out. On the outskirts of town, on top of a small hill, there stood rows of rounded stones. It was a graveyard.","html":"Around midday on that day, I went out. On the outskirts of town, on top of a small hill, there stood rows of rounded stones. It was a graveyard.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0043","sourceIndex":43,"type":"speech","text":"“Hello. I really appreciate all this.” At the entrance, I said a word of thanks to the grave keeper, as I always did. Over the past ten years, the number of graves here had increased. People come into the world and leave it, but gravestones don’t thin out much. In other graveyards, sometimes gravestones can be torn down when a whole family dies or something, but this graveyard was for nobles. Unless the line ended, the gravestones would remain—especially since the Ranoa Kingdom and the Magic City of Sharia were growing ever more powerful. As their might swelled, so did the number of nobles, and the number of gravestones soared with them.","html":"“Hello. I really appreciate all this.” At the entrance, I said a word of thanks to the grave keeper, as I always did. Over the past ten years, the number of graves here had increased. People come into the world and leave it, but gravestones don’t thin out much. In other graveyards, sometimes gravestones can be torn down when a whole family dies or something, but this graveyard was for nobles. Unless the line ended, the gravestones would remain—especially since the Ranoa Kingdom and the Magic City of Sharia were growing ever more powerful. As their might swelled, so did the number of nobles, and the number of gravestones soared with them.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch06-p0044","sourceIndex":44,"type":"narration","text":"I stopped in front of one grave.","html":"I stopped in front of one grave.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0045","sourceIndex":45,"type":"narration","text":"On the rounded stone was written Paul Greyrat. It was much more worn than it had been when it was first built. Using the gear I’d brought, I tidied the area around the grave and polished the stone. After that, I put out some alcohol as an offering, then put my hands together.","html":"On the rounded stone was written Paul Greyrat. It was much more worn than it had been when it was first built. Using the gear I’d brought, I tidied the area around the grave and polished the stone. After that, I put out some alcohol as an offering, then put my hands together.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0046","sourceIndex":46,"type":"narration","text":"I hadn’t come here for a long time. Long ago, any time anything had happened I’d come to report it, but lately, my visits had grown less frequent. We still came once a year with the whole family…but that wasn’t the same, somehow. That annual visit, it seemed to me, was more of a custom than a visit to see Paul. There wasn’t enough gratitude in it.","html":"I hadn’t come here for a long time. Long ago, any time anything had happened I’d come to report it, but lately, my visits had grown less frequent. We still came once a year with the whole family…but that wasn’t the same, somehow. That annual visit, it seemed to me, was more of a custom than a visit to see Paul. There wasn’t enough gratitude in it.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0047","sourceIndex":47,"type":"speech","text":"“Hey, Dad. Everyone’s doing great.”","html":"“Hey, Dad. Everyone’s doing great.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch06-p0048","sourceIndex":48,"type":"narration","text":"With this first announcement out of the way, I went on to give him a rundown of recent events. I did this every year, but you know, just in case.","html":"With this first announcement out of the way, I went on to give him a rundown of recent events. I did this every year, but you know, just in case.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0049","sourceIndex":49,"type":"speech","text":"“I’ll be thirty-four this year.”","html":"“I’ll be thirty-four this year.” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch06-p0050","sourceIndex":50,"type":"narration","text":"Thirty-four was the age I’d been when I died in my previous life. Without even thinking about it, I’d gotten that old. For some reason, it felt like getting to thirty-four had taken longer in this world than in the last one. Probably because I’d had more on my plate. That, and I’d traveled way more.","html":"Thirty-four was the age I’d been when I died in my previous life. Without even thinking about it, I’d gotten that old. For some reason, it felt like getting to thirty-four had taken longer in this world than in the last one. Probably because I’d had more on my plate. That, and I’d traveled way more.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0051","sourceIndex":51,"type":"speech","text":"“But even though I’m turning thirty-four, I had a dream where I die at seventy-four.”","html":"“But even though I’m turning thirty-four, I had a dream where I die at seventy-four.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch06-p0052","sourceIndex":52,"type":"narration","text":"Where had that dream come from? Maybe it was just that: a dream. Or maybe the Man-God had been showing me my future—the Man-God sealed away, and me meeting my death in contentment. It had happened the moment that Lara slipped my bracelet off, so the Man-God could have intervened then.","html":"Where had that dream come from? Maybe it was just that: a dream. Or maybe the Man-God had been showing me my future—the Man-God sealed away, and me meeting my death in contentment. It had happened the moment that Lara slipped my bracelet off, so the Man-God could have intervened then.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0053","sourceIndex":53,"type":"speech","text":"“If that really was the future…”","html":"“If that really was the future…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch06-p0054","sourceIndex":54,"type":"narration","text":"If the dream had been shown to me by the Man-God, then maybe it had shown the fruits of all the work I’d put in up to now. We had won the Battle of the Biheiril Kingdom. It had really been the last battle—after that, the Man-God no longer had any way to defeat me and Orsted, and so he had given up. Ten years had gone by with no interference from him. There’d been nothing at all.","html":"If the dream had been shown to me by the Man-God, then maybe it had shown the fruits of all the work I’d put in up to now. We had won the Battle of the Biheiril Kingdom. It had really been the last battle—after that, the Man-God no longer had any way to defeat me and Orsted, and so he had given up. Ten years had gone by with no interference from him. There’d been nothing at all.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0055","sourceIndex":55,"type":"narration","text":"It might be that he was skulking around in the shadows, but just like Geese and Badigadi had said, I hadn’t heard a peep out of him. Sometimes, I even found myself forgetting what I was doing all this for.","html":"It might be that he was skulking around in the shadows, but just like Geese and Badigadi had said, I hadn’t heard a peep out of him. Sometimes, I even found myself forgetting what I was doing all this for.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0056","sourceIndex":56,"type":"speech","text":"“That means I can stop trying so hard. Right?”","html":"“That means I can stop trying so hard. Right?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch06-p0057","sourceIndex":57,"type":"narration","text":"If the Man-God really had given up, if my work was really at an end, then I could cut back to about half the work I was doing now and live a more laid-back life. I could spend one whole day in every three or so on devoting myself to baby-making with my wives, or teaching all sorts of things to my children… A quiet life like that didn’t sound so bad.","html":"If the Man-God really had given up, if my work was really at an end, then I could cut back to about half the work I was doing now and live a more laid-back life. I could spend one whole day in every three or so on devoting myself to baby-making with my wives, or teaching all sorts of things to my children… A quiet life like that didn’t sound so bad.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0058","sourceIndex":58,"type":"speech","text":"“Just kidding,” I said, laughing. What an idea! Even if the Man-God had given up on me, so what? It wasn’t like I hated my job now. I wasn’t suffering. I was getting things ready to lead Orsted to victory in the battle to come. It was a blast. Yeah, there were hard times, and painful times besides, but never enough that I wanted to run away from it. There were things I had to take care of, tasks I wanted to do, new challenges to try. For all I knew, making me feel like everything was okay now was the Man-God’s plot.","html":"“Just kidding,” I said, laughing. What an idea! Even if the Man-God had given up on me, so what? It wasn’t like I hated my job now. I wasn’t suffering. I was getting things ready to lead Orsted to victory in the battle to come. It was a blast. Yeah, there were hard times, and painful times besides, but never enough that I wanted to run away from it. There were things I had to take care of, tasks I wanted to do, new challenges to try. For all I knew, making me feel like everything was okay now was the Man-God’s plot.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch06-p0059","sourceIndex":59,"type":"speech","text":"“I’m going to keep on giving it my all, Dad.”","html":"“I’m going to keep on giving it my all, Dad.” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch06-p0060","sourceIndex":60,"type":"narration","text":"I’d just keep on going as I always had. It had been a dream, I decided. A dream born out of hope, showing me what I wanted to see.","html":"I’d just keep on going as I always had. It had been a dream, I decided. A dream born out of hope, showing me what I wanted to see.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0061","sourceIndex":61,"type":"speech","text":"“Please watch over me,” I said, just like I said every time. Then, I put my hands together once more.","html":"“Please watch over me,” I said, just like I said every time. Then, I put my hands together once more.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch06-p0062","sourceIndex":62,"type":"narration","text":"The fact I existed had to mean there was a world after death. Only, that didn’t necessarily mean Paul was here in this grave. He’d be off enjoying himself somewhere else. There might not be any reason at all to come here.","html":"The fact I existed had to mean there was a world after death. Only, that didn’t necessarily mean Paul was here in this grave. He’d be off enjoying himself somewhere else. There might not be any reason at all to come here. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0063","sourceIndex":63,"type":"narration","text":"I was okay with that. This was a ritual. From today, I was going to go on trying my best, and pledging that in front of Paul’s grave mattered to me.","html":"I was okay with that. This was a ritual. From today, I was going to go on trying my best, and pledging that in front of Paul’s grave mattered to me. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0064","sourceIndex":64,"type":"speech","text":"“Oh, and Geese…” Geese’s grave was next to Paul’s. I laid an offering on it, then put my hands together. I wasn’t sure what Geese thought about this, but then, it wasn’t like the guy had wholeheartedly wanted to destroy me or anything.","html":"“Oh, and Geese…” Geese’s grave was next to Paul’s. I laid an offering on it, then put my hands together. I wasn’t sure what Geese thought about this, but then, it wasn’t like the guy had wholeheartedly wanted to destroy me or anything.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch06-p0065","sourceIndex":65,"type":"speech","text":"“If you don’t like how things worked out, you can tell me about it in forty years… Though I might live longer than that. Or I might die sooner.”","html":"“If you don’t like how things worked out, you can tell me about it in forty years… Though I might live longer than that. Or I might die sooner.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch06-p0066","sourceIndex":66,"type":"narration","text":"I didn’t want to gloss over Geese’s death, but a lot of my feelings over that time had faded in the past ten years. What I remembered now was his smile. He’d always been wearing that stupid grin and talking about jinxes. Imagining it now, I could only think of it as a good memory. No one I loved had died because of Geese. I had no reason to hold a grudge.","html":"I didn’t want to gloss over Geese’s death, but a lot of my feelings over that time had faded in the past ten years. What I remembered now was his smile. He’d always been wearing that stupid grin and talking about jinxes. Imagining it now, I could only think of it as a good memory. No one I loved had died because of Geese. I had no reason to hold a grudge.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0067","sourceIndex":67,"type":"narration","text":"Now that he was gone, I could at least visit his grave.","html":"Now that he was gone, I could at least visit his grave.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0068","sourceIndex":68,"type":"speech","text":"“Right, I’ll be back soon. Probably with the family, next time.”","html":"“Right, I’ll be back soon. Probably with the family, next time.”","className":"P_Prose_Formatting__And__Page_Break","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch06-p0069","sourceIndex":69,"type":"narration","text":"I stood up. I wasn’t going to change anything just because of a weird dream. I was going to do what I wanted to, and what I had to. That was all.","html":"I stood up. I wasn’t going to change anything just because of a weird dream. I was going to do what I wanted to, and what I had to. That was all.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch06-p0070","sourceIndex":70,"type":"narration","text":"And with that, I set off back to the house where my family was waiting.","html":"And with that, I set off back to the house where my family was waiting.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false}],"wordCount":1084,"speechCount":12,"speakers":["Rudeus"]}],"images":[{"id":"ch06-img01","type":"image","src":"INTERIORIMAGES_09.jpg","alt":""}],"sequence":6,"cast":["Aisha","Ariel","Cliff","Eris","Geese","Grave Keeper","Lara","Leo","Lilia","Luke","Nanahoshi","Norn","Paul","Roxy","Rudeus","Sylphiette","Zanoba","Zenith"],"sceneCount":3,"speechCount":22,"speakers":["Lara","Rudeus"]},{"id":"ch07","number":3,"title":"Story 3: The World After Death","pov":"Rudeus","kind":"story","wordCount":2095,"scenes":[{"id":"ch07-s01","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The Man-God's white room, after Rudeus's death","cast":["Perugius","Rudeus"],"blocks":[{"id":"ch07-p0002","sourceIndex":2,"type":"narration","text":"I FOUND MYSELF in a white room.","html":"I FOUND MYSELF in a white room.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0003","sourceIndex":3,"type":"speech","text":"“Hey.”","html":"“Hey.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0004","sourceIndex":4,"type":"speech","text":"“Howdy.”","html":"“Howdy.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch07-p0005","sourceIndex":5,"type":"narration","text":"The pixelated asshole here was in good shape as usual. Just because he was sealed in here, of course, didn’t mean he was moping. He was as pixelated as ever, so…","html":"The pixelated asshole here was in good shape as usual. Just because he was sealed in here, of course, didn’t mean he was moping. He was as pixelated as ever, so…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0006","sourceIndex":6,"type":"speech","text":"“That stuff I saw forty years back… That was future vision, huh?”","html":"“That stuff I saw forty years back… That was future vision, huh?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0007","sourceIndex":7,"type":"speech","text":"“You got it.”","html":"“You got it.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch07-p0008","sourceIndex":8,"type":"narration","text":"The Man-God was the same as ever. But forty, even fifty years had passed since I saw him last. His “same as ever” qualities had long since faded into my distant memory. I did remember him being just as arrogant back when we first met as he was now, though.","html":"The Man-God was the same as ever. But forty, even fifty years had passed since I saw him last. His “same as ever” qualities had long since faded into my distant memory. I did remember him being just as arrogant back when we first met as he was now, though.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0009","sourceIndex":9,"type":"speech","text":"“I thought if you saw that you might cut me a bit of slack.”","html":"“I thought if you saw that you might cut me a bit of slack.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0010","sourceIndex":10,"type":"speech","text":"“Lost that bet, huh?”","html":"“Lost that bet, huh?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch07-p0011","sourceIndex":11,"type":"speech","text":"“Whatever. I was doomed anyway.”","html":"“Whatever. I was doomed anyway.” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0012","sourceIndex":12,"type":"narration","text":"I wasn’t so weak-willed that I’d give up on everything I’d worked for just because of one dream. Though admittedly, I might have if it hadn’t been in the form of a dream.","html":"I wasn’t so weak-willed that I’d give up on everything I’d worked for just because of one dream. Though admittedly, I might have if it hadn’t been in the form of a dream.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0013","sourceIndex":13,"type":"speech","text":"“That was what you looked like, huh,” he said.","html":"“That was what you looked like, huh,” he said.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","mixed":true,"speakerConfidence":"high"},{"id":"ch07-p0014","sourceIndex":14,"type":"narration","text":"I looked at myself. The big, blubbery body…was gone. At some point, my appearance had changed. I was in pretty good shape—you could see muscle definition, and my abs were trim and toned. It was the kind of body that looked like it could float like a butterfly. It was the body I’d grown used to in this world… The body of Rudeus Greyrat. I couldn’t see my own face, but I didn’t feel like it was very old.","html":"I looked at myself. The big, blubbery body…was gone. At some point, my appearance had changed. I was in pretty good shape—you could see muscle definition, and my abs were trim and toned. It was the kind of body that looked like it could float like a butterfly. It was the body I’d grown used to in this world… The body of Rudeus Greyrat. I couldn’t see my own face, but I didn’t feel like it was very old.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0015","sourceIndex":15,"type":"speech","text":"“You didn’t know?”","html":"“You didn’t know?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0016","sourceIndex":16,"type":"speech","text":"“No. My eyes see straight to the soul. I knew there was something different between your body and your soul, but this is the first time I’ve actually seen you.”","html":"“No. My eyes see straight to the soul. I knew there was something different between your body and your soul, but this is the first time I’ve actually seen you.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch07-p0017","sourceIndex":17,"type":"narration","text":"He was really dropping some hot new information on me now! Then again, I didn’t know what the Man-God looked like either. Technically, we were even.","html":"He was really dropping some hot new information on me now! Then again, I didn’t know what the Man-God looked like either. Technically, we were even.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0018","sourceIndex":18,"type":"narration","text":"How come my body’s only just changed to look like this now? Actually, never mind. I don’t need an answer.","html":"How come my body’s only just changed to look like this now? Actually, never mind. I don’t need an answer.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0019","sourceIndex":19,"type":"speech","text":"“Anyhow. This is the end of the line for you,” said the Man-God.","html":"“Anyhow. This is the end of the line for you,” said the Man-God.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","mixed":true,"speakerConfidence":"high"},{"id":"ch07-p0020","sourceIndex":20,"type":"speech","text":"“Yeah,” I replied at length.","html":"“Yeah,” I replied at length. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0021","sourceIndex":21,"type":"narration","text":"I’d died, at seventy-four years old. It was hazy, but I remembered my final moments. I was surrounded by my children and my grandchildren. I think I was happy at the end. At the very least, it was a world away from the final moments in my previous life. When I compared it to that lonely, powerless, pathetic, pitiful end…","html":"I’d died, at seventy-four years old. It was hazy, but I remembered my final moments. I was surrounded by my children and my grandchildren. I think I was happy at the end. At the very least, it was a world away from the final moments in my previous life. When I compared it to that lonely, powerless, pathetic, pitiful end…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0022","sourceIndex":22,"type":"speech","text":"“It’ll make things easier for me with you out of the picture.”","html":"“It’ll make things easier for me with you out of the picture.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch07-p0023","sourceIndex":23,"type":"speech","text":"“That so?”","html":"“That so?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0024","sourceIndex":24,"type":"speech","text":"“While you were alive, everything I tried to do came to nothing. So I had a think. I took a leaf from your book, and ever so slowly, I’ve been building up my allies.”","html":"“While you were alive, everything I tried to do came to nothing. So I had a think. I took a leaf from your book, and ever so slowly, I’ve been building up my allies.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch07-p0025","sourceIndex":25,"type":"speech","text":"“You still haven’t quit, huh?”","html":"“You still haven’t quit, huh?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0026","sourceIndex":26,"type":"narration","text":"The Man-God’s mood changed. Now he was angry.","html":"The Man-God’s mood changed. Now he was angry. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0027","sourceIndex":27,"type":"speech","text":"“Obviously,” he said. “Would you give up if you knew that future was coming? Always alone, unable to do anything, see anything—and spending ten or even a hundred thousand years like that. I know I couldn’t live like that. How could I give up?”","html":"“Obviously,” he said. “Would you give up if you knew that future was coming? Always alone, unable to do anything, see anything—and spending ten or even a hundred thousand years like that. I know I couldn’t live like that. How could I give up?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","mixed":true,"speakerConfidence":"high"},{"id":"ch07-p0028","sourceIndex":28,"type":"narration","text":"Okay, fair enough. Can’t imagine it turning into such an epic thing, though.","html":"Okay, fair enough. Can’t imagine it turning into such an epic thing, though.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0029","sourceIndex":29,"type":"narration","text":"Still, I understood a little of what he felt. If you knew that something was going to happen to you, the sort of future that awaited you, and that you’d regret it unless you acted now, you wouldn’t be able to sit back and let it happen.","html":"Still, I understood a little of what he felt. If you knew that something was going to happen to you, the sort of future that awaited you, and that you’d regret it unless you acted now, you wouldn’t be able to sit back and let it happen.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0030","sourceIndex":30,"type":"speech","text":"“Yeah, I guess you can’t quit.”","html":"“Yeah, I guess you can’t quit.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0031","sourceIndex":31,"type":"speech","text":"“What’re you acting so ambivalent for? Think you’ve already won or something?”","html":"“What’re you acting so ambivalent for? Think you’ve already won or something?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch07-p0032","sourceIndex":32,"type":"speech","text":"“You have a plan then?”","html":"“You have a plan then?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0033","sourceIndex":33,"type":"speech","text":"“I do. And now I know that Orsted loops through these same two hundred years. Also, you had too many descendants. I thought of a way to use that. Over the past fifty years, I’ve gotten everything ready…”","html":"“I do. And now I know that Orsted loops through these same two hundred years. Also, you had too many descendants. I thought of a way to use that. Over the past fifty years, I’ve gotten everything ready…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch07-p0034","sourceIndex":34,"type":"speech","text":"“That so?”","html":"“That so?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0035","sourceIndex":35,"type":"speech","text":"“Is what I’m saying getting through to you? I’m going to turn everything you built against you, then spoil it. Once you’re gone from this world, I’m going to use what you made to win. And there’s nothing you can do about it because, in the end, you’re dead! You can’t do anything to stop your descendants from feuding and murdering each other. You can’t come to me crying ‘Please, stop this!’. You won’t even be able to see it!”","html":"“Is what I’m saying getting through to you? I’m going to turn everything you built against you, then spoil it. Once you’re gone from this world, I’m going to use what you made to win. And there’s nothing you can do about it because, in the end, you’re dead! You can’t do anything to stop your descendants from feuding and murdering each other. You can’t come to me crying ‘Please, stop this!’. You won’t even be able to see it!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch07-p0036","sourceIndex":36,"type":"narration","text":"While the Man-God’s gleeful spiel went on, I scratched my face, then while I was at it, I scratched the back of my head too. Not because I was itchy—I just wasn’t really sure how I was supposed to respond.","html":"While the Man-God’s gleeful spiel went on, I scratched my face, then while I was at it, I scratched the back of my head too. Not because I was itchy—I just wasn’t really sure how I was supposed to respond.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0037","sourceIndex":37,"type":"speech","text":"“You don’t say?” I said.","html":"“You don’t say?” I said. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch07-p0038","sourceIndex":38,"type":"speech","text":"“What the hell?!” he yelled, stamping his foot up and down. “Why the hell are you so smug?!”","html":"“What the hell?!” he yelled, stamping his foot up and down. “Why the hell are you so smug?!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","mixed":true,"speakerConfidence":"high"},{"id":"ch07-p0039","sourceIndex":39,"type":"speech","text":"“Probably because I’m dead,” I said promptly. The Man-God didn’t seem to know what to say to that.","html":"“Probably because I’m dead,” I said promptly. The Man-God didn’t seem to know what to say to that.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch07-p0040","sourceIndex":40,"type":"narration","text":"I closed my eyes and thought back on everything that had happened up until now. In this world, I’d done the things I wanted to do. I got married, and I made friends. I had children and lots of grandchildren. I even excelled at my job. True, it troubled me to hear the Man-God talking about the future, and there were things I thought I ought to have done better. But somehow, mysteriously, I had no regrets. No…maybe I ought to say I had no unfinished business. I was worried and anxious, but I didn’t feel the urge to do something about it. Hearing the Man-God talk now, I wasn’t filled with the need to find some way to resurrect myself and save my children.","html":"I closed my eyes and thought back on everything that had happened up until now. In this world, I’d done the things I wanted to do. I got married, and I made friends. I had children and lots of grandchildren. I even excelled at my job. True, it troubled me to hear the Man-God talking about the future, and there were things I thought I ought to have done better. But somehow, mysteriously, I had no regrets. No…maybe I ought to say I had no unfinished business. I was worried and anxious, but I didn’t feel the urge to do something about it. Hearing the Man-God talk now, I wasn’t filled with the need to find some way to resurrect myself and save my children.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0041","sourceIndex":41,"type":"narration","text":"If I had to guess, I’d say it’s because I thought all of them—kids and grandkids both—would work things out themselves from now on. Just as I’d done myself, I trusted the kids to apply themselves to whatever problems came at them and do their best to overcome them.","html":"If I had to guess, I’d say it’s because I thought all of them—kids and grandkids both—would work things out themselves from now on. Just as I’d done myself, I trusted the kids to apply themselves to whatever problems came at them and do their best to overcome them. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0042","sourceIndex":42,"type":"narration","text":"I slowly walked towards the Man-God. He was far smaller than I’d thought. Up until now, neither of us had gotten any closer to the other than was necessary, so I hadn’t had a good idea of his size.","html":"I slowly walked towards the Man-God. He was far smaller than I’d thought. Up until now, neither of us had gotten any closer to the other than was necessary, so I hadn’t had a good idea of his size.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0043","sourceIndex":43,"type":"speech","text":"“I’m content,” I said. I’d lived plenty. I wouldn’t say everything was perfect, and I’d surely left a few things undone. When I closed my eyes, not all the memories I saw were good. There were failures as well as successes, but even so, I wouldn’t have done it over. I was dead. My job was over, and I could hand over what came next to the living. It was crazy to feel this way when the guy in front of me was telling me he planned on doing them harm. But I couldn’t do anything about it. My heart was so at peace I could scarcely believe it.","html":"“I’m content,” I said. I’d lived plenty. I wouldn’t say everything was perfect, and I’d surely left a few things undone. When I closed my eyes, not all the memories I saw were good. There were failures as well as successes, but even so, I wouldn’t have done it over. I was dead. My job was over, and I could hand over what came next to the living. It was crazy to feel this way when the guy in front of me was telling me he planned on doing them harm. But I couldn’t do anything about it. My heart was so at peace I could scarcely believe it.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch07-p0044","sourceIndex":44,"type":"speech","text":"“Hey, Man-God?”","html":"“Hey, Man-God?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0045","sourceIndex":45,"type":"narration","text":"He didn’t say anything.","html":"He didn’t say anything.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0046","sourceIndex":46,"type":"speech","text":"“I’m pretty sure I tried to tell you this once.”","html":"“I’m pretty sure I tried to tell you this once.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0047","sourceIndex":47,"type":"speech","text":"“What,” he said finally.","html":"“What,” he said finally.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","mixed":true,"speakerConfidence":"high"},{"id":"ch07-p0048","sourceIndex":48,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch07-p0049","sourceIndex":49,"type":"speech","text":"“I don’t think I actually hated you that much.”","html":"“I don’t think I actually hated you that much.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0050","sourceIndex":50,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch07-p0051","sourceIndex":51,"type":"narration","text":"I think the Man-God looked sour.","html":"I think the Man-God looked sour. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0052","sourceIndex":52,"type":"narration","text":"Sure, maybe I only thought it because right at that moment, I was winning. Sylphie and Roxy were still alive, and our children were all healthy. Eris had died before me, but she’d reached the end of her life—it hadn’t been the Man-God’s fault. If some little thing had gone differently, I could have ended up hating the Man-God with every fiber of my being. I might have turned into a machine whose only purpose was killing the Man-God, like the me from the future. I doubt he was able to die feeling as peaceful as I did now. The person I was now was a result of how things had happened to turn out, nothing more.","html":"Sure, maybe I only thought it because right at that moment, I was winning. Sylphie and Roxy were still alive, and our children were all healthy. Eris had died before me, but she’d reached the end of her life—it hadn’t been the Man-God’s fault. If some little thing had gone differently, I could have ended up hating the Man-God with every fiber of my being. I might have turned into a machine whose only purpose was killing the Man-God, like the me from the future. I doubt he was able to die feeling as peaceful as I did now. The person I was now was a result of how things had happened to turn out, nothing more.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0053","sourceIndex":53,"type":"speech","text":"“What are you talking about?” the Man-God said.","html":"“What are you talking about?” the Man-God said.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","mixed":true,"speakerConfidence":"high"},{"id":"ch07-p0054","sourceIndex":54,"type":"speech","text":"“I don’t really know myself. But I think it’s thanks to you I’m able to feel so peaceful. If I hadn’t had such a clear enemy, I don’t think I’d be so content now.”","html":"“I don’t really know myself. But I think it’s thanks to you I’m able to feel so peaceful. If I hadn’t had such a clear enemy, I don’t think I’d be so content now.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0055","sourceIndex":55,"type":"narration","text":"Right. That was it. If not for the Man-God, I’d probably have started getting lazy around when I turned twenty.","html":"Right. That was it. If not for the Man-God, I’d probably have started getting lazy around when I turned twenty.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0056","sourceIndex":56,"type":"narration","text":"I’d have married Sylphie, worked reasonably hard, and tried a reasonable amount. I’d have come to the end of a reasonable life, feeling reasonably content, and then died. That would’ve been that. A life like that wouldn’t have been bad, in and of itself, but there’s no way it would have brought me the contentment I felt now. Even if I didn’t actually regret anything before I died, I might have wanted another chance, or to do something over, or to go back to some point in the past.","html":"I’d have married Sylphie, worked reasonably hard, and tried a reasonable amount. I’d have come to the end of a reasonable life, feeling reasonably content, and then died. That would’ve been that. A life like that wouldn’t have been bad, in and of itself, but there’s no way it would have brought me the contentment I felt now. Even if I didn’t actually regret anything before I died, I might have wanted another chance, or to do something over, or to go back to some point in the past. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0057","sourceIndex":57,"type":"narration","text":"It was only having a clear enemy and a clear goal that kept me moving to the end. That had turned me into the person I was now.","html":"It was only having a clear enemy and a clear goal that kept me moving to the end. That had turned me into the person I was now.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0058","sourceIndex":58,"type":"speech","text":"“Keep talking all you like,” the Man-God muttered. “I’m still not going to let them off easily.”","html":"“Keep talking all you like,” the Man-God muttered. “I’m still not going to let them off easily.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","mixed":true,"speakerConfidence":"high"},{"id":"ch07-p0059","sourceIndex":59,"type":"speech","text":"“Oh… I mean, um, that wasn’t why I said it…”","html":"“Oh… I mean, um, that wasn’t why I said it…”","className":"P_Prose_Formatting__And__Page_Break","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0060","sourceIndex":60,"type":"narration","text":"What was I trying to say? It wasn’t that there was anything I really wanted to say to the Man-God. Just because I didn’t hate him didn’t mean I particularly liked him. I obviously wasn’t planning on thanking him, either.","html":"What was I trying to say? It wasn’t that there was anything I really wanted to say to the Man-God. Just because I didn’t hate him didn’t mean I particularly liked him. I obviously wasn’t planning on thanking him, either.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0061","sourceIndex":61,"type":"narration","text":"With that, our conversation petered out and we stood there in silence. The atmosphere was unbearable.","html":"With that, our conversation petered out and we stood there in silence. The atmosphere was unbearable.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0062","sourceIndex":62,"type":"speech","text":"Then, suddenly, something occurred to me. “I wonder why I came to this world,” I said, trying out the words.","html":"Then, suddenly, something occurred to me. “I wonder why I came to this world,” I said, trying out the words.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch07-p0063","sourceIndex":63,"type":"speech","text":"“Like I know,” the Man-God muttered.","html":"“Like I know,” the Man-God muttered.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch07-p0064","sourceIndex":64,"type":"speech","text":"“You really don’t know anything about it?”","html":"“You really don’t know anything about it?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0065","sourceIndex":65,"type":"speech","text":"“If I’d known, I’d have stopped it. You genuinely came out of nowhere—so out of nowhere that even I didn’t notice until the Displacement Incident.”","html":"“If I’d known, I’d have stopped it. You genuinely came out of nowhere—so out of nowhere that even I didn’t notice until the Displacement Incident.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch07-p0066","sourceIndex":66,"type":"speech","text":"“Huh…”","html":"“Huh…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0067","sourceIndex":67,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch07-p0068","sourceIndex":68,"type":"narration","text":"In the end, we never got to the bottom of the Displacement Incident during my lifetime either. Nanahoshi had come up with a weird hypothesis, and something else might happen in the future…","html":"In the end, we never got to the bottom of the Displacement Incident during my lifetime either. Nanahoshi had come up with a weird hypothesis, and something else might happen in the future…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0069","sourceIndex":69,"type":"speech","text":"“If someone out there deliberately reincarnated me, thank them for me.”","html":"“If someone out there deliberately reincarnated me, thank them for me.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0070","sourceIndex":70,"type":"speech","text":"“No way.”","html":"“No way.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","speakerConfidence":"high"},{"id":"ch07-p0071","sourceIndex":71,"type":"speech","text":"“Yeah, figures.” He’d turned me down flat. Ah, well. The Man-God probably had a lot of bitterness he was dying to vent.","html":"“Yeah, figures.” He’d turned me down flat. Ah, well. The Man-God probably had a lot of bitterness he was dying to vent.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","mixed":true,"speakerConfidence":"high"},{"id":"ch07-p0072","sourceIndex":72,"type":"speech","text":"“So, what happens to me next? I mean, I know I died.”","html":"“So, what happens to me next? I mean, I know I died.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0073","sourceIndex":73,"type":"speech","text":"“Yeah, about that.” The Man-God looked at me, still irritated. “Normally, your soul would turn back into mana, mix with other mana, and be reconstituted into something else. But you’re from another world, so I don’t know what happens in your case.”","html":"“Yeah, about that.” The Man-God looked at me, still irritated. “Normally, your soul would turn back into mana, mix with other mana, and be reconstituted into something else. But you’re from another world, so I don’t know what happens in your case.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Perugius","mixed":true,"speakerConfidence":"high"},{"id":"ch07-p0074","sourceIndex":74,"type":"speech","text":"“Right.”","html":"“Right.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0075","sourceIndex":75,"type":"narration","text":"I’d thought maybe I’d be able to see Paul and Geese again after I died, but I guess not. It made sense, but I was still disappointed… Oh, well. My bones should’ve been buried in the same place. I’d have to be content with that.","html":"I’d thought maybe I’d be able to see Paul and Geese again after I died, but I guess not. It made sense, but I was still disappointed… Oh, well. My bones should’ve been buried in the same place. I’d have to be content with that.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0076","sourceIndex":76,"type":"silence","text":"…","html":"…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0077","sourceIndex":77,"type":"narration","text":"I noticed my body was slowly fading. Was this what turning back into mana looked like? This must be how death worked in this world. Perhaps, right before they died, the other residents of this world came to this white room too. Only, if the Man-God didn’t feel like seeing them, they’d just wait here to fade away. In that sense, he was a bit like Yama, the God who judged you after death. This guy showed up when people died to smirk and mock them about their lives, though…so a nasty Yama.","html":"I noticed my body was slowly fading. Was this what turning back into mana looked like? This must be how death worked in this world. Perhaps, right before they died, the other residents of this world came to this white room too. Only, if the Man-God didn’t feel like seeing them, they’d just wait here to fade away. In that sense, he was a bit like Yama, the God who judged you after death. This guy showed up when people died to smirk and mock them about their lives, though…so a nasty Yama.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0078","sourceIndex":78,"type":"speech","text":"“Ugh…”","html":"“Ugh…”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0079","sourceIndex":79,"type":"narration","text":"The Man-God wasn’t sporting his usual smirk. He was actually tapping his foot as though he couldn’t disguise his annoyance. He’d wanted to gloat to me about his victory and see me consumed by regret as I faded away, and he was pissed off because I’d shrugged him off.","html":"The Man-God wasn’t sporting his usual smirk. He was actually tapping his foot as though he couldn’t disguise his annoyance. He’d wanted to gloat to me about his victory and see me consumed by regret as I faded away, and he was pissed off because I’d shrugged him off.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0080","sourceIndex":80,"type":"narration","text":"He really was a piece of work.","html":"He really was a piece of work.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0081","sourceIndex":81,"type":"speech","text":"I stood in front of him. “Look, maybe this isn’t for me to say,” I began. I vaguely put a hand on his shoulder. “But give it your all, okay?”","html":"I stood in front of him. “Look, maybe this isn’t for me to say,” I began. I vaguely put a hand on his shoulder. “But give it your all, okay?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","mixed":true,"speakerConfidence":"high"},{"id":"ch07-p0082","sourceIndex":82,"type":"narration","text":"Is he going to get mad… I thought. But the Man-God only sighed and slumped his shoulders. Then, he fell silent.","html":"Is he going to get mad… I thought. But the Man-God only sighed and slumped his shoulders. Then, he fell silent.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0083","sourceIndex":83,"type":"narration","text":"As I looked down at him, I cast an eye over our surroundings. It was pure white, as usual. And empty. My body was on the verge of disappearing entirely, and little by little, my consciousness was fading too. Maybe I’d go back to my old world. Maybe I’d become something else in this world. Maybe I’d keep my memories. Maybe I wouldn’t. I didn’t know what would happen, but whatever it was, I didn’t mind. Even if my mind and memories remained, even if I was born into a place a million times worse than my former life, I’d be all right.","html":"As I looked down at him, I cast an eye over our surroundings. It was pure white, as usual. And empty. My body was on the verge of disappearing entirely, and little by little, my consciousness was fading too. Maybe I’d go back to my old world. Maybe I’d become something else in this world. Maybe I’d keep my memories. Maybe I wouldn’t. I didn’t know what would happen, but whatever it was, I didn’t mind. Even if my mind and memories remained, even if I was born into a place a million times worse than my former life, I’d be all right.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0084","sourceIndex":84,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch07-p0085","sourceIndex":85,"type":"speech","text":"“See you around.”","html":"“See you around.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","speakerConfidence":"high"},{"id":"ch07-p0086","sourceIndex":86,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch07-p0087","sourceIndex":87,"type":"narration","text":"Those were my last words. As my consciousness slipped away, I passed the Man-God and started to walk. I went on straight ahead and didn’t turn back…","html":"Those were my last words. As my consciousness slipped away, I passed the Man-God and started to walk. I went on straight ahead and didn’t turn back…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch07-p0088","sourceIndex":88,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch07-p0089","sourceIndex":89,"type":"narration","text":"The End","html":"<strong>The End</strong>","className":"P_TEXTBODY_CENTERALIGN","italic":false,"bold":true,"dropCap":false}],"wordCount":2095,"speechCount":49,"speakers":["Perugius","Rudeus"]}],"images":[{"id":"ch07-img01","type":"image","src":"INTERIORIMAGES_10.jpg","alt":""}],"sequence":7,"cast":["Perugius","Rudeus"],"sceneCount":1,"speechCount":49,"speakers":["Perugius","Rudeus"]},{"id":"ch08","number":"appendix","title":"Appendix: The Asuran Kingdom's Dossier on Rudeus Greyrat","pov":"Rudeus","kind":"appendix","wordCount":4180,"scenes":[{"id":"ch08-s01","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The Royal Asuran Archive, 485 Armored Dragon Era","cast":["Jed Bluewolf","Rudeus"],"blocks":[{"id":"ch08-p0002","sourceIndex":2,"type":"narration","text":"THE SUBJECT RUDEUS GREYRAT is extremely famous. Today, his name is inscribed in the histories of every nation on the map. Many researchers will have had the experience of casually glancing at letters or an artifact only to realize they were signed “Rudeus Greyrat.” Whether in a corner of the teleportation circles drawn in all the nations of the world, in the appendices of the new editions of the magic textbook, or on the side of a bridge on a road, his name appears everywhere. Those alive today who have encountered his name likely outnumber those who haven’t.","html":"THE SUBJECT RUDEUS GREYRAT is extremely famous. Today, his name is inscribed in the histories of every nation on the map. Many researchers will have had the experience of casually glancing at letters or an artifact only to realize they were signed “Rudeus Greyrat.” Whether in a corner of the teleportation circles drawn in all the nations of the world, in the appendices of the new editions of the magic textbook, or on the side of a bridge on a road, his name appears everywhere. Those alive today who have encountered his name likely outnumber those who haven’t.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0003","sourceIndex":3,"type":"narration","text":"However, many would be at a loss to describe what he truly did.","html":"However, many would be at a loss to describe what he truly did. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0004","sourceIndex":4,"type":"narration","text":"Some might recognize him as “the greatest magician of the 400s, Armored Dragon Era.” Others might know him as “an academic genius who turned formal education on its head,” or “an intellectual who had a transformative influence on the culture around toys and figurines.”","html":"Some might recognize him as “the greatest magician of the 400s, Armored Dragon Era.” Others might know him as “an academic genius who turned formal education on its head,” or “an intellectual who had a transformative influence on the culture around toys and figurines.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0005","sourceIndex":5,"type":"narration","text":"Even then, there are very few records of what he began and what he left behind. In each field, other names come to mind before his: in magic, Silent Sevenstar; in education, Roxy M. Greyrat; and in art, Zanoba Shirone. Because of this, some believe that he was “a hanger-on whose only talent was brownnosing the powerful,” while others call him “a con artist who cozied up to those with talent in order to steal their glory.”","html":"Even then, there are very few records of what he began and what he left behind. In each field, other names come to mind before his: in magic, Silent Sevenstar; in education, Roxy M. Greyrat; and in art, Zanoba Shirone. Because of this, some believe that he was “a hanger-on whose only talent was brownnosing the powerful,” while others call him “a con artist who cozied up to those with talent in order to steal their glory.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0006","sourceIndex":6,"type":"narration","text":"Some even claim that “There was no one person named Rudeus Greyrat. Rather, it was a title bestowed upon members of Ruquag’s Mercenary Band for a great accomplishment. Thus, multiple people bear the name.”","html":"Some even claim that “There was no one person named Rudeus Greyrat. Rather, it was a title bestowed upon members of Ruquag’s Mercenary Band for a great accomplishment. Thus, multiple people bear the name.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0007","sourceIndex":7,"type":"narration","text":"Theories abound about Rudeus Greyrat, but one thing is certain—that whatever it was he achieved changed the world. As time goes on, that knowledge will fade into the dark corners of history without any one deed truly ascribed to him. To let this mystery fade would be to lose knowledge of historical importance. And so, it is my intention to create an entry in the archive compiling the evidence of the life and existence of Rudeus Greyrat.","html":"Theories abound about Rudeus Greyrat, but one thing is certain—that whatever it was he achieved changed the world. As time goes on, that knowledge will fade into the dark corners of history without any one deed truly ascribed to him. To let this mystery fade would be to lose knowledge of historical importance. And so, it is my intention to create an entry in the archive compiling the evidence of the life and existence of Rudeus Greyrat.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0008","sourceIndex":8,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0009","sourceIndex":9,"type":"narration","text":"—485 Armored Dragon Era Head Archivist Jed Bluewolf of the Royal Asuran Archive","html":"—485 Armored Dragon Era Head Archivist <br/>Jed Bluewolf of the Royal Asuran Archive","className":"P_Prose_Formatting__And__Right_Alignment","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0010","sourceIndex":10,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":356,"speechCount":0,"speakers":[]},{"id":"ch08-s02","pov":"Rudeus","povHeader":null,"sceneHeader":"Rudeus Greyrat","location":"The Royal Asuran Archive, the dossier on Rudeus Greyrat","cast":["Archivist","Ariel","Clule Elrond","Orsted","Paul","Perugius","Rudeus"],"blocks":[{"id":"ch08-p0012","sourceIndex":12,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0013","sourceIndex":13,"type":"narration","text":"Summary","html":"<strong>Summary</strong>","className":"P_TEXTBODY_CENTERALIGN","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0014","sourceIndex":14,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0015","sourceIndex":15,"type":"narration","text":"Rudeus Greyrat (407-481 Armored Dragon Era) was a magician from the Kingdom of Ranoa. In 430, he joined the ranks of the Seven Great Powers. He was one of the great magicians of the 400s, alongside Roxy M. Greyrat and Silent Sevenstar. He also went by the aliases “Quagmire,” “the Dragon God’s Right Hand,” “the Magician King,” “the Great Magician,” and the “silent caster” among others. On the other hand, his cowardice in battle also led to him being given such names “spineless,” “groveler,” “yellowbelly,” and “the frightened rabbit.” In his later years, his many epithets led to his title “Seven-Named Rudeus.”","html":"Rudeus Greyrat (407-481 Armored Dragon Era) was a magician from the Kingdom of Ranoa. In 430, he joined the ranks of the Seven Great Powers. He was one of the great magicians of the 400s, alongside Roxy M. Greyrat and Silent Sevenstar. He also went by the aliases “Quagmire,” “the Dragon God’s Right Hand,” “the Magician King,” “the Great Magician,” and the “silent caster” among others. On the other hand, his cowardice in battle also led to him being given such names “spineless,” “groveler,” “yellowbelly,” and “the frightened rabbit.” In his later years, his many epithets led to his title “Seven-Named Rudeus.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0016","sourceIndex":16,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0017","sourceIndex":17,"type":"narration","text":"Life","html":"<strong>Life</strong>","className":"P_TEXTBODY_CENTERALIGN","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0018","sourceIndex":18,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0019","sourceIndex":19,"type":"narration","text":"YOUTH","html":"<strong>YOUTH</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0020","sourceIndex":20,"type":"narration","text":"Rudeus Greyrat was born in 407 in the village of Buena in Fittoa, Asura, the eldest son of the low-ranking Asuran knight Paul (388–413) and the former adventurer-turned-healer Zenith (390–459). The young Rudeus is said to have used intermediate-level magic around the age of three. His father, recognizing his son’s potential, hired Roxy Migurdia (373–) to tutor him. As a result of her spartan education regimen, he became a Saint-tier water magician at the age of five. Rudeus would go on to display talent surpassing that of his teacher, but he would continue to hold her in high regard until his death. At the age of seven, the Boreas Greyrats, the governors of Fittoa at the time, took notice of his talent and asked him to come to them as a tutor. There, he taught magic to Eris Boreas Greyrat (later known as Mad Sword King Eris) while also taking up the creation of figurines using earth magic.","html":"Rudeus Greyrat was born in 407 in the village of Buena in Fittoa, Asura, the eldest son of the low-ranking Asuran knight Paul (388–413) and the former adventurer-turned-healer Zenith (390–459). The young Rudeus is said to have used intermediate-level magic around the age of three. His father, recognizing his son’s potential, hired Roxy Migurdia (373–) to tutor him. As a result of her spartan education regimen, he became a Saint-tier water magician at the age of five. Rudeus would go on to display talent surpassing that of his teacher, but he would continue to hold her in high regard until his death. At the age of seven, the Boreas Greyrats, the governors of Fittoa at the time, took notice of his talent and asked him to come to them as a tutor. There, he taught magic to Eris Boreas Greyrat (later known as Mad Sword King Eris) while also taking up the creation of figurines using earth magic. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0021","sourceIndex":21,"type":"narration","text":"Despite possessing talent that set him apart from other children, Rudeus is said to have cried over missing his parents when they did not visit even on his tenth birthday, as one would expect from a child his age.","html":"Despite possessing talent that set him apart from other children, Rudeus is said to have cried over missing his parents when they did not visit even on his tenth birthday, as one would expect from a child his age.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0022","sourceIndex":22,"type":"narration","text":"In the Displacement Incident of 417, he and Eris were transported to the Biegoya Region of the Demon Continent. It was there that he befriended Ruijerd Superdia, at the time known and feared under the epithet “Dead End.” As an adventurer, he embarked on a journey from the Demon Continent back to Fittoa in Asura on the Central Continent. It was at this time he first met Zanoba Shirone and Cliff Grimor, who were to become his lifelong friends. In his thirteenth year, he saw Eris back to Fittoa, then set off for the north of the Central Continent to search for his missing family. This was when he made a name for himself as the adventurer Rudeus “Quagmire” Greyrat.","html":"In the Displacement Incident of 417, he and Eris were transported to the Biegoya Region of the Demon Continent. It was there that he befriended Ruijerd Superdia, at the time known and feared under the epithet “Dead End.” As an adventurer, he embarked on a journey from the Demon Continent back to Fittoa in Asura on the Central Continent. It was at this time he first met Zanoba Shirone and Cliff Grimor, who were to become his lifelong friends. In his thirteenth year, he saw Eris back to Fittoa, then set off for the north of the Central Continent to search for his missing family. This was when he made a name for himself as the adventurer Rudeus “Quagmire” Greyrat.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0023","sourceIndex":23,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0024","sourceIndex":24,"type":"narration","text":"STUDENT YEARS","html":"<strong>STUDENT YEARS</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0025","sourceIndex":25,"type":"narration","text":"In 422, Rudeus moved to the Magic City of Sharia in Ranoa, where he entered the Magic University on the recommendation of Jenius Halfas. There, he outshone Linia Dedoldia, Pursena Adoldia, Silent Sevenstar, and Immortal Demon King Badigadi and earned a reputation as the greatest magician at the university. The following year, a sixteen-year-old Rudeus married the magician guardian of Ariel Anemoi Asura, Sylphiette, after a long period of courtship. It is at this point that he seems to have put down roots in Sharia and decided to spend the rest of his days there.","html":"In 422, Rudeus moved to the Magic City of Sharia in Ranoa, where he entered the Magic University on the recommendation of Jenius Halfas. There, he outshone Linia Dedoldia, Pursena Adoldia, Silent Sevenstar, and Immortal Demon King Badigadi and earned a reputation as the greatest magician at the university. The following year, a sixteen-year-old Rudeus married the magician guardian of Ariel Anemoi Asura, Sylphiette, after a long period of courtship. It is at this point that he seems to have put down roots in Sharia and decided to spend the rest of his days there. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0026","sourceIndex":26,"type":"narration","text":"That same year he received word from his father Paul that his mother Zenith had been found on the Begaritt continent, and so he traveled there. With Paul and Silent Sevenstar’s aid, he was able to use a teleportation circle that had miraculously survived to make the journey. Together with Paul, Elinalise Dragonroad, Talhand, Geese, and Roxy Migurdia, he braved and defeated the Teleportation Labyrinth. In the battle with the Manatite Hydra, the guardian of the labyrinth, Paul was killed. Although he rescued his Zenith, the Displacement Incident had left her in a mindless state. Rudeus was plunged into the depths of depression. It was his teacher, Roxy Migurdia, who saved him. This is how Rudeus came to take her as his second wife.","html":"That same year he received word from his father Paul that his mother Zenith had been found on the Begaritt continent, and so he traveled there. With Paul and Silent Sevenstar’s aid, he was able to use a teleportation circle that had miraculously survived to make the journey. Together with Paul, Elinalise Dragonroad, Talhand, Geese, and Roxy Migurdia, he braved and defeated the Teleportation Labyrinth. In the battle with the Manatite Hydra, the guardian of the labyrinth, Paul was killed. Although he rescued his Zenith, the Displacement Incident had left her in a mindless state. Rudeus was plunged into the depths of depression. It was his teacher, Roxy Migurdia, who saved him. This is how Rudeus came to take her as his second wife.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0027","sourceIndex":27,"type":"narration","text":"In 415, Rudeus and Eris Boreas Greyrat fought Dragon God Orsted in a forest on the outskirts of Sharia. The reason for the battle is unknown, but some theorize that Dragon God Orsted meant harm to Ariel Anemoi Asura, and Rudeus was acting to protect her. After this battle, Eris Boreas Greyrat became his third wife. In the same year, Rudeus fought in the Asuran civil war on the side of Ariel Anemoi Asura. He did battle with North Emperor Auber Corbet, North King Wi Taa, and Water God Reida and defeated them, for which he was called the architect of Ariel Anemoi Asura’s ascension to the throne.","html":"In 415, Rudeus and Eris Boreas Greyrat fought Dragon God Orsted in a forest on the outskirts of Sharia. The reason for the battle is unknown, but some theorize that Dragon God Orsted meant harm to Ariel Anemoi Asura, and Rudeus was acting to protect her. After this battle, Eris Boreas Greyrat became his third wife. In the same year, Rudeus fought in the Asuran civil war on the side of Ariel Anemoi Asura. He did battle with North Emperor Auber Corbet, North King Wi Taa, and Water God Reida and defeated them, for which he was called the architect of Ariel Anemoi Asura’s ascension to the throne.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0028","sourceIndex":28,"type":"narration","text":"Rudeus established Ruquag’s Mercenary Band in the Magic City of Sharia in 417. Though he took the role of chairman, he is believed to have delegated all actual running of the Company to his younger sister Aisha.","html":"Rudeus established Ruquag’s Mercenary Band in the Magic City of Sharia in 417. Though he took the role of chairman, he is believed to have delegated all actual running of the Company to his younger sister Aisha.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0029","sourceIndex":29,"type":"narration","text":"In his twentieth year, he and Zanoba Shirone allied themselves with Pax Shirone to fight in the Shirone Kingdom’s war of defense. They engaged the enemy force from the north at Fort Karon. Rudeus is said to have killed over ten thousand people in this battle. Following his graduation from the Magic University in 419, he journeyed to the Holy Country of Millis with Cliff Grimor.","html":"In his twentieth year, he and Zanoba Shirone allied themselves with Pax Shirone to fight in the Shirone Kingdom’s war of defense. They engaged the enemy force from the north at Fort Karon. Rudeus is said to have killed over ten thousand people in this battle. Following his graduation from the Magic University in 419, he journeyed to the Holy Country of Millis with Cliff Grimor.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0030","sourceIndex":30,"type":"narration","text":"While there is no detailed account of that time, he is believed to have applied himself to deepening his friendship with the Blessed Child, as well as to appointing Cliff Grimor to a position of importance in the Millis Church.","html":"While there is no detailed account of that time, he is believed to have applied himself to deepening his friendship with the Blessed Child, as well as to appointing Cliff Grimor to a position of importance in the Millis Church. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0031","sourceIndex":31,"type":"narration","text":"In 430, he fought alongside Dragon God Orsted in the Biheiril Kingdom. In the course of that battle, he overcame North God Kalman III and so became one of the Seven Great Powers.","html":"In 430, he fought alongside Dragon God Orsted in the Biheiril Kingdom. In the course of that battle, he overcame North God Kalman III and so became one of the Seven Great Powers. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0032","sourceIndex":32,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0033","sourceIndex":33,"type":"narration","text":"YEARS IN THE SEVEN GREAT POWERS","html":"<strong>YEARS IN THE SEVEN GREAT POWERS</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0034","sourceIndex":34,"type":"narration","text":"Following his ascension to the Seven Great Powers, Rudeus ceases to appear at the center of events. This may account for why, in the present, he enjoys less recognition than other great names of the same generation: Silent Sevenstar, the Witch Nanahoshi who stepped into the spotlight more or less as Rudeus stepped out, and Roxy M. Greyrat, who later became headmistress of the Magic University. Both are more widely known.","html":"Following his ascension to the Seven Great Powers, Rudeus ceases to appear at the center of events. This may account for why, in the present, he enjoys less recognition than other great names of the same generation: Silent Sevenstar, the Witch Nanahoshi who stepped into the spotlight more or less as Rudeus stepped out, and Roxy M. Greyrat, who later became headmistress of the Magic University. Both are more widely known.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0035","sourceIndex":35,"type":"narration","text":"Because of this, few are aware that he was one of the Seven Great Powers. It has been proposed that Rudeus died in the Biheiril Battle, and the one who appeared afterward was a body double, or that it was only a name. As records remain of his involvement in the establishment of Ariel National University, these theories can be immediately discounted.","html":"Because of this, few are aware that he was one of the Seven Great Powers. It has been proposed that Rudeus died in the Biheiril Battle, and the one who appeared afterward was a body double, or that it was only a name. As records remain of his involvement in the establishment of Ariel National University, these theories can be immediately discounted. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0036","sourceIndex":36,"type":"narration","text":"It is unknown what Rudeus was trying to achieve by stepping out of the public eye. Sources indicate that, as a follower of the Dragon God, he enjoyed the friendship of figurine-maker and president of the Doll Making Company Zanoba Shirone, Pope Cliff Grimor of the Millis Church, the Blessed Child of the Millis Church, Queen Ariel Anemoi Asura of Asura, Death God Randolph of the King Dragon Kingdom, the Doldias of the Great Forest, and Immortal Demon King Atofe of the Demon Continent. It is believed that he was attempting to bring the world under one banner in preparation for the resurrection of Laplace eighty years hence.","html":"It is unknown what Rudeus was trying to achieve by stepping out of the public eye. Sources indicate that, as a follower of the Dragon God, he enjoyed the friendship of figurine-maker and president of the Doll Making Company Zanoba Shirone, Pope Cliff Grimor of the Millis Church, the Blessed Child of the Millis Church, Queen Ariel Anemoi Asura of Asura, Death God Randolph of the King Dragon Kingdom, the Doldias of the Great Forest, and Immortal Demon King Atofe of the Demon Continent. It is believed that he was attempting to bring the world under one banner in preparation for the resurrection of Laplace eighty years hence.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0037","sourceIndex":37,"type":"narration","text":"Other sources call him a paragon of wickedness who resurrected the forbidden teleportation circles as part of a plot to use their expediency to achieve world domination.","html":"Other sources call him a paragon of wickedness who resurrected the forbidden teleportation circles as part of a plot to use their expediency to achieve world domination.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0038","sourceIndex":38,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0039","sourceIndex":39,"type":"narration","text":"DEATH","html":"<strong>DEATH</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0040","sourceIndex":40,"type":"narration","text":"Rudeus’s wife, Sylphiette Greyrat, announced his death from old age in 481. He passed away peacefully in his bed at the age of seventy-four. An extraordinary five thousand people came rushing in to attend his funeral. Also present, after disappearing even more completely than all but Rudeus himself, was Dragon God Orsted.","html":"Rudeus’s wife, Sylphiette Greyrat, announced his death from old age in 481. He passed away peacefully in his bed at the age of seventy-four. An extraordinary five thousand people came rushing in to attend his funeral. Also present, after disappearing even more completely than all but Rudeus himself, was Dragon God Orsted.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0041","sourceIndex":41,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0042","sourceIndex":42,"type":"narration","text":"Equipment","html":"<strong>Equipment</strong>","className":"P_TEXTBODY_CENTERALIGN","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0043","sourceIndex":43,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0044","sourceIndex":44,"type":"narration","text":"Magicians usually bear a staff and favor suppression attacks at long range. Rudeus, however, engaged in close range combat.","html":"Magicians usually bear a staff and favor suppression attacks at long range. Rudeus, however, engaged in close range combat.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0045","sourceIndex":45,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0046","sourceIndex":46,"type":"narration","text":"AQUA HEARTIA","html":"<strong>AQUA HEARTIA</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0047","sourceIndex":47,"type":"narration","text":"A staff given to him by the Boreas family on his tenth birthday. It was made from the arm of an Elder Treant, native to the eastern reaches of the Great Forest on the Millis Continent. Its magic stone was an ultramarine blue water stone, an A-rank item from a wandering Sea Dragon in the north of the Begaritt Continent.","html":"A staff given to him by the Boreas family on his tenth birthday. It was made from the arm of an Elder Treant, native to the eastern reaches of the Great Forest on the Millis Continent. Its magic stone was an ultramarine blue water stone, an A-rank item from a wandering Sea Dragon in the north of the Begaritt Continent. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0048","sourceIndex":48,"type":"narration","text":"The staff was made by Rod Director Chein Procyon. Although extremely powerful, Rudeus ceased to use it after the completion of the Magic Armor (see below).","html":"The staff was made by Rod Director Chein Procyon. Although extremely powerful, Rudeus ceased to use it after the completion of the Magic Armor (see below).","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0049","sourceIndex":49,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0050","sourceIndex":50,"type":"narration","text":"MAGIC ARMOR VERSION ONE","html":"<strong>MAGIC ARMOR VERSION ONE</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0051","sourceIndex":51,"type":"narration","text":"A prototype set of magic armor crafted with the assistance of Zanoba Shirone and Cliff Grimor. It stood around three meters tall. A Stone Cannon Gatling gun was mounted on its right arm and it bore a shield and stone of absorption in the left. While it consumed vast amounts of mana, it is believed to have possessed offensive and defensive capabilities on a level with the Seven Great Powers. Rudeus built it to fight Dragon God Orsted, then continued to make use of it after allying with his would-be enemy. However, it was destroyed by the Fighting God in the Battle of Biheiril.","html":"A prototype set of magic armor crafted with the assistance of Zanoba Shirone and Cliff Grimor. It stood around three meters tall. A Stone Cannon Gatling gun was mounted on its right arm and it bore a shield and stone of absorption in the left. While it consumed vast amounts of mana, it is believed to have possessed offensive and defensive capabilities on a level with the Seven Great Powers. Rudeus built it to fight Dragon God Orsted, then continued to make use of it after allying with his would-be enemy. However, it was destroyed by the Fighting God in the Battle of Biheiril.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0052","sourceIndex":52,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0053","sourceIndex":53,"type":"narration","text":"MAGIC ARMOR VERSION TWO","html":"<strong>MAGIC ARMOR VERSION TWO</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0054","sourceIndex":54,"type":"narration","text":"A jet-black set of armor composed of arm, leg, and body parts. A detuned model of the Version One. This armor gives the wearer the abilities of a Saint-tier sword fighter.","html":"A jet-black set of armor composed of arm, leg, and body parts. A detuned model of the Version One. This armor gives the wearer the abilities of a Saint-tier sword fighter. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0055","sourceIndex":55,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0056","sourceIndex":56,"type":"narration","text":"MAGIC ARMOR VERSION ZERO","html":"<strong>MAGIC ARMOR VERSION ZERO</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0057","sourceIndex":57,"type":"narration","text":"Rudeus’s ultimate weapon that was used in the Battle of Biheiril. Details unknown.","html":"Rudeus’s ultimate weapon that was used in the Battle of Biheiril. Details unknown.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0058","sourceIndex":58,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0059","sourceIndex":59,"type":"narration","text":"MAGIC ARMOR VERSION THREE","html":"<strong>MAGIC ARMOR VERSION THREE</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0060","sourceIndex":60,"type":"narration","text":"The Magic Armor used by Rudeus in his later years. Standing around two meters tall, it possessed the same functionality as the Version One. The General Purpose Magic Armor Series that came later is said to have been based on the Version Three.","html":"The Magic Armor used by Rudeus in his later years. Standing around two meters tall, it possessed the same functionality as the Version One. The General Purpose Magic Armor Series that came later is said to have been based on the Version Three.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0061","sourceIndex":61,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0062","sourceIndex":62,"type":"narration","text":"STONE CANNON GATLING GUN","html":"<strong>STONE CANNON GATLING GUN</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0063","sourceIndex":63,"type":"narration","text":"A bundle of staff-type magical implements that fire stone cannons without regard for mana expenditure. When activated, the Gatling gun fires off stone cannons at a tremendous rate, consuming so much mana that any ordinary person would be drained to zero in moments. It was created by Magical Implement Director Jacqueline of the Ranoa Kingdom.","html":"A bundle of staff-type magical implements that fire stone cannons without regard for mana expenditure. When activated, the Gatling gun fires off stone cannons at a tremendous rate, consuming so much mana that any ordinary person would be drained to zero in moments. It was created by Magical Implement Director Jacqueline of the Ranoa Kingdom.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0064","sourceIndex":64,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0065","sourceIndex":65,"type":"narration","text":"STONE CANNON SHOTGUN","html":"<strong>STONE CANNON SHOTGUN</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0066","sourceIndex":66,"type":"narration","text":"A version of the Gatling gun above configured to shoot twelve times in a single burst. It was created by Magical Implement Director Jacqueline of the Ranoa Kingdom.","html":"A version of the Gatling gun above configured to shoot twelve times in a single burst. It was created by Magical Implement Director Jacqueline of the Ranoa Kingdom.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0067","sourceIndex":67,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0068","sourceIndex":68,"type":"narration","text":"PAUL’S SWORD","html":"<strong>PAUL’S SWORD</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0069","sourceIndex":69,"type":"narration","text":"A magic item that cuts better the harder its target. This is the most famous of Paul’s swords, though as an adventurer, he favored a different weapon.","html":"A magic item that cuts better the harder its target. This is the most famous of Paul’s swords, though as an adventurer, he favored a different weapon.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0070","sourceIndex":70,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0071","sourceIndex":71,"type":"narration","text":"Spells","html":"<strong>Spells</strong>","className":"P_TEXTBODY_CENTERALIGN","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0072","sourceIndex":72,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0073","sourceIndex":73,"type":"narration","text":"Rudeus was proficient in all schools of magic. As one might guess from the name Quagmire, he particularly favored earth and water magic.","html":"Rudeus was proficient in all schools of magic. As one might guess from the name Quagmire, he particularly favored earth and water magic.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0074","sourceIndex":74,"type":"narration","text":"Rudeus is said to have utilized a wide range of spells depending on his opponent, so here I shall list the most common ones.","html":"Rudeus is said to have utilized a wide range of spells depending on his opponent, so here I shall list the most common ones.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0075","sourceIndex":75,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0076","sourceIndex":76,"type":"narration","text":"STONE CANNON","html":"<strong>STONE CANNON</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0077","sourceIndex":77,"type":"narration","text":"A well-known Intermediate-level spell. It shoots a chunk of rock at high speed at one’s opponent. However, when Rudeus used the spell with unvoiced casting, it carried enough power to disintegrate an immortal demon king. He also used variations including Blast Cannon and Stone Shot.","html":"A well-known Intermediate-level spell. It shoots a chunk of rock at high speed at one’s opponent. However, when Rudeus used the spell with unvoiced casting, it carried enough power to disintegrate an immortal demon king. He also used variations including Blast Cannon and Stone Shot.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0078","sourceIndex":78,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0079","sourceIndex":79,"type":"narration","text":"QUAGMIRE","html":"<strong>Q</strong><strong>UAGMIRE</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0080","sourceIndex":80,"type":"narration","text":"An example of Rudeus’s patented combination magic. Rudeus is supposed to have been able to conjure a quagmire large enough to submerge an entire town.","html":"An example of Rudeus’s patented combination magic. Rudeus is supposed to have been able to conjure a quagmire large enough to submerge an entire town.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0081","sourceIndex":81,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0082","sourceIndex":82,"type":"narration","text":"DEEP MIST","html":"<strong>DEEP MIST</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0083","sourceIndex":83,"type":"narration","text":"Another example (as above) of Rudeus’s combination magic. It is said he could conjure enough mist to conceal an entire forest.","html":"Another example (as above) of Rudeus’s combination magic. It is said he could conjure enough mist to conceal an entire forest.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0084","sourceIndex":84,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0085","sourceIndex":85,"type":"narration","text":"ELECTRIC","html":"<strong>ELECTRIC</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0086","sourceIndex":86,"type":"narration","text":"Rudeus’s original spell, condensing the King-tier water magic Lightning. By using this spell in close combat, Rudeus was able to neutralize an immortal demon king in a single hit.","html":"Rudeus’s original spell, condensing the King-tier water magic Lightning. By using this spell in close combat, Rudeus was able to neutralize an immortal demon king in a single hit.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0087","sourceIndex":87,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0088","sourceIndex":88,"type":"narration","text":"SHOCK WAVE","html":"<strong>SHOCK WAVE</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0089","sourceIndex":89,"type":"narration","text":"A wind spell that creates a pulse in the air to send one’s opponent flying. Rudeus allegedly used this spell in close combat to fight as though he were flying.","html":"A wind spell that creates a pulse in the air to send one’s opponent flying. Rudeus allegedly used this spell in close combat to fight as though he were flying.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0090","sourceIndex":90,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0091","sourceIndex":91,"type":"narration","text":"Research","html":"<strong>Research</strong>","className":"P_TEXTBODY_CENTERALIGN","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0092","sourceIndex":92,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0093","sourceIndex":93,"type":"narration","text":"Over the course of his life, Rudeus researched and developed many spells and magical implements. He also funded a range of different research fields.","html":"Over the course of his life, Rudeus researched and developed many spells and magical implements. He also funded a range of different research fields.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0094","sourceIndex":94,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0095","sourceIndex":95,"type":"narration","text":"A LEARNING METHOD FOR UNVOICED MAGIC","html":"<strong>A LEARNING METHOD FOR UNVOICED MAGIC</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0096","sourceIndex":96,"type":"narration","text":"Rudeus Greyrat was said to have used voiceless magic from a young age. His teacher, Roxy M. Greyrat, wrote up his method for voiceless magic as a paper, developing a didactic method for the skill. This method was enthusiastically implemented by the three great magic universities into their magical education programs, contributing to the emergence of many talented magicians.","html":"Rudeus Greyrat was said to have used voiceless magic from a young age. His teacher, Roxy M. Greyrat, wrote up his method for voiceless magic as a paper, developing a didactic method for the skill. This method was enthusiastically implemented by the three great magic universities into their magical education programs, contributing to the emergence of many talented magicians.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0097","sourceIndex":97,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0098","sourceIndex":98,"type":"narration","text":"MANA RECOVERY THERAPY (MAGIC POTION)","html":"<strong>MANA RECOVERY THERAPY (MAGIC POTION)</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0099","sourceIndex":99,"type":"narration","text":"With funding from Rudeus, Silent Sevenstar developed a drink that restores mana. This so-called magic potion unshackled magicians from the whims of their magic reserves. This, combined with the learning method above, was so influential it is said to have “ended the era of sword fighter supremacy” by raising the status of magicians.","html":"With funding from Rudeus, Silent Sevenstar developed a drink that restores mana. This so-called magic potion unshackled magicians from the whims of their magic reserves. This, combined with the learning method above, was so influential it is said to have “ended the era of sword fighter supremacy” by raising the status of magicians.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0100","sourceIndex":100,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0101","sourceIndex":101,"type":"narration","text":"MAGICAL PROSTHETICS","html":"<strong>MAGICAL PROSTHETICS</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0102","sourceIndex":102,"type":"narration","text":"Magical prosthetics have helped a great many people: adventurers, for instance, or those too poor to access healing magic beyond Saint- or King-tier. These prosthetics were the result of research by Zanoba Shirone and Cliff Grimor, made possible through funding provided by Rudeus. It was Silent Sevenstar who popularized the magical prosthetics not as magical implements but as medical tools.","html":"Magical prosthetics have helped a great many people: adventurers, for instance, or those too poor to access healing magic beyond Saint- or King-tier. These prosthetics were the result of research by Zanoba Shirone and Cliff Grimor, made possible through funding provided by Rudeus. It was Silent Sevenstar who popularized the magical prosthetics not as magical implements but as medical tools.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0103","sourceIndex":103,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0104","sourceIndex":104,"type":"narration","text":"MAGIC ARMOR","html":"<strong>MAGIC ARMOR</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0105","sourceIndex":105,"type":"narration","text":"Rudeus was implied to be the only one who could operate the Magic Armor. In time, the Greyrats’ third daughter, Lily Greyrat, took over his research and in 483 perfected the General Purpose Magic Armor. This development significantly reduced the risk of hunting large monsters.","html":"Rudeus was implied to be the only one who could operate the Magic Armor. In time, the Greyrats’ third daughter, Lily Greyrat, took over his research and in 483 perfected the General Purpose Magic Armor. This development significantly reduced the risk of hunting large monsters.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0106","sourceIndex":106,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0107","sourceIndex":107,"type":"narration","text":"MAGIC DOLLS","html":"<strong>MAGIC DOLLS</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0108","sourceIndex":108,"type":"narration","text":"With funding provided by Rudeus, Zanoba Shirone successfully developed a magical figurine. These figurines look exactly like humans. They are used in a wide variety of ways: serving as cherished pets, performing odd tasks, testing for poison, and working as scouts. However, they are enormously expensive and few in number. At present only the royalty of nations who enjoyed Rudeus’s friendship use them.","html":"With funding provided by Rudeus, Zanoba Shirone successfully developed a magical figurine. These figurines look exactly like humans. They are used in a wide variety of ways: serving as cherished pets, performing odd tasks, testing for poison, and working as scouts. However, they are enormously expensive and few in number. At present only the royalty of nations who enjoyed Rudeus’s friendship use them.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0109","sourceIndex":109,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0110","sourceIndex":110,"type":"narration","text":"TELEPORTATION CIRCLES","html":"<strong>TELEPORTATION CIRCLES</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0111","sourceIndex":111,"type":"narration","text":"With funding provided by Rudeus, Silent Sevenstar researched and revived the forbidden teleportation circles. With teleportation circles placed in strategic locations throughout the different nations, the danger of long journeys was mitigated and travel to distant lands became simple.","html":"With funding provided by Rudeus, Silent Sevenstar researched and revived the forbidden teleportation circles. With teleportation circles placed in strategic locations throughout the different nations, the danger of long journeys was mitigated and travel to distant lands became simple.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0112","sourceIndex":112,"type":"narration","text":"Rudeus is said to have broken the taboo after reflecting on the death of his father Paul in the Teleportation Labyrinth. Records suggest that the actual research was conducted by Silent Sevenstar, with Rudeus as her sponsor. However, for some unknown reason old merchant and noble families, along with those involved in the Millis Church, curse Rudeus as the “taboo breaker.”","html":"Rudeus is said to have broken the taboo after reflecting on the death of his father Paul in the Teleportation Labyrinth. Records suggest that the actual research was conducted by Silent Sevenstar, with Rudeus as her sponsor. However, for some unknown reason old merchant and noble families, along with those involved in the Millis Church, curse Rudeus as the “taboo breaker.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0113","sourceIndex":113,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0114","sourceIndex":114,"type":"narration","text":"Memoirs and Code","html":"<strong>Memoirs and Code</strong>","className":"P_TEXTBODY_CENTERALIGN","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0115","sourceIndex":115,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0116","sourceIndex":116,"type":"narration","text":"It is believed that the records of the research above were written in the fifty-two volumes that form the Book of Rudeus. Since they are written entirely in a code only used between himself and Silent Sevenstar that is yet to be fully decrypted, however, their credibility is questionable.","html":"It is believed that the records of the research above were written in the fifty-two volumes that form the Book of Rudeus. Since they are written entirely in a code only used between himself and Silent Sevenstar that is yet to be fully decrypted, however, their credibility is questionable.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0117","sourceIndex":117,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0118","sourceIndex":118,"type":"narration","text":"Build and Character","html":"<strong>Build and Character</strong>","className":"P_TEXTBODY_CENTERALIGN","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0119","sourceIndex":119,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0120","sourceIndex":120,"type":"narration","text":"Rudeus was approximately 175 centimeters tall and had, for a magician, a comparatively strong and muscular build. He had pale skin, and his eyes were mismatched, as used the eye of foresight right eye and the Eye of Distant Sight for his left. He is never described as handsome, but his wife Sylphiette is said to have thought, “Looking at his face for just a few seconds was enough to make me weak at the knees” when they met at the Magic University. His other wives, Eris Greyrat and Roxy M. Greyrat, didn’t make any comment on his looks, but we can assume he wasn’t exceptionally ugly.","html":"Rudeus was approximately 175 centimeters tall and had, for a magician, a comparatively strong and muscular build. He had pale skin, and his eyes were mismatched, as used the eye of foresight right eye and the Eye of Distant Sight for his left. He is never described as handsome, but his wife Sylphiette is said to have thought, “Looking at his face for just a few seconds was enough to make me weak at the knees” when they met at the Magic University. His other wives, Eris Greyrat and Roxy M. Greyrat, didn’t make any comment on his looks, but we can assume he wasn’t exceptionally ugly.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0121","sourceIndex":121,"type":"narration","text":"His preferred outfit is supposed to have been a light gray robe without a hat. He was disinterested in clothing in his youth. It is written in the remaining records that while attending university he “wore a robe fraying at the hem,” and in the Asura Kingdom “a number of nobles looked disapprovingly at his strange appearance when he presented himself in the audience chamber.” He came to pay more attention to his personal appearance after turning twenty, and around 430 Armored Dragon King Perugius commented that, “he has made himself more presentable lately.” While insensitive to his own appearance, he was fastidious about cleanliness, renovating a room of his home into a large bath which he is said to have used every day.","html":"His preferred outfit is supposed to have been a light gray robe without a hat. He was disinterested in clothing in his youth. It is written in the remaining records that while attending university he “wore a robe fraying at the hem,” and in the Asura Kingdom “a number of nobles looked disapprovingly at his strange appearance when he presented himself in the audience chamber.” He came to pay more attention to his personal appearance after turning twenty, and around 430 Armored Dragon King Perugius commented that, “he has made himself more presentable lately.” While insensitive to his own appearance, he was fastidious about cleanliness, renovating a room of his home into a large bath which he is said to have used every day. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0122","sourceIndex":122,"type":"narration","text":"Rudeus was feared in Sharia, but he was also more beloved than any other magician, as can be seen in his grand funeral and the many mourners who attended, as well as in the monument erected in a corner of the Magic University engraved with Rudeus’s own words.","html":"Rudeus was feared in Sharia, but he was also more beloved than any other magician, as can be seen in his grand funeral and the many mourners who attended, as well as in the monument erected in a corner of the Magic University engraved with Rudeus’s own words.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0123","sourceIndex":123,"type":"narration","text":"Rudeus is believed to have been sociable, with a kind and good-natured personality, but his intense libido did not go without comment. Descriptions remain of how he touched and fondled his wives without any restraint or regard for watchers-on. He was, in fact, devoted to his wives and never made a move on other women, so some historians opine that his lechery is a groundless rumor. In addition, he was of such a gentle disposition that he smiled through insults and violence directed at him, but when harm came to his family or friends he would get into such a fury that at times he became violent.","html":"Rudeus is believed to have been sociable, with a kind and good-natured personality, but his intense libido did not go without comment. Descriptions remain of how he touched and fondled his wives without any restraint or regard for watchers-on. He was, in fact, devoted to his wives and never made a move on other women, so some historians opine that his lechery is a groundless rumor. In addition, he was of such a gentle disposition that he smiled through insults and violence directed at him, but when harm came to his family or friends he would get into such a fury that at times he became violent.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0124","sourceIndex":124,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0125","sourceIndex":125,"type":"narration","text":"The following anecdotes describe Rudeus’s personality:","html":"The following anecdotes describe Rudeus’s personality:","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0126","sourceIndex":126,"type":"quotation","text":"“At a party in the Asura Kingdom, when a noble made fun of Rudeus’s wife, Rudeus seized him by the throat and dragged him out of the party, burned a whole forest to ash before his eyes, and demanded an apology.”","html":"“At a party in the Asura Kingdom, when a noble made fun of Rudeus’s wife, Rudeus seized him by the throat and dragged him out of the party, burned a whole forest to ash before his eyes, and demanded an apology.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Archivist","attributionNote":"Anecdote quoted in the Asuran dossier, not spoken dialogue.","speakerConfidence":"high"},{"id":"ch08-p0127","sourceIndex":127,"type":"quotation","text":"“When his great friends Linia and Pursena broke a figurine modeled on his wife, Rudeus punished them in the most humiliating way possible for beastfolk.”","html":"“When his great friends Linia and Pursena broke a figurine modeled on his wife, Rudeus punished them in the most humiliating way possible for beastfolk.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Archivist","attributionNote":"Anecdote quoted in the Asuran dossier, not spoken dialogue.","speakerConfidence":"high"},{"id":"ch08-p0128","sourceIndex":128,"type":"quotation","text":"“When Perugius invited Rudeus to the floating fortress to name his child, Rudeus, misunderstood and thought Perugius intended to harm the child. He appeared fully armed and threatened Perugius that there would be war if any harm came to his child.”","html":"“When Perugius invited Rudeus to the floating fortress to name his child, Rudeus, misunderstood and thought Perugius intended to harm the child. He appeared fully armed and threatened Perugius that there would be war if any harm came to his child.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Archivist","attributionNote":"Anecdote quoted in the Asuran dossier, not spoken dialogue.","speakerConfidence":"high"},{"id":"ch08-p0129","sourceIndex":129,"type":"narration","text":"* It should be noted that the veracity of these anecdotes is unconfirmed.","html":"* It should be noted that the veracity of these anecdotes is unconfirmed.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0130","sourceIndex":130,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0131","sourceIndex":131,"type":"narration","text":"While Rudeus is not generally well-known, the majority of the world’s most prominent figures know of him and regard him with admiration or awe.","html":"While Rudeus is not generally well-known, the majority of the world’s most prominent figures know of him and regard him with admiration or awe.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0132","sourceIndex":132,"type":"narration","text":"A piece of white cloth was found in his pocket after his death. His wife Roxy hurried to hide it, leading to rumors that some great secret might be concealed within it. It is unclear whether those rumors contain any shred of truth.","html":"A piece of white cloth was found in his pocket after his death. His wife Roxy hurried to hide it, leading to rumors that some great secret might be concealed within it. It is unclear whether those rumors contain any shred of truth.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0133","sourceIndex":133,"type":"narration","text":"He is said to be the origin point for the Theory of Critical Period for Mana Capacity, namely that mana capacity can be strengthened in early childhood, and is resultantly responsible for its incorporation into education.","html":"He is said to be the origin point for the Theory of Critical Period for Mana Capacity, namely that mana capacity can be strengthened in early childhood, and is resultantly responsible for its incorporation into education.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0134","sourceIndex":134,"type":"narration","text":"He loved rice, eggs, and the ogre water of the Biheiril Kingdom. He is also said to have had an unsavory habit of eating eggs raw.","html":"He loved rice, eggs, and the ogre water of the Biheiril Kingdom. He is also said to have had an unsavory habit of eating eggs raw.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0135","sourceIndex":135,"type":"narration","text":"Records indicate he worshipped some unknown dark god. Puzzlingly, no gods can be matched to the coat of arms he worshipped—we can assume this god disappeared in antiquity, or Rudeus perhaps created this god for himself. Some also theorize that he was irreligious, or that he worshipped the Dragon God.","html":"Records indicate he worshipped some unknown dark god. Puzzlingly, no gods can be matched to the coat of arms he worshipped—we can assume this god disappeared in antiquity, or Rudeus perhaps created this god for himself. Some also theorize that he was irreligious, or that he worshipped the Dragon God.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0136","sourceIndex":136,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0137","sourceIndex":137,"type":"narration","text":"Family & Relatives","html":"<strong>Family &amp; Relatives</strong>","className":"P_TEXTBODY_CENTERALIGN","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0138","sourceIndex":138,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0139","sourceIndex":139,"type":"narration","text":"THE GREYRAT FAMILY","html":"<strong>THE GREYRAT FAMILY</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0140","sourceIndex":140,"type":"narration","text":"A high-ranking noble family in the Asura Kingdom. It contains the four families of Notos, Boreas, Zephyros, and Euros. All four families governed their own large domain, which is why they are also called the Four Great Houses. Rudeus was a direct descendant of the Notos Greyrats, but his father Paul ran away from his family and was therefore expunged from the Notos Greyrat family tree.","html":"A high-ranking noble family in the Asura Kingdom. It contains the four families of Notos, Boreas, Zephyros, and Euros. All four families governed their own large domain, which is why they are also called the Four Great Houses. Rudeus was a direct descendant of the Notos Greyrats, but his father Paul ran away from his family and was therefore expunged from the Notos Greyrat family tree.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0141","sourceIndex":141,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0142","sourceIndex":142,"type":"narration","text":"PAUL GREYRAT: father. Eldest son of the Notos Greyrats, a high-ranking Asuran noble family. Ran away as a young man and became an adventurer. Later, he met Zenith, then appealed to his old friend Philip Boreas Greyrat and became a low-ranking knight of the Fittoa Region.","html":"PAUL GREYRAT: father. Eldest son of the Notos Greyrats, a high-ranking Asuran noble family. Ran away as a young man and became an adventurer. Later, he met Zenith, then appealed to his old friend Philip Boreas Greyrat and became a low-ranking knight of the Fittoa Region.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0143","sourceIndex":143,"type":"narration","text":"ZENITH GREYRAT: mother. Second daughter of the Latrias of the Holy Land of Millis.","html":"ZENITH GREYRAT: mother. Second daughter of the Latrias of the Holy Land of Millis.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0144","sourceIndex":144,"type":"narration","text":"LILIA GREYRAT: maid. Paul’s lover.","html":"LILIA GREYRAT: maid. Paul’s lover.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0145","sourceIndex":145,"type":"narration","text":"NORN GREYRAT: legitimate younger sister. Novelist.","html":"NORN GREYRAT: legitimate younger sister. Novelist.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0146","sourceIndex":146,"type":"narration","text":"AISHA GREYRAT: younger sister by his stepmother. Advisor to Ruquag’s Mercenary Band.","html":"AISHA GREYRAT: younger sister by his stepmother. Advisor to Ruquag’s Mercenary Band.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0147","sourceIndex":147,"type":"narration","text":"SYLPHIETTE GREYRAT: wife. One quarter elf.","html":"SYLPHIETTE GREYRAT: wife. One quarter elf.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0148","sourceIndex":148,"type":"narration","text":"ROXY M. GREYRAT: wife. Demon (of the Migurd). Headmistress of the Magic University.","html":"ROXY M. GREYRAT: wife. Demon (of the Migurd). Headmistress of the Magic University.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0149","sourceIndex":149,"type":"narration","text":"ERIS GREYRAT: Wife. Human. Sword King.","html":"ERIS GREYRAT: Wife. Human. Sword King.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0150","sourceIndex":150,"type":"narration","text":"LUCIE GREYRAT: eldest daughter.","html":"LUCIE GREYRAT: eldest daughter.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0151","sourceIndex":151,"type":"narration","text":"LARA GREYRAT: second daughter.","html":"LARA GREYRAT: second daughter.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0152","sourceIndex":152,"type":"narration","text":"ARS GREYRAT: eldest son.","html":"ARS GREYRAT: eldest son.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0153","sourceIndex":153,"type":"narration","text":"SIEGHEART SALADIN GREYRAT: second son.","html":"SIEGHEART SALADIN GREYRAT: second son.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0154","sourceIndex":154,"type":"narration","text":"LILY GREYRAT: third daughter.","html":"LILY GREYRAT: third daughter.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0155","sourceIndex":155,"type":"narration","text":"CHRISTINA GREYRAT: fourth daughter.","html":"CHRISTINA GREYRAT: fourth daughter.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0156","sourceIndex":156,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0157","sourceIndex":157,"type":"narration","text":"OTHER ASSOCIATED INDIVIDUALS","html":"<strong>OTHER ASSOCIATED INDIVIDUALS</strong>","className":"P_Prose_Formatting","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0158","sourceIndex":158,"type":"narration","text":"ZANOBA SHIRONE: upperclassman at the Magic University. A former prince of Shirone. President of a figurine company. Blessed Child of fantastic strength. The publication of the picture book The Superd’s Adventure was largely thanks to his and Norn’s efforts. Zanoba respected Rudeus as his mentor, but Rudeus always said, “When it comes to knowledge of figurines, Zanoba’s the best.”","html":"ZANOBA SHIRONE: upperclassman at the Magic University. A former prince of Shirone. President of a figurine company. Blessed Child of fantastic strength. The publication of the picture book The Superd’s Adventure was largely thanks to his and Norn’s efforts. Zanoba respected Rudeus as his mentor, but Rudeus always said, “When it comes to knowledge of figurines, Zanoba’s the best.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0159","sourceIndex":159,"type":"narration","text":"CLIFF GRIMOR: upperclassman at the Magic University. Later became the pope of the Millis Church. He is said to have protected Rudeus, who was often in some trouble or other with the Millis Church. Rudeus reportedly relied on him and is believed to have said with conviction that “I wouldn’t be here if it weren’t for Cliff.”","html":"CLIFF GRIMOR: upperclassman at the Magic University. Later became the pope of the Millis Church. He is said to have protected Rudeus, who was often in some trouble or other with the Millis Church. Rudeus reportedly relied on him and is believed to have said with conviction that “I wouldn’t be here if it weren’t for Cliff.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0160","sourceIndex":160,"type":"narration","text":"SILENT SEVENSTAR: upperclassman at the Magic University. Also known as the Witch Nanahoshi. She set up teleportation circles in nations throughout the world and collaborated with Rudeus to develop and bring about many revolutionary inventions.","html":"SILENT SEVENSTAR: upperclassman at the Magic University. Also known as the Witch Nanahoshi. She set up teleportation circles in nations throughout the world and collaborated with Rudeus to develop and bring about many revolutionary inventions. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0161","sourceIndex":161,"type":"quotation","text":"ARIEL ANEMOI ASURA: Queen of the Asura Kingdom. According to the Chronicle of the Asura Kingdom, right before her death, she told her trusted retainer Luke that, “it is largely thanks to Rudeus’s efforts that the Asura Kingdom is at peace today. Be sure not to make an enemy of him after my death.”","html":"ARIEL ANEMOI ASURA: Queen of the Asura Kingdom. According to the Chronicle of the Asura Kingdom, right before her death, she told her trusted retainer Luke that, “it is largely thanks to Rudeus’s efforts that the Asura Kingdom is at peace today. Be sure not to make an enemy of him after my death.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Ariel","attributionNote":"Ariel's words to Luke, quoted from the Chronicle of the Asura Kingdom.","speakerConfidence":"high"},{"id":"ch08-p0162","sourceIndex":162,"type":"narration","text":"ALEXANDER K. RYBAK: North God Kalman III. Originally number seven of the Seven Great Powers. The “left hand of the Dragon God.” After Rudeus stepped down from the center stage, Alexander is believed to have gone around the nations of the world as the Dragon God’s representative in his stead.","html":"ALEXANDER K. RYBAK: North God Kalman III. Originally number seven of the Seven Great Powers. The “left hand of the Dragon God.” After Rudeus stepped down from the center stage, Alexander is believed to have gone around the nations of the world as the Dragon God’s representative in his stead.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0163","sourceIndex":163,"type":"narration","text":"LINIANA DEDOLDIA: Leader of Ruquag’s Mercenary Band. As the leader of her beastfolk tribe, she is believed to have served as an intermediary between Rudeus and the beastfolk.","html":"LINIANA DEDOLDIA: Leader of Ruquag’s Mercenary Band. As the leader of her beastfolk tribe, she is believed to have served as an intermediary between Rudeus and the beastfolk.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0164","sourceIndex":164,"type":"narration","text":"PURSENA ADOLDIA: Second-in-command of Ruquag’s Mercenary Band. Like Liliana, as leader of a beastfolk tribe, she is believed to have served as an intermediary between Rudeus and the beastfolk.","html":"PURSENA ADOLDIA: Second-in-command of Ruquag’s Mercenary Band. Like Liliana, as leader of a beastfolk tribe, she is believed to have served as an intermediary between Rudeus and the beastfolk.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0165","sourceIndex":165,"type":"narration","text":"PERUGIUS DOLA: The Armored Dragon King, one of the Three Godslayers. A prominent figure in the Asura Kingdom and Silent Sevenstar’s mentor. There are frequent references to Rudeus in The Chronicle of the Asura Kingdom, but the nature of his relationship with Rudeus is unknown.","html":"PERUGIUS DOLA: The Armored Dragon King, one of the Three Godslayers. A prominent figure in the Asura Kingdom and Silent Sevenstar’s mentor. There are frequent references to Rudeus in The Chronicle of the Asura Kingdom, but the nature of his relationship with Rudeus is unknown.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0166","sourceIndex":166,"type":"narration","text":"ORSTED: The Dragon God. Number two of the Seven Great Powers. Though Rudeus’s covert activities are assumed to have been in service to Orsted’s goals, details of these activities are unknown. Orsted very rarely appeared center stage, but he attended Rudeus’s funeral and allegedly was with the family to witness Rudeus’s death.","html":"ORSTED: The Dragon God. Number two of the Seven Great Powers. Though Rudeus’s covert activities are assumed to have been in service to Orsted’s goals, details of these activities are unknown. Orsted very rarely appeared center stage, but he attended Rudeus’s funeral and allegedly was with the family to witness Rudeus’s death.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0167","sourceIndex":167,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0168","sourceIndex":168,"type":"narration","text":"Bibliography","html":"<strong>Bibliography</strong>","className":"P_TEXTBODY_CENTERALIGN","italic":false,"bold":true,"dropCap":false},{"id":"ch08-p0169","sourceIndex":169,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0170","sourceIndex":170,"type":"narration","text":"The Royal Asura Historiographical Institute. The Chronicle of the Asura Kingdom. The Asura Kingdom, 480.","html":"The Royal Asura Historiographical Institute. The Chronicle of the Asura Kingdom. The Asura Kingdom, 480.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0171","sourceIndex":171,"type":"narration","text":"Greyrat, Norn. The Superd’s Adventure. Zanoba Figurine Company, 427.","html":"Greyrat, Norn. The Superd’s Adventure. Zanoba Figurine Company, 427.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0172","sourceIndex":172,"type":"narration","text":"Greyrat, Norn. Aisha Greyrat: The Agonies of Genius. Ruquag’s Mercenary Band, 455.","html":"Greyrat, Norn. Aisha Greyrat: The Agonies of Genius. Ruquag’s Mercenary Band, 455.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0173","sourceIndex":173,"type":"narration","text":"Greyrat, Norn. The Adventures of Rudeus the Great Magician. Zanoba Figurine Company, 470.","html":"Greyrat, Norn. The Adventures of Rudeus the Great Magician. Zanoba Figurine Company, 470.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0174","sourceIndex":174,"type":"narration","text":"Greyrat, Norn. Surrounded by Genius: an Autobiography of a Mediocrity. Zanoba Figurine Company, 482.","html":"Greyrat, Norn. Surrounded by Genius: an Autobiography of a Mediocrity. Zanoba Figurine Company, 482.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0175","sourceIndex":175,"type":"narration","text":"The Millis Church Archival Division. Millis Church Minutes. Millis Church, 460.","html":"The Millis Church Archival Division. Millis Church Minutes. Millis Church, 460.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0176","sourceIndex":176,"type":"narration","text":"The Royal Biheiril Historiographical Institute. The History of the Biheiril Kingdom 420-430. The Biheiril Kingdom, 433.","html":"The Royal Biheiril Historiographical Institute. The History of the Biheiril Kingdom 420-430. The Biheiril Kingdom, 433.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0177","sourceIndex":177,"type":"narration","text":"Dedoldia, Liniana. Activity Log of Ruquag’s Mercenary Band. Ruquag’s Mercenary Band, 456.","html":"Dedoldia, Liniana. Activity Log of Ruquag’s Mercenary Band. Ruquag’s Mercenary Band, 456.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0178","sourceIndex":178,"type":"narration","text":"Juliette. Zanoba Figurine Company Executive Committee Minutes. 477.","html":"Juliette. Zanoba Figurine Company Executive Committee Minutes. 477.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0179","sourceIndex":179,"type":"narration","text":"Silent Sevenstar. Textbook of Magic: New Edition. 442.","html":"Silent Sevenstar. Textbook of Magic: New Edition. 442.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0180","sourceIndex":180,"type":"narration","text":"Bradicant. Great Figures and Heroes of the World. Publisher unknown, 480.","html":"Bradicant. Great Figures and Heroes of the World. Publisher unknown, 480.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch08-p0181","sourceIndex":181,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch08-p0182","sourceIndex":182,"type":"narration","text":"—Recorded by Deputy Head ArchivistClule Elrond of the Royal Asuran Archive","html":"—Recorded by Deputy Head Archivist<br/>Clule Elrond of the Royal Asuran Archive","className":"P_Prose_Formatting__And__Right_Alignment","italic":false,"bold":false,"dropCap":false}],"wordCount":3822,"speechCount":0,"speakers":[]}],"images":[],"sequence":8,"cast":["Archivist","Ariel","Clule Elrond","Jed Bluewolf","Orsted","Paul","Perugius","Rudeus"],"sceneCount":2,"speechCount":0,"speakers":[]},{"id":"ch09","number":"afterword","title":"Afterword (Excerpted from The Book of Rudeus, Vol. 26)","pov":"Rudeus","kind":"afterword","wordCount":2050,"scenes":[{"id":"ch09-s01","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"Rudeus's diary, written for whoever reads it after his death","cast":["Ariel","Cliff","Eris","Orsted","Paul","Roxy","Rudeus","Sylphiette","Zenith"],"blocks":[{"id":"ch09-p0002","sourceIndex":2,"type":"narration","text":"RIGHT, SO UP UNTIL NOW I’ve just been scribbling things down in this diary. Now that I’ve filled over twenty-five books and made a bit of a name for myself, I’ve had this strange idea. Maybe, just maybe, someone might read this.","html":"RIGHT, SO UP UNTIL NOW I’ve just been scribbling things down in this diary. Now that I’ve filled over twenty-five books and made a bit of a name for myself, I’ve had this strange idea. Maybe, just maybe, someone might read this.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0003","sourceIndex":3,"type":"narration","text":"I wrote it all in Japanese, so theoretically, no one in this world should be able to read it. Still, someone with too much free time might decode it, and after I die, someone else who came from the same world as me might read it.","html":"I wrote it all in Japanese, so theoretically, no one in this world should be able to read it. Still, someone with too much free time might decode it, and after I die, someone else who came from the same world as me might read it.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0004","sourceIndex":4,"type":"narration","text":"…I’d feel pretty bad if someone actually put all the effort into decoding these when there’s nothing all that important written in them. But I mean, that’s just what diaries are like, right?","html":"…I’d feel pretty bad if someone actually put all the effort into decoding these when there’s nothing all that important written in them. But I mean, that’s just what diaries are like, right? ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0005","sourceIndex":5,"type":"narration","text":"Whatever purpose someone decodes it for, it won’t go out into the world until after I’m dead. I’d like to record for later generations that Dragon God Orsted wasn’t a bad person.","html":"Whatever purpose someone decodes it for, it won’t go out into the world until after I’m dead. I’d like to record for later generations that Dragon God Orsted wasn’t a bad person.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0006","sourceIndex":6,"type":"narration","text":"And then there’s that other thing…","html":"And then there’s that other thing…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0007","sourceIndex":7,"type":"narration","text":"Okay, so as I’ve written a few times in these diaries, I’m not originally from this world. I died in another world and was reborn here. I’ve decided not to write my name from my previous life. If the person reading this knew the person I was in my old world, they might get the wrong idea. Still, I might have a previous life, but aside from that I’m not actually special. If you’ve decoded this diary and are reading it, you’ll know that I lived an ordinary life in this world. I didn’t choose to be reborn, and in the end, I never found out what caused it. No big deal.","html":"Okay, so as I’ve written a few times in these diaries, I’m not originally from this world. I died in another world and was reborn here. I’ve decided not to write my name from my previous life. If the person reading this knew the person I was in my old world, they might get the wrong idea. Still, I might have a previous life, but aside from that I’m not actually special. If you’ve decoded this diary and are reading it, you’ll know that I lived an ordinary life in this world. I didn’t choose to be reborn, and in the end, I never found out what caused it. No big deal.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0008","sourceIndex":8,"type":"narration","text":"I just lived the best life I could—so that if I died the next day, I’d have no regrets. That’s what’s important.","html":"I just lived the best life I could—so that if I died the next day, I’d have no regrets. That’s what’s important.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0009","sourceIndex":9,"type":"narration","text":"You may scoff at that, whoever it is who’s reading this diary. Maybe you’re thinking, “He was just lucky with where he was born,” or, “Easy for this guy to say when he was blessed with talent.” Or maybe you’ve seen my portrait, so you put it down to my pretty face…","html":"You may scoff at that, whoever it is who’s reading this diary. Maybe you’re thinking, “He was just lucky with where he was born,” or, “Easy for this guy to say when he was blessed with talent.” Or maybe you’ve seen my portrait, so you put it down to my pretty face…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0010","sourceIndex":10,"type":"narration","text":"I mean, as I wrote in here the other day, Cliff told me his classmates said things like that. They said he had an unfair advantage because he’d been born into good circumstances, and they hadn’t. He said he felt really uncomfortable about it. That made me think about my own privileges. To be honest, my own upbringing was pretty cushy. Paul, my father, was a scumbag when it came to women, but he wasn’t a bad person. The real scumbag stuff was how he got caught cheating, then lied about it even though there was damning evidence, then played dumb, then lashed out like he was the victim… If I cheated, then tried to pull something like that, Eris would beat me up, Sylphie would hate me, and Roxy would have nothing but contempt. I’d end up losing everything.","html":"I mean, as I wrote in here the other day, Cliff told me his classmates said things like that. They said he had an unfair advantage because he’d been born into good circumstances, and they hadn’t. He said he felt really uncomfortable about it. That made me think about my own privileges. To be honest, my own upbringing was pretty cushy. Paul, my father, was a scumbag when it came to women, but he wasn’t a bad person. The real scumbag stuff was how he got caught cheating, then lied about it even though there was damning evidence, then played dumb, then lashed out like he was the victim… If I cheated, then tried to pull something like that, Eris would beat me up, Sylphie would hate me, and Roxy would have nothing but contempt. I’d end up losing everything.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0011","sourceIndex":11,"type":"narration","text":"Jeez, that’s a scary thought.","html":"Jeez, that’s a scary thought.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0012","sourceIndex":12,"type":"narration","text":"I couldn’t have asked for a better mother than Zenith. She was young when her mind failed, but when you consider what it’s usually like to care for a bedridden person by comparison, it wasn’t so bad. I did end up pretty much entirely handing her off to Lilia and Sylphie, but compared to my previous life, where I wasn’t able to do anything for my parents, I think I did all right by her. The point is, I was born to parents who loved me. I can’t say we wanted for nothing, but at the very least we didn’t have any debt, and my parents weren’t fighting over money every day. That was kinda lucky.","html":"I couldn’t have asked for a better mother than Zenith. She was young when her mind failed, but when you consider what it’s usually like to care for a bedridden person by comparison, it wasn’t so bad. I did end up pretty much entirely handing her off to Lilia and Sylphie, but compared to my previous life, where I wasn’t able to do anything for my parents, I think I did all right by her. The point is, I was born to parents who loved me. I can’t say we wanted for nothing, but at the very least we didn’t have any debt, and my parents weren’t fighting over money every day. That was kinda lucky.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0013","sourceIndex":13,"type":"narration","text":"I also had a talent for magic. I had a leg up from the knowledge from my past life and a vast pool of mana from the Laplace aspect. It’s thanks to both that I was able to excel in unvoiced magic. Even if you searched the world over you’d have a hard time finding anyone who can shoot a Stone Cannon harder or faster than me. While I’d like to chalk it up to my own hard work, I’m pretty sure it was the gifts I was born with. Just luck, really.","html":"I also had a talent for magic. I had a leg up from the knowledge from my past life and a vast pool of mana from the Laplace aspect. It’s thanks to both that I was able to excel in unvoiced magic. Even if you searched the world over you’d have a hard time finding anyone who can shoot a Stone Cannon harder or faster than me. While I’d like to chalk it up to my own hard work, I’m pretty sure it was the gifts I was born with. Just luck, really.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0014","sourceIndex":14,"type":"narration","text":"So far as my looks go, I reckon I’m better off now than I was, but for all that…I still haven’t had many women take an interest in me just for my face. On the flip side, I have been treated unfairly because people didn’t like my face before. Soldat, for example, said he didn’t like the look of me. He might have been talking about my expression, though. Expressions are important, too.","html":"So far as my looks go, I reckon I’m better off now than I was, but for all that…I still haven’t had many women take an interest in me just for my face. On the flip side, I have been treated unfairly because people didn’t like my face before. Soldat, for example, said he didn’t like the look of me. He might have been talking about my expression, though. Expressions are important, too.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0015","sourceIndex":15,"type":"narration","text":"Most people aren’t repelled by my face, at any rate. More luck.","html":"Most people aren’t repelled by my face, at any rate. More luck.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0016","sourceIndex":16,"type":"narration","text":"I don’t doubt it’s that good luck that gave me the motivation to try hard. Still, I wonder. What if I’d been even better off? How would I have turned out if, say, I’d been born an Asuran aristocrat, never wanting for money or women or anything else? I know I’m a bit of a perv, and there’ve been times when that perviness motivated me to work hard. Not having those sorts of things for all those years is what allowed me to appreciate them.","html":"I don’t doubt it’s that good luck that gave me the motivation to try hard. Still, I wonder. What if I’d been even better off? How would I have turned out if, say, I’d been born an Asuran aristocrat, never wanting for money or women or anything else? I know I’m a bit of a perv, and there’ve been times when that perviness motivated me to work hard. Not having those sorts of things for all those years is what allowed me to appreciate them.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0017","sourceIndex":17,"type":"narration","text":"If it’d been easy for me to get with women, if I’d had women throwing themselves at me, and all without having to lift a finger, would I have seen the value in it? I wonder if I wouldn’t have just gotten bored early on and stopped making any effort to make women like me.","html":"If it’d been easy for me to get with women, if I’d had women throwing themselves at me, and all without having to lift a finger, would I have seen the value in it? I wonder if I wouldn’t have just gotten bored early on and stopped making any effort to make women like me.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0018","sourceIndex":18,"type":"narration","text":"The same goes for magic. I’ve worked my ass off practicing magic every single day. My training looks tedious from the outside, but it’s because I kept going with it that I can now wield magic with a high level of precision. What if the first time I picked up a magic textbook I’d been able to cast not just Beginner-tier, but Advanced-tier—or even God-tier magic? Would I have gone on training hard after that?","html":"The same goes for magic. I’ve worked my ass off practicing magic every single day. My training looks tedious from the outside, but it’s because I kept going with it that I can now wield magic with a high level of precision. What if the first time I picked up a magic textbook I’d been able to cast not just Beginner-tier, but Advanced-tier—or even God-tier magic? Would I have gone on training hard after that?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0019","sourceIndex":19,"type":"narration","text":"I think people find value and strive for the things they can’t have—the things that don’t come easily. In the end, we all have to play with the hand we’re dealt, but there’ll always be something in our hand we’re unhappy with. Someone else will be envious of one of your cards while you yourself are unable to see its worth.","html":"I think people find value and strive for the things they can’t have—the things that don’t come easily. In the end, we all have to play with the hand we’re dealt, but there’ll always be something in our hand we’re unhappy with. Someone else will be envious of one of your cards while you yourself are unable to see its worth. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0020","sourceIndex":20,"type":"narration","text":"I know I sound like I’m bragging, but I do have a past life. My home in my past life was even better off than Paul’s, and as far as talent goes, if I hadn’t given up, I could’ve made something of myself. I’m probably better looking now, but if I’d exercised and slimmed down a bit, and groomed my hair and eyebrows, I wouldn’t have looked half bad. Looking back, I had way more advantages back then than in this life. Despite all that, despite the privilege I had, I stayed a garbage person. When I died, that was what I regretted. So even if I hadn’t been born in a peaceful village like Buena, even if it had been the slums of the Conflict Zone, or if I’d been abused by my parents, or if when I first opened a magic textbook I hadn’t managed to whip up so much as a water bomb… I feel like I’d have still tried my best. I doubt my life would have been as happy as this one. I might have resented the world more. But if nothing else, I think I’d have acted more than I did in my previous life. I think I would have lived with the desperation of a drowning man. I’m sure that life would have been worth more than my previous one.","html":"I know I sound like I’m bragging, but I do have a past life. My home in my past life was even better off than Paul’s, and as far as talent goes, if I hadn’t given up, I could’ve made something of myself. I’m probably better looking now, but if I’d exercised and slimmed down a bit, and groomed my hair and eyebrows, I wouldn’t have looked half bad. Looking back, I had way more advantages back then than in this life. Despite all that, despite the privilege I had, I stayed a garbage person. When I died, that was what I regretted. So even if I hadn’t been born in a peaceful village like Buena, even if it had been the slums of the Conflict Zone, or if I’d been abused by my parents, or if when I first opened a magic textbook I hadn’t managed to whip up so much as a water bomb… I feel like I’d have still tried my best. I doubt my life would have been as happy as this one. I might have resented the world more. But if nothing else, I think I’d have acted more than I did in my previous life. I think I would have lived with the desperation of a drowning man. I’m sure that life would have been worth more than my previous one.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0021","sourceIndex":21,"type":"narration","text":"If anything, even if that truck didn’t hit me and I went on living in my original world without getting reincarnated, if I’d only had a bit of luck, I might have been able to apply myself. Well, okay, it wouldn’t have been easy. I was an incredible sulk back then, so it took the jumbo-size helping of luck that let me be reincarnated to finally get me moving.","html":"If anything, even if that truck didn’t hit me and I went on living in my original world without getting reincarnated, if I’d only had a bit of luck, I might have been able to apply myself. Well, okay, it wouldn’t have been easy. I was an incredible sulk back then, so it took the jumbo-size helping of luck that let me be reincarnated to finally get me moving.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0022","sourceIndex":22,"type":"narration","text":"What I’m trying to say is that circumstances are all relative, and sometimes “good circumstances” actually means having a few things that seem like disadvantages.","html":"What I’m trying to say is that circumstances are all relative, and sometimes “good circumstances” actually means having a few things that seem like disadvantages.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0023","sourceIndex":23,"type":"narration","text":"I’m not here to tell you not to blame things on the way things are for you. I know I’ve been privileged. I try to remember there are people in terrible circumstances out there. I don’t mean to pretend to know what that’s like. All I’m saying is that, whether you get a good hand or a bad one, if you want to be satisfied with your life, you have to live life as hard and as fully as you can.","html":"I’m not here to tell you not to blame things on the way things are for you. I know I’ve been privileged. I try to remember there are people in terrible circumstances out there. I don’t mean to pretend to know what that’s like. All I’m saying is that, whether you get a good hand or a bad one, if you want to be satisfied with your life, you have to live life as hard and as fully as you can.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0024","sourceIndex":24,"type":"narration","text":"It’s not like those classmates of Cliff’s were that badly off. I guess they were unlucky with their parents, but they had enough drive to get into school through their own efforts and to work towards their goals.","html":"It’s not like those classmates of Cliff’s were that badly off. I guess they were unlucky with their parents, but they had enough drive to get into school through their own efforts and to work towards their goals. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0025","sourceIndex":25,"type":"narration","text":"Anyway, for my part, I’ve given my all to my life in this world. Naturally, I’m going to continue to do so. Maybe to others, my “all” seemed a little shallow and unserious. Don’t other people’s lives always seem that way? And no matter what anyone says about you, it’s not going to change your life, so why care about it? You know?","html":"Anyway, for my part, I’ve given my all to my life in this world. Naturally, I’m going to continue to do so. Maybe to others, my “all” seemed a little shallow and unserious. Don’t other people’s lives always seem that way? And no matter what anyone says about you, it’s not going to change your life, so why care about it? You know?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0026","sourceIndex":26,"type":"narration","text":"So, hey, if you’re reading this, live your life to the fullest… Ugh, we’re getting real preachy here, huh? I must be getting old. I guess it’s happened. I’ve become a dad.","html":"So, hey, if you’re reading this, live your life to the fullest… Ugh, we’re getting real preachy here, huh? I must be getting old. I guess it’s happened. I’ve become a dad.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0027","sourceIndex":27,"type":"narration","text":"Right, that’s enough talk about circumstances. It turned into a bit of a lecture.","html":"Right, that’s enough talk about circumstances. It turned into a bit of a lecture.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0028","sourceIndex":28,"type":"narration","text":"Now, I wonder who decoded my language. Maybe a scholar or something? Or a magician, expecting some amazing magical secret concealed within the pages of my diary… Either way, sorry for the lack of amazing secrets. I’ve said pretty much all of what I know about magic to Roxy, so it should all be available for you to learn about at the Ranoa Magic University or the Asuran Institute of Magic.","html":"Now, I wonder who decoded my language. Maybe a scholar or something? Or a magician, expecting some amazing magical secret concealed within the pages of my diary… Either way, sorry for the lack of amazing secrets. I’ve said pretty much all of what I know about magic to Roxy, so it should all be available for you to learn about at the Ranoa Magic University or the Asuran Institute of Magic.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0029","sourceIndex":29,"type":"narration","text":"If I were to give one piece of advice to those who follow in my footsteps, it would be that whether you want to learn voiced casting, unvoiced casting, casting with magic circles, or whatever happens to be the hot thing in your day, then reader, you must practice. You cast the same spell over and over again until your head’s spinning, then when you’re resting, you think up clever ways to use it. You devote yourself to it fully.","html":"If I were to give one piece of advice to those who follow in my footsteps, it would be that whether you want to learn voiced casting, unvoiced casting, casting with magic circles, or whatever happens to be the hot thing in your day, then reader, you must practice. You cast the same spell over and over again until your head’s spinning, then when you’re resting, you think up clever ways to use it. You devote yourself to it fully.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0030","sourceIndex":30,"type":"narration","text":"If you do that, even if you’re not a once-in-a-­generation genius, you’ll be skilled enough to earn the respect of your peers.","html":"If you do that, even if you’re not a once-in-a-­generation genius, you’ll be skilled enough to earn the respect of your peers.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0031","sourceIndex":31,"type":"narration","text":"Right! One more thing. If you’re thinking about translating this diary to offer it up to the ruler of some country, don’t. I get it, translating the language of a different world is impressive, and you want your success to be praised. You want appropriate compensation for your efforts. Thing is, there’s some stuff written in here that looks bad for the Asuran royal family in particular. There’s no way they’ll stand for claims like “the Asuran queen was Dragon God Orsted’s puppet!” It’s their prestige on the line, you know? Ariel might settle for just locking you up, but I can’t guarantee her descendants will spare your life. I guess if all the nations that appear in this diary have disappeared clean off the face of the world, then you can do what you like.","html":"Right! One more thing. If you’re thinking about translating this diary to offer it up to the ruler of some country, don’t. I get it, translating the language of a different world is impressive, and you want your success to be praised. You want appropriate compensation for your efforts. Thing is, there’s some stuff written in here that looks bad for the Asuran royal family in particular. There’s no way they’ll stand for claims like “the Asuran queen was Dragon God Orsted’s puppet!” It’s their prestige on the line, you know? Ariel might settle for just locking you up, but I can’t guarantee her descendants will spare your life. I guess if all the nations that appear in this diary have disappeared clean off the face of the world, then you can do what you like. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0032","sourceIndex":32,"type":"narration","text":"Huh. I suppose if that much time has passed, you might be a historian. If so, I hope you’ll reference this extensively as an example of an ordinary family in this period. Only, I did use my knowledge from my past life to reinvent some uncommon gadgets, so don’t rely on it too much.","html":"Huh. I suppose if that much time has passed, you might be a historian. If so, I hope you’ll reference this extensively as an example of an ordinary family in this period. Only, I did use my knowledge from my past life to reinvent some uncommon gadgets, so don’t rely on it too much.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0033","sourceIndex":33,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch09-p0034","sourceIndex":34,"type":"narration","text":"And yeah…one more thing. Just in case whoever’s reading this is someone from the same world as me. If, unlike me, you want to go home…I’ll give you a piece of advice.","html":"And yeah…one more thing. Just in case whoever’s reading this is someone from the same world as me. If, unlike me, you want to go home…I’ll give you a piece of advice.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0035","sourceIndex":35,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch09-p0036","sourceIndex":36,"type":"quotation","text":"“There is a way to return to your old world. Follow in the footsteps of Silent Sevenstar.”","html":"“There is a way to return to your old world. Follow in the footsteps of Silent Sevenstar.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Rudeus","attributionNote":"Written diary entry, not spoken aloud.","speakerConfidence":"high"},{"id":"ch09-p0037","sourceIndex":37,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch09-p0038","sourceIndex":38,"type":"narration","text":"Oh yeah, and if you ever dream of a white space with some pixelated asshole giving you advice, hard pass. He’s a liar, got it?","html":"Oh yeah, and if you ever dream of a white space with some pixelated asshole giving you advice, hard pass. He’s a liar, got it?","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch09-p0039","sourceIndex":39,"type":"narration","text":"Rudeus, over and out.","html":"Rudeus, over and out.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false}],"wordCount":2050,"speechCount":0,"speakers":[]}],"images":[],"sequence":9,"cast":["Ariel","Cliff","Eris","Orsted","Paul","Roxy","Rudeus","Sylphiette","Zenith"],"sceneCount":1,"speechCount":0,"speakers":[]},{"id":"ch10","number":"epilogue","title":"Epilogue: Prologue Zero","pov":"Rudeus","kind":"epilogue","wordCount":3007,"scenes":[{"id":"ch10-s01","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"A village in the kingdom, year 500 of the Armored Dragon Era","cast":["King of the Kingdom","Lyria","Rudeus"],"blocks":[{"id":"ch10-p0002","sourceIndex":2,"type":"narration","text":"IN THE YEAR 500 of the Armored Dragon Era, there lived a girl called the Blessed Child of Restoration. There was no life in her eyes. Ever since she was born, they had been empty save for despair. The adults around her found her uncanny and kept their distance.","html":"IN THE YEAR 500 of the Armored Dragon Era, there lived a girl called the Blessed Child of Restoration. There was no life in her eyes. Ever since she was born, they had been empty save for despair. The adults around her found her uncanny and kept their distance.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0003","sourceIndex":3,"type":"narration","text":"The girl knew what fate had in store for her. She had known since before birth—only, to say “before birth” is misleading. She had not known before her first, true birth. For this girl had been reborn many times. Again and again, she had repeated the same life. Again and again, she had repeated a life with minute differences each time. Different lives, albeit only slightly…and they all ended the same way. Her life was always fixed. There were never any great upheavals, and those lives always came to the same end.","html":"The girl knew what fate had in store for her. She had known since before birth—only, to say “before birth” is misleading. She had not known before her first, true birth. For this girl had been reborn many times. Again and again, she had repeated the same life. Again and again, she had repeated a life with minute differences each time. Different lives, albeit only slightly…and they all ended the same way. Her life was always fixed. There were never any great upheavals, and those lives always came to the same end.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0004","sourceIndex":4,"type":"narration","text":"That end was death. She died. No one living creature may escape death, but her death was a particularly awful one. After being manipulated as a tool by her country, she was captured and murdered by an enemy nation. She was like a toy fought over by children. Sometimes she was brutally raped, sometimes she was eaten alive by monsters, sometimes she was bound and thrown into water…","html":"That end was death. She died. No one living creature may escape death, but her death was a particularly awful one. After being manipulated as a tool by her country, she was captured and murdered by an enemy nation. She was like a toy fought over by children. Sometimes she was brutally raped, sometimes she was eaten alive by monsters, sometimes she was bound and thrown into water…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0005","sourceIndex":5,"type":"narration","text":"The girl died in suffering and despair. To her, life was a road that ended in despair. Every day was nothing but another step closer to the executioner’s block. She was without hope.","html":"The girl died in suffering and despair. To her, life was a road that ended in despair. Every day was nothing but another step closer to the executioner’s block. She was without hope.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0006","sourceIndex":6,"type":"narration","text":"The girl had a power. She could reverse time for an object by, at most, a single day. With this power, she restored broken things. She could even bring people back from the dead.","html":"The girl had a power. She could reverse time for an object by, at most, a single day. With this power, she restored broken things. She could even bring people back from the dead.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0007","sourceIndex":7,"type":"narration","text":"A single day. But even the power to bring the dead back to life for just a single day was enough for the Blessed Child to be pressed into service for the nation. The king kept her all to himself.","html":"A single day. But even the power to bring the dead back to life for just a single day was enough for the Blessed Child to be pressed into service for the nation. The king kept her all to himself. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0008","sourceIndex":8,"type":"narration","text":"Her power to reverse a single day freed the king from injury and illness. Mysteriously, she could not stop him from aging, but this was of little importance to the king.","html":"Her power to reverse a single day freed the king from injury and illness. Mysteriously, she could not stop him from aging, but this was of little importance to the king.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0009","sourceIndex":9,"type":"narration","text":"The girl had known three versions of the king. Though his name and appearance never changed, there were small variances in his personality and his conduct. Every time she died, and a new nightmare began, the king she served changed a little. Another, seeing these slight changes, might have praised the king for his wisdom, or condemned him as a fool. None of it mattered to the girl. There was no difference in how any of the kings treated her. To her, the kings all blended into the same monster.","html":"The girl had known three versions of the king. Though his name and appearance never changed, there were small variances in his personality and his conduct. Every time she died, and a new nightmare began, the king she served changed a little. Another, seeing these slight changes, might have praised the king for his wisdom, or condemned him as a fool. None of it mattered to the girl. There was no difference in how any of the kings treated her. To her, the kings all blended into the same monster. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0010","sourceIndex":10,"type":"narration","text":"The power that made her a Blessed Child brought her no happiness. She could not turn back her own time, nor could she use her power for her own purposes. All it did was shackle her to the palace that served as her prison.","html":"The power that made her a Blessed Child brought her no happiness. She could not turn back her own time, nor could she use her power for her own purposes. All it did was shackle her to the palace that served as her prison.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0011","sourceIndex":11,"type":"narration","text":"And then, she died. She was kept like an animal in a corner of the palace, meeting slightly different people ­every time, until she finally perished. Sometimes her power was insufficient, and she incurred the wrath of the king. Sometimes another nation invaded the kingdom, and she was taken prisoner. Sometimes the kingdom was overrun by demons who slaughtered them all. Her life faded away in misery. And then, she returned to the beginning. She started again from her birth in a remote, rural corner of the kingdom. After spending her early years enduring the adults’ disgust, she was taken to the palace, where she would ultimately die yet again.","html":"And then, she died. She was kept like an animal in a corner of the palace, meeting slightly different people ­every time, until she finally perished. Sometimes her power was insufficient, and she incurred the wrath of the king. Sometimes another nation invaded the kingdom, and she was taken prisoner. Sometimes the kingdom was overrun by demons who slaughtered them all. Her life faded away in misery. And then, she returned to the beginning. She started again from her birth in a remote, rural corner of the kingdom. After spending her early years enduring the adults’ disgust, she was taken to the palace, where she would ultimately die yet again.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0012","sourceIndex":12,"type":"narration","text":"The girl tried to escape her fate in the beginning. She hid her power so that she could stay with her mother and father. It did no good. For some reason, just before her fifth birthday, soldiers came from the palace and took her away with them. She tried to run away from the village before the soldiers came, but that too was futile. She was either killed by a monster or captured by bandits or kidnappers. Who she was sold on to next varied, but she ended up at the palace without fail. Fate dragged her back to the palace like an antlion’s trap, crushed her hope, then murdered her. It was hell—an eternal, unceasing hell ­cycle that utterly destroyed her. She ceased to feel anything. She followed the king’s orders, her face as devoid of expression as a machine. A hundred years passed, then two hundred. Or was it a thousand? Two thousand? Perhaps ten, or twenty thousand. She no longer remembered how many times she had died, or how long she had lived. Her memory was perpetually hazy, and she couldn’t recall a single instance of joy.","html":"The girl tried to escape her fate in the beginning. She hid her power so that she could stay with her mother and father. It did no good. For some reason, just before her fifth birthday, soldiers came from the palace and took her away with them. She tried to run away from the village before the soldiers came, but that too was futile. She was either killed by a monster or captured by bandits or kidnappers. Who she was sold on to next varied, but she ended up at the palace without fail. Fate dragged her back to the palace like an antlion’s trap, crushed her hope, then murdered her. It was hell—an eternal, unceasing hell ­cycle that utterly destroyed her. She ceased to feel anything. She followed the king’s orders, her face as devoid of expression as a machine. A hundred years passed, then two hundred. Or was it a thousand? Two thousand? Perhaps ten, or twenty thousand. She no longer remembered how many times she had died, or how long she had lived. Her memory was perpetually hazy, and she couldn’t recall a single instance of joy.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0013","sourceIndex":13,"type":"narration","text":"The moment of her murder was always crystal clear.","html":"The moment of her murder was always crystal clear.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0014","sourceIndex":14,"type":"narration","text":"Perhaps it was instinct. Some pure animal urge within her that clung to life, that recorded the memory of her murder as something to be avoided. Alas, the result was that her whole life was blotted out by her own deaths. She no longer recalled anything else. Nothing but a chain of memories of death.","html":"Perhaps it was instinct. Some pure animal urge within her that clung to life, that recorded the memory of her murder as something to be avoided. Alas, the result was that her whole life was blotted out by her own deaths. She no longer recalled anything else. Nothing but a chain of memories of death.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0015","sourceIndex":15,"type":"narration","text":"Immersed in an endless stream of death, the girl made a wish. She wished with all her heart.","html":"Immersed in an endless stream of death, the girl made a wish. She wished with all her heart. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0016","sourceIndex":16,"type":"narration","text":"I can’t bear this anymore… Somebody, help me…","html":"I can’t bear this anymore… Somebody, help me…","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0017","sourceIndex":17,"type":"narration","text":"In that moment, the laws of the world shifted.","html":"In that moment, the laws of the world shifted.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0018","sourceIndex":18,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":880,"speechCount":0,"speakers":[]},{"id":"ch10-s02","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The magic circle chamber beneath the palace","cast":["Lyria","Priest","Rudeus","Shinohara Akito"],"blocks":[{"id":"ch10-p0020","sourceIndex":20,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch10-p0021","sourceIndex":21,"type":"narration","text":"Things in her next life had changed.","html":"Things in her next life had changed. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0022","sourceIndex":22,"type":"narration","text":"She was born in a provincial village she couldn’t even name and was taken to the palace. She obeyed the king’s every whim and used her power day in and day out. None of this had changed. But when she was ten, something different happened. Something that had never happened before. It was her tenth birthday. As though to celebrate the occasion, the girl was taken away. She was taken beneath the palace, to a space with a vast magic circle. The girl hadn’t known there was such a magic circle in the palace, for she had never been allowed to walk freely within it.","html":"She was born in a provincial village she couldn’t even name and was taken to the palace. She obeyed the king’s every whim and used her power day in and day out. None of this had changed. But when she was ten, something different happened. Something that had never happened before. It was her tenth birthday. As though to celebrate the occasion, the girl was taken away. She was taken beneath the palace, to a space with a vast magic circle. The girl hadn’t known there was such a magic circle in the palace, for she had never been allowed to walk freely within it.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0023","sourceIndex":23,"type":"narration","text":"Several dozen adults stood around the magic circle. They held staffs and wore black robes. Hoods covered their faces. The knowledge she had gleaned from her eternal hell told her that these people were magicians. But what would happen to her next, she did not know. She knew little about magic and magic circles. She had never had the opportunity to learn such things in her hellish prison.","html":"Several dozen adults stood around the magic circle. They held staffs and wore black robes. Hoods covered their faces. The knowledge she had gleaned from her eternal hell told her that these people were magicians. But what would happen to her next, she did not know. She knew little about magic and magic circles. She had never had the opportunity to learn such things in her hellish prison.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0024","sourceIndex":24,"type":"narration","text":"The girl was bound to the magic circle. Her eyes were empty as always. Something new had happened, but it failed to stir her heart at all. She would still die in the end. No matter what happened along the way, nothing would change. This sense of resignation crowded out everything else.","html":"The girl was bound to the magic circle. Her eyes were empty as always. Something new had happened, but it failed to stir her heart at all. She would still die in the end. No matter what happened along the way, nothing would change. This sense of resignation crowded out everything else.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0025","sourceIndex":25,"type":"narration","text":"The ritual began. The magic circle relentlessly drew the mana from her body. Blessed Children held an inconceivable volume of mana within their bodies. It was a different stripe of mana to that which was used in magic and swordcraft, and in theory, it could not typically have been used for a magic circle like this one. Was it chance, then, that the magic circle was drawing out her mana? No. This magic circle had been created for a purpose. It was designed to be activated using the mana of the Blessed Child of Restoration. Who had made it? Though they were out of the girl’s sight, the architect was present at the ritual. She observed the magic circle looking only a little less bored than the girl.","html":"The ritual began. The magic circle relentlessly drew the mana from her body. Blessed Children held an inconceivable volume of mana within their bodies. It was a different stripe of mana to that which was used in magic and swordcraft, and in theory, it could not typically have been used for a magic circle like this one. Was it chance, then, that the magic circle was drawing out her mana? No. This magic circle had been created for a purpose. It was designed to be activated using the mana of the Blessed Child of Restoration. Who had made it? Though they were out of the girl’s sight, the architect was present at the ritual. She observed the magic circle looking only a little less bored than the girl. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0026","sourceIndex":26,"type":"narration","text":"The ritual was a success. The magic circle blazed with light. Light in a prism of seven colors—the light of summoning.","html":"The ritual was a success. The magic circle blazed with light. Light in a prism of seven colors—the light of summoning.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0027","sourceIndex":27,"type":"narration","text":"Then, when the light died away, there was a boy standing in the middle of the circle.","html":"Then, when the light died away, there was a boy standing in the middle of the circle.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0028","sourceIndex":28,"type":"speech","text":"“It worked.”","html":"“It worked.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Priest","speakerConfidence":"high"},{"id":"ch10-p0029","sourceIndex":29,"type":"speech","text":"“We did it!”","html":"“We did it!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Priest","speakerConfidence":"high"},{"id":"ch10-p0030","sourceIndex":30,"type":"speech","text":"“The kingdom is saved!”","html":"“The kingdom is saved!”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Priest","speakerConfidence":"high"},{"id":"ch10-p0031","sourceIndex":31,"type":"narration","text":"While the magicians celebrated, the boy looked around at his surroundings in amazement. Then, his gaze turned to the girl with empty eyes who sat on the ground in front of him.","html":"While the magicians celebrated, the boy looked around at his surroundings in amazement. Then, his gaze turned to the girl with empty eyes who sat on the ground in front of him.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0032","sourceIndex":32,"type":"speech","text":"“Um… Could you tell me where this is? I was just with Nana and Kuro…huh?”","html":"“Um… Could you tell me where this is? I was just with Nana and Kuro…huh?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Shinohara Akito","speakerConfidence":"high"},{"id":"ch10-p0033","sourceIndex":33,"type":"narration","text":"The language he spoke was unknown to all there, and yet somehow, the girl understood. Perhaps it was because her own mana had been used, or perhaps it was because she was connected to his presence here.","html":"The language he spoke was unknown to all there, and yet somehow, the girl understood. Perhaps it was because her own mana had been used, or perhaps it was because she was connected to his presence here.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0034","sourceIndex":34,"type":"speech","text":"“Oh, um, my name’s Shinohara Akito,” he said. “How about you?”","html":"“Oh, um, my name’s Shinohara Akito,” he said. “How about you?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Shinohara Akito","mixed":true,"speakerConfidence":"high"},{"id":"ch10-p0035","sourceIndex":35,"type":"speech","text":"“I am the Blessed Child of Restoration.”","html":"“I am the Blessed Child of Restoration.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lyria","speakerConfidence":"high"},{"id":"ch10-p0036","sourceIndex":36,"type":"speech","text":"“Blessed…? Um, I wanted to know your name.”","html":"“Blessed…? Um, I wanted to know your name.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Shinohara Akito","speakerConfidence":"high"},{"id":"ch10-p0037","sourceIndex":37,"type":"narration","text":"The girl realized that in every iteration of her personal hell, and in particular after she came to the palace, no one ever asked her name.","html":"The girl realized that in every iteration of her personal hell, and in particular after she came to the palace, no one ever asked her name.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0038","sourceIndex":38,"type":"narration","text":"A Blessed Child had no name. Perhaps if they were royalty, an exception might be made, but as a rule, Blessed Children had their names taken from them. From that point on. They were only ever referred to as “Blessed Child.” The girl was no exception.","html":"A Blessed Child had no name. Perhaps if they were royalty, an exception might be made, but as a rule, Blessed Children had their names taken from them. From that point on. They were only ever referred to as “Blessed Child.” The girl was no exception. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0039","sourceIndex":39,"type":"narration","text":"But while usually, Blessed Children had their names taken before they could learn them, the girl remembered her name. She remembered it precisely because she had died so many times.","html":"But while usually, Blessed Children had their names taken before they could learn them, the girl remembered her name. She remembered it precisely because she had died so many times.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0040","sourceIndex":40,"type":"narration","text":"It was the name her mother and father had given her.","html":"It was the name her mother and father had given her.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0041","sourceIndex":41,"type":"speech","text":"“Lyria,” she said.","html":"“Lyria,” she said.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lyria","speakerConfidence":"high"},{"id":"ch10-p0042","sourceIndex":42,"type":"speech","text":"“Lyria? That’s a nice name.” The boy smiled, and the girl’s heart sang.","html":"“Lyria? That’s a nice name.” The boy smiled, and the girl’s heart sang.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Shinohara Akito","mixed":true,"speakerConfidence":"high"},{"id":"ch10-p0043","sourceIndex":43,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":646,"speechCount":9,"speakers":["Lyria","Priest","Shinohara Akito"]},{"id":"ch10-s03","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The palace and its grounds","cast":["Lyria","Mage Knight","Rudeus","Shinohara Akito"],"blocks":[{"id":"ch10-p0045","sourceIndex":45,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch10-p0046","sourceIndex":46,"type":"narration","text":"The girl felt something had changed. The king released her from her duties as Blessed Child. Instead, she was made the boy’s interpreter. After a mage knight joined them as a bodyguard, the three of them wandered freely through the palace.","html":"The girl felt something had changed. The king released her from her duties as Blessed Child. Instead, she was made the boy’s interpreter. After a mage knight joined them as a bodyguard, the three of them wandered freely through the palace.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0047","sourceIndex":47,"type":"speech","text":"“Lilia, what’s that?” The boy from another world asked her about everything—about the world, about how they lived, about the people in it. Despite dying so many times, the girl knew nothing.","html":"“Lilia, what’s that?” The boy from another world asked her about everything—about the world, about how they lived, about the people in it. Despite dying so many times, the girl knew nothing.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Shinohara Akito","mixed":true,"speakerConfidence":"high"},{"id":"ch10-p0048","sourceIndex":48,"type":"speech","text":"“He asked…what that is.”","html":"“He asked…what that is.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lyria","speakerConfidence":"high"},{"id":"ch10-p0049","sourceIndex":49,"type":"speech","text":"“That? That’s a magical implement. When you put magic into it, fire comes out of the end. I wonder if they’re going to the forest to drive out monsters.”","html":"“That? That’s a magical implement. When you put magic into it, fire comes out of the end. I wonder if they’re going to the forest to drive out monsters.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Mage Knight","speakerConfidence":"high"},{"id":"ch10-p0050","sourceIndex":50,"type":"narration","text":"The girl, knowing nothing, asked the knight and the knight answered. The mage knight, who was said to be a genius, looked half-asleep but answered all her questions. Unlike the girl, she knew everything.","html":"The girl, knowing nothing, asked the knight and the knight answered. The mage knight, who was said to be a genius, looked half-asleep but answered all her questions. Unlike the girl, she knew everything.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0051","sourceIndex":51,"type":"speech","text":"“Ohh, so it’s like a flamethrower…” the boy said. “Come to think of it, there are lots of tree monsters in this world, aren’t there? Have you ever seen one, Lilia?”","html":"“Ohh, so it’s like a flamethrower…” the boy said. “Come to think of it, there are lots of tree monsters in this world, aren’t there? Have you ever seen one, Lilia?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Shinohara Akito","mixed":true,"speakerConfidence":"high"},{"id":"ch10-p0052","sourceIndex":52,"type":"speech","text":"“Several times,” Lilia said slowly. “They…swooshed.”","html":"“Several times,” Lilia said slowly. “They…swooshed.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lyria","mixed":true,"attributionNote":"The text calls her Lilia here; her own name is Lyria.","speakerConfidence":"high"},{"id":"ch10-p0053","sourceIndex":53,"type":"speech","text":"“‘Swooshed’…?” The boy laughed. “I can’t picture it. No, wait! Actually, I’ve seen them in movies.”","html":"“‘Swooshed’…?” The boy laughed. “I can’t picture it. No, wait! Actually, I’ve seen them in movies.”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Shinohara Akito","mixed":true,"speakerConfidence":"high"},{"id":"ch10-p0054","sourceIndex":54,"type":"speech","text":"“Movies…?”","html":"“Movies…?”","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Lyria","speakerConfidence":"high"},{"id":"ch10-p0055","sourceIndex":55,"type":"speech","text":"“Yeah, a movie is—”","html":"“Yeah, a movie is—” ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false,"speaker":"Shinohara Akito","speakerConfidence":"high"},{"id":"ch10-p0056","sourceIndex":56,"type":"narration","text":"Her life as an interpreter was nothing like her life before. Everything was fresh. Every time the boy learned something about the world, he smiled his easy smile, and every time, the girl’s heart sang.","html":"Her life as an interpreter was nothing like her life before. Everything was fresh. Every time the boy learned something about the world, he smiled his easy smile, and every time, the girl’s heart sang.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0057","sourceIndex":57,"type":"narration","text":"At first, she’d thought nothing would change. She’d thought everything was over for her. But she could dream about the stories the boy sometimes told her about his world. When the knight answered the boy’s questions, she felt her world expanding. She learned that this world was unimaginably vast and full of all sorts of people she had never known.","html":"At first, she’d thought nothing would change. She’d thought everything was over for her. But she could dream about the stories the boy sometimes told her about his world. When the knight answered the boy’s questions, she felt her world expanding. She learned that this world was unimaginably vast and full of all sorts of people she had never known.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0058","sourceIndex":58,"type":"narration","text":"A little while after the boy came, she realized that her food had taste. Her ears opened to the chirping of the birds when she woke in the morning and to enjoy the warmth of the sun.","html":"A little while after the boy came, she realized that her food had taste. Her ears opened to the chirping of the birds when she woke in the morning and to enjoy the warmth of the sun.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0059","sourceIndex":59,"type":"narration","text":"She felt alive. She believed her stint in hell was over. The boy had come to save her. He had come to pull her out of this long, hellish cycle. She had been born to meet him. Now, her real life would begin.","html":"She felt alive. She believed her stint in hell was over. The boy had come to save her. He had come to pull her out of this long, hellish cycle. She had been born to meet him. Now, her real life would begin.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0060","sourceIndex":60,"type":"narration","text":"This is fate, she thought. The boy was so strong and so gentle, and such a support to her, that it seemed true.","html":"This is fate, she thought. The boy was so strong and so gentle, and such a support to her, that it seemed true.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0061","sourceIndex":61,"type":"narration","text":"But fate betrayed her.","html":"But fate betrayed her.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0062","sourceIndex":62,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":400,"speechCount":8,"speakers":["Lyria","Mage Knight","Shinohara Akito"]},{"id":"ch10-s04","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The battlefield outside the city, then the ruined palace","cast":["Lyria","Rudeus","Shinohara Akito"],"blocks":[{"id":"ch10-p0064","sourceIndex":64,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch10-p0065","sourceIndex":65,"type":"narration","text":"War engulfed the kingdom. The girl knew that every time this war came, it swept her up and she died. She knew it better than anyone. But there were things she didn’t know: that the boy had been summoned to win the war. That the kingdom’s prophet had advised that they summon a champion from another world and have him fight for them. And that after the kingdom had taken the prophet’s advice and spent ten years summoning the boy, they were now at a point of no return.","html":"War engulfed the kingdom. The girl knew that every time this war came, it swept her up and she died. She knew it better than anyone. But there were things she didn’t know: that the boy had been summoned to win the war. That the kingdom’s prophet had advised that they summon a champion from another world and have him fight for them. And that after the kingdom had taken the prophet’s advice and spent ten years summoning the boy, they were now at a point of no return. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0066","sourceIndex":66,"type":"narration","text":"The girl knew nothing. And the boy fought. He did not know war, however. The people of the kingdom knew that the boy did not know how to fight, yet still, they sent him out on the battlefield. They clad him in armor, put a sword in his hand, and placed him on the army’s front line. This was what they had summoned him for.","html":"The girl knew nothing. And the boy fought. He did not know war, however. The people of the kingdom knew that the boy did not know how to fight, yet still, they sent him out on the battlefield. They clad him in armor, put a sword in his hand, and placed him on the army’s front line. This was what they had summoned him for.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0067","sourceIndex":67,"type":"narration","text":"And the boy died. He was mercilessly cut down on the battlefield. As he stood there on trembling legs, an enemy general cut his head off in a single blow, and he died. The enemy general took his head, so it was only his body that came back to the girl. The people of the kingdom, when they saw the dead boy, only sighed and muttered in disgust that, in the end, their champion from another world had been useless. They had been fools to trust the prophet’s ravings.","html":"And the boy died. He was mercilessly cut down on the battlefield. As he stood there on trembling legs, an enemy general cut his head off in a single blow, and he died. The enemy general took his head, so it was only his body that came back to the girl. The people of the kingdom, when they saw the dead boy, only sighed and muttered in disgust that, in the end, their champion from another world had been useless. They had been fools to trust the prophet’s ravings. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0068","sourceIndex":68,"type":"narration","text":"The girl embraced the boy’s corpse and tried desperately to restore him, but it was futile. Already more than a day had passed since his death, and he was beginning to rot. The girl’s power was of no use here.","html":"The girl embraced the boy’s corpse and tried desperately to restore him, but it was futile. Already more than a day had passed since his death, and he was beginning to rot. The girl’s power was of no use here. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0069","sourceIndex":69,"type":"narration","text":"She wept and screamed, asking why, why must always suffer so, why was fate so cruel to her alone. She wept, but not only out of grief. She felt like fate was toying with her, laughing at her for trying when no matter what she did, she was doomed. She was overcome with a sense of powerlessness.","html":"She wept and screamed, asking why, why must always suffer so, why was fate so cruel to her alone. She wept, but not only out of grief. She felt like fate was toying with her, laughing at her for trying when no matter what she did, she was doomed. She was overcome with a sense of powerlessness. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0070","sourceIndex":70,"type":"narration","text":"Then, the kingdom fell. The girl was captured and, as she had every time before, died in the depths of despair.","html":"Then, the kingdom fell. The girl was captured and, as she had every time before, died in the depths of despair.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0071","sourceIndex":71,"type":"narration","text":"Unlike every time before, the girl made a wish. For the first time since she was first born, she wished and wished with all her heart, I want to live!","html":"Unlike every time before, the girl made a wish. For the first time since she was first born, she wished and wished with all her heart, I want to live! ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0072","sourceIndex":72,"type":"narration","text":"Not that she didn’t want to die, or that she wanted someone to save her.","html":"Not that she didn’t want to die, or that she wanted someone to save her. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0073","sourceIndex":73,"type":"narration","text":"I want to live with him…!","html":"I want to live with him…!","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0074","sourceIndex":74,"type":"narration","text":"The time she had spent living with the boy had not been long. But even in that short span, he had stolen her heart and usurped all the memories of death that had filled it.","html":"The time she had spent living with the boy had not been long. But even in that short span, he had stolen her heart and usurped all the memories of death that had filled it.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0075","sourceIndex":75,"type":"narration","text":"The boy was hope. He was the first hope the girl had known. That hope kept her head raised high and facing forward. For the first time since she was first born, she turned an eye to her own power. The moment she died, she bit her lip hard enough to draw blood, then used her power.","html":"The boy was hope. He was the first hope the girl had known. That hope kept her head raised high and facing forward. For the first time since she was first born, she turned an eye to her own power. The moment she died, she bit her lip hard enough to draw blood, then used her power.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0076","sourceIndex":76,"type":"narration","text":"Her power could turn back time for a single day. Or at least, it was believed to do so. Everyone had a vague sense that something was strange about her power, but the ability was so convenient that no one had bothered to investigate any further. Now, the girl forced out so much of her own might that she thought her mind would burst. She used the Power to Alter the Past.","html":"Her power could turn back time for a single day. Or at least, it was believed to do so. Everyone had a vague sense that something was strange about her power, but the ability was so convenient that no one had bothered to investigate any further. Now, the girl forced out so much of her own might that she thought her mind would burst. She used the Power to Alter the Past.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0077","sourceIndex":77,"type":"narration","text":"The world looped, with the girl at its center.","html":"The world looped, with the girl at its center.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0078","sourceIndex":78,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"}],"wordCount":585,"speechCount":0,"speakers":[]},{"id":"ch10-s05","pov":"Rudeus","povHeader":null,"sceneHeader":null,"location":"The Citadel of Roa in Fittoa, year 400 of the Armored Dragon Era","cast":["Lyria","Nanahoshi","Rudeus"],"blocks":[{"id":"ch10-p0080","sourceIndex":80,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch10-p0081","sourceIndex":81,"type":"narration","text":"The girl’s power stretched back into the past to the year 400 of the Armored Dragon Era, to the Citadel of Roa in Fittoa, where the boy she loved had lost his life.","html":"The girl’s power stretched back into the past to the year 400 of the Armored Dragon Era, to the Citadel of Roa in Fittoa, where the boy she loved had lost his life. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0082","sourceIndex":82,"type":"narration","text":"A rift in spacetime opened in the sky above the town. In the depths of the rift was a being with a powerful connection to the boy. This being bore a striking resemblance to the soul of the girl who had wanted to live together with the boy. Thus, to create a future where the boy would be spared, she altered the world and opened a path for him to live. As a result, in the year 500 of the Armored Dragon Era, the boy was saved—or he should have been. Even with the girl’s great power, causing a person who was not supposed to have a future to exist in the past was impossible. It was nothing like preventing someone from being injured or contracting a disease. Though the rift in space-time remained, the being within did not come down into the world. The girl’s power became locked in a bitter stalemate with the power of the world itself.","html":"A rift in spacetime opened in the sky above the town. In the depths of the rift was a being with a powerful connection to the boy. This being bore a striking resemblance to the soul of the girl who had wanted to live together with the boy. Thus, to create a future where the boy would be spared, she altered the world and opened a path for him to live. As a result, in the year 500 of the Armored Dragon Era, the boy was saved—or he should have been. Even with the girl’s great power, causing a person who was not supposed to have a future to exist in the past was impossible. It was nothing like preventing someone from being injured or contracting a disease. Though the rift in space-time remained, the being within did not come down into the world. The girl’s power became locked in a bitter stalemate with the power of the world itself.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0083","sourceIndex":83,"type":"narration","text":"The world moved on, uncaring: 400, 401, 402, 403. But as it did, a single lost soul found its way through the rift. This soul bore no connection to the boy. When the boy was transported, before the girl’s power had been used to summon him, this soul had simply happened to be close by. But it was a soul, and so it managed to slip unseen through the rift, even as the world was trying to block it up. The soul wandered aimlessly for a while, until it came across an infant on the verge of death and slipped inside it. That soul belonged to the person who would be named Rudeus Greyrat.","html":"The world moved on, uncaring: 400, 401, 402, 403. But as it did, a single lost soul found its way through the rift. This soul bore no connection to the boy. When the boy was transported, before the girl’s power had been used to summon him, this soul had simply happened to be close by. But it was a soul, and so it managed to slip unseen through the rift, even as the world was trying to block it up. The soul wandered aimlessly for a while, until it came across an infant on the verge of death and slipped inside it. That soul belonged to the person who would be named Rudeus Greyrat.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0084","sourceIndex":84,"type":"narration","text":"Rudeus Greyrat’s existence left the smallest of alterations on the world. He changed the thinking of Roxy Migurdia, he derailed the life of Sylphiette, and he imparted knowledge to Eris Boreas Greyrat. These actions weakened the world’s ability to resist, and the rift expanded outwards.","html":"Rudeus Greyrat’s existence left the smallest of alterations on the world. He changed the thinking of Roxy Migurdia, he derailed the life of Sylphiette, and he imparted knowledge to Eris Boreas Greyrat. These actions weakened the world’s ability to resist, and the rift expanded outwards. ","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0085","sourceIndex":85,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch10-p0086","sourceIndex":86,"type":"narration","text":"In the year 417 of the Armored Dragon Era, Nanahoshi Shizuka was summoned.","html":"In the year 417 of the Armored Dragon Era, Nanahoshi Shizuka was summoned.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false},{"id":"ch10-p0087","sourceIndex":87,"type":"spacer","text":"","html":"","className":"P_Prose_Formatting"},{"id":"ch10-p0088","sourceIndex":88,"type":"narration","text":"Rudeus Greyrat’s existence had altered the world more than the girl had hoped for. It was only supposed to have been enough change that the boy would be saved, but it did not stop there. History branched off in an unknown direction. The world changed. It is impossible to know if these changes were those that the girl wished for, as she has not yet been born. A few years after Rudeus’s death, she will be. In exchange for the loops, she will be born as an empty shell of a Blessed Child, losing all but the slightest hint of her powers. To grant her wish, she will be born into one final world. Whether she will survive to the end is a tale for another time.","html":"Rudeus Greyrat’s existence had altered the world more than the girl had hoped for. It was only supposed to have been enough change that the boy would be saved, but it did not stop there. History branched off in an unknown direction. The world changed. It is impossible to know if these changes were those that the girl wished for, as she has not yet been born. A few years after Rudeus’s death, she will be. In exchange for the loops, she will be born as an empty shell of a Blessed Child, losing all but the slightest hint of her powers. To grant her wish, she will be born into one final world. Whether she will survive to the end is a tale for another time.","className":"P_Prose_Formatting","italic":false,"bold":false,"dropCap":false}],"wordCount":492,"speechCount":0,"speakers":[]}],"images":[],"sequence":10,"cast":["King of the Kingdom","Lyria","Mage Knight","Nanahoshi","Priest","Rudeus","Shinohara Akito"],"sceneCount":5,"speechCount":17,"speakers":["Lyria","Mage Knight","Priest","Shinohara Akito"]}],"speakers":[{"name":"Rudeus","lines":258,"chapters":["ch01","ch02","ch03","ch04","ch05","ch06","ch07"],"scenes":["ch01-s02","ch01-s03","ch01-s04","ch02-s02","ch02-s03","ch02-s05","ch02-s06","ch03-s01","ch03-s02","ch03-s03","ch03-s04","ch03-s05","ch04-s01","ch04-s02","ch04-s03","ch04-s04","ch04-s05","ch05-s01","ch05-s02","ch06-s01","ch06-s03","ch07-s01"]},{"name":"Badigadi","lines":55,"chapters":["ch01","ch02","ch03","ch04"],"scenes":["ch01-s01","ch01-s02","ch01-s03","ch02-s05","ch02-s06","ch03-s01","ch03-s02","ch04-s03"]},{"name":"Orsted","lines":54,"chapters":["ch01","ch02","ch03","ch04","ch05"],"scenes":["ch01-s04","ch02-s06","ch03-s05","ch03-s06","ch04-s02","ch04-s03","ch05-s02"]},{"name":"Perugius","lines":32,"chapters":["ch04","ch05","ch07"],"scenes":["ch04-s01","ch05-s01","ch07-s01"]},{"name":"Alexander","lines":28,"chapters":["ch03","ch04"],"scenes":["ch03-s04","ch03-s05","ch03-s06","ch04-s02","ch04-s03"]},{"name":"Sylphiette","lines":24,"chapters":["ch02","ch03","ch04","ch05"],"scenes":["ch02-s06","ch03-s01","ch03-s02","ch04-s05","ch05-s02"]},{"name":"Geese","lines":23,"chapters":["ch01","ch03"],"scenes":["ch01-s01","ch01-s02","ch01-s03","ch03-s03"]},{"name":"Sandor","lines":23,"chapters":["ch01","ch04"],"scenes":["ch01-s01","ch01-s02","ch01-s04","ch04-s01"]},{"name":"Eris","lines":19,"chapters":["ch01","ch03","ch04"],"scenes":["ch01-s02","ch01-s03","ch01-s04","ch03-s02","ch04-s05"]},{"name":"Ruijerd","lines":19,"chapters":["ch01","ch02","ch03","ch04"],"scenes":["ch01-s04","ch02-s03","ch02-s05","ch03-s04","ch04-s01"]},{"name":"Cliff","lines":9,"chapters":["ch01","ch04"],"scenes":["ch01-s03","ch04-s01"]},{"name":"Ghislaine","lines":8,"chapters":["ch03","ch04"],"scenes":["ch03-s03","ch03-s04","ch04-s01"]},{"name":"Lilia","lines":8,"chapters":["ch04"],"scenes":["ch04-s04","ch04-s05"]},{"name":"Shinohara Akito","lines":8,"chapters":["ch10"],"scenes":["ch10-s02","ch10-s03"]},{"name":"Atofe","lines":6,"chapters":["ch01"],"scenes":["ch01-s02","ch01-s03"]},{"name":"Aisha","lines":5,"chapters":["ch02","ch04"],"scenes":["ch02-s06","ch04-s01"]},{"name":"Lyria","lines":5,"chapters":["ch10"],"scenes":["ch10-s02","ch10-s03"]},{"name":"Roxy","lines":5,"chapters":["ch02","ch04","ch05"],"scenes":["ch02-s06","ch04-s05","ch05-s02"]},{"name":"Lara","lines":4,"chapters":["ch06"],"scenes":["ch06-s01"]},{"name":"Dohga","lines":3,"chapters":["ch04"],"scenes":["ch04-s01"]},{"name":"Feris","lines":3,"chapters":["ch05"],"scenes":["ch05-s02"]},{"name":"Lucie","lines":3,"chapters":["ch04"],"scenes":["ch04-s04"]},{"name":"Norn","lines":3,"chapters":["ch02","ch04"],"scenes":["ch02-s06","ch04-s01"]},{"name":"Priest","lines":3,"chapters":["ch10"],"scenes":["ch10-s02"]},{"name":"Isolde","lines":2,"chapters":["ch02","ch04"],"scenes":["ch02-s06","ch04-s01"]},{"name":"Zanoba","lines":2,"chapters":["ch02","ch04"],"scenes":["ch02-s06","ch04-s04"]},{"name":"Julie","lines":1,"chapters":["ch02"],"scenes":["ch02-s06"]},{"name":"Leo","lines":1,"chapters":["ch04"],"scenes":["ch04-s05"]},{"name":"Mage Knight","lines":1,"chapters":["ch10"],"scenes":["ch10-s03"]}]};
